CM.data.topics([{"id":"abbasid-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"沈没船が語るインド洋の交易","l":"abbasid","x":"1998年、インドネシアのスマトラ島とボルネオ島の間にあるブリトゥン島の沖の海底で、1隻の沈没船が発見された。木の板をココヤシの繊維のひもで縫い合わせて造られた、アラブ・ペルシア系"},{"id":"abbasid-t2","k":"source","f":"src","kj":"史料｜記録","t":"9世紀のアラブ商人が見た中国","l":"abbasid","x":"9世紀半ばにまとめられた『中国とインドの諸情報』は、ペルシア湾から中国まで航海した商人たちの見聞を記録した書物である。そこには、中国の港の様子が、次のように記されている。広府（広州"},{"id":"abbasid-t3","k":"source","f":"src","kj":"史料｜記録","t":"ユダヤ人の国際商人ラーザーニーヤ","l":"abbasid","x":"9世紀のアッバース朝の駅伝の長官イブン・フルダーズベは、『諸道と諸国の書』の中で、「ラーザーニーヤ」と呼ばれるユダヤ人の商人たちについて、次のように記している。原文الذين يت"},{"id":"abbasid-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"ズバイダ――巡礼者のための道","l":"abbasid","x":"ハールーンの妻ズバイダは、マンスールの孫娘で、莫大な富を持っていた。伝承によれば、彼女の食卓には金と銀の器しか並ばず、宝石で飾った靴をはいたという。一方で、ズバイダは、メッカへの巡"},{"id":"abbasid-t5","k":"source","f":"src","kj":"史料｜記録","t":"カリフが贈った水時計","l":"abbasid","x":"アッバース朝のカリフ、ハールーン・アッラシードは、遠いフランク王国のカール大帝と使節を交わした。807年、カリフの使節がカールのもとにもたらした贈り物の中に、ヨーロッパの人々を驚か"},{"id":"abbasid-t6","k":"now","f":"now","kj":"いま","t":"バグダードの現在","l":"abbasid","x":"バグダードは、現在、イラク共和国の首都であり、人口は800万人を超える。しかし、マンスールの円城の跡は、現在の市街地の下に完全に埋もれ、地上には何も残っていない。1258年、モンゴ"},{"id":"abbasid-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"abbasid","x":"『千夜一夜物語』（アラビアン・ナイト）：ハールーン・アッラシードや宰相ジャアファル（バルマク家）が登場する物語が多く含まれる。日本語訳には、前嶋信次・池田修訳（平凡社東洋文庫、アラ"},{"id":"achaemenid-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"キュロスの円筒碑文は「最初の人権宣言」か","l":"achaemenid","x":"1879年、バビロンの遺跡で、楔形文字のアッカド語がびっしり刻まれた樽の形の粘土製品が発見された。キュロス2世がバビロンを征服したときのことを記した「キュロス＝シリンダー（キュロス"},{"id":"achaemenid-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ダレイオス1世の即位の謎","l":"achaemenid","x":"ダレイオス1世は、即位の事情をイラン西部のベヒストゥーンの崖に刻ませた碑文で、次のように説明している。カンビュセスは弟のバルディヤをひそかに殺していた。カンビュセスが遠征中に、ガウ"},{"id":"achaemenid-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"サトラップと「属州総督」","l":"achaemenid","x":"アケメネス朝のサトラップは、ローマの属州総督や中国の郡県制の役人とよく比べられる。いずれも中央から地方に派遣された支配者だが、違いもある。サトラップ：主にペルシア人の貴族が任命され"},{"id":"achaemenid-t4","k":"source","f":"src","kj":"史料｜記録","t":"「雪も雨も」――ヘロドトスの記録","l":"achaemenid","x":"原文τούτων δὲ τῶν ἀγγέλων ἐστὶ οὐδὲν ὅ τι θᾶσσον παραγίνεται θνητὸν ἐόν …… τοὺς οὔτε νιφετός"},{"id":"achaemenid-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"ベヒストゥーン碑文と楔形文字の解読","l":"achaemenid","x":"ベヒストゥーン碑文は、イラン西部の交通路沿いの崖の、地上から約60mの高さに刻まれている。同じ内容が、古代ペルシア語・エラム語・アッカド語（バビロニア語）の3つの言語で、いずれも楔"},{"id":"achaemenid-t6","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"粘土板が語る労働者たち――産休手当もあった","l":"achaemenid","x":"1933〜34年、ペルセポリスの城壁の中から、数万枚の小さな粘土板が見つかった。エラム語で書かれた、宮殿の建設や運営にかかわる物資の支給の記録である（ペルセポリス城砦文書）。この記"},{"id":"achaemenid-t7","k":"now","f":"now","kj":"いま","t":"アメリカの裁判に巻き込まれた粘土板","l":"achaemenid","x":"ペルセポリス城砦文書は、研究のために1930年代にアメリカのシカゴ大学に貸し出され、その一部が現在も研究されている。2000年代に入り、イランが支援したとされるテロの被害者たちが、"},{"id":"achaemenid-t8","k":"view","f":"think","kj":"考える｜別の視点","t":"ゾロアスター教の遺したもの","l":"achaemenid","x":"「最後の審判」「天使と悪魔」「天国と地獄」「救世主の到来」――こうした考え方は、ユダヤ教・キリスト教・イスラームにも見られる。これらの考え方の一部は、バビロン捕囚から解放されたユダ"},{"id":"achaemenid-t9","k":"confuse","f":"confuse","kj":"混同注意","t":"アケメネス朝とササン朝","l":"achaemenid","x":"どちらもイラン（ペルシア）人の帝国なので、混同しやすい。アケメネス朝ササン朝時代前550〜前330年後224〜651年建国キュロス2世（メディアを倒す）アルダシール1世（パルティア"},{"id":"achaemenid-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"achaemenid","x":"ヘンデル『セルセ』（オペラ、1738年初演）：アケメネス朝の王クセルクセス1世（セルセ）を主人公にした喜劇的なオペラ。冒頭のアリア「オンブラ・マイ・フ（なつかしい木陰よ）」は、「ヘ"},{"id":"aegean-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"クレタ文明とミケーネ文明","l":"aegean","x":"クレタ文明（ミノア文明）ミケーネ文明時期前2000〜前1400年ごろ前1600〜前1200年ごろ中心クレタ島（クノッソス）ギリシア本土（ミケーネ・ティリンス・ピュロス）担い手民族系"},{"id":"aegean-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"迷宮ラビュリントスとミノタウロス","l":"aegean","x":"ギリシア神話によれば、クレタ島の王ミノスは、牛の頭と人の体をもつ怪物ミノタウロスを、名工ダイダロスに造らせた迷宮（ラビュリントス）に閉じ込め、アテネから毎年少年少女を貢ぎ物として送"},{"id":"aegean-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"牛跳びの競技","l":"aegean","x":"クノッソスの壁画で最も有名なのが、「牛跳び」の場面である。突進してくる牛の角をつかんで、その背の上で宙返りし、後ろに降り立つ若者たちが描かれている。祭りの儀式として行われた競技と考"},{"id":"aegean-t4","k":"now","f":"now","kj":"いま","t":"「復元」された宮殿","l":"aegean","x":"現在、クノッソスを訪れた人が見る宮殿の赤い柱や、色鮮やかな壁画の多くは、発掘者エヴァンズが20世紀前半に、鉄筋コンクリートを使って「復元」したものである。エヴァンズは、崩れかけた遺"},{"id":"aegean-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"テラ島の噴火とアトランティス","l":"aegean","x":"前17世紀ごろ（年代には諸説）、クレタの北約100kmにあるテラ島（現在のサントリーニ島）で、人類の歴史の上でも最大級の火山の噴火が起こった。島の中央部は吹き飛び、海に沈んで、現在"},{"id":"aegean-t6","k":"voice","f":"src","kj":"史料｜証言","t":"「ぶどう酒色の海の真ん中に、クレタという国がある」――ホメロスの歌うクレタ","l":"aegean","x":"前8世紀ごろにまとめられたホメロスの叙事詩『オデュッセイア』で、故郷に帰り着いた主人公オデュッセウスは、身分を隠すために、自分はクレタの生まれだと作り話をする。そのとき彼は、クレタ"},{"id":"aegean-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「アガメムノンの顔を見た」","l":"aegean","x":"1876年、シュリーマンはミケーネの城門の内側にある円形の墓域で、黄金のマスクをつけた遺体を発見した。彼は、ギリシア王に「私は今日、アガメムノンの顔を見ました」という電報を送ったと"},{"id":"aegean-t8","k":"voice","f":"src","kj":"史料｜証言","t":"「私はアガメムノンの顔を見た」――シュリーマンの電報","l":"aegean","x":"1876年、ドイツの実業家シュリーマンは、ギリシアのミケーネの城塞の中の円形墓域を掘り、黄金の仮面をつけた遺体を見つけた。彼は、ギリシア王に、こう電報を打ったと伝えられる。原文Ic"},{"id":"aegean-t9","k":"debate","f":"think","kj":"考える｜諸説あり","t":"トロイア戦争の史実性","l":"aegean","x":"小アジア北西部のトロイア（現在のトルコのヒサルルク）の遺跡には、前3000年ごろから後の時代まで、9層以上にわたって都市が重なっている。シュリーマンは、黄金の財宝が出た第2層をホメ"},{"id":"aegean-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"aegean","x":"ホメロス『イリアス』『オデュッセイア』：トロイア戦争の伝説を歌った叙事詩そのものが、今も読み継がれる「作品」である。映画『トロイ』（2004年）：『イリアス』をもとにした映画。神々"},{"id":"afghanistan-soviet-t1","k":"source","f":"src","kj":"史料｜記録","t":"「すぐにばれる」","l":"afghanistan-soviet","x":"1979年3月、西部の都市ヘラートで大規模な反乱が起こり、ソ連人の顧問たちも殺された。アフガニスタンの最高指導者タラキーは、モスクワのコスイギン首相に電話をかけ、ソ連軍の派遣を懇願"},{"id":"afghanistan-soviet-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"毒入りの昼食","l":"afghanistan-soviet","x":"1979年12月27日、首都カブールの郊外の丘の上に建つタージベク宮殿で、アミンは、昼食をとっていた。その料理には、KGBが送り込んだ料理人によって、毒が盛られていた。アミンは、昏"},{"id":"afghanistan-soviet-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「ソ連に、ソ連のベトナム戦争を与える機会が来た」――ブレジンスキー","l":"afghanistan-soviet","x":"ソ連軍がアフガニスタンに侵攻した1979年12月、アメリカのカーター大統領の安全保障担当補佐官ブレジンスキーは、大統領に覚書を送った。彼は、のちの1998年、フランスの週刊誌のイン"},{"id":"afghanistan-soviet-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"涙の記者会見","l":"afghanistan-soviet","x":"1980年7月、モスクワで、オリンピックが開かれた。アメリカは、ソ連のアフガニスタン侵攻に抗議して、大会への不参加を決め、同盟国にも同調を求めた。日本、西ドイツ、中国、韓国など、6"},{"id":"afghanistan-soviet-t5","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"「亜鉛の少年たち」","l":"afghanistan-soviet","x":"アフガニスタンで戦死したソ連の兵士の遺体は、亜鉛でできた密封された棺に納められ、輸送機で故郷に送り返された。軍の暗号では、遺体は「貨物200」と呼ばれた。遺族は、多くの場合、棺を開"},{"id":"afghanistan-soviet-t6","k":"person","f":"deep","kj":"深掘り｜人物","t":"中村哲と用水路","l":"afghanistan-soviet","x":"1984年、福岡県出身の医師の中村哲は、パキスタンの北西部の都市ペシャワールの病院に赴任し、ハンセン病の治療に取り組み始めた。そこには、ソ連との戦争を逃れてきたアフガニスタンの難民"},{"id":"afghanistan-soviet-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"afghanistan-soviet","x":"カーレド・ホッセイニ『君のためなら千回でも』（小説、2003年）：ソ連の侵攻とターリバーンの支配に引き裂かれたアフガニスタンを舞台に、二人の少年の友情と裏切り、償いを描いた小説。映"},{"id":"africa-early-medieval-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"沈黙交易","l":"africa-early-medieval","x":"金の産地での取引は、「沈黙交易」で行われたという話が伝わっている。前5世紀のヘロドトスは、カルタゴ人が、「ヘラクレスの柱（ジブラルタル海峡）」の外のアフリカの海岸の人々と、次のよう"},{"id":"africa-early-medieval-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「塩と金は同じ重さで交換された」？","l":"africa-early-medieval","x":"サハラ交易について、「塩と金は、同じ重さで交換された」という話がよく語られる。しかし、これは誇張である。実際の交換比率は、時代と場所によって大きく違った。たしかに、森林地帯に近いサ"},{"id":"africa-early-medieval-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"黄金の雨を降らせた蛇","l":"africa-early-medieval","x":"ソニンケ人の間には、ワガドゥの繁栄と衰退について、次のような伝説が語り継がれている伝承。ワガドゥの都の近くの井戸には、ビダという名の大蛇が住んでいた。ビダは、毎年、一人の美しい娘を"},{"id":"africa-early-medieval-t4","k":"source","f":"src","kj":"史料｜記録","t":"ガーナの王の葬儀","l":"africa-early-medieval","x":"バクリーは、ガーナの王が亡くなったときの葬儀の様子を、次のように記している。王が亡くなると、人々は、墓となる場所の上に、チーク材で大きな丸屋根の建物をつくる。そして、敷物とクッショ"},{"id":"africa-early-medieval-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「顔を覆う者たち」","l":"africa-early-medieval","x":"ムラービトゥーンの中心となったのは、サハラ西部の遊牧のベルベル人（サンハージャ族）であった。彼らの男性は、今日のトゥアレグの人々と同じように、布で顔の下半分を覆う習慣をもっていた。"},{"id":"africa-early-medieval-t6","k":"now","f":"now","kj":"いま","t":"二つの「ガーナ」と「マリ」","l":"africa-early-medieval","x":"1957年、イギリスの植民地「黄金海岸」は、サハラ以南のアフリカで最も早く独立を果たした国の一つとなった際、国名を「ガーナ」とした。しかし、現在のガーナ共和国は、ギニア湾に面した国"},{"id":"africa-early-medieval-t7","k":"works","f":"works","kj":"作品","t":"サハラ交易にまつわる作品","l":"africa-early-medieval","x":"イブン＝バットゥータ『大旅行記』：14世紀にサハラ砂漠を越えてマリを訪れたイブン＝バットゥータの旅行記には、タガザの塩の町や、砂漠の旅の様子が生き生きと描かれている。日本語訳に、家"},{"id":"africa-independence-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"国連事務総長の謎の死","l":"africa-independence","x":"コンゴの混乱の収拾に全力をあげたのが、スウェーデン出身の国連事務総長ハマーショルドであった。ハマーショルドは、国連軍を派遣し、カタンガの分離を終わらせようとした。画像はオンライン時"},{"id":"africa-independence-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「アフリカは自らの歴史を書くだろう」――ルムンバの最後の手紙","l":"africa-independence","x":"コンゴの初代首相パトリス・ルムンバは、1960年の独立からわずか数か月で失脚し、反対派に捕らえられた。獄中から妻ポーリーヌにあてて書いた手紙は、こう結ばれている。原文…… Je p"},{"id":"africa-independence-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"はだしの王者","l":"africa-independence","x":"1960年9月10日、ローマ・オリンピックの最終日のマラソン。トップでゴールのコンスタンティヌスの凱旋門をくぐったのは、エチオピアの皇帝の親衛隊の兵士、アベベ・ビキラであった。しか"},{"id":"africa-independence-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"africa-independence","x":"チヌア・アチェベ『崩れゆく絆』（小説、1958年）：19世紀の末、イギリスの植民地支配とキリスト教の宣教が、ナイジェリアのイボ人の村社会を崩していく姿を、アフリカの側から描いた小説"},{"id":"aksum-t1","k":"source","f":"src","kj":"史料｜記録","t":"マニの「四つの王国」","l":"aksum","x":"地上には四つの大王国がある。第一はバビロンとペルシアの王国、第二はローマの王国、第三はアクスム人の王国、第四は中国人の王国である。出典：『ケファライア』第77章（マニ教の教説集、コ"},{"id":"aksum-t2","k":"source","f":"src","kj":"史料｜記録","t":"『エリュトゥラー海案内記』に描かれたアドゥリスとアクスム","l":"aksum","x":"アドゥリスから、アクソーミタイ（アクスム人）と呼ばれる人々の町までは、さらに5日の行程である。ナイル川の向こうの地から産するすべての象牙が、その町に運ばれ、そこからアドゥリスへと運"},{"id":"aksum-t3","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"奴隷から司教へ――フルメンティオスの物語","l":"aksum","x":"ルフィヌスの『教会史』によれば、4世紀の初め、ティルス（現在のレバノン）の哲学者メロピオスが、二人の少年フルメンティオスとアエデシオスを連れて、紅海を船で旅していた。船が水と食料を"},{"id":"aksum-t4","k":"source","f":"src","kj":"史料｜記録","t":"エザナ王の碑文（キリスト教改宗後）","l":"aksum","x":"天と地においてすべてのものを支配する天の主の力によって……主の力と、主の子である勝利者イエス・キリストの恵みによって――わたしはこの方を信じる――……出典：エザナ王の碑文（アクスム"},{"id":"aksum-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"ローマ皇帝からの手紙","l":"aksum","x":"アクスムのキリスト教は、すぐにローマ帝国の教会の争いに巻き込まれた。356年ごろ、ローマ皇帝コンスタンティウス2世は、アクスムの王「アイザナスとサザナス」（エザナとその兄弟）に手紙"},{"id":"aksum-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"アクスムはメロエを滅ぼしたのか","l":"aksum","x":"教科書では、「アクスム王国が4世紀にメロエ王国を滅ぼした」と書かれることが多い。たしかに、エザナ王の碑文には、ナイル川流域への遠征が記され、メロエ遺跡からはアクスムの王の碑文の断片"},{"id":"aksum-t7","k":"now","f":"now","kj":"いま","t":"ローマから帰ってきた石碑","l":"aksum","x":"1937年、エチオピアを侵略・占領したイタリアのムッソリーニ政権は、倒れていたアクスムの第2石碑（高さ約24m）を戦利品としてローマへ運び、ローマ進軍15周年を記念して、市内に建て"},{"id":"aksum-t8","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"契約の箱はアクスムにあるのか","l":"aksum","x":"アクスムには、エチオピア正教会で最も神聖な教会の一つ、シオンの聖マリア教会がある。エチオピアの人々の間では、この教会の敷地内の礼拝堂に、古代イスラエルの「契約の箱」（モーセの十戒を"},{"id":"aksum-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"ムスリムを守った王","l":"aksum","x":"610年ごろ、メッカでムハンマドが教えを説き始めると、メッカの有力者たちは、信者たちを迫害した。615年ごろ、ムハンマドは、一部の信者に、紅海の対岸のアクスムへ逃れるよう勧めたとい"},{"id":"aksum-t10","k":"source","f":"src","kj":"史料｜記録","t":"「象の持ち主たちに、主がどうなされたか」――『コーラン』象章","l":"aksum","x":"570年ごろ、アクスム王国の支配下にあった南アラビアの総督アブラハは、象を連れた軍勢を率いて、メッカに攻め寄せたと伝えられる。イスラームの伝承では、このとき、神の送った鳥の群れが軍"},{"id":"aksum-t11","k":"now","f":"now","kj":"いま","t":"古都アクスムと現代の紛争","l":"aksum","x":"アクスムは、現在のエチオピア北部のティグライ州にある。この地域は、1993年に独立したエリトリアとの国境に近く、1998〜2000年のエチオピア・エリトリア国境紛争では、両国あわせ"},{"id":"aksum-t12","k":"works","f":"works","kj":"作品","t":"アクスムとエチオピアにまつわる作品","l":"aksum","x":"『ケブラ・ナガスト』（14世紀）：シバの女王とソロモン王の子メネリクが、契約の箱をエチオピアにもたらしたという物語を中心とする、エチオピアの書物。エチオピアの王家の正統性を語る「建"},{"id":"al-andalus-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「レコンキスタ」という言葉","l":"al-andalus","x":"「レコンキスタ（再征服）」という言葉には、イベリア半島はもともとキリスト教徒の土地であり、それをイスラーム教徒から「取り戻した」という考え方が込められている。しかし、この言葉が歴史"},{"id":"al-andalus-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「キリスト教徒は、自分たちの言葉を知らない」――コルドバのアルバルスの嘆き","l":"al-andalus","x":"9世紀の半ば、後ウマイヤ朝の都コルドバでは、キリスト教徒の若者たちの多くが、アラビア語を話し、アラビア語の詩や学問に夢中になっていた。アラブ風の暮らしや言葉を身につけたキリスト教徒"},{"id":"al-andalus-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"スペイン語に残るアラビア語","l":"al-andalus","x":"スペイン語には、アラビア語に由来する言葉が、4000語以上あるといわれる。その多くは、アラビア語の定冠詞「アル（al）」がついた形で取り入れられている。アセイテ（aceite、油）"},{"id":"al-andalus-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"壁に刻まれた言葉","l":"al-andalus","x":"アルハンブラ宮殿の壁には、アラビア文字の装飾が、びっしりと刻まれている。その中で、最も多く繰り返されているのが、「ワ・ラー・ガーリバ・イッラッラー（神のほかに勝者なし）」という言葉"},{"id":"al-andalus-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"al-andalus","x":"ワシントン・アーヴィング『アルハンブラ物語』（1832年）：グラナダのアルハンブラ宮殿に滞在したアメリカの作家が、宮殿にまつわるナスル朝の伝説や、地元の人々の話を集めた作品。アルハ"},{"id":"alexander-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"暴れ馬ブケファラス","l":"alexander","x":"アレクサンドロスがまだ少年だったころ、テッサリアから一頭の見事な馬が売りに出された。しかし、この馬はひどく暴れて、誰も乗りこなすことができなかった。フィリッポス2世が買うのをあきら"},{"id":"alexander-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ゴルディオンの結び目","l":"alexander","x":"小アジア中部の町ゴルディオンには、昔の王の戦車が、複雑な結び目で縛りつけられていた。「この結び目を解いた者が、アジアの王になる」という言い伝えがあった。前333年、この町を訪れたア"},{"id":"alexander-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"捕らえられたペルシアの王母","l":"alexander","x":"イッソスの戦いで、ダレイオス3世は母のシシュガンビス、妃、子どもたちを陣営に残したまま逃走した。捕虜となった王の家族を、アレクサンドロスは王族にふさわしく丁重に扱った。ある逸話によ"},{"id":"alexander-t4","k":"voice","f":"src","kj":"史料｜証言","t":"テュロスの浜に並んだ十字架","l":"alexander","x":"前332年、アレクサンドロスは、海に浮かぶ島の町テュロス（現在のレバノン）を7か月にわたって包囲した。陸から島まで堤防を築き、ついに町を攻め落とすと、長い抵抗に怒った大王は、容赦の"},{"id":"alexander-t5","k":"source","f":"src","kj":"史料｜記録","t":"兵士たちの拒否","l":"alexander","x":"アレクサンドロスは、さらに東のガンジス川流域へ進もうとした。しかし、ヒュファシス川（現在のビアス川）のほとりで、8年にわたって故郷を離れて戦い続けてきた兵士たちが、ついに進軍を拒ん"},{"id":"alexander-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「征服する世界がもう残っていない」と泣いた？","l":"alexander","x":"アレクサンドロスは、征服すべき世界がもう残っていないと嘆いて泣いた――という話は、映画などでもよく使われる。しかし、古代の記録にそのような話はない。もとになったのは、プルタルコスの"},{"id":"alexander-t7","k":"confuse","f":"confuse","kj":"混同注意","t":"アレクサンドロスの帝国とアケメネス朝","l":"alexander","x":"アレクサンドロスの帝国の範囲は、ほぼアケメネス朝ペルシアの領土をそのまま引き継いだものだった。ギリシアとマケドニアを加え、アラビア半島や黒海北岸などは含まない。アケメネス朝（最大領"},{"id":"alexander-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"alexander","x":"岩明均『ヒストリエ』（漫画、2003年〜連載）：アレクサンドロス大王の書記官で、のちに後継者戦争を戦ったエウメネスの生涯を描く。少年時代のエウメネスの放浪から、マケドニアの宮廷での"},{"id":"american-colonies-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ポカホンタスの物語","l":"american-colonies","x":"ジェームズタウンの指導者の一人ジョン・スミスは、この地方の先住民の首長ポウハタンに捕らえられ、処刑されそうになった時、首長の幼い娘ポカホンタスが、身を投げ出して命乞いをしてくれたと"},{"id":"american-colonies-t2","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"american-colonies","x":"アーサー・ミラー『るつぼ』（戯曲、1953年）：1692年のマサチューセッツのセイラムで起こった魔女裁判を描いた戯曲。アメリカで共産主義者を追及した「赤狩り」を、重ね合わせて批判し"},{"id":"american-revolution-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「すべての人は平等」","l":"american-revolution","x":"「すべての人は平等につくられ」と書いたジェファソンは、生涯に600人以上の黒人奴隷を所有した大農園主であった。ジェファソンの草案には、イギリス国王が奴隷貿易を押しつけたと非難する一"},{"id":"american-revolution-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"7月4日の偶然","l":"american-revolution","x":"独立宣言の起草に関わったジェファソンとジョン・アダムズは、のちに、それぞれ第3代と第2代の大統領となった。二人は、政治的には激しく対立したが、晩年には手紙を交わして友情を取り戻した"},{"id":"american-revolution-t3","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"去っていった人々","l":"american-revolution","x":"独立戦争で、イギリス国王の側についた国王派の人々の多くは、戦後、財産を奪われ、迫害を受けた。6万〜8万人が、カナダやイギリス、カリブ海の島々に移り住んだ。カナダの英語圏の社会は、こ"},{"id":"american-revolution-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"american-revolution","x":"ミュージカル『ハミルトン』（リン＝マニュエル・ミランダ作、2015年初演）：建国の父の一人アレクサンダー・ハミルトンの生涯を、ヒップホップの音楽で描いたミュージカル。建国の父たちを"},{"id":"american-revolution-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ワシントンの入れ歯は「木」だったのか","l":"american-revolution","x":"初代大統領ワシントンは、若いころから歯が悪く、大統領に就任した1789年には、自分の歯は1本しか残っていなかった。彼の入れ歯は「木でできていた」とよくいわれるが、これは誤りである。"},{"id":"americas-oceania-peopling-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"2万3000年前の足跡？――ホワイトサンズ","l":"americas-oceania-peopling","x":"2021年、アメリカのニューメキシコ州ホワイトサンズで、かつての湖のほとりの地層に残された人間の足跡が、約2万3000〜2万1000年前のものだと発表された。最終氷期の最盛期のころ"},{"id":"americas-oceania-peopling-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"ケネウィック人は誰のものか","l":"americas-oceania-peopling","x":"1996年、アメリカ北西部のワシントン州ケネウィックで、川岸から古い人骨が見つかった。約9000年前の男性の骨であった。最初に骨を調べた研究者が、頭骨の形はヨーロッパ系の人々に似て"},{"id":"americas-oceania-peopling-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"「インディアン」「インディオ」という呼び名","l":"americas-oceania-peopling","x":"アメリカ大陸の先住民は、長く「インディアン」（英語）や「インディオ」（スペイン語）と呼ばれてきた。これは、1492年にカリブ海の島に着いたコロンブスが、そこをインドの一部だと思い込"},{"id":"americas-oceania-peopling-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"星と波を読む航海術","l":"americas-oceania-peopling","x":"ポリネシアの人々は、羅針盤も海図も持たずに、何千キロメートルもの大洋を渡った。使ったのは、2つの船体を板でつないだ大型の双胴カヌーである。人々や食料、豚や鶏、犬、タロイモやヤムイモ"},{"id":"americas-oceania-peopling-t5","k":"source","f":"src","kj":"史料｜記録","t":"クックを驚かせた航海者たち","l":"americas-oceania-peopling","x":"18世紀、太平洋を3度にわたって探検したイギリスの航海者クックは、ニュージーランドからハワイ、イースター島まで、何千キロメートルも離れた島々の人々が、よく似た言葉を話し、同じような"},{"id":"americas-oceania-peopling-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ポリネシア人はアメリカ大陸に到達していた？","l":"americas-oceania-peopling","x":"南アメリカ原産のサツマイモは、ヨーロッパ人が来るより前から、ポリネシアの島々で栽培されていた。しかもポリネシアの言葉でサツマイモを指す「クマラ」は、南アメリカのケチュア語の「クマル"},{"id":"americas-oceania-peopling-t7","k":"debate","f":"think","kj":"考える｜諸説あり","t":"イースター島の「文明崩壊」は本当か","l":"americas-oceania-peopling","x":"イースター島（ラパ・ヌイ）は、巨大な石像モアイで知られる。かつては、島民がモアイを運ぶために森の木をすべて切り倒してしまい、その結果、資源が尽きて争いが起き、人口が激減して社会が崩"},{"id":"americas-oceania-peopling-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"巨鳥モアの絶滅","l":"americas-oceania-peopling","x":"ニュージーランドには、かつてモアと呼ばれる飛べない巨大な鳥がいた。最大の種は、首を伸ばすと高さ3.6メートル、体重は200キログラムを超えた。ニュージーランドにはもともと陸上の哺乳"},{"id":"americas-oceania-peopling-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"コロンブスより500年前にアメリカに来た人々","l":"americas-oceania-peopling","x":"アメリカ大陸に最初に来たヨーロッパ人は、コロンブスではない。11世紀初め、ノルウェー系のヴァイキング（ノルマン人）が、グリーンランドからさらに西へ航海し、北アメリカに到達していた。"},{"id":"americas-oceania-peopling-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"americas-oceania-peopling","x":"映画『モアナと伝説の海』（ディズニー、2016年、アニメ）：太平洋の島の少女モアナが、祖先たちの航海の技術を受け継いで、大海原に旅立つ物語。ポリネシアの人々の、星と波を読む航海の伝"},{"id":"an-shi-t1","k":"source","f":"src","kj":"史料｜記録","t":"杜甫「憶昔」――開元の全盛の日","l":"an-shi","x":"のちに安史の乱を経験した詩人の杜甫は、開元の時代をこう振り返っている。原文憶昔開元全盛日，小邑猶藏萬家室。稻米流脂粟米白，公私倉廩俱豐實。九州道路無豺虎，遠行不勞吉日出。書き下し憶"},{"id":"an-shi-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"早馬で運ばれたライチ","l":"an-shi","x":"楊貴妃は、南方の果物ライチ（茘枝）を好んだ。ライチは、摘み取ってから数日で色も香りも失われてしまう。そこで、南方の産地から長安まで、早馬を乗り継いで、鮮度を保ったまま運ばせたという"},{"id":"an-shi-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"「腹の中には、赤心があるだけ」――道化を演じた男","l":"an-shi","x":"安禄山は、宮廷で、わざと粗野でとぼけた「胡人」を演じてみせることで、玄宗の警戒心を解いた。その逸話が、歴史書にいくつも残されている伝承。ある日、玄宗は、膝の下まで垂れ下がった安禄山"},{"id":"an-shi-t4","k":"source","f":"src","kj":"史料｜記録","t":"杜甫「春望」","l":"an-shi","x":"反乱軍に占領された長安に捕らわれていた杜甫は、757年の春、荒れ果てた都の姿を見て、こう詠んだ。原文國破山河在，城春草木深。感時花濺淚，恨別鳥驚心。烽火連三月，家書抵萬金。白頭搔更"},{"id":"an-shi-t5","k":"voice","f":"src","kj":"史料｜証言","t":"杜甫「石壕吏」――夜の徴兵","l":"an-shi","x":"759年、安史の乱の鎮圧に向かった唐の大軍は、鄴城（河南省）で大敗した。兵士を補うため、役人たちは村々で、男たちを手当たりしだいに連れ去った。旅の途中、石壕村に泊まった杜甫は、その"},{"id":"an-shi-t6","k":"confuse","f":"confuse","kj":"混同注意","t":"租庸調制と両税法","l":"an-shi","x":"租庸調制両税法（780年〜）前提均田制で土地を与えられた成年男子（丁男）実際に住んでいる土地の戸（本籍地に関係なく）課税の基準人（丁男）ごとに一律戸の資産と土地の広さに応じて納める"},{"id":"an-shi-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"円仁が見た会昌の廃仏","l":"an-shi","x":"9世紀の唐では、仏教寺院が莫大な土地と財産を持ち、多くの人々が税や兵役を逃れるために僧となっていた。845年、道教を信じる武宗は、大規模な仏教弾圧を行い、4600余りの寺院を破壊し"},{"id":"an-shi-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"広州の外国人の虐殺","l":"an-shi","x":"10世紀のアラブの著述家アブー・ザイドは、黄巣の軍が広州を攻め落としたとき、そこに住んでいたムスリム・ユダヤ教徒・キリスト教徒・ゾロアスター教徒の外国人12万人が殺されたと記してい"},{"id":"an-shi-t9","k":"source","f":"src","kj":"史料｜記録","t":"黄巣「菊を賦す」","l":"an-shi","x":"黄巣は、科挙に落第した後、次のような詩を作ったと伝えられる伝承。原文待到秋來九月八，我花開後百花殺。衝天香陣透長安，滿城盡帶黃金甲。書き下し待ち到る秋来たりて九月八日 我が花開くの"},{"id":"an-shi-t10","k":"voice","f":"src","kj":"史料｜証言","t":"「天街に踏み尽くす公卿の骨」――黄巣の乱","l":"an-shi","x":"880年、黄巣の軍は長安に入った。黄巣は皇帝を名乗ったが、その軍は都で略奪と殺戮を繰り返した。長安から逃れた詩人韋荘は、都の惨状を、一人の女性の語りの形で長編の詩にした。原文長安寂"},{"id":"an-shi-t11","k":"works","f":"works","kj":"作品","t":"この時代にまつわる作品","l":"an-shi","x":"白居易「長恨歌」（806年）：玄宗と楊貴妃の悲恋を歌った長編詩。日本では平安時代に広く愛読され、『源氏物語』の冒頭の「桐壺」の巻は、その影響を強く受けている。陳鴻「長恨歌伝」：「長"},{"id":"andes-early-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"細長い頭と頭蓋骨の手術","l":"andes-early","x":"パラカスの墓から見つかった人骨には、頭蓋骨が後ろに細長く伸びたものが多い。これは、赤ん坊のうちに頭を板や布で締めつけて、意図的に形を変えたものである。頭の形は、どの集団に属するかを"},{"id":"andes-early-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"宇宙人が描いた？","l":"andes-early","x":"上空からでないと全体が見えないことから、地上絵は、宇宙人の宇宙船の滑走路や目印として描かれたのだという説が、1960年代末に出版されて話題を呼んだ。しかし、これは根拠のない俗説であ"},{"id":"andes-early-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"マリア・ライヘ――地上絵に生涯をささげた人","l":"andes-early","x":"ドイツ生まれの数学者マリア・ライヘ（1903〜1998年）は、1940年代から半世紀以上にわたって、ナスカの砂漠に住み込み、地上絵の測量と研究を続けた。彼女は、ほうきで地上絵の線を"},{"id":"andes-early-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「世界最大の天文学の本」――コソックとナスカの地上絵","l":"andes-early","x":"1941年6月22日、アメリカの歴史学者ポール・コソックは、ペルー南部のナスカの乾いた台地で、地上に描かれた長い直線の一本の上に立って、夕日を眺めていた。その日は、南半球の冬至であ"},{"id":"andes-early-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"入れ墨の女王","l":"andes-early","x":"2006年、モチェ川の北のエル・ブルホ遺跡で、4〜5世紀ごろの女性のミイラが発見された。腕や足には、ヘビやクモなどの入れ墨が残っており、「カオの貴婦人」と呼ばれている。彼女は、王冠"},{"id":"andes-early-t6","k":"now","f":"now","kj":"いま","t":"盗掘と開発に脅かされる遺跡","l":"andes-early","x":"シパン王墓の発見のきっかけが盗掘であったように、アンデスの遺跡は、長い間、盗掘に苦しめられてきた。ペルーでは、遺跡を掘って副葬品を売る者を「ワケーロ」と呼ぶ。スペインの植民地時代に"},{"id":"andes-early-t7","k":"works","f":"works","kj":"作品","t":"アンデスの古代文明にまつわる作品","l":"andes-early","x":"エーリッヒ・フォン・デニケン『未来の記憶』（1968年）：ナスカの地上絵などの古代の遺跡を、宇宙人が地球を訪れた証拠だと主張して、世界的なベストセラーとなった本。本編で見たように、"},{"id":"angkor-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「水利都市」論争","l":"angkor","x":"20世紀の半ば、フランスの研究者グロリエは、アンコールの巨大な貯水池の水が、水路を通じて周りの田に配られ、年に何回も米をつくることを可能にしていた、と考えた。アンコールの繁栄は、高"},{"id":"angkor-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"浮き彫りの中の王と「シャムの兵」","l":"angkor","x":"アンコール＝ワットの南側の回廊には、スールヤヴァルマン2世自身の姿が彫られている。王は、日傘を何本もさしかけられて玉座に座り、家臣たちの報告を受けている。そして、その先には、王が率"},{"id":"angkor-t3","k":"source","f":"src","kj":"史料｜記録","t":"「民の苦しみこそが王の苦しみ」","l":"angkor","x":"ジャヤヴァルマン7世は、王国の各地に102の病院を建て、主な道路に沿って旅人のための宿駅を設けたと、碑文に記されている。病院には、医者や薬を作る者などが置かれ、薬や食糧が国から支給"},{"id":"angkor-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"市場を仕切る女性たち","l":"angkor","x":"周達観によれば、カンボジアでは、市場での商売は、もっぱら女性たちが行っていた。「この国の人で商売ができるのは、みな女性である。そのため、中国人がこの国に来ると、必ずまず妻を迎える。"},{"id":"angkor-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"アンコール＝ワットに名前を残した日本人","l":"angkor","x":"アンコール＝ワットの十字回廊の柱には、日本語の墨の書き込みが残っている。そこには、寛永9年（1632年）の正月に、肥前（現在の長崎県・佐賀県）の森本右近太夫一房という人物がこの地を"},{"id":"angkor-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"アンコールは「再発見」されたのか","l":"angkor","x":"1860年、フランスの博物学者アンリ・ムオは、カンボジアの密林の中でアンコール＝ワットを見た。彼の死後に出版された旅行記によって、アンコールの存在はヨーロッパに広く知られるようにな"},{"id":"angkor-t7","k":"source","f":"src","kj":"史料｜記録","t":"ラームカムヘーン王碑文","l":"angkor","x":"碑文には、スコータイの国の豊かさと、王の政治のありさまが、こう書かれている。「ラームカムヘーン王の時代、スコータイの国は豊かである。水には魚がおり、田には稲がある。……王は、通行税"},{"id":"angkor-t8","k":"source","f":"src","kj":"史料｜記録","t":"「南国の山河は南帝の住むところ」","l":"angkor","x":"1077年、宋の大軍がベトナムに攻め込んだとき、李朝の将軍李常傑は、川の防衛線で宋軍を迎え撃った。言い伝えによれば、そのとき、川のほとりの祠から、夜ごと、次のような詩を吟じる声が聞"},{"id":"angkor-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"angkor","x":"映画『トゥームレイダー』（2001年）：アンコール遺跡群のタ・プローム寺院でロケが行われた冒険映画。巨大なガジュマルの木の根に呑み込まれた遺跡の姿が、世界に知られるきっかけの一つと"},{"id":"apartheid-t1","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"鉛筆のテスト","l":"apartheid","x":"人種の分類は、人々の運命を決めた。どの人種に分類されるかによって、住める場所も、通える学校も、就ける仕事も、結婚できる相手も、すべてが決まったからである。しかし、人間を「人種」に分"},{"id":"apartheid-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「バンツーには、ヨーロッパ人の社会に居場所はない」――フルウールトの演説","l":"apartheid","x":"1953年、南アフリカでは、アフリカ人の子どもたちの教育を、政府が統制する「バンツー教育法」が定められた。法案を提出した原住民問題相（のちの首相）フルウールトは、議会で、その狙いを"},{"id":"apartheid-t3","k":"source","f":"src","kj":"史料｜記録","t":"リヴォニア裁判の陳述","l":"apartheid","x":"1964年4月20日、国家反逆の罪に問われた裁判（リヴォニア裁判）の法廷で、被告席のマンデラは、3時間にわたって陳述を行った。その結びの言葉は、こうであった。「私は、白人の支配と闘"},{"id":"apartheid-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「そのために死ぬ覚悟がある理想」――マンデラの法廷演説","l":"apartheid","x":"1964年4月20日、国家反逆の罪に問われたリヴォニア裁判の法廷で、被告席のネルソン・マンデラは、4時間にわたる陳述を、こう結んだ。原文I have cherished the i"},{"id":"apartheid-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"名誉白人","l":"apartheid","x":"アパルトヘイトのもとで、日本人は、「名誉白人」と呼ばれる扱いを受けていた。1960年代の初め、南アフリカは、日本の製鉄会社と、鉄鉱石などの大規模な輸出の契約を結んだ。日本との経済の"},{"id":"apartheid-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"6発の原爆","l":"apartheid","x":"1993年3月、デクラークは、議会で、驚くべき事実を明らかにした。南アフリカは、ひそかに6発の原子爆弾をつくっていた。そして、それらを、1989年から1991年にかけて、すべて解体"},{"id":"apartheid-t7","k":"voice","f":"src","kj":"史料｜証言","t":"「決して、決して、二度と」――マンデラの大統領就任演説","l":"apartheid","x":"1994年5月10日、プレトリアの政府庁舎の前で、南アフリカで初めての全人種参加の選挙によって選ばれた大統領、ネルソン・マンデラの就任式が行われた。75歳のマンデラは、こう語った。"},{"id":"apartheid-t8","k":"now","f":"now","kj":"いま","t":"ラグビーと南アフリカ","l":"apartheid","x":"1995年、南アフリカで、ラグビーのワールドカップが開かれた。ラグビーは、白人、とくにアフリカーナーのスポーツであり、代表チームの「スプリングボクス」は、黒人たちにとって、アパルト"},{"id":"apartheid-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"apartheid","x":"映画『遠い夜明け』（リチャード・アッテンボロー監督、1987年）：反アパルトヘイトの活動家スティーヴ・ビコと、彼の死の真相を追った白人の新聞記者の友情を描いた映画。映画『インビクタ"},{"id":"arab-conquests-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ウマルの礼拝","l":"arab-conquests","x":"伝承によれば、ソフロニオスは、ウマルを、イエスの墓の上に建つとされる聖墳墓教会に案内した。礼拝の時刻になると、ソフロニオスは、教会の中で礼拝するよう勧めた。しかしウマルは、それを断"},{"id":"arab-conquests-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「ムハンマドは死んだ。しかし、神は生きている」――アブー＝バクルの言葉","l":"arab-conquests","x":"632年6月、預言者ムハンマドがメディナで亡くなったとき、信徒たちは大きな混乱に陥った。勇猛で知られたウマルは、「ムハンマドは死んでいない。モーセのように、神のもとへ行かれただけだ"},{"id":"arab-conquests-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"切り刻まれた「ホスローの春」","l":"arab-conquests","x":"637年、アラブ軍がササン朝の首都クテシフォンを占領した時、宮殿からは、想像を絶する財宝が見つかった。その中に、「ホスローの春」と呼ばれる巨大な絨毯があったと伝えられる。伝承によれ"},{"id":"arab-conquests-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"アレクサンドリア図書館を焼いたのは誰か","l":"arab-conquests","x":"アラブ軍がアレクサンドリアを占領した時、カリフのウマルの命令で、アレクサンドリアの図書館の書物が焼かれたという話がある。伝説によれば、ウマルは、「もし書物が『クルアーン』と同じこと"},{"id":"arab-conquests-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"征服された人々は、アラブ軍を歓迎したのか","l":"arab-conquests","x":"シリアやエジプトの住民の多くは、ビザンツ帝国の正統の教義とは異なる、キリストの神性だけを認める「単性論」の教えを信じるキリスト教徒であった。彼らは、ビザンツ帝国から異端として弾圧さ"},{"id":"arab-conquests-t6","k":"voice","f":"src","kj":"史料｜証言","t":"「ここにいる人々に、生命と財産の安全を与える」――ウマルのエルサレム保証書","l":"arab-conquests","x":"638年、イスラーム軍に包囲されたエルサレムのキリスト教徒たちは、総主教ソフロニオスの指導のもとで、カリフ自身が来るならば、町を明け渡すと申し出た。カリフ・ウマルは、メディナから、"},{"id":"arab-conquests-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"血に染まった『クルアーン』","l":"arab-conquests","x":"伝承によれば、反乱者たちが家に押し入った時、80歳を超えていたウスマーンは、『クルアーン』を読んでいた。ウスマーンは、その場で殺され、その血が『クルアーン』のページに飛び散ったとい"},{"id":"arab-conquests-t8","k":"source","f":"src","kj":"史料｜記録","t":"槍の先の『クルアーン』","l":"arab-conquests","x":"戦いは数か月にわたって続き、アリーの軍が優勢になった。追い詰められたムアーウィヤの軍は、知恵者のアムル・イブン・アル＝アース（エジプトの征服者）の策に従って、兵士たちの槍の先に、『"},{"id":"arab-conquests-t9","k":"now","f":"now","kj":"いま","t":"現代に続く「最初の内乱」","l":"arab-conquests","x":"アリーとムアーウィヤの争いから始まったスンナ派とシーア派の分裂は、1300年以上たった現代の中東の政治にも、大きな影を落としている。シーア派の多いイランと、スンナ派の多いサウジアラ"},{"id":"arab-conquests-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"arab-conquests","x":"バラーズリー『諸国征服史』（花田宇秋訳、岩波書店、全3巻）：9世紀のアラブの歴史家による、アラブの大征服の記録の日本語訳。テレビドラマ『オマル』（Omar）（2012年、MBC・カ"},{"id":"arab-spring-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「ゼンガ・ゼンガ」","l":"arab-spring","x":"チュニジアとエジプトに挟まれたリビアでは、1969年のクーデタから、カダフィが42年にわたって独裁を続けていた。2011年2月、東部の都市ベンガジで反政府の抗議が起こると、カダフィ"},{"id":"arab-spring-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「人々は体制の打倒を望む」","l":"arab-spring","x":"2010年12月17日、チュニジアの地方の町シディ・ブージードで、野菜や果物を売る26歳の青年ムハンマド・ブーアズィーズィーは、許可がないとして、警察に商品と秤を取り上げられた。役"},{"id":"arab-spring-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「フェイスブック革命」だったのか","l":"arab-spring","x":"アラブの春は、「フェイスブック革命」「ツイッター革命」とも呼ばれた。インターネットと交流サイト（SNS）が、抗議の呼びかけや、弾圧の映像の拡散に、大きな役割を果たしたことは確かであ"},{"id":"arab-spring-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"白いヘルメット","l":"arab-spring","x":"空爆で崩れた建物の瓦礫の下から、素手で人々を掘り出す男たちがいた。反体制派の支配地域で活動した民間の救助隊「シリア民間防衛隊」である。彼らは、そのかぶっているヘルメットの色から、「"},{"id":"arab-spring-t5","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"シリアと日本人","l":"arab-spring","x":"2012年8月20日、シリアの北部のアレッポで、日本のジャーナリストの山本美香が、取材中に政府軍の側の銃撃を受けて死亡した。45歳であった。彼女は、アフガニスタンやイラクなどの戦場"},{"id":"arab-spring-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"arab-spring","x":"映画『娘は戦場で生まれた』（2019年）：内戦下のシリアのアレッポで、ジャーナリストの母が、生まれた娘のために撮りためた映像で構成したドキュメンタリー。作品は史実をもとにした創作を"},{"id":"arrow-war-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「夷」と書いてはならない","l":"arrow-war","x":"天津条約は、清と欧米との関係を大きく変える内容を含んでいた。外国の外交官が北京に常駐すること、外国人が中国の内地を旅行できること、キリスト教の布教の自由、長江の沿岸の漢口など新たな"},{"id":"arrow-war-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"2人の盗賊","l":"arrow-war","x":"フランスの作家ヴィクトル・ユゴーは、円明園の焼き討ちを知って、怒りを込めた手紙を書いた（→「19世紀の文化と科学」の回）。原文Il y avait, dans un coin du"},{"id":"arrow-war-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"アメリカに渡った120人の少年","l":"arrow-war","x":"1872年から、清は、10代の少年たちを、4回に分けて合わせて120人、アメリカに留学させた。計画を提案したのは、中国人として初めてアメリカの大学（イェール大学）を卒業した容閎であ"},{"id":"arrow-war-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"石の船","l":"arrow-war","x":"北京の郊外の頤和園の池のほとりには、大理石でできた二階建ての船が浮かんでいる。この「石舫」は、清の衰退の象徴としてよく語られる。画像はオンライン時に表示される（Wikimedia "},{"id":"asian-national-movements-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"「朝鮮人を想ふ」","l":"asian-national-movements","x":"三・一独立運動が鎮圧された直後の1919年5月、日本の思想家で、のちに民芸運動を起こした柳宗悦は、新聞に「朝鮮人を想ふ」という文章を発表した。柳は、朝鮮の陶磁器や工芸の美しさを深く"},{"id":"asian-national-movements-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"中山","l":"asian-national-movements","x":"孫文は、日本に亡命していた時期、東京で、旅館に泊まる際に、近くにあった華族の中山家の表札を見て、「中山樵」という日本名を名乗ったという伝承。この「中山」が、のちに孫文の号として広ま"},{"id":"asian-national-movements-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"大渡河の鉄の鎖の橋","l":"asian-national-movements","x":"長征の中で最も有名な場面の一つが、1935年5月の、大渡河にかかる瀘定橋の戦いである。中国の公式の歴史によれば、敵は橋の床板を外し、川の上には13本の鉄の鎖だけが残されていた。紅軍"},{"id":"asian-national-movements-t4","k":"source","f":"src","kj":"史料｜記録","t":"腕を上げた者は一人もいなかった","l":"asian-national-movements","x":"1930年5月、ガンディーが逮捕された後、詩人のサロージニー・ナーイドゥーらに率いられた2500人の人々が、グジャラート地方のダラサナの製塩所に向かって、非暴力の行進を行った。アメ"},{"id":"asian-national-movements-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"中村屋のボース","l":"asian-national-movements","x":"インドの独立運動家の中には、日本に活路を求めた人々もいた。ラース・ビハーリー・ボースは、1912年、インド総督に爆弾を投げつけた事件の首謀者として、イギリスに追われていた。1915"},{"id":"asian-nationalism-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"パン・イスラーム主義","l":"asian-nationalism","x":"イスラーム世界では、19世紀の後半、ヨーロッパの支配に対抗するために、イスラーム教徒は、国や民族の違いを超えて団結すべきだという思想が生まれた。これを、パン・イスラーム主義 と呼ぶ"},{"id":"asian-nationalism-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"タゴール","l":"asian-nationalism","x":"ベンガル分割に反対する運動の中で、ベンガルの詩人ラビンドラナート・タゴール は、多くの愛国の歌をつくった。その一つ「わが黄金のベンガルよ」は、のちに、東ベンガルが独立して生まれた国"},{"id":"asian-nationalism-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「スワラージは、われわれの生まれながらの権利である」――ティラク","l":"asian-nationalism","x":"1916年、インドの急進派の指導者バール・ガンガーダル・ティラクは、故郷のマハーラーシュトラ地方で、自治を求める運動（自治連盟）を広める演説の中で、こう叫んだ。原文स्वराज्य"},{"id":"asian-nationalism-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"浅羽佐喜太郎の記念碑","l":"asian-nationalism","x":"日本を追われることになったファン・ボイ・チャウを、私財を投げうって助けた日本人がいた。静岡県の医師、浅羽佐喜太郎である。浅羽は、困窮していたベトナム人の留学生たちに、見ず知らずの間"},{"id":"assyria-t1","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"2万通の手紙が語る商人の家族","l":"assyria","x":"キュルテペの遺跡からは、アッシュルの商人たちが残した約2万3000枚の粘土板が見つかっている。その多くが、アナトリアの商人と、アッシュルにいる家族とのあいだでやりとりされた手紙や、"},{"id":"assyria-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"浮き彫りは「宣伝」だった","l":"assyria","x":"アッシリアの王宮の壁は、戦争の場面を描いた浮き彫りで埋め尽くされていた。そこには、攻め落とした町の住民を串刺しにしたり、生きたまま皮をはいだりする、目をそむけたくなるような場面も含"},{"id":"assyria-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"「アッシリア」と「シリア」","l":"assyria","x":"名前がよく似ているので混同しないようにしたい。アッシリアは、メソポタミア北部（現在のイラク北部）を本拠地とした国である。一方、シリアは、地中海の東岸、現在のシリア・レバノン・イスラ"},{"id":"assyria-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「籠の鳥のように」――アッシリアの征服","l":"assyria","x":"アッシリアの王たちは、自らの残虐さを隠さず、むしろ誇らしげに碑文に刻んだ。前9世紀のアッシュルナツィルパル2世は、反乱を起こした町について、こう記している。現代語訳私は、その町の門"},{"id":"assyria-t5","k":"source","f":"src","kj":"史料｜記録","t":"文字を読む王","l":"assyria","x":"アッシリアの王の多くは、自ら文字を読み書きしなかったと考えられている。しかし、アッシュルバニパルは、自分が文字を学んだことを誇りにしていた。私は、賢者アダパの技（書記の技）を学んだ"},{"id":"assyria-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"大洪水の物語を見つけた男","l":"assyria","x":"ニネヴェの遺跡は、19世紀半ばにイギリスのレヤードらによって発掘され、図書館の粘土板はロンドンの大英博物館に運ばれた。1872年、大英博物館で粘土板の整理をしていたジョージ＝スミス"},{"id":"assyria-t7","k":"source","f":"src","kj":"史料｜記録","t":"「流血の町は災いだ」","l":"assyria","x":"アッシリアに苦しめられたユダ王国の預言者ナホムは、ニネヴェの滅亡を、喜びをもって歌っている。原文הוֹי עִיר דָּמִים כֻּלָּהּ כַּחַשׁ פֶּרֶק "},{"id":"assyria-t8","k":"now","f":"now","kj":"いま","t":"破壊された遺跡、生き続ける人々","l":"assyria","x":"2014年、イラク北部のモスルを制圧した過激派組織「イスラム国（IS）」は、2015年に、モスル博物館の像を打ち壊す映像を公開し、さらにアッシリアの都カルフ（ニムルド）の遺跡を爆破"},{"id":"assyria-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"assyria","x":"バイロン「セナケリブの破滅」（詩、1815年）：旧約聖書に記された、アッシリア王センナケリブの軍のエルサレム包囲と、その一夜の壊滅をうたった詩。「アッシリア人は、羊の囲いに襲いかか"},{"id":"athenian-democracy-t1","k":"source","f":"src","kj":"史料｜記録","t":"ソロンの詩――「黒い大地を自由にした」","l":"athenian-democracy","x":"ソロンは、自らの改革を詩に詠んでいる。原文συμμαρτυροίη ταῦτ᾽ ἂν ἐν δίκῃ Χρόνουμήτηρ μεγίστη δαιμόνων Ὀλυμπίωνἄρ"},{"id":"athenian-democracy-t2","k":"confuse","f":"confuse","kj":"混同注意","t":"財産政治の4等級","l":"athenian-democracy","x":"等級年収（穀物などの量）参政権兵役五百メディムノス級500メディムノス以上アルコンなど最高の役職に就ける騎兵・三段櫂船の艤装騎士級300以上アルコンに就ける（のちに）騎兵農民級（ゼ"},{"id":"athenian-democracy-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"僭主は「暴君」ではない","l":"athenian-democracy","x":"「僭主」の原語「テュランノス」は、英語の「タイラント（tyrant、暴君）」の語源である。しかし、古代ギリシアの僭主は、必ずしも暴君ではなかった。「僭主」とは、王の家柄でもなく、正"},{"id":"athenian-democracy-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"僭主殺しの像","l":"athenian-democracy","x":"前514年、ヒッピアスの弟ヒッパルコスを暗殺したのは、ハルモディオスとアリストゲイトンという二人の若者であった。動機は政治的なものではなく、ヒッパルコスがハルモディオスに言い寄って"},{"id":"athenian-democracy-t5","k":"source","f":"src","kj":"史料｜記録","t":"字の書けない市民とアリステイデス","l":"athenian-democracy","x":"陶片追放には、次のような逸話が伝えられている。前482年の陶片追放のとき、字の書けない一人の農民が、近くにいた男に陶片を渡し、「アリステイデス」と書いてくれと頼んだ。男が「アリステ"},{"id":"athenian-democracy-t6","k":"now","f":"now","kj":"いま","t":"陶片は今も残っている","l":"athenian-democracy","x":"陶片追放の投票に使われた陶片（オストラコン）は、アテネのアゴラやケラメイコス地区の発掘で、これまでに1万枚以上見つかっている。そこには、テミストクレス、アリステイデス、ペリクレス、"},{"id":"athenian-democracy-t7","k":"confuse","f":"confuse","kj":"混同注意","t":"「陶片追放」の名前と目的","l":"athenian-democracy","x":"陶片追放は「貝殻追放」と訳されることもあるが、実際に使われたのは貝殻ではなく、割れた陶器のかけらである（ギリシア語の「オストラコン」には貝殻の意味もあったため、誤訳が広まった）。ま"},{"id":"athenian-democracy-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"athenian-democracy","x":"アリストファネス『女の議会』（喜劇、前392年ごろ）：アテネの女たちが男装して民会に乗り込み、政権を握ってしまう喜劇。当時の民会の様子や、市民たちの日当への関心がうかがえる。作品は"},{"id":"athens-sparta-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"ヘイロータイ・ペリオイコイ・奴隷","l":"athens-sparta","x":"ヘイロータイ：スパルタの国家が所有する隷属農民。個人の市民が売買することはできず、家族をもち、土地に縛りつけられていた。農奴に近い存在である。ペリオイコイ：スパルタの周辺に住む自由"},{"id":"athens-sparta-t2","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"スパルタの少年の一生","l":"athens-sparta","x":"プルタルコスの『リュクルゴス伝』などによれば、スパルタの男子の一生は次のようだった伝承。生まれると、長老たちが赤ん坊を調べ、弱々しい子は山中の谷間に捨てられたという（ただし、これを"},{"id":"athens-sparta-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「もしも」――ラコニア式の簡潔さ","l":"athens-sparta","x":"スパルタ人は無駄な言葉を嫌い、短く鋭い言い回しを好んだ。スパルタのあるラコニア地方の名から、英語で簡潔な物言いを「ラコニック（laconic）」という。伝えられるところでは、のちに"},{"id":"athens-sparta-t4","k":"source","f":"src","kj":"史料｜記録","t":"「盾とともに、さもなくば盾の上で」","l":"athens-sparta","x":"戦いに向かう息子に、スパルタの母親は盾を手渡しながら、こう言ったと伝えられる伝承。原文ἢ τὰν ἢ ἐπὶ τᾶς.現代語訳これ（盾）とともに帰れ。さもなくば、これの上に（乗せら"},{"id":"athens-sparta-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"スパルタは本当に「軍国主義の理想郷」だったか","l":"athens-sparta","x":"スパルタの制度は、のちの時代にくり返し理想化された。プラトンは理想国家の構想にスパルタを参考にし、近代ヨーロッパでも、スパルタの質実剛健さや愛国心はたたえられた。20世紀には、ナチ"},{"id":"athens-sparta-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"athens-sparta","x":"映画『300（スリーハンドレッド）』（2007年）：テルモピュライで戦ったスパルタ王レオニダスと300人の兵士を描いた映画。スパルタの少年教育の厳しさも描かれるが、全体は誇張と創作"},{"id":"atlantic-slave-trade-t1","k":"voice","f":"src","kj":"史料｜証言","t":"ゾング号事件","l":"atlantic-slave-trade","x":"1781年、イギリスの奴隷船ゾング号は、西アフリカからジャマイカに向かう途中で、航路を誤り、飲み水が不足した。船長は、病気の奴隷たちを、生きたまま海に投げ込むよう命じた。3日間で、"},{"id":"atlantic-slave-trade-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「屠殺場のようであった」――奴隷船の船医の証言","l":"atlantic-slave-trade","x":"イギリスの船医アレクサンダー・ファルコンブリッジは、1780年代に4度、奴隷船に乗り組んだ。のちに奴隷貿易の廃止運動に加わった彼は、船の中のありさまを、こう証言した。原文…… Th"},{"id":"atlantic-slave-trade-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"奴隷貿易は産業革命を生んだのか","l":"atlantic-slave-trade","x":"1944年、トリニダード出身の歴史家エリック・ウィリアムズ（のちのトリニダード・トバゴの初代首相）は、『資本主義と奴隷制』を著し、奴隷貿易とカリブ海のプランテーションが生み出した莫"},{"id":"atlantic-slave-trade-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「アメイジング・グレイス」を書いた奴隷船の船長","l":"atlantic-slave-trade","x":"世界中で歌われている讃美歌「アメイジング・グレイス」を作詞したジョン・ニュートンは、若いころ、奴隷船の船長であった。彼は、航海中の嵐で死にかけた体験をきっかけに信仰に目覚めたが、そ"},{"id":"atlantic-slave-trade-t5","k":"now","f":"now","kj":"いま","t":"日本に来たアフリカの人々","l":"atlantic-slave-trade","x":"大航海時代、ポルトガル人とともに、アフリカの人々も日本にやって来た。1581年、イエズス会の宣教師ヴァリニャーノに従って京都にやって来たアフリカ出身の従者は、織田信長に気に入られ、"},{"id":"atlantic-slave-trade-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"atlantic-slave-trade","x":"映画『アミスタッド』（スティーヴン・スピルバーグ監督、1997年）：1839年、奴隷船アミスタッド号の上で反乱を起こしたアフリカの人々が、アメリカの法廷で自由を求めて争った実話を描"},{"id":"atomic-bomb-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"勲章を受けた将軍","l":"atomic-bomb","x":"戦後の1964年、日本政府は、カーチス・ルメイに、勲一等旭日大綬章を贈った。航空自衛隊の創設に協力した、というのがその理由であった。東京大空襲の指揮官に勲章を贈ることには、当時から"},{"id":"atomic-bomb-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「偏奇館焼亡す」――東京大空襲","l":"atomic-bomb","x":"1945年3月10日未明、約300機のB29爆撃機が、東京の下町に焼夷弾を投下した。強い北風にあおられて、火は燃え広がり、一夜のうちに約10万人が亡くなった。東京の麻布の自宅「偏奇"},{"id":"atomic-bomb-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「やらせ」だったのか？","l":"atomic-bomb","x":"摺鉢山の頂上に星条旗を立てる海兵隊員たちの写真は、ピュリツァー賞を受け、アメリカの戦意を大いに高めた。のちに、この場面を写した巨大な銅像がワシントンの郊外に建てられた。画像はオンラ"},{"id":"atomic-bomb-t4","k":"voice","f":"src","kj":"史料｜証言","t":"沖縄県民斯ク戦ヘリ","l":"atomic-bomb","x":"6月6日、那覇の南の小禄で、アメリカ軍に包囲された海軍の沖縄方面根拠地隊の司令官、大田実少将は、海軍次官にあてて、長い電報を打った。電報は、本来は県知事が報告すべき沖縄の県民の様子"},{"id":"atomic-bomb-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"日本の原爆研究","l":"atomic-bomb","x":"日本でも、原子爆弾の研究は行われていた。陸軍は、理化学研究所の仁科芳雄に研究を依頼し（仁科の頭文字から「ニ号研究」と呼ばれた）、海軍は、京都帝国大学の荒勝文策に研究を依頼した（「F"},{"id":"atomic-bomb-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"京都はなぜ外されたのか","l":"atomic-bomb","x":"原爆の投下目標の候補地には、はじめ、京都が含まれていた。京都は、大きな工業都市であり、周囲を山に囲まれた盆地にあって、爆弾の効果を測るのに適しているとされたのである。また、目標の候"},{"id":"atomic-bomb-t7","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"石に残った影","l":"atomic-bomb","x":"原爆の熱線は、人や物の「影」を、その場所に焼きつけた。銀行の入口の石段に腰かけて開店を待っていた人は、強烈な熱線を浴びて亡くなり、石段には、その人の影の部分だけが、黒く残った。この"},{"id":"atomic-bomb-t8","k":"voice","f":"src","kj":"史料｜証言","t":"「ちちをかえせ ははをかえせ」――峠三吉","l":"atomic-bomb","x":"広島で被爆した詩人峠三吉は、1951年、『原爆詩集』を出した。その序にあたる詩は、こう始まる。原文ちちをかえせ ははをかえせとしよりをかえせこどもをかえせわたしをかえせ わたしにつ"},{"id":"atomic-bomb-t9","k":"person","f":"deep","kj":"深掘り｜人物","t":"二度被爆した男","l":"atomic-bomb","x":"長崎の三菱重工業の造船所の技師、山口彊は、1945年8月、出張で広島に来ていた。8月6日の朝、出張の最終日に、造船所に向かう途中で、彼は、爆心地から約3キロメートルの地点で被爆した"},{"id":"atomic-bomb-t10","k":"voice","f":"src","kj":"史料｜証言","t":"原民喜「コレガ人間ナノデス」","l":"atomic-bomb","x":"広島で被爆した作家原民喜は、被爆直後の広島を描いた小説「夏の花」（1947年）や、カタカナで書かれた詩を残した。原文コレガ人間ナノデス原子爆弾ニ依ル変化ヲゴラン下サイ肉体ガ恐ロシク"},{"id":"atomic-bomb-t11","k":"person","f":"deep","kj":"深掘り｜人物","t":"二度、被爆した人――山口彊","l":"atomic-bomb","x":"長崎の三菱重工業の造船所の技師であった山口彊は、1945年8月、出張で広島に来ていた。8月6日の朝、彼は、爆心地から約3kmの場所で被爆し、顔や腕に大やけどを負った。翌日、彼は、壊"},{"id":"atomic-bomb-t12","k":"person","f":"deep","kj":"深掘り｜人物","t":"29年間、戦い続けた少尉――小野田寛郎","l":"atomic-bomb","x":"戦争が終わったことを知らずに、あるいは信じずに、戦い続けた日本兵もいた。陸軍の少尉の小野田寛郎は、1944年、フィリピンのルバング島に送られ、ゲリラ戦を続けるよう命じられた。終戦の"},{"id":"atomic-bomb-t13","k":"trivia","f":"side","kj":"こぼれ話","t":"ミズーリ号に掲げられた旗","l":"atomic-bomb","x":"調印式の会場となったミズーリ号の甲板には、額に入れられた、1枚の古い星条旗が飾られていた。1853年から翌年にかけて、ペリーが黒船を率いて日本に来航し、開国を迫った時に、艦隊に掲げ"},{"id":"atomic-bomb-t14","k":"view","f":"think","kj":"考える｜別の視点","t":"原爆の投下は必要だったのか","l":"atomic-bomb","x":"原爆の投下が必要であったのかどうかは、今も、日本とアメリカの間で、そして歴史家の間で、激しく議論されている問題である。アメリカでは、長く、「原爆が戦争を早く終わらせ、日本本土への上"},{"id":"atomic-bomb-t15","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"atomic-bomb","x":"中沢啓治『はだしのゲン』（漫画、1973〜1987年）：自らの被爆体験をもとに、広島で被爆した少年ゲンが、戦後の焼け跡を生き抜く姿を描いた漫画。多くの言語に翻訳されている。井伏鱒二"},{"id":"ayyubid-mamluk-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"シャジャル・アッドゥッルの最期","l":"ayyubid-mamluk","x":"アイバクと結婚した後も、シャジャル・アッドゥッルは、実権を手放そうとはしなかった。1257年、アイバクが、別の王家の娘を新しい妃に迎えようとしたとき、彼女は、浴場でアイバクを殺させ"},{"id":"ayyubid-mamluk-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"片目に傷のある奴隷","l":"ayyubid-mamluk","x":"バイバルス（1223ごろ〜1277年）は、キプチャク草原のトルコ人であった。少年のころ、モンゴルの侵入から逃れる途中で捕らえられ、アナトリアのスィヴァスの奴隷市場で売られた。彼は背"},{"id":"ayyubid-mamluk-t3","k":"source","f":"src","kj":"史料｜記録","t":"アンティオキア攻略を知らせる手紙","l":"ayyubid-mamluk","x":"1268年、バイバルスは、アンティオキアを攻め落とした後、町の領主で、そのときトリポリにいたボエモン6世に、次のような手紙を送った。もしおまえが、わが軍の騎兵がおまえの騎士たちを馬"},{"id":"ayyubid-mamluk-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"ayyubid-mamluk","x":"映画『キングダム・オブ・ヘブン』（リドリー・スコット監督、2005年）：1187年のヒッティーンの戦いと、サラーフ・アッディーンによるエルサレムの奪回を描いた映画。サラーフ・アッデ"},{"id":"aztec-t1","k":"source","f":"src","kj":"史料｜記録","t":"トラテロルコの大市場","l":"aztec","x":"テノチティトランの北のトラテロルコには、巨大な市場があった。コルテスは、スペイン王カルロス1世にあてた手紙の中で、その市場のようすを、こう書いている。原文…… tiene otra"},{"id":"aztec-t2","k":"now","f":"now","kj":"いま","t":"頭蓋骨の塔の発見","l":"aztec","x":"スペイン人の記録には、大神殿の前に、生贄にされた人々の頭蓋骨を並べた巨大な棚（ツォンパントリ）があったと書かれている。長い間、これは征服者たちの誇張ではないかとも考えられてきた。2"},{"id":"aztec-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ケツァルコアトルの帰還？","l":"aztec","x":"なぜ、モクテスマは、侵入者たちを都に迎え入れたのか。よく知られている説明は、次のようなものである。アステカには、白い肌でひげを生やした神ケツァルコアトルが、いつか東の海から戻ってく"},{"id":"aztec-t4","k":"voice","f":"src","kj":"史料｜証言","t":"トシュカトルの祭りの虐殺（1520年）","l":"aztec","x":"1520年5月、コルテスが都を離れている間に、留守を預かったアルバラードは、大神殿の広場で祭りを祝っていたアステカの貴族や戦士たちを襲った。のちにアステカの人々の証言をもとにまとめ"},{"id":"bandung-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"バンドンの日本代表","l":"bandung","x":"日本は、アジア・アフリカ会議に参加した29か国の一つであった。日本の代表団を率いたのは、経済審議庁長官の高碕達之助であった。戦後10年、まだ国際連合にも加盟していなかった日本にとっ"},{"id":"bandung-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"スカルノの日本人の妻","l":"bandung","x":"インドネシアのスカルノ大統領の夫人の一人は、日本人であった。根本七保子である。七保子は、1959年、来日したスカルノと、東京の帝国ホテルで出会った。日本からインドネシアへの戦争の賠"},{"id":"barbarossa-t1","k":"music","f":"music","kj":"音楽","t":"「聖なる戦い」","l":"barbarossa","x":"開戦から2日後の1941年6月24日、ソ連の新聞に、詩人レーベジェフ＝クマーチの詩「聖なる戦い」が掲載された。「起て、巨大な国よ、死をかけた戦いに起て」。赤軍の歌と踊りのアンサンブ"},{"id":"barbarossa-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「2日間で3万3771人」――バビ・ヤール","l":"barbarossa","x":"独ソ戦が始まると、ドイツ軍の後を追って、親衛隊の「行動部隊（アインザッツグルッペン）」が占領地に入り、ユダヤ人や共産党員を銃殺していった。1941年9月、ドイツ軍がウクライナのキー"},{"id":"barbarossa-t3","k":"voice","f":"src","kj":"史料｜証言","t":"ターニャの日記","l":"barbarossa","x":"レニングラードの11歳の少女、ターニャ・サヴィチェワは、包囲の冬、姉が使っていた小さな手帳に、短い記録を書き残した。画像はオンライン時に表示される（Wikimedia Common"},{"id":"barbarossa-t4","k":"music","f":"music","kj":"音楽","t":"交響曲第7番「レニングラード」","l":"barbarossa","x":"ショスタコーヴィチの交響曲第7番は、1942年3月、疎開先のクイビシェフで初演され、楽譜はマイクロフィルムに写されてアメリカにも運ばれた。そして8月9日、包囲されたレニングラードで"},{"id":"barbarossa-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"北か、南か","l":"barbarossa","x":"独ソ戦の始まりは、日本にとっても、重大な選択の時であった。その2か月前の1941年4月、外相の松岡洋右は、モスクワで、ソ連と 日ソ中立条約 を結んでいた。帰国する松岡を、スターリン"},{"id":"barbarossa-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"狙撃兵の決闘","l":"barbarossa","x":"スターリングラードの廃墟の戦いでは、狙撃兵が大きな役割を果たした。中でも、ウラル地方の羊飼いの出身の狙撃兵ヴァシーリー・ザイツェフは、200人を超えるドイツ兵を倒したとされ、ソ連の"},{"id":"barbarossa-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"barbarossa","x":"スヴェトラーナ・アレクシエーヴィチ『戦争は女の顔をしていない』（1985年）：独ソ戦に従軍したソ連の女性たち500人以上から聞き取った証言を集めた本。作者は2015年にノーベル文学"},{"id":"bismarck-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ビスマルクの名を残したもの","l":"bismarck","x":"ビスマルクの名は、さまざまなところに残っている。ドイツでは、酢漬けのニシン「ビスマルク・ヘリング」が、今も人気の料理である。ビスマルク自身がニシンを好んだという話から名づけられたと"},{"id":"black-death-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"「黒死病」と呼んだのは後の時代の人々","l":"black-death","x":"当時の人々はこの病気を「黒死病」とは呼んでいない。ヨーロッパの記録では「大いなる死」「疫病」「悪疫」などと書かれた。「黒死病」という呼び名が定着するのは、16〜17世紀以降のことで"},{"id":"black-death-t2","k":"term","f":"deep","kj":"深掘り｜ことば","t":"ペストの三つのかたち","l":"black-death","x":"ペストには主に三つの病型がある。腺ペスト：ノミに刺されたところから菌が入り、近くのリンパ節が鶏卵ほどに腫れ上がる。わきの下や足の付け根の腫れが特徴で、当時の記録にもくり返し出てくる"},{"id":"black-death-t3","k":"voice","f":"src","kj":"史料｜証言","t":"死体を投げ込んだ？――ガブリエーレ・デ・ムッシの記録","l":"black-death","x":"イタリアのピアチェンツァの公証人ガブリエーレ・デ・ムッシは、この包囲の様子を次のように書いている。「タタール人の軍勢は病に打ちのめされ、日ごとに何千人もが死んでいった。……彼らは死"},{"id":"black-death-t4","k":"voice","f":"src","kj":"史料｜証言","t":"『デカメロン』序文――家族が家族を見捨てた","l":"black-death","x":"原文che l'uno fratello l'altro abbandonava e il zio il nipote e la sorella il fratello e spe"},{"id":"black-death-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「私は5人の子を自分の手で埋めた」――シエナの年代記","l":"black-death","x":"フィレンツェの南の町シエナでは、靴職人で徴税人でもあったアーニョロ・ディ・トゥーラが、町の年代記を書いていた。1348年の項で、彼は流行のありさまを記したあと、ふいに自分のことを書"},{"id":"black-death-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"ペトラルカとラウラ","l":"black-death","x":"イタリアの詩人ペトラルカは、若いころに見初めた女性ラウラへの愛を、生涯にわたって詩に歌い続けた。そのラウラは、1348年4月6日、アヴィニョンで亡くなった。ペストだったと考えられて"},{"id":"black-death-t7","k":"view","f":"think","kj":"考える｜別の視点","t":"大旅行家イブン＝バットゥータが見たダマスクス","l":"black-death","x":"モロッコ出身の旅行家イブン＝バットゥータは、1348年、旅の帰り道でダマスクスに立ち寄り、ペストの流行に出会った。彼によれば、町の人々は3日間の断食を行い、そのあと、ムスリムもユダ"},{"id":"black-death-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"病気は「うつる」のか――イスラームの学者たちの論争","l":"black-death","x":"イスラーム世界では、預言者ムハンマドの言葉として「伝染というものはない」とする伝承があり、病気は神の定めによるものだとする考え方が有力だった。これに対して、グラナダの医師で政治家で"},{"id":"black-death-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"王女の死と教皇の「火」","l":"black-death","x":"1348年、イングランド王エドワード3世の娘ジョーンは、カスティリャの王子との結婚のためスペインへ向かう途中、フランスのボルドーでペストにかかって亡くなった。王家の人間も逃れられな"},{"id":"black-death-t10","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"当時の人々は原因をどう考えたか","l":"black-death","x":"1348年、パリ大学の医学部はフランス王の求めに応じて、流行の原因についての報告書をまとめた。それによれば、1345年3月に土星・木星・火星が水瓶座で会合したことで大気が汚れ、その"},{"id":"black-death-t11","k":"voice","f":"src","kj":"史料｜証言","t":"ストラスブールの虐殺","l":"black-death","x":"1349年2月14日、ドイツ南西部のストラスブールでは、町の参事会がユダヤ人を捕らえ、ユダヤ人墓地に作った木の小屋に閉じ込めて火を放った。この町の年代記作者ケーニヒスホーフェンは、"},{"id":"black-death-t12","k":"trivia","f":"side","kj":"こぼれ話","t":"「死の舞踏」","l":"black-death","x":"黒死病のあと、ヨーロッパの教会や墓地の壁には、骸骨の姿をした「死」が、教皇や皇帝、騎士、商人、農民、子どもの手を取って踊る絵が描かれるようになった。「死の舞踏」である。身分の高い者"},{"id":"black-death-t13","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"くちばしのマスクの医者は14世紀にはいなかった","l":"black-death","x":"ペストというと、鳥のくちばしのようなマスクをつけ、長いコートを着た医者の姿がよく描かれる。しかし、この服装は17世紀のフランスやイタリアで考案されたもので、14世紀の黒死病の時代に"},{"id":"black-death-t14","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ネズミのせいか、人のせいか","l":"black-death","x":"ペストは、クマネズミについたノミが人を刺すことで広がる、と長く説明されてきた。しかし、14世紀の流行の速さや、北欧のようにネズミの少ない地域でも大流行したことを、ネズミとノミだけで"},{"id":"black-death-t15","k":"trivia","f":"side","kj":"こぼれ話","t":"「検疫」の始まり","l":"black-death","x":"感染症の流行地から来た船や人を一定期間とどめておく「検疫」の制度は、黒死病の後にイタリアやアドリア海の港町で始まった。1377年、ドゥブロヴニク（当時のラグーザ）は、流行地から来た"},{"id":"black-death-t16","k":"now","f":"now","kj":"いま","t":"歴史の中の感染症と現代","l":"black-death","x":"2020年からの新型コロナウイルス感染症の世界的な流行のなかで、黒死病の時代の記録は改めて注目された。外出を控える人と出歩く人、流行を特定の集団のせいにしようとする動き、人手不足と"},{"id":"black-death-t17","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"black-death","x":"ボッカッチョ『デカメロン』（1349〜1353年ごろ）：ペストの流行するフィレンツェを逃れた10人の男女が、郊外の別荘で、10日間にわたって100の物語を語り合う。冒頭には、ペスト"},{"id":"boxer-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"1997年7月1日","l":"boxer","x":"イギリスが九竜半島の北部（新界）を租借したのは、1898年7月1日のことで、その期限は99年であった。99年後の1997年7月1日、イギリスは、新界だけでなく、アヘン戦争と北京条約"},{"id":"boxer-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"北京にいた伊藤博文","l":"boxer","x":"戊戌の政変のちょうどその時、北京には、首相を辞めたばかりの伊藤博文が訪れていた。9月20日、伊藤は、光緒帝に謁見している。政変の前日である。改革派の中には、伊藤を清の顧問として迎え"},{"id":"boxer-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"柴五郎","l":"boxer","x":"籠城戦で、各国の人々から最も称賛されたのは、日本の公使館の駐在武官、陸軍中佐の柴五郎であった。わずか25人ほどの日本兵と義勇兵を率いて、2800人の中国人キリスト教徒が避難した粛親"},{"id":"boxer-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"読まれた自分の死亡記事","l":"boxer","x":"籠城の間、北京との連絡は途絶え、外の世界には、さまざまな噂が流れた。1900年7月、イギリスの新聞『タイムズ』は、公使館は陥落し、中にいた外国人は皆殺しにされたという誤った報道に基"},{"id":"boxer-t5","k":"source","f":"src","kj":"史料｜記録","t":"ヴィルヘルム2世の「フン族演説」","l":"boxer","x":"ドイツは、殺された公使の報復のため、大軍を中国に送った。1900年7月27日、ドイツの北海の港ブレーマーハーフェンで、皇帝ヴィルヘルム2世は、出発する兵士たちにこう演説した。原文P"},{"id":"boxer-t6","k":"now","f":"now","kj":"いま","t":"盧溝橋への道","l":"boxer","x":"北京議定書によって、日本も、北京から天津にかけての地域に軍隊を置く権利を得た。この部隊は、のちに「支那駐屯軍」と呼ばれるようになる。36年後の1937年7月、北京の郊外の盧溝橋の近"},{"id":"boxer-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"boxer","x":"浅田次郎『蒼穹の昴』（小説、1996年）：貧しい少年春児が宦官となって西太后に仕え、その幼なじみの梁文秀が光緒帝の改革（戊戌の変法）に加わる。清の末期の宮廷と改革の挫折を描いた長編"},{"id":"british-reforms-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「保守するために、改革せよ」――マコーリーの演説","l":"british-reforms","x":"第1回選挙法改正の法案が議会で激しく争われていた1831年3月、ホイッグ党の若い議員で、のちに『イングランド史』を書く歴史家となるマコーリーは、下院で、改革に反対する人々に向けて、"},{"id":"british-reforms-t2","k":"now","f":"now","kj":"いま","t":"2015年まで払い続けた「補償金」","l":"british-reforms","x":"奴隷制の廃止にあたって、イギリス政府は、「財産」を失う奴隷の所有者たちに、2000万ポンドという巨額の補償金を支払った。当時の政府の年間支出の約4割に当たる額であった。一方、自由に"},{"id":"british-reforms-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"1ペニーの革命","l":"british-reforms","x":"1840年5月、イギリスで、世界で最初の郵便切手「ペニー・ブラック」が発行された。それまで、郵便料金は、距離と紙の枚数によって決まり、しかも受け取る側が支払う仕組みで、たいへん高か"},{"id":"british-reforms-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「藁の上の6体の骸骨」――ジャガイモ飢饉","l":"british-reforms","x":"1846年12月、アイルランド南部のコークの治安判事ニコラス・カミンズは、スキバリーンの村を訪れた。彼は、イギリスのウェリントン公に宛てた手紙を『タイムズ』に公開し、目にした光景を"},{"id":"british-reforms-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"なぜイギリスでは革命が起こらなかったのか","l":"british-reforms","x":"1830年と1848年、ヨーロッパの大陸では革命の嵐が吹き荒れたが、イギリスでは革命は起こらなかった。その理由については、さまざまな説明がなされている。議会という、不満を政治の場に"},{"id":"british-reforms-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"british-reforms","x":"ディケンズ『オリバー・ツイスト』（小説、1837〜1839年）：救貧院で生まれた孤児オリバーが、ロンドンの犯罪の世界に巻き込まれる物語。1834年の新救貧法の非人間的な救貧院を、痛"},{"id":"byzantine-decline-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「サラセン人のほうが、まだ慈悲深かった」――1204年","l":"byzantine-decline","x":"1204年4月、第4回十字軍はコンスタンティノープルを攻め落とし、3日間にわたって略奪した。ビザンツの高官で歴史家のニケタス・コニアテスは、その場に居合わせ、家族とともに町を逃れた"},{"id":"byzantine-decline-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"ロンドンでクリスマスを過ごした皇帝","l":"byzantine-decline","x":"14世紀の末、ビザンツ帝国は、オスマン帝国に領土のほとんどを奪われ、コンスタンティノープルとその周辺だけの小国となっていた。1399年、皇帝マヌエル2世は、西ヨーロッパの君主たちに"},{"id":"byzantine-society-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"東西の「兵農一致」","l":"byzantine-society","x":"国家が農民に土地を与え、その代わりに兵役を課すしくみは、同じころの東アジアにも見られた。中国の北魏から唐にかけての均田制と府兵制である（→「律令体制と唐の制度」の回）。ビザンツ帝国"},{"id":"byzantine-society-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"三重の城壁","l":"byzantine-society","x":"ギリシアの火とともにコンスタンティノープルを守ったのが、5世紀前半のテオドシウス2世の時代に築かれた、陸側の「テオドシウスの城壁」である。城壁は、幅約20mの堀、低い外壁、そして高"},{"id":"byzantine-society-t3","k":"source","f":"src","kj":"史料｜記録","t":"聖像を擁護する神学者","l":"byzantine-society","x":"原文Οὐ προσκυνῶ τῇ ὕλῃ, προσκυνῶ δὲ τὸν τῆς ὕλης δημιουργόν, τὸν ὕλην δι᾽ ἐμὲ γενόμενον …… Π"},{"id":"byzantine-society-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「紫の生まれ」","l":"byzantine-society","x":"ビザンツの皇宮には、壁を紫色の斑岩で張りつめた「紫の間（ポルフュラ）」と呼ばれる部屋があった。在位中の皇帝の子どもは、この部屋で生まれた。そのような皇子・皇女は、「紫の生まれ（ポル"},{"id":"byzantine-society-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「吠えるライオン、さえずる鳥、宙に昇る玉座」――リウトプランドの見た皇帝","l":"byzantine-society","x":"949年、北イタリアの王の使節として、コンスタンティノープルの宮廷を訪れたクレモナのリウトプランドは、皇帝コンスタンティノス7世に謁見したときの驚きを、ラテン語で書き残している。現"},{"id":"byzantine-society-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「ブルガリア人殺し」","l":"byzantine-society","x":"バシレイオス2世は、「ブルガロクトノス（ブルガリア人殺し）」と呼ばれる。12世紀の歴史家スキュリツェスによれば、1014年のクレイディオンの戦いの後、バシレイオス2世は、捕虜にした"},{"id":"byzantine-society-t7","k":"person","f":"deep","kj":"深掘り｜人物","t":"二人の女帝――ゾエとテオドラ","l":"byzantine-society","x":"バシレイオス2世には子がなく、帝位は弟のコンスタンティノス8世を経て、その娘ゾエに受け継がれた。ゾエは、次々に3人の夫を皇帝に迎え、さらに養子を皇帝とした。1042年、その養子の皇"},{"id":"byzantine-society-t8","k":"now","f":"now","kj":"いま","t":"正教会の分裂とウクライナ","l":"byzantine-society","x":"東方正教会は、ローマ教皇のような単一の首長をもたず、国ごとに独立した教会が並び立っている。その中で、コンスタンティノープル（イスタンブル）の総主教は、「同等の者の中の第一人者」とし"},{"id":"byzantine-society-t9","k":"works","f":"works","kj":"作品","t":"ビザンツ帝国にまつわる作品","l":"byzantine-society","x":"『ディゲネス・アクリタス』（12世紀ごろ）：アラブ人の父とビザンツ人の母をもつ英雄ディゲネスが、帝国の東の国境地帯で活躍する叙事詩。キリスト教徒とイスラーム教徒が戦いながらも交わり"},{"id":"caesar-augustus-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"海賊に身代金を値上げさせた男","l":"caesar-augustus","x":"若いころ、カエサルは留学のため船で東方に向かう途中、海賊に捕まった。海賊が身代金として20タラントンを要求すると、カエサルは笑って「自分にはそんな安い値段はつかない」と言い、50タ"},{"id":"caesar-augustus-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"アレクサンドロスの像の前で泣いた","l":"caesar-augustus","x":"スエトニウスによれば、30代の初め、ヒスパニア（スペイン）に赴任していたカエサルは、ガデス（現カディス）の神殿でアレクサンドロス大王の像を見て、ため息をついたという。大王が世界を征"},{"id":"caesar-augustus-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"第1回と第2回の三頭政治の違い","l":"caesar-augustus","x":"第1回三頭政治（前60年）は、三人の非公式な盟約にすぎなかった。これに対して第2回三頭政治（前43年）は、民会で法律を通して作られた、5年任期の正式な国家機関である。名前は同じでも"},{"id":"caesar-augustus-t4","k":"source","f":"src","kj":"史料｜記録","t":"『ガリア戦記』の書き出し","l":"caesar-augustus","x":"原文Gallia est omnis divisa in partes tres, quarum unam incolunt Belgae, aliam Aquitani, ter"},{"id":"caesar-augustus-t5","k":"war","f":"deep","kj":"深掘り｜戦術","t":"アレシアの二重の包囲線","l":"caesar-augustus","x":"カエサルは、アレシアを力ずくで攻め落とそうとはしなかった。町の周りをぐるりと囲む防御線を築き、兵糧攻めにしたのである。カエサル自身の記録によれば、内側の包囲線は全長11ローマ・マイ"},{"id":"caesar-augustus-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ガリア遠征の犠牲はどれほどだったのか","l":"caesar-augustus","x":"古代の著述家プリニウスは、カエサルが生涯の戦いで敵を119万2000人殺したと記している。プルタルコスは、ガリア遠征だけで100万人を殺し、100万人を捕虜にしたとする。いずれも正"},{"id":"caesar-augustus-t7","k":"voice","f":"src","kj":"史料｜証言","t":"「老人も、女も、幼な子も」――ガリア征服","l":"caesar-augustus","x":"前52年、カエサルの軍は、ガリアの町アウァリクム（現在のブールジュ）を攻め落とした。カエサルは、自らの戦記に、こう書いている。原文Sic et caede et labore in"},{"id":"caesar-augustus-t8","k":"source","f":"src","kj":"史料｜記録","t":"「賽は投げられた」","l":"caesar-augustus","x":"スエトニウスによれば、ルビコン川の前でカエサルはしばらく迷ったのち、こう言ったという。原文Eatur quo deorum ostenta et inimicorum iniqui"},{"id":"caesar-augustus-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"寝具の袋に入って現れた女王","l":"caesar-augustus","x":"プルタルコスによれば、弟の側の兵に阻まれてカエサルに会えなかったクレオパトラは、寝具を包む袋に身を隠し、召使いに担がせて宮殿に入り込んだ。袋から現れたクレオパトラの機知に、カエサル"},{"id":"caesar-augustus-t10","k":"trivia","f":"side","kj":"こぼれ話","t":"445日あった1年","l":"caesar-augustus","x":"当時のローマの暦は、1年が355日しかなく、ずれを直すために、神官たちがときどき「閏月」を差し込んでいた。ところが、この閏月の扱いが政治の駆け引きに使われ、いいかげんになっていた。"},{"id":"caesar-augustus-t11","k":"confuse","f":"confuse","kj":"混同注意","t":"7月・8月はカエサルとアウグストゥス、では10月は？","l":"caesar-augustus","x":"カエサルの死後の前44年、彼の生まれ月だった「5番目の月（クインティリス）」は、「ユリウスの月（ユリウス）」に改められた。これが英語のJulyである。前8年には、「6番目の月（セク"},{"id":"caesar-augustus-t12","k":"source","f":"src","kj":"史料｜記録","t":"なぜ8月が「アウグストゥスの月」になったのか","l":"caesar-augustus","x":"5世紀の著述家マクロビウスは、8月の名を改めたときの元老院決議を伝えている。それによると、アウグストゥスはこの月に初めてコンスルに就任し、三度の凱旋式を行い、エジプトをローマの支配"},{"id":"caesar-augustus-t13","k":"trivia","f":"side","kj":"こぼれ話","t":"月桂冠で薄い髪を隠した？","l":"caesar-augustus","x":"スエトニウスによれば、カエサルは薄くなった頭髪をひどく気にしていた。頭頂の髪を前にとかしつけ、元老院から常に月桂冠をかぶる許可を与えられたことを、何よりも喜んだという。ガリア遠征の"},{"id":"caesar-augustus-t14","k":"source","f":"src","kj":"史料｜記録","t":"「ブルートゥス、お前もか」は本当か","l":"caesar-augustus","x":"スエトニウスは、暗殺の場面をこう書いている。原文atque ita tribus et viginti plagis confossus est uno modo ad primu"},{"id":"caesar-augustus-t15","k":"trivia","f":"side","kj":"こぼれ話","t":"「3月15日は来たが、まだ過ぎてはいない」","l":"caesar-augustus","x":"占い師スプリンナは、以前からカエサルに「3月15日まで危険に気をつけよ」と警告していたという。当日の朝、議場に向かう途中でスプリンナに会ったカエサルは、「3月15日は来たではないか"},{"id":"caesar-augustus-t16","k":"debate","f":"think","kj":"考える｜諸説あり","t":"クレオパトラは「逃げた」のか","l":"caesar-augustus","x":"古代の史料は、クレオパトラが臆病風に吹かれて逃げ出し、恋に溺れたアントニウスがそれを追った、という筋書きで描いている。しかし、これは勝者であるオクタウィアヌスの側が作った物語の色が"},{"id":"caesar-augustus-t17","k":"trivia","f":"side","kj":"こぼれ話","t":"クレオパトラは本当に毒蛇で死んだのか","l":"caesar-augustus","x":"クレオパトラが毒蛇（コブラの一種）に自分を噛ませて死んだという話は有名だが、プルタルコスはこの話を紹介したうえで、「真相は誰にも分からない」と書いている。毒蛇はイチジクの籠に隠して"},{"id":"caesar-augustus-t18","k":"source","f":"src","kj":"史料｜記録","t":"『業績録』の言葉","l":"caesar-augustus","x":"アウグストゥスは死の直前、自分の業績を記した文章を残し、ローマの霊廟の前に青銅板に刻んで掲げさせた。その写しが、現在のトルコのアンカラの神殿の壁に残っている。『神君アウグストゥスの"},{"id":"caesar-augustus-t19","k":"confuse","f":"confuse","kj":"混同注意","t":"「皇帝」「インペラトル」「カエサル」","l":"caesar-augustus","x":"日本語ではアウグストゥスを「初代ローマ皇帝」と呼ぶが、彼が「皇帝」という称号を名乗ったわけではない。英語のemperorの語源となった「インペラトル」は、もともと勝利した将軍を兵士"},{"id":"caesar-augustus-t20","k":"trivia","f":"side","kj":"こぼれ話","t":"「喜劇はうまく演じられたか」――最期の言葉","l":"caesar-augustus","x":"後14年8月19日、アウグストゥスはナポリ近くのノラで、75歳の生涯を閉じた。スエトニウスによれば、臨終の日、彼は鏡を持ってこさせて髪を整えさせ、友人たちを呼び入れて「人生という喜"},{"id":"caesar-augustus-t21","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"caesar-augustus","x":"シェイクスピア『ジュリアス・シーザー』（1599年ごろ初演）：カエサル暗殺と、その後のブルートゥスとアントニウスの争いを描いた悲劇。「ブルータス、おまえもか」のせりふで有名だが、こ"},{"id":"calvin-england-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"プロテスタンティズムと資本主義","l":"calvin-england","x":"1904〜05年、ドイツの社会学者マックス・ヴェーバーは、『プロテスタンティズムの倫理と資本主義の精神』を発表した。ヴェーバーは、カルヴァン派などのプロテスタントの人々が、救いの確"},{"id":"calvin-england-t2","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"ヘンリ8世の6人の妃","l":"calvin-england","x":"跡継ぎの男子を求めたヘンリ8世は、生涯に6回結婚した。イギリスでは、その運命を、「離婚、斬首、死亡、離婚、斬首、生存」という語呂合わせで覚えるという。王妃結婚運命キャサリン・オブ・"},{"id":"calvin-england-t3","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"calvin-england","x":"映画『わが命つきるとも』（フレッド・ジンネマン監督、1966年）：ヘンリ8世の離婚と首長法に反対して処刑されたトマス・モアを描き、アカデミー賞作品賞を受賞した。ヒラリー・マンテル『"},{"id":"catholic-church-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"天使の城","l":"catholic-church","x":"590年、ペストの流行を鎮めるために、グレゴリウスは、ローマ市民を率いて、祈りの行列を行った。伝承によれば、行列がテヴェレ川のほとりのハドリアヌス帝の霊廟の近くにさしかかった時、霊"},{"id":"catholic-church-t2","k":"source","f":"src","kj":"史料｜記録","t":"神殿を壊すな","l":"catholic-church","x":"グレゴリウス1世は、601年、ブリテン島に向かう修道士メリトゥスに、布教の方法について、次のような手紙を送っている。原文…… fana idolorum destrui in ea"},{"id":"catholic-church-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"『ケルズの書』のネコとネズミ","l":"catholic-church","x":"『ケルズの書』は、子牛の皮から作った羊皮紙340枚に、4つの福音書をラテン語で書き写し、渦巻きや組みひも、動物や人の姿を組み合わせた、細かな装飾をほどこした写本である。アイオナ島の"},{"id":"catholic-church-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"剣を受け止めた本","l":"catholic-church","x":"754年、80歳近い老人となったボニファティウスは、最後の布教の旅として、北海沿岸のフリースラント（現在のオランダ北部）に向かった。6月5日、ドックムの近くで、ボニファティウスの一"},{"id":"catholic-church-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「神のしもべたちのしもべ」","l":"catholic-church","x":"ローマ教皇は、正式の文書で、自分のことを「神のしもべたちのしもべ」（servus servorum Dei）と名乗る。この称号を好んで用いたのが、グレゴリウス1世（大教皇、在位59"},{"id":"catholic-church-t6","k":"now","f":"now","kj":"いま","t":"モンテ・カッシーノの破壊と再建","l":"catholic-church","x":"ベネディクトゥスが開いたモンテ・カッシーノ修道院は、その歴史の中で、何度も破壊された。6世紀末にはランゴバルド人に、9世紀にはイスラーム勢力に、14世紀には地震によって破壊され、そ"},{"id":"catholic-church-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"catholic-church","x":"ウンベルト・エーコ『薔薇の名前』（1980年）：14世紀のイタリアのベネディクト会修道院を舞台に、写字室と図書館の秘密をめぐって起こる連続殺人を描いた小説。修道院の1日の生活が、聖"},{"id":"cave-art-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"8歳の少女の発見は、20年以上信じてもらえなかった","l":"cave-art","x":"アルタミラの洞窟壁画を最初に見つけたのは、8歳の少女マリアだった。1879年、父のサウトゥオラが洞窟の床を掘っていたとき、そばで天井を見上げたマリアが「パパ、見て、牛がいる！」と叫"},{"id":"cave-art-t2","k":"now","f":"now","kj":"いま","t":"ラスコーはなぜ閉ざされたのか","l":"cave-art","x":"ラスコーの洞窟は1948年に一般公開され、多くの観光客が訪れた。ところが、1日に1000人を超える人々の吐く息や体温、持ち込まれた菌によって、洞窟の中の環境が変わり、壁に緑色のカビ"},{"id":"cave-art-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「見て、パパ、牛がいる！」――アルタミラの発見","l":"cave-art","x":"1879年、スペイン北部のカンタブリア地方で、地元の貴族で考古学の愛好家マルセリーノ・サンス・デ・サウトゥオラは、アルタミラの洞窟で、石器などを探して床を掘っていた。一緒について来"},{"id":"cave-art-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"少年の足跡とオオカミの足跡","l":"cave-art","x":"1994年12月18日、3人の洞窟探検家が、南フランスのアルデシュ渓谷の崖で、かすかに風が吹き出す小さな穴を見つけた。岩をどけて中に入った彼らは、懐中電灯の光の中に、赤い色で描かれ"},{"id":"cave-art-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ネアンデルタール人も絵を描いた？","l":"cave-art","x":"2018年、スペインの三つの洞窟で見つかった赤い顔料の線や手形が、6万4000年以上前のものだと発表された。この時代のヨーロッパには、まだホモ＝サピエンスは到達していなかった。もし"},{"id":"cave-art-t6","k":"voice","f":"src","kj":"史料｜証言","t":"「われわれは何も発明していない」――ピカソとラスコー","l":"cave-art","x":"1940年、フランス南西部のラスコーの洞窟が、4人の少年によって発見された。少年たちは、穴に落ちた犬を探していたとも伝えられる。第二次世界大戦の後、洞窟が一般に公開されると、多くの"},{"id":"cave-art-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"「ヴィーナス」と呼ばれる女性像","l":"cave-art","x":"ヨーロッパからシベリアにかけての旧石器時代の遺跡からは、胸や腹、腰を強調した小さな女性の像がたくさん見つかっている。オーストリアで見つかった「ヴィレンドルフのヴィーナス」（約3万年"},{"id":"cave-art-t8","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"3万4000年前の豪華な墓","l":"cave-art","x":"ロシアのスンギール遺跡では、約3万4000年前の墓が見つかっている。少年と少女が頭を合わせるように葬られた墓には、マンモスの牙で作った1万個以上のビーズや、長い槍、動物の彫刻などが"},{"id":"cave-art-t9","k":"view","f":"think","kj":"考える｜別の視点","t":"アボリジニにとっての岩絵","l":"cave-art","x":"アボリジニの人々は、世界で最も長く続く文化の担い手の一つとされる。彼らの考え方では、祖先の霊が大地を旅しながら、山や川、動植物、人間の決まりごとを作った「ドリーミング」の世界は、遠"},{"id":"cave-art-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"cave-art","x":"映画『世界最古の洞窟壁画 忘れられた夢の記憶』（ヴェルナー・ヘルツォーク監督、2010年）：ふだんは研究者しか入れないフランスのショーヴェ洞窟の内部を、3Dカメラで撮影したドキュメ"},{"id":"charlemagne-t1","k":"source","f":"src","kj":"史料｜記録","t":"ザクセン人への勅令","l":"charlemagne","x":"ザクセン人の征服は、キリスト教への改宗と一体となって進められた。782年ごろ（785年ごろとも）に出されたと考えられている「ザクセン地方に関する勅令」には、次のような条文が並んでい"},{"id":"charlemagne-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"『ローランの歌』","l":"charlemagne","x":"ロンスヴォーで戦死した後衛の指揮官の一人が、ブルターニュ辺境の長官ローランであった。アインハルトが名前を一度だけ挙げているにすぎないこの人物は、約300年後に、フランス最古の叙事詩"},{"id":"charlemagne-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"1ポンド＝240ペンス","l":"charlemagne","x":"カールは、父ピピンの改革を受け継いで、通貨の制度を整えた。重さ1リブラ（ポンド）の銀から240枚のデナリウス銀貨を作り、12デナリウスを1ソリドゥスとして、計算の単位とした。つまり"},{"id":"charlemagne-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"文字を書こうとした皇帝","l":"charlemagne","x":"アインハルトは、カールの人柄について、多くのことを書き残している。カールは背が高く、その身長は自分の足の長さの7倍あったという。2010年には、アーヘン大聖堂に伝わるカールの遺骨と"},{"id":"charlemagne-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"象のアブル・アッバース","l":"charlemagne","x":"カールは、遠くアッバース朝のカリフ、ハールーン・アッラシードとも使節を交換した（→「アッバース朝とバグダード」の回）。797年、カールが送った使節団は、802年、ハールーンからの贈"},{"id":"charlemagne-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「ムハンマドなくして、カールなし」","l":"charlemagne","x":"ベルギーの歴史家アンリ・ピレンヌは、1937年に出版された『ヨーロッパ世界の誕生――マホメットとシャルルマーニュ』の中で、「ムハンマドなくしては、シャルルマーニュ（カール大帝）は考"},{"id":"charlemagne-t7","k":"source","f":"src","kj":"史料｜記録","t":"ストラスブールの誓約","l":"charlemagne","x":"842年、ルートヴィヒとシャルルは、ストラスブールで、互いの軍隊の前で、同盟の誓いを交わした。この時、ルートヴィヒは、シャルルの兵士たちにわかるように、ロマンス語（のちのフランス語"},{"id":"charlemagne-t8","k":"now","f":"now","kj":"いま","t":"ロタールの国の名残り","l":"charlemagne","x":"ロタールの中部フランクの北の部分は、ロタールの息子ロタール2世の名にちなんで「ロタリンギア」（ロタールの国）と呼ばれた。この名前が、現在のフランス東部の「ロレーヌ」地方（ドイツ語で"},{"id":"charlemagne-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"charlemagne","x":"アインハルト『カール大帝伝』：カールに仕えた学者による伝記。古代ローマのスエトニウスの『皇帝伝』を手本に書かれた。日本語訳に、國原吉之助訳『カロルス大帝伝』（筑摩書房）がある。『ロ"},{"id":"china-neolithic-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"黄河は「黄色い川」","l":"china-neolithic","x":"黄河の水は、黄土を大量に含んでいるため、名前の通り黄色く濁っている。1立方メートルの水に含まれる土砂の量は、世界の大河の中でも際立って多い。運ばれた土砂が下流で積もるため、黄河の川"},{"id":"china-neolithic-t2","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"半坡遺跡――濠に囲まれた村","l":"china-neolithic","x":"陝西省の西安郊外にある半坡遺跡は、仰韶文化の代表的な集落の跡である。直径約200mほどの居住区を、深さ5〜6m、幅6〜8mの大きな濠が取り囲んでいた。中央の広場の周りに数十軒の住居"},{"id":"china-neolithic-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"「中国文明は西から来た」？","l":"china-neolithic","x":"仰韶文化を発見したアンダーソンは、その彩陶が、遠く西アジアや東ヨーロッパの新石器時代の彩文土器に似ていることに注目し、中国の文明は西方から伝わった文化の影響を受けて生まれたのではな"},{"id":"china-neolithic-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"陶寺遺跡の「観象台」","l":"china-neolithic","x":"山西省の陶寺遺跡は、竜山文化の時代（前2300〜前1900年ごろ）の大規模な城壁都市の跡である。ここで見つかった半円形の土台には、版築の柱が弧を描いて並び、柱のすき間から、季節ごと"},{"id":"china-neolithic-t5","k":"confuse","f":"confuse","kj":"混同注意","t":"仰韶文化と竜山文化","l":"china-neolithic","x":"仰韶文化竜山文化時期前5000〜前3000年ごろ前3000〜前2000年ごろ中心地黄河中流域黄河下流域から中流域へ土器彩陶（赤地に黒・白の文様）黒陶（薄く光沢がある）・灰陶発見19"},{"id":"china-neolithic-t6","k":"now","f":"now","kj":"いま","t":"良渚――「中国最古の国家」？","l":"china-neolithic","x":"浙江省杭州市の郊外にある良渚遺跡では、2000年代以降の調査で、東西約1.7km・南北約1.9kmの城壁に囲まれた都市の跡が明らかになった。中央には人工的に築かれた巨大な基壇があり"},{"id":"china-neolithic-t7","k":"view","f":"think","kj":"考える｜別の視点","t":"「満天の星」――多元的な中国文明","l":"china-neolithic","x":"中国の考古学者・蘇秉琦は、新石器時代の中国各地に、それぞれ個性的な文化がいくつも並び立っていた様子を、「満天の星」にたとえた。黄河流域だけが光っていたのではなく、空一面に星が散らば"},{"id":"china-neolithic-t8","k":"source","f":"src","kj":"史料｜記録","t":"禹の治水","l":"china-neolithic","x":"『史記』は、禹の治水の苦労を次のように伝えている。原文禹傷先人父鯀功之不成受誅，乃勞身焦思，居外十三年，過家門不敢入。現代語訳禹は、父が治水に失敗して罰せられたことを悲しみ、身を苦"},{"id":"china-neolithic-t9","k":"debate","f":"think","kj":"考える｜諸説あり","t":"夏王朝は実在したか","l":"china-neolithic","x":"夏王朝が実在したかどうかは、今も議論が続いている諸説。河南省の二里頭遺跡（前1900〜前1500年ごろ）からは、大規模な宮殿の基壇や、中国で最も古い青銅の礼器（儀式に使う器）、トル"},{"id":"china-rise-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「能力を隠して、時機を待て」――鄧小平の遺訓","l":"china-rise","x":"1989年の天安門事件の後、西側の国々から経済制裁を受け、さらにソ連と東欧の社会主義体制が崩れていく中で、中国の最高実力者鄧小平は、中国の対外政策の方針について、指導部に、こう指示"},{"id":"china-rise-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「中華民族の偉大な復興」――習近平の「中国の夢」","l":"china-rise","x":"2012年11月、中国共産党の総書記に就任したばかりの習近平は、北京の国家博物館で開かれていた展覧会「復興の道」を、他の最高指導部のメンバーとともに見学し、こう語った。展覧会は、ア"},{"id":"china-rise-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"パンダのいない日本","l":"china-rise","x":"1972年、日中の国交が正常化した時、中国は、日本に2頭のジャイアントパンダ、カンカンとランランを贈った。東京の上野動物園には、パンダを一目見ようと、長い行列ができた。それから半世"},{"id":"cholera-public-health-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ヘーゲルの死","l":"cholera-public-health","x":"1831年11月、ドイツの哲学者ヘーゲルが、ベルリンで急死した。この年、ベルリンでは、コレラが流行していた。ヘーゲルの死因は、コレラとされた。しかし、ヘーゲルの症状は、コレラの典型"},{"id":"cholera-public-health-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「その翌日、ポンプの取っ手は取り外された」――スノーの報告","l":"cholera-public-health","x":"1855年、ジョン・スノーは、『コレラの伝染様式について』の第2版を出版し、前年のブロード・ストリートの流行について、詳しく報告した。そこには、彼が教区の役員会に訴えたときのことが"},{"id":"cholera-public-health-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"コレラ菌を飲んだ学者","l":"cholera-public-health","x":"1892年10月、73歳のペッテンコーファーは、コッホの説が誤っていることを証明するために、驚くべき実験を行った。コッホの研究所から取り寄せたコレラ菌の培養液を、自ら飲み干したので"},{"id":"cholera-public-health-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「私は、静かに死の目を見つめたであろう」――ペッテンコーファーの実験","l":"cholera-public-health","x":"1892年10月7日、ミュンヘン大学の衛生学者マックス・フォン・ペッテンコーファーは、74歳であった。彼は、コッホの研究室から取り寄せた、コレラ患者の便から培養したコレラ菌の液を、"},{"id":"cholera-public-health-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"23万人の検疫","l":"cholera-public-health","x":"1895年、日清戦争が終わり、中国大陸から23万人を超える兵士たちが帰国することになった。戦地では、コレラが流行していた。兵士たちがそのまま帰国すれば、日本の全国にコレラが広がるお"},{"id":"cholera-public-health-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"cholera-public-health","x":"ガルシア＝マルケス『コレラの時代の愛』（小説、1985年）：19世紀の末から20世紀の初め、コレラの流行がくり返されるカリブ海沿岸の町を舞台に、50年以上にわたって一人の女性を思い"},{"id":"christianity-origin-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"イエスの時代のユダヤ教の主な宗派","l":"christianity-origin","x":"宗派担い手特色サドカイ派神殿の祭司・貴族エルサレム神殿の儀式を重視。ローマの支配に協力的。死後の復活を否定パリサイ派（ファリサイ派）律法学者・中流の人々律法を日常生活の細部まで厳格"},{"id":"christianity-origin-t2","k":"now","f":"now","kj":"いま","t":"死海文書の発見","l":"christianity-origin","x":"1947年、死海の北西岸のクムランの洞窟で、羊を探していたベドウィン（遊牧民）の少年が、壺に入った古い巻物を見つけた。その後の調査で、11の洞窟から、900点を超える文書の断片が発"},{"id":"christianity-origin-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"イエスは「紀元前」に生まれた？","l":"christianity-origin","x":"現在の西暦は、6世紀のローマの修道士ディオニュシウス＝エクシグウスが、イエスの誕生の年を計算し、それを紀元1年としたものである。ところが、福音書によれば、イエスはヘロデ王の時代に生"},{"id":"christianity-origin-t4","k":"source","f":"src","kj":"史料｜記録","t":"山上の垂訓","l":"christianity-origin","x":"原文Μακάριοι οἱ πτωχοὶ τῷ πνεύματι, ὅτι αὐτῶν ἐστιν ἡ βασιλεία τῶν οὐρανῶν. ……現代語訳心の貧しい人々は、幸"},{"id":"christianity-origin-t5","k":"source","f":"src","kj":"史料｜記録","t":"ローマの歴史家が記したキリスト","l":"christianity-origin","x":"イエスについて記したローマ側の史料は少ないが、歴史家タキトゥスは、64年のローマの大火について記した中で、次のように書いている。原文ergo abolendo rumori Ner"},{"id":"christianity-origin-t6","k":"confuse","f":"confuse","kj":"混同注意","t":"ユダヤ教とキリスト教","l":"christianity-origin","x":"ユダヤ教キリスト教神唯一神ヤハウェ同じ唯一神（父なる神）イエス救世主とは認めない救世主（キリスト）・神の子聖典ヘブライ語聖書（キリスト教のいう旧約聖書）旧約聖書＋新約聖書救いの対象"},{"id":"christianity-origin-t7","k":"source","f":"src","kj":"史料｜記録","t":"「ユダヤ人もギリシア人もない」","l":"christianity-origin","x":"パウロは、旅先から各地の教会に宛てて、多くの手紙を書いた。それらは『新約聖書』に収められ、新約聖書の中で最も古い文書となっている。原文Πάντες γὰρ υἱοὶ θεοῦ ἐσ"},{"id":"christianity-origin-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"「新約」「旧約」とは","l":"christianity-origin","x":"「約」とは、神と人間との「契約」のことである。ユダヤ教では、神がモーセを通じてユダヤ人と結んだ契約を重んじる。キリスト教では、イエス＝キリストによって、神とすべての人間との「新しい"},{"id":"christianity-origin-t9","k":"voice","f":"src","kj":"史料｜証言","t":"包囲されたエルサレム（70年）","l":"christianity-origin","x":"66年に始まったユダヤ人の反乱は、70年、ティトゥスの率いるローマ軍によるエルサレムの包囲で頂点を迎えた。町の中では、反乱軍の派閥どうしの争いの中で、恐ろしい飢えが広がった。ローマ"},{"id":"christianity-origin-t10","k":"now","f":"now","kj":"いま","t":"「嘆きの壁」とエルサレム","l":"christianity-origin","x":"70年に焼かれた神殿のうち、ヘロデ王が築いた神殿の丘を囲む擁壁の一部が、今も残っている。これが「嘆きの壁」（西の壁）で、ユダヤ教の最も重要な祈りの場となっている。一方、神殿の丘の上"},{"id":"christianity-origin-t11","k":"source","f":"src","kj":"史料｜記録","t":"小プリニウスとトラヤヌス帝の往復書簡","l":"christianity-origin","x":"112年ごろ、小アジアの属州ビテュニアの総督であった小プリニウス（→「ローマ人の暮らし」の回）は、キリスト教徒の扱いについて、トラヤヌス帝に問い合わせる手紙を書いた。原文Inter"},{"id":"christianity-origin-t12","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"christianity-origin","x":"映画『ベン・ハー』（1959年、ウィリアム・ワイラー監督）：イエスと同じ時代を生きたユダヤ人の貴族ベン・ハーの数奇な運命を描く。原作はルー・ウォーレスの小説（1880年）。戦車競走"},{"id":"christianity-rome-t1","k":"source","f":"src","kj":"史料｜記録","t":"犠牲証明書","l":"christianity-rome","x":"原文Τοῖς ἐπὶ τῶν θυσιῶν ᾑρημένοις …… παρὰ Αὐρηλίου …… καὶ ἀεὶ θύων τοῖς θεοῖς διετέλεσα καὶ "},{"id":"christianity-rome-t2","k":"source","f":"src","kj":"史料｜記録","t":"コンスタンティヌスが見たもの","l":"christianity-rome","x":"原文Commonitus est in quiete Constantinus, ut caeleste signum dei notaret in scutis atque it"},{"id":"christianity-rome-t3","k":"source","f":"src","kj":"史料｜記録","t":"ミラノ勅令","l":"christianity-rome","x":"原文Cum feliciter tam ego Constantinus Augustus quam etiam ego Licinius Augustus apud Mediol"},{"id":"christianity-rome-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"ヘレナと「聖十字架」","l":"christianity-rome","x":"コンスタンティヌスの母ヘレナは、熱心なキリスト教徒となり、320年代後半、70歳を超えて聖地エルサレムを巡礼した。彼女は、イエスの生誕地ベツレヘムや、エルサレムのオリーブ山に教会を"},{"id":"christianity-rome-t5","k":"source","f":"src","kj":"史料｜記録","t":"ニケーア信条（325年）","l":"christianity-rome","x":"原文Πιστεύομεν εἰς ἕνα Θεόν, Πατέρα παντοκράτορα, πάντων ὁρατῶν τε καὶ ἀοράτων ποιητήν· καὶ "},{"id":"christianity-rome-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"サンタクロースがアリウスを殴った？","l":"christianity-rome","x":"後世の伝説によれば、ニケーア公会議の席で、小アジアのミラの司教ニコラオスは、アリウスの主張に激怒して、彼の顔を平手で打ったという。このニコラオスが、子どもたちに贈り物をしたという伝"},{"id":"christianity-rome-t7","k":"source","f":"src","kj":"史料｜記録","t":"ユリアヌスが見たキリスト教徒の強さ","l":"christianity-rome","x":"原文αἰσχρὸν γάρ, εἰ τῶν μὲν Ἰουδαίων οὐδεὶς μεταιτεῖ, τρέφουσι δὲ οἱ δυσσεβεῖς Γαλιλαῖοι πρὸ"},{"id":"christianity-rome-t8","k":"source","f":"src","kj":"史料｜記録","t":"テオドシウス帝の勅令（380年）","l":"christianity-rome","x":"原文Cunctos populos, quos clementiae nostrae regit temperamentum, in tali volumus religione "},{"id":"christianity-rome-t9","k":"now","f":"now","kj":"いま","t":"ニケーア信条の1700年","l":"christianity-rome","x":"2025年は、ニケーア公会議から1700年の節目の年であった。2025年11月、ローマ教皇レオ14世は、トルコのイズニク（古代のニケーア）を訪れ、コンスタンティノープル総主教バルト"},{"id":"christianity-rome-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"christianity-rome","x":"辻邦生『背教者ユリアヌス』（1972年）：皇族の粛清を生き延びた少年ユリアヌスが、哲学に目覚め、皇帝となって伝統の神々の復活に挑み、遠征の地で倒れるまでを描いた長編小説。毎日芸術賞"},{"id":"chu-han-t1","k":"source","f":"src","kj":"史料｜記録","t":"「王侯将相いずくんぞ種あらんや」","l":"chu-han","x":"陳勝は若いころ、日雇いで畑を耕していたとき、仲間に「金持ちになっても、お互い忘れないようにしよう」と言った。仲間が「雇われ者の身で、金持ちになどなれるものか」と笑うと、陳勝はため息"},{"id":"chu-han-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"遅刻したら本当に死刑だったのか","l":"chu-han","x":"『史記』は、期限に遅れれば「法では皆斬」と記している。ところが、1975年に発見された睡虎地秦簡の法律（徭律）では、労役の集合に遅れた場合の罰は、3〜5日の遅れで叱責、6〜10日で"},{"id":"chu-han-t3","k":"source","f":"src","kj":"史料｜記録","t":"始皇帝の行列を見た二人","l":"chu-han","x":"若いころ、二人はそれぞれ、巡幸する始皇帝の行列を見たことがあった。会稽で行列を見た項羽は言った。原文彼可取而代也。書き下し彼、取って代わるべきなり（あいつに取って代わってやる）。出"},{"id":"chu-han-t4","k":"source","f":"src","kj":"史料｜記録","t":"法三章","l":"chu-han","x":"原文父老苦秦苛法久矣……與父老約，法三章耳：殺人者死，傷人及盜抵罪。現代語訳父老たちは、秦の苛酷な法に長い間苦しんできた。……私は、父老たちと約束する。法はただ三章のみとする。人を"},{"id":"chu-han-t5","k":"voice","f":"src","kj":"史料｜証言","t":"火は三か月消えず――項羽の怒り","l":"chu-han","x":"秦の都に向かう途中、項羽は、降伏した秦の兵士たちが不穏な動きを見せていると聞くと、夜のうちに彼らを生き埋めにした。原文楚軍夜擊阬秦卒二十餘萬人新安城南。現代語訳楚の軍は、夜襲をかけ"},{"id":"chu-han-t6","k":"source","f":"src","kj":"史料｜記録","t":"背水の陣","l":"chu-han","x":"前204年、韓信は、わずか数万の兵で、20万と号する趙の大軍と、井陘で戦った。韓信は、川を背にして陣を敷いた。兵法では、川や沼を背にして陣を敷くことは、逃げ場がなくなるので禁じ手と"},{"id":"chu-han-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"韓信の股くぐり","l":"chu-han","x":"韓信は、若いころ、貧しくて食べる物にも困っていた。故郷の淮陰の町で、ある若者が韓信をばかにして言った。「おまえは図体が大きくて剣を帯びているが、実は臆病者だろう。死ぬ気があるなら俺"},{"id":"chu-han-t8","k":"source","f":"src","kj":"史料｜記録","t":"垓下の歌","l":"chu-han","x":"原文項王則夜起，飲帳中。有美人名虞，常幸從；駿馬名騅，常騎之。現代語訳項王は夜中に起きて、とばりの中で酒を飲んだ。美人がいて、名を虞といい、いつも寵愛されて付き従っていた。駿馬がい"},{"id":"chu-han-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"捲土重来","l":"chu-han","x":"のちの唐の詩人杜牧は、烏江を訪れて、項羽を惜しむ詩をつくった。「江東の子弟 才俊多し 捲土重来 未だ知るべからず」――江東の若者には優れた者が多い。もし項羽が江東に戻っていれば、土"},{"id":"chu-han-t10","k":"source","f":"src","kj":"史料｜記録","t":"劉邦の自己分析","l":"chu-han","x":"天下を統一したのち、劉邦は、宴席で臣下たちに、自分が天下を取り、項羽が天下を失った理由を問うた。臣下たちの答えを聞いたのち、劉邦は自ら言った。原文夫運籌策帷帳之中，決勝於千里之外，"},{"id":"chu-han-t11","k":"view","f":"think","kj":"考える｜別の視点","t":"「勝者の歴史」としての『史記』","l":"chu-han","x":"私たちが知る項羽と劉邦の物語は、そのほとんどが、劉邦の子孫が皇帝として君臨する漢の時代に、司馬遷が書いた『史記』による。それでも、司馬遷は、皇帝にならなかった項羽のために、皇帝の伝"},{"id":"chu-han-t12","k":"confuse","f":"confuse","kj":"混同注意","t":"封建制・郡県制・郡国制","l":"chu-han","x":"封建制郡県制郡国制王朝周秦（始皇帝）前漢初め（高祖）しくみ一族・功臣を諸侯に封じ、世襲で治めさせる全国を郡・県に分け、中央から役人を派遣する直轄地は郡県制、遠方は一族・功臣を王に封"},{"id":"chu-han-t13","k":"source","f":"src","kj":"史料｜記録","t":"狡兎死して走狗烹らる","l":"chu-han","x":"前196年、韓信は、謀反を企てたとして、高祖の皇后呂后と蕭何の計略によって捕らえられ、処刑された。その数年前、楚王であった韓信が謀反の疑いで捕らえられたとき、韓信は次のように嘆いた"},{"id":"chu-han-t14","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"chu-han","x":"司馬遼太郎『項羽と劉邦』（1980年刊）：秦の滅亡から垓下の戦いまでを、2人の英雄と、彼らを取り巻く人々の群像劇として描いた長編小説。「なぜ劉邦が勝ったのか」という問いが、作品全体"},{"id":"civil-rights-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「みんなに、あの子に何をしたのか見てもらいたい」――エメット・ティル","l":"civil-rights","x":"1955年8月、シカゴから南部ミシシッピ州の親類の家を訪れていた14歳の黒人の少年エメット・ティルは、食料品店で白人の女性に口笛を吹いた（あるいは声をかけた）とされ、数日後、女性の"},{"id":"civil-rights-t2","k":"music","f":"music","kj":"音楽","t":"「勝利を我らに（We Shall Overcome）」","l":"civil-rights","x":"公民権運動の人々が、腕を組み、体を揺らしながら歌ったのが、「勝利を我らに」である。もとは20世紀の初めの黒人教会のゴスペル「いつの日か、私は乗り越える」であった。1945年、ストラ"},{"id":"civil-rights-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"衛星中継が伝えた悲報","l":"civil-rights","x":"ケネディの暗殺の知らせは、日本の人々に、思いがけない形で伝えられた。1963年11月23日の早朝（日本時間）、日本とアメリカを結ぶ、初めての通信衛星によるテレビの中継の実験が行われ"},{"id":"civil-rights-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"表彰台の3人目","l":"civil-rights","x":"1968年10月、メキシコ・シティで開かれたオリンピックの陸上男子200メートル。金メダルのトミー・スミスと銅メダルのジョン・カーロス――二人のアメリカの黒人選手――は、表彰台の上"},{"id":"civil-rights-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"読まれなかった演説――「月面の事故の場合に」","l":"civil-rights","x":"アポロ11号の打ち上げの直前、ニクソン大統領のスピーチライターのウィリアム・サファイアは、ある演説の原稿を用意していた。題は「月面の事故の場合に」。宇宙飛行士たちが月から帰れなくな"},{"id":"civil-rights-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"civil-rights","x":"映画『グローリー／明日への行進』（2014年）：1965年、投票権を求めてアラバマ州のセルマからモンゴメリーへ行進したキング牧師たちを描いた映画。映画『ドリーム』（2016年）：1"},{"id":"climate-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"真鍋淑郎","l":"climate","x":"1960年代、アメリカの気象局の研究所で、地球の気候をコンピュータで計算する研究に取り組んだ日本人がいた。愛媛県の山あいの村に生まれ、東京大学で気象学を学んだ後、1958年にアメリ"},{"id":"climate-t2","k":"source","f":"src","kj":"史料｜記録","t":"「世界を5分間黙らせた少女」","l":"climate","x":"地球サミットの会場で、カナダから来た12歳の少女セヴァン・カリス＝スズキが、各国の代表を前に演説した。彼女は、日系カナダ人の環境学者デヴィッド・スズキの娘で、子どもたちの環境団体を"},{"id":"climate-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「共通だが差異ある責任」","l":"climate","x":"温暖化の問題は、先進国と途上国の深い対立を抱えていた。途上国の言い分はこうである。大気中の二酸化炭素を増やしてきたのは、産業革命以来、石炭や石油を燃やし続けて豊かになった先進国であ"},{"id":"climate-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「化石賞」と「セクシー」","l":"climate","x":"国連の気候変動の会議の期間中、世界の環境団体のネットワークは、温暖化対策に後ろ向きな国に、皮肉を込めて「化石賞」を贈っている。日本は、石炭火力発電を続けていることなどを理由に、何度"},{"id":"climate-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「よくもそんなことを」――グレタ・トゥーンベリの国連演説","l":"climate","x":"2019年9月23日、ニューヨークの国連本部で開かれた気候行動サミットで、16歳のスウェーデンの少女グレタ・トゥーンベリは、各国の首脳たちを前に、怒りに声を震わせながら、こう語った"},{"id":"climate-t6","k":"now","f":"now","kj":"いま","t":"「沈む国」の選択","l":"climate","x":"2023年、オーストラリアとツバルは、新しい条約を結んだ。オーストラリアが、毎年、最大280人のツバルの人々に、永住の権利を与えるというのである。2025年に申請の受け付けが始まる"},{"id":"climate-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"climate","x":"映画『不都合な真実』（2006年）：元アメリカ副大統領アル・ゴアの、地球温暖化についての講演を記録したドキュメンタリー。アカデミー賞を受賞し、ゴアは翌2007年にノーベル平和賞を受"},{"id":"climate-t8","k":"now","f":"now","kj":"いま","t":"解けていく北極","l":"climate","x":"地球温暖化の影響が最もはっきりと現れているのが、北極である。北極の気温は、地球全体の平均の2倍から3倍以上の速さで上がっており、夏に北極海を覆う海氷の面積は、1980年ごろに比べて"},{"id":"cold-war-start-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「冷戦」という言葉","l":"cold-war-start","x":"米ソの対立を表す「冷戦（冷たい戦争、Cold War）」という言葉を、最初に使ったのは誰か。1945年10月、作家のジョージ・オーウェルは、原子爆弾についての評論の中で、原爆を持つ"},{"id":"cold-war-start-t2","k":"source","f":"src","kj":"史料｜記録","t":"「ソ連の奴隷として帰ってきた」","l":"cold-war-start","x":"マーシャル・プランへの参加をめぐって、最も劇的な経過をたどったのは、チェコスロヴァキアであった。チェコスロヴァキアの政府は、はじめ、援助を話し合うパリの会議への参加を決めた。ところ"},{"id":"cold-war-start-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"冷戦初期の東西の対抗","l":"cold-war-start","x":"冷戦の初期には、アメリカの政策と、それに対するソ連の対抗策が、組になって現れる。順序と組み合わせで覚えるとよい。西側（アメリカ）東側（ソ連）トルーマン・ドクトリン（1947年3月）"},{"id":"cold-war-start-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"「キャンディ・ボマー」","l":"cold-war-start","x":"ベルリン空輸に参加したアメリカの輸送機のパイロット、ゲイル・ハルヴォーセン中尉は、ある日、テンペルホーフ空港のフェンスの外に集まっていた子どもたちと話をした。子どもたちは、物ほしそ"},{"id":"cold-war-start-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"1票差の首相","l":"cold-war-start","x":"西ドイツの初代首相には、キリスト教民主同盟の党首アデナウアーが選ばれた。1949年9月の連邦議会での首相の選挙で、アデナウアーは、402人の議員の過半数にあたる202票を獲得して当"},{"id":"cold-war-start-t6","k":"view","f":"think","kj":"考える｜別の視点","t":"冷戦は、なぜ始まったのか","l":"cold-war-start","x":"冷戦の起源をめぐっては、アメリカの歴史学界で、長い論争があった。正統派（伝統派）：冷戦の原因は、東ヨーロッパを支配し、世界に共産主義を広げようとしたソ連の膨張主義にあり、アメリカは"},{"id":"cold-war-start-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"日本へのアメリカの援助","l":"cold-war-start","x":"マーシャル・プランは西ヨーロッパへの援助であったが、アメリカは、占領下の日本にも、「ガリオア」「エロア」と呼ばれる資金によって、食料や原料などの援助を行った。その総額は、約18億ド"},{"id":"cold-war-start-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"cold-war-start","x":"オーウェル『一九八四年』（小説、1949年）：「ビッグ・ブラザー」が国民を監視する全体主義国家を描いた小説。「冷戦（cold war）」という言葉を広めたのも、オーウェルであった。"},{"id":"colonial-rivalry-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"若きワシントンの一発","l":"colonial-rivalry","x":"1754年、オハイオ川の上流の森で、ヴァージニア植民地の民兵を率いた22歳の若い士官が、フランス軍の偵察隊を襲撃した。フランス側の指揮官は殺された。士官は、続いて築いた小さな砦をフ"},{"id":"colonial-rivalry-t2","k":"music","f":"music","kj":"音楽","t":"「統治せよ、ブリタニア！」","l":"colonial-rivalry","x":"1740年、ロンドン郊外で上演された仮面劇のために、作曲家トマス・アーンが曲をつけた歌が、のちにイギリスの愛国歌として広く歌われるようになった。「統治せよ、ブリタニア！ ブリタニア"},{"id":"colonial-rivalry-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「神に感謝する。安らかに死ねる」――ケベックのウルフ将軍","l":"colonial-rivalry","x":"1759年9月13日、フランス領カナダの中心ケベックの町の外、アブラハム平原で、イギリス軍とフランス軍が戦った。イギリス軍を率いる32歳の将軍ジェームズ・ウルフは、前夜、兵士たちを"},{"id":"colonial-rivalry-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「数エーカーの雪」","l":"colonial-rivalry","x":"パリ条約の交渉で、フランスは、広大なカナダを手放す一方で、カリブ海の小さな島グアドループとマルティニークを取り戻すことを選んだ。砂糖を生み出すこれらの島々の方が、寒くて人の少ないカ"},{"id":"columbian-exchange-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"見張りつきのジャガイモ畑","l":"columbian-exchange","x":"フランスで、ジャガイモの普及に尽くしたのは、薬剤師のパルマンティエであった。彼は七年戦争でプロイセン軍の捕虜となり、収容所で毎日ジャガイモを食べさせられて、その栄養価に気づいたとい"},{"id":"columbian-exchange-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"名前が語る作物の旅","l":"columbian-exchange","x":"新しい作物の名前には、それがどこから来たと思われていたかが、刻み込まれている。アメリカ大陸の鳥である七面鳥は、英語で「ターキー（トルコ）」と呼ばれる。トルコから来た鳥と思われたため"},{"id":"columbian-exchange-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「皮膚がむしろに張りつき」――天然痘に倒れた人々","l":"columbian-exchange","x":"ヨーロッパ人がもたらした病気に対して、アメリカ大陸の人々は免疫を持たなかった。1634年、北アメリカのプリマス植民地の総督ウィリアム・ブラッドフォードは、天然痘に襲われた先住民の村"},{"id":"columbian-exchange-t4","k":"now","f":"now","kj":"いま","t":"地球の空気に刻まれた「大いなる死」","l":"columbian-exchange","x":"アメリカ大陸の人口の激減は、地球の気候にまで影響を与えたかもしれない。南極の氷床の中に閉じ込められた昔の空気を調べると、1610年ごろに、大気中の二酸化炭素の濃度が、7〜10ppm"},{"id":"columbian-exchange-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"梅毒はアメリカ大陸から来たのか","l":"columbian-exchange","x":"コロンブス交換で、アメリカ大陸から旧大陸へ渡った病気として、しばしば挙げられるのが梅毒である。1495年、フランス王シャルル8世がイタリアに攻め込み、ナポリを占領したとき、フランス"},{"id":"columbian-exchange-t6","k":"source","f":"src","kj":"史料｜記録","t":"「金の旦那は、たいそうなお方」","l":"columbian-exchange","x":"スペインの黄金時代の詩人ケベードは、1603年ごろ、次のような風刺詩をつくった。原文Madre, yo al oro me humillo;él es mi amante y mi"},{"id":"columbus-t1","k":"source","f":"src","kj":"史料｜記録","t":"コロンブスの航海日誌","l":"columbus","x":"コロンブスの航海日誌の原本は失われてしまった。現在伝わっているのは、16世紀の宣教師ラス・カサスが書き写した要約である。その中で、コロンブスは、初めて出会ったカリブ海の先住民タイノ"},{"id":"columbus-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"月食を「予言」したコロンブス","l":"columbus","x":"4回目の航海の途中、コロンブスの船は、虫に食われて傷み、1503年、ジャマイカの海岸に乗り上げた。一行は、1年近くも島に取り残された。はじめは食料を分けてくれていた先住民も、やがて"},{"id":"columbus-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「われらの鏡、光、慰め、まことの導き手」――ピガフェッタの見たマゼランの最期","l":"columbus","x":"マゼランの世界周航に同行し、旅の記録を残したのが、イタリアのヴィチェンツァ出身のアントニオ・ピガフェッタであった。1521年4月27日、フィリピンのマクタン島で、王ラプ＝ラプの軍勢"},{"id":"columbus-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"消えた1日","l":"columbus","x":"マゼランの死後、残された乗組員たちは、モルッカ諸島で香辛料を積み込み、スペイン人のエルカーノの指揮のもとで、ただ1隻残ったヴィクトリア号で、インド洋とアフリカの南端を回って帰国の途"},{"id":"columbus-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"columbus","x":"映画『1492 コロンブス』（リドリー・スコット監督、1992年）：「アメリカ大陸の発見」の500周年に製作された映画。コロンブスの航海と、先住民への支配の始まりを描く。作品は史実"},{"id":"conquest-americas-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「彼らのいる天国には行きたくない」――ラス・カサスの告発","l":"conquest-americas","x":"ラス・カサスの『インディアスの破壊についての簡潔な報告』は、カリブ海の島々で彼が見聞きしたことを、こう書いている。原文Entraban en los pueblos, ni dej"},{"id":"conquest-americas-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ラス・カサスの「過ち」","l":"conquest-americas","x":"先住民の保護に生涯をささげたラス・カサスであるが、その生涯には、一つの大きな影があった。1516年ごろ、ラス・カサスは、先住民の負担を軽くするための案の一つとして、先住民の代わりに"},{"id":"conquest-americas-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"グアダルーペの聖母","l":"conquest-americas","x":"1531年12月、メキシコ市の北の丘テペヤクで、フアン・ディエゴという名の先住民の男性の前に、聖母マリアが姿を現した――という伝承がある伝承。聖母は、先住民の言葉ナワトル語で語りか"},{"id":"conquest-americas-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"conquest-americas","x":"映画『アギーレ／神の怒り』（ヴェルナー・ヘルツォーク監督、1972年）：黄金郷エル・ドラードを求めてアマゾン川を下ったスペインの遠征隊が、反乱を起こした隊員アギーレのもとで破滅して"},{"id":"counter-reformation-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"魔女狩りの時代","l":"counter-reformation","x":"宗教改革と対抗宗教改革の時代は、ヨーロッパで「魔女狩り」が最も激しかった時代でもあった。悪魔と契約を結んで、人々に害を与えるとされた「魔女」を探し出して裁く魔女裁判は、中世の末から"},{"id":"counter-reformation-t2","k":"source","f":"src","kj":"史料｜記録","t":"「しかばねのように」――イエズス会の服従","l":"counter-reformation","x":"イエズス会の会員たちは、清貧・貞潔・服従の誓いに加えて、教皇の命令に従って、世界のどこへでも赴くという特別な誓いを立てた。創設者イグナティウス・デ・ロヨラが定めた『イエズス会会憲』"},{"id":"counter-reformation-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"消えた10日間","l":"counter-reformation","x":"少年たちが謁見した教皇グレゴリウス13世は、1582年、暦の改革を行ったことで知られる。それまでヨーロッパで使われていた、古代ローマのユリウス・カエサルが定めたユリウス暦は、1年を"},{"id":"counter-reformation-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"counter-reformation","x":"映画『ミッション』（ローランド・ジョフィ監督、1986年）：18世紀の南アメリカで、先住民グアラニーの人々の中で布教したイエズス会の宣教師たちが、スペインとポルトガルの国境の取り決"},{"id":"covid-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ウイルスはどこから来たのか","l":"covid","x":"新型コロナウイルスは、どこから来たのか。この問いには、今も、決着がついていない諸説。多くの科学者は、コウモリなどの野生の動物が持っていたウイルスが、武漢の華南海鮮市場などで売られて"},{"id":"covid-t2","k":"source","f":"src","kj":"史料｜記録","t":"「戦争状態にある」","l":"covid","x":"2020年3月16日、フランスのマクロン大統領は、テレビで国民に演説し、翌日からの全国の外出の禁止を発表した。演説の中で、マクロンは、6回にわたって、同じ言葉をくり返した。「私たち"},{"id":"covid-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"アマビエ","l":"covid","x":"2020年の春、日本のインターネットの上に、奇妙な姿の妖怪が大量に現れた。長い髪に、くちばしを持ち、うろこにおおわれた体から3本の足が生えた、アマビエである。アマビエは、江戸時代の"},{"id":"covid-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"歴史の中のパンデミック","l":"covid","x":"人類の歴史は、感染症との闘いの歴史でもあった。14世紀のヨーロッパでは、ペスト（黒死病）によって人口の3分の1ほどが失われ、中世の社会の仕組みが大きく揺らいだ（→「黒死病の大流行」"},{"id":"crimean-war-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"戦場から生まれた言葉","l":"crimean-war","x":"クリミア戦争からは、今も使われている言葉がいくつも生まれた。冬の寒さから兵士の顔を守るために編まれた目出し帽は、戦場の地名をとって「バラクラバ」と呼ばれた。軽騎兵旅団を率いたカーデ"},{"id":"crimean-war-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"もう一人の看護の母、メアリー・シーコール","l":"crimean-war","x":"クリミアの戦場で兵士たちを看護したのは、ナイティンゲールだけではなかった。ジャマイカ出身の黒人とスコットランド人の両親を持つメアリー・シーコールは、カリブ海で身につけた薬草や看護の"},{"id":"crimean-war-t3","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"crimean-war","x":"テニソン「軽騎兵の突撃」（詩、1854年）：バラクラヴァの戦いで、命令の誤りのために、ロシア軍の砲列に向かって突撃した軽騎兵旅団をたたえた詩。「なぜかと問うのは彼らの務めではない、"},{"id":"crisis-3rd-t1","k":"source","f":"src","kj":"史料｜記録","t":"死の床の遺言","l":"crisis-3rd","x":"原文ὁμονοεῖτε, τοὺς στρατιώτας πλουτίζετε, τῶν ἄλλων πάντων καταφρονεῖτε.現代語訳兄弟仲良くせよ。兵士を富ませよ"},{"id":"crisis-3rd-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"エラガバルスのバラ","l":"crisis-3rd","x":"4世紀末に書かれた皇帝伝記集『ローマ皇帝群像（ヒストリア＝アウグスタ）』は、エラガバルスについて、宴会の天井から大量のバラの花びらを降らせて客を窒息死させた、といった数々の奇行を伝"},{"id":"crisis-3rd-t3","k":"source","f":"src","kj":"史料｜記録","t":"シャープール1世の勝利の碑文","l":"crisis-3rd","x":"カエサル（ローマ皇帝）ウァレリアヌスが、7万の軍勢を率いて我らに向かってきた。カルラエとエデッサの向こう側で、我らはカエサル＝ウァレリアヌスと大いに戦い、カエサル＝ウァレリアヌスを"},{"id":"crisis-3rd-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"ゼノビア――ローマと渡り合った女王","l":"crisis-3rd","x":"パルミラは、シリア砂漠のオアシスにある隊商都市で、ローマとペルシア、さらにインドを結ぶ交易で繁栄していた（→「パルティアとイラン世界」の回）。夫オダエナトゥスが267年ごろに暗殺さ"},{"id":"crisis-3rd-t5","k":"source","f":"src","kj":"史料｜記録","t":"最高価格令が定めた価格","l":"crisis-3rd","x":"最高価格令は、帝国各地の都市の広場に碑文として掲げられ、その断片が現在まで残っている。そこに記された価格の一部を見てみよう（単位はデナリウス）。画像はオンライン時に表示される（Wi"},{"id":"crisis-3rd-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"「わたしが育てたキャベツを見せたい」","l":"crisis-3rd","x":"ディオクレティアヌスの退位後、皇帝たちの争いが激しくなると、308年、皇帝たちはドナウ川沿いのカルヌントゥムに集まって会議を開き、引退していたディオクレティアヌスにも出席を求めた。"},{"id":"crisis-3rd-t7","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「危機」はあったのか","l":"crisis-3rd","x":"「3世紀の危機」という言葉は、帝国が内乱・外敵・経済の混乱によって崩壊寸前に陥ったというイメージを与える。しかし、近年の研究では、危機の深刻さには地域差が大きかったことが指摘されて"},{"id":"crisis-3rd-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"crisis-3rd","x":"映画『グラディエーターII 英雄を呼ぶ声』（2024年、リドリー・スコット監督）：カラカラとゲタの兄弟が共同皇帝として統治する時代のローマを舞台に、剣闘士となった主人公の戦いを描く"},{"id":"crusades-arab-view-t1","k":"source","f":"src","kj":"史料｜記録","t":"「フランクの力が初めて現れた」","l":"crusades-arab-view","x":"十字軍の時代のイスラーム側の歴史家の中で、最も重要な人物の一人が、北イラクのジャズィーラ（現在のトルコのジズレ）に生まれ、モスルで活躍したイブン・アルアスィール（1160〜1233"},{"id":"crusades-arab-view-t2","k":"source","f":"src","kj":"史料｜記録","t":"ウサーマ・イブン・ムンキズの見たフランク","l":"crusades-arab-view","x":"シリアの小さな城の町シャイザルの領主の一族に生まれたウサーマ・イブン・ムンキズ（1095〜1188年）は、93歳まで生き、戦士・外交官・詩人として、十字軍の時代のほぼすべてを見届け"},{"id":"crusades-arab-view-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"サラーフ・アッディーンの「寛大さ」","l":"crusades-arab-view","x":"サラーフ・アッディーンは、ヨーロッパでも、敵ながら寛大で気高い君主として語り継がれた。しかし、彼の行動のすべてが寛大であったわけではない。ハッティーンの戦いの後、彼は、捕虜となった"},{"id":"crusades-arab-view-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"葬式の費用もなかったスルタン","l":"crusades-arab-view","x":"イブン・シャッダードによれば、サラーフ・アッディーンが亡くなったとき、その金庫に残っていたのは、銀貨47枚と金1片だけであったという。彼は、手に入れた富を、兵士や学者、貧しい人々に"},{"id":"crusades-arab-view-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"破門された皇帝とスルタンの友情","l":"crusades-arab-view","x":"1229年、神聖ローマ皇帝フリードリヒ2世（→「十字軍」の回）は、戦うことなく、交渉だけでイェルサレムを手に入れた。相手は、サラーフ・アッディーンの甥で、アイユーブ朝のスルタンであ"},{"id":"crusades-arab-view-t6","k":"now","f":"now","kj":"いま","t":"よみがえるサラーフ・アッディーン","l":"crusades-arab-view","x":"13世紀以降、イスラーム世界では、モンゴルの侵入という、十字軍よりもはるかに大きな衝撃が起こり（→「フレグの西アジア遠征とバグダード陥落」の回）、十字軍の記憶は、しだいに薄れていっ"},{"id":"crusades-arab-view-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"crusades-arab-view","x":"アミン・マアルーフ『アラブが見た十字軍』（1983年）：アラブの年代記作者たちの記録をもとに、十字軍を、侵略を受けた側から描いた歴史書。この回の題材の多くを、読みやすい物語として知"},{"id":"crusades-t1","k":"source","f":"src","kj":"史料｜記録","t":"「その旅は、すべての償いに代わる」","l":"crusades","x":"クレルモン教会会議は、演説のほかに、遠征に加わる者への約束を、正式な決議として残している。原文Quicumque pro sola devotione, non pro honor"},{"id":"crusades-t2","k":"voice","f":"src","kj":"史料｜証言","t":"マアッラの飢え","l":"crusades","x":"1098年末、シリアの町マアッラ・アンヌウマーンを攻め落とした十字軍は、激しい飢えに苦しんだ。従軍した聖職者や、のちに参加者から話を聞いた年代記作者たちは、目を背けたくなるような出"},{"id":"crusades-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「くるぶしまで血に浸かった」","l":"crusades","x":"イェルサレムを攻め落とした十字軍は、町の住民を無差別に殺した。十字軍に参加した騎士が書いたとされる『フランク人の事績』は、その様子を、次のように記している。原文Nostri ver"},{"id":"crusades-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"テンプル騎士団と「13日の金曜日」","l":"crusades","x":"テンプル騎士団の印章には、二人の騎士が一頭の馬にまたがる姿が描かれていた。これは、騎士団の初期の清貧を表すものとされる。しかし、騎士団は、ヨーロッパ各地に寄進された土地を持ち、巡礼"},{"id":"crusades-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"捕らわれの獅子心王","l":"crusades","x":"1192年、イングランドへの帰途についたリチャード1世は、船が難破したため、変装して陸路でヨーロッパを横断しようとした。しかし、ウィーンの近くで、第3回十字軍の際に侮辱を受けて恨み"},{"id":"crusades-t6","k":"works","f":"works","kj":"作品","t":"十字軍にまつわる作品","l":"crusades","x":"映画『キングダム・オブ・ヘブン』（2005年、リドリー・スコット監督）：1187年のイェルサレム陥落までを描いた映画。サラディンが、気高い指導者として描かれている。ウォルター・スコ"},{"id":"cuba-crisis-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"大統領の葉巻","l":"cuba-crisis","x":"1962年2月のある夜、ケネディ大統領は、報道官のサリンジャーを執務室に呼んで、こう頼んだという。「明日の朝までに、キューバ産の葉巻を、できるだけたくさん手に入れてくれ。1000本"},{"id":"cuba-crisis-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"誰が勝ったのか","l":"cuba-crisis","x":"キューバ危機は、長い間、ケネディの勝利、フルシチョフの敗北として語られてきた。ソ連のミサイルはキューバから撤去されたが、アメリカのトルコのミサイルの撤去は、秘密にされたからである。"},{"id":"cuba-crisis-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「赤い電話」はなかった","l":"cuba-crisis","x":"米ソの首脳を結んだホットラインというと、ホワイトハウスの机の上の「赤い電話」を思い浮かべる人が多い。映画などでよく描かれる場面である。しかし、実際のホットラインは、電話ではなかった"},{"id":"cuba-crisis-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"ゴジラが生まれた年","l":"cuba-crisis","x":"1954年11月、1本の日本の怪獣映画が公開された。『ゴジラ』である。太古の海の底で眠っていた恐竜が、水爆の実験によって目を覚まし、放射能を帯びた巨大な怪獣となって、東京を襲う。映"},{"id":"cuba-crisis-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「ミス原子爆弾」と、32万本の乳歯","l":"cuba-crisis","x":"1950年代のアメリカ社会は、核兵器を恐れる一方で、どこか楽しんでもいた。ネヴァダ核実験場に近いラスヴェガスでは、ホテルの屋上で夜明けの核実験の閃光を眺める催しが開かれ、「アトミッ"},{"id":"cuba-crisis-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"cuba-crisis","x":"映画『博士の異常な愛情』（スタンリー・キューブリック監督、1964年）：アメリカの将軍の暴走から核戦争が始まってしまう過程を、ブラックユーモアで描いた映画。キューバ危機の翌年に製作"},{"id":"cultural-revolution-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「三分は天災、七分は人災」","l":"cultural-revolution","x":"大躍進の惨状を、党の指導者たちは知らなかったわけではない。1961年春、国家主席の劉少奇は、故郷の湖南省の村に1か月あまり滞在して、農民の暮らしを調べた。家々の台所はからっぽで、村"},{"id":"cultural-revolution-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「白いネコ、黒いネコ」","l":"cultural-revolution","x":"鄧小平の言葉として有名な「白いネコでも黒いネコでも、ネズミをとるのがよいネコだ」は、もともとは、鄧小平の故郷の四川省のことわざで、1962年に鄧小平が語った時には、「黄色いネコ」で"},{"id":"cultural-revolution-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"プールサイドの首脳会談","l":"cultural-revolution","x":"1958年の夏、フルシチョフは、北京を訪れ、毛沢東と会談した。2日目の会談の場所は、なんと、中南海の毛沢東の住居のプールであった。水泳が得意な毛沢東は、水着姿で、悠々とプールを泳ぎ"},{"id":"cultural-revolution-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「要武嘛」――腕章を巻いた少女","l":"cultural-revolution","x":"1966年8月5日、北京師範大学附属女子中学校で、副校長の卞仲耘（50歳）が、生徒の紅衛兵たちに何時間にもわたって殴打され、死亡した。文化大革命で、生徒に殺された最初の教育者とされ"},{"id":"cultural-revolution-t5","k":"mech","f":"deep","kj":"深掘り｜しくみ","t":"なぜ若者たちは毛沢東を崇拝したのか","l":"cultural-revolution","x":"1966年8月から11月にかけて、毛沢東は天安門広場で8回にわたって紅衛兵を接見し、その数は延べ1000万人を超えた。毛沢東の姿を一目見た若者たちは、涙を流して「毛主席万歳」を叫ん"},{"id":"cultural-revolution-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"名古屋のバス","l":"cultural-revolution","x":"1971年4月、名古屋で、世界卓球選手権大会が開かれた。中国は、文化大革命の混乱で、2回続けて大会に参加していなかったが、日本卓球協会の会長の後藤鉀二が、北京を訪れて説得し、6年ぶ"},{"id":"cultural-revolution-t7","k":"person","f":"deep","kj":"深掘り｜人物","t":"江青――上海の女優から「四人組」へ","l":"cultural-revolution","x":"毛沢東の4番目の妻江青（1914〜1991年）は、山東省の貧しい家に生まれた。1930年代の上海で、「藍蘋」という芸名の映画女優・舞台女優として活動したが、大スターにはなれなかった"},{"id":"cultural-revolution-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"cultural-revolution","x":"劉慈欣『三体』（SF小説、2008年）：文化大革命の中で、物理学者の父を紅衛兵に殺された女性科学者の物語から始まる。中国のSFとして初めてヒューゴー賞を受賞し、ドラマ化もされた。ユ"},{"id":"culture-19c-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"門番の最期","l":"culture-19c","x":"ジョゼフ・マイスターは、1940年6月、ドイツ軍がパリを占領した直後に世を去った。そのため、ドイツ兵にパストゥールの墓所を開けるよう命じられた彼が、それを拒んで死を選んだ、という感"},{"id":"culture-19c-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"ワルシャワに帰った心臓","l":"culture-19c","x":"1830年11月、20歳のポーランドの青年ピアニスト ショパン は、演奏旅行に出るため、故郷ワルシャワを後にした。その直後、ワルシャワでは、ロシアの支配に対する蜂起（11月蜂起）が"},{"id":"culture-19c-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"北里柴三郎と「近代日本医学の父」","l":"culture-19c","x":"コッホの研究室には、遠い日本から来た一人の若者がいた。北里柴三郎 である。1886年からベルリンでコッホのもとで学んだ北里は、1889年、それまで誰も成功しなかった破傷風菌だけを取"},{"id":"culture-19c-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「死の商人、死す」","l":"culture-19c","x":"ノーベル賞をつくったスウェーデンの化学者 ノーベル は、1867年に、扱いやすく強力な爆薬ダイナマイトを発明して、巨万の富を築いた。ダイナマイトは、トンネルや鉄道の工事に使われる一"},{"id":"delhi-sultanate-t1","k":"source","f":"src","kj":"史料｜記録","t":"ビールーニーの見たインド","l":"delhi-sultanate","x":"マフムードのインド遠征には、中央アジアのホラズム出身の大学者ビールーニー（973〜1050年ごろ）が同行していた。ビールーニーは、インドに長く滞在してサンスクリット語を学び、インド"},{"id":"delhi-sultanate-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"インド初の女性のスルタン","l":"delhi-sultanate","x":"アイバクの娘婿で、やはり奴隷出身のイルトゥトミシュ（在位1211〜1236年）は、王朝の基礎を固めた名君である。彼は、チンギス・ハンに追われてインダス川まで逃れてきたホラズム・シャ"},{"id":"delhi-sultanate-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"チットールの王妃パドミニー","l":"delhi-sultanate","x":"1303年、アラー・アッディーンは、ラージャスターンのラージプートの城チットールを攻め落とした。のちの伝説では、アラー・アッディーンは、チットールの王妃パドミニーの美しさのうわさを"},{"id":"delhi-sultanate-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「デリーはまだ遠い」","l":"delhi-sultanate","x":"トゥグルク朝を開いたギヤース・アッディーン・トゥグルクは、デリーで人々の尊敬を集めていた聖者ニザームッディーン・アウリヤーと対立していた。1325年、ベンガルへの遠征から戻る途中、"},{"id":"democratization-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"タクシー運転手とドイツ人記者","l":"democratization","x":"光州で何が起こったのかを、世界に伝えたのは、一人の外国人記者であった。西ドイツの公共放送の東京駐在の記者ユルゲン・ヒンツペーターは、光州の異変を知ると、すぐにソウルに飛んだ。光州へ"},{"id":"democratization-t2","k":"source","f":"src","kj":"史料｜記録","t":"「机をたたいたら、ウッと言って死んだ」","l":"democratization","x":"1987年1月14日、ソウル大学の学生の朴鍾哲（パク・ジョンチョル）が、警察の取り調べの最中に死亡した。警察の幹部は、記者たちに、こう説明した。「机をドンとたたいたら、ウッと言って"},{"id":"democratization-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「フィリピン人は、そのために死ぬ価値がある」――ベニグノ・アキノの帰国声明","l":"democratization","x":"1983年8月21日、アメリカに亡命していたフィリピンの野党の指導者ベニグノ・アキノは、マルコス政権の警告を無視して、マニラの空港に降り立とうとしていた。暗殺の危険があることは、本"},{"id":"democratization-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"「蜂谷真由美」","l":"democratization","x":"ソウル・オリンピックの開幕を10か月後に控えた1987年11月29日、中東からソウルへ向かう大韓航空858便が、ミャンマー（ビルマ）の沖の上空で爆発し、乗客・乗員115人全員が死亡"},{"id":"democratization-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"日本人として生まれた総統","l":"democratization","x":"李登輝は、1923年、日本の統治下の台湾で生まれた（→「日清戦争と朝鮮」の回）。旧制の台北高等学校を経て、京都帝国大学で農業経済学を学んだ。学生時代には、「岩里政男」という日本名を"},{"id":"democratization-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"残された靴","l":"democratization","x":"マルコスが去った後のマニラの大統領官邸には、イメルダ夫人の、おびただしい数の衣装やバッグや靴が残されていた。靴の数は、1000足を超えていたとも、3000足であったともいわれる諸説"},{"id":"democratization-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"democratization","x":"映画『タクシー運転手 約束は海を越えて』（2017年、韓国）：1980年の光州事件の際に、ドイツ人の記者を光州まで乗せて行ったソウルのタクシー運転手の実話をもとにした映画。映画『1"},{"id":"developmental-states-t1","k":"source","f":"src","kj":"史料｜記録","t":"東京のホテルから消えた男","l":"developmental-states","x":"1973年8月8日の昼過ぎ、東京の九段にあるホテル・グランドパレスの一室から、来日中の金大中が、何者かによって連れ去られた。金大中は、維新体制に反対し、日本やアメリカで、朴正熙の独"},{"id":"developmental-states-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「私にとって、これは苦悩の瞬間である」――リー・クアンユーの涙","l":"developmental-states","x":"1965年8月9日、シンガポールは、マレーシア連邦から分離され、独立した。マレー人を優遇しようとするマレーシアの中央政府と、華人が多数を占めるシンガポールとの対立が、深まった結果で"},{"id":"developmental-states-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"ガムのない国","l":"developmental-states","x":"シンガポールは、清潔で、秩序の保たれた国として知られる。その秩序は、細かな規則と、厳しい罰によって支えられていた。道にごみを捨てれば、高い罰金を科される。公衆トイレで水を流さなけれ"},{"id":"developmental-states-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"デヴィ夫人","l":"developmental-states","x":"スカルノの第3夫人のデヴィは、日本人であった。本名を根本七保子という。東京の生まれで、1959年、東京のホテルで来日中のスカルノと知り合い、インドネシアに渡って、1962年に結婚し"},{"id":"developmental-states-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"ジャカルタの炎","l":"developmental-states","x":"1974年1月、田中角栄首相は、フィリピン、タイ、シンガポール、マレーシア、インドネシアの5か国を歴訪した。行く先々で、田中を待っていたのは、日本の経済の進出に抗議する学生たちのデ"},{"id":"developmental-states-t6","k":"source","f":"src","kj":"史料｜記録","t":"「心と心のふれ合う相互信頼関係」――福田ドクトリン","l":"developmental-states","x":"1974年1月、東南アジアを訪問した田中角栄首相は、タイやインドネシアで、日本企業の進出に反発する学生たちの激しい抗議デモに迎えられた。ジャカルタでは暴動が起こり、日本車が焼かれた"},{"id":"developmental-states-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"developmental-states","x":"映画『国際市場で逢いましょう』（2014年、韓国）：朝鮮戦争で避難民となった少年が、西ドイツの炭鉱への出稼ぎやベトナム戦争への従軍を経て、家族を支えながら生きた半生を描いた映画。韓"},{"id":"disputes-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「竹島」と「松島」","l":"disputes","x":"江戸時代の初め、伯耆国の米子（今の鳥取県）の商人の大谷家と村川家は、江戸幕府の許可を得て、日本海の遠くの島へ渡り、アワビやアシカをとっていた。その島の名は、「竹島」。ところが、この"},{"id":"disputes-t2","k":"source","f":"src","kj":"史料｜記録","t":"「日本帝国沖縄県八重山郡尖閣列島」","l":"disputes","x":"1919年の冬、中国の福建省の漁民31人を乗せた漁船が嵐で遭難し、尖閣諸島の魚釣島に漂着した。島にいた日本人と、石垣島の人々は、漁民たちを救助し、手厚く世話をして、中国に送り届けた"},{"id":"disputes-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"沖ノ鳥島――「島」か「岩」か","l":"disputes","x":"日本の最も南の端の沖ノ鳥島は、東京から約1700キロメートル離れた太平洋の上にある。満潮の時には、海面の上に出ているのは、ベッドほどの大きさの2つの小さな岩だけである。日本は、この"},{"id":"dutch-independence-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"60ギルダーのマンハッタン島","l":"dutch-independence","x":"1626年、オランダ西インド会社のミヌイットは、ハドソン川の河口のマンハッタン島を、先住民から、60ギルダー相当の品物と引き換えに「買い取った」とされる。のちに、この金額は24ドル"},{"id":"dutch-independence-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"チューリップ・バブル","l":"dutch-independence","x":"オランダの繁栄の陰で、人々は、奇妙な熱狂にとりつかれた。チューリップである。16世紀にオスマン帝国から伝わったチューリップは、オランダで大流行した（→「オスマン帝国の統治と社会」の"},{"id":"dutch-independence-t3","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"dutch-independence","x":"映画『真珠の耳飾りの少女』（2003年）：フェルメールの名画をもとに、画家の家で働く少女との関係を想像で描いた映画。黄金時代のオランダの都市デルフトの暮らしが再現されている。作品は"},{"id":"east-asia-early-t1","k":"term","f":"deep","kj":"深掘り｜ことば","t":"漢字は朝鮮半島を経て伝わった","l":"east-asia-early","x":"楽浪郡の遺跡からは、紀元前45年の楽浪郡の各県の人口を記録した木簡（「楽浪郡初元四年県別戸口簿」）が見つかっている。それによれば、楽浪郡には、約4万3000戸、28万人余りが登録さ"},{"id":"east-asia-early-t2","k":"source","f":"src","kj":"史料｜記録","t":"弁辰の鉄","l":"east-asia-early","x":"原文國出鐵，韓、濊、倭皆從取之。諸市買皆用鐵，如中國用錢。現代語訳国は鉄を産出し、韓・濊・倭はみなこれを取っている。どの市での売買にも鉄を用いており、それは中国で銭を用いるのと同じ"},{"id":"east-asia-early-t3","k":"source","f":"src","kj":"史料｜記録","t":"中国の史書に記された倭","l":"east-asia-early","x":"原文夫樂浪海中有倭人，分為百餘國，以歲時來獻見云。現代語訳そもそも楽浪の海の中に倭人がおり、分かれて百余りの国をなしている。毎年、季節ごとにやって来て、貢ぎ物を献じ、皇帝に謁見する"},{"id":"east-asia-early-t4","k":"debate","f":"think","kj":"考える｜諸説あり","t":"金印は本物か","l":"east-asia-early","x":"金印の発見のいきさつには、はっきりしない点が多く、発見した人物や正確な場所についても、記録によって食い違いがある。そのため、江戸時代の偽作ではないかとする説も唱えられてきた。しかし"},{"id":"east-asia-early-t5","k":"source","f":"src","kj":"史料｜記録","t":"『魏志』倭人伝が記す卑弥呼","l":"east-asia-early","x":"原文其國本亦以男子為王，住七八十年，倭國亂，相攻伐歷年，乃共立一女子為王，名曰卑彌呼，事鬼道，能惑眾。現代語訳その国（倭）は、もとは男子を王としていた。70〜80年たつと、倭国は乱"},{"id":"east-asia-early-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"邪馬台国はどこにあったのか","l":"east-asia-early","x":"倭人伝は、帯方郡から邪馬台国までの道のりを、方角と距離（または日数）で記している。ところが、その記述どおりに進むと、九州のはるか南の海の上に出てしまう。そのため、方角か距離のどちら"},{"id":"east-asia-early-t7","k":"now","f":"now","kj":"いま","t":"古代史をめぐる歴史論争","l":"east-asia-early","x":"古代の東アジアの歴史は、現在の国家の枠組みとは一致しない。そのため、古代の国家がどの国の歴史に属するのかが、現代の国家間の争点になることがある。その代表が、高句麗の帰属をめぐる中国"},{"id":"east-asia-early-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"east-asia-early","x":"手塚治虫『火の鳥 黎明編』（漫画、1967年）：3世紀の日本列島を舞台に、ヤマタイ国の女王ヒミコと、不老不死をもたらす「火の鳥」をめぐる人々の物語。ヒミコを、老いを恐れる女王として"},{"id":"east-india-companies-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ナツメグの島とマンハッタン島","l":"east-india-companies","x":"バンダ諸島の中の小さなルン島だけは、イギリスが占領を続けていた。17世紀後半、イギリスとオランダは、北アメリカやアジアをめぐって戦争をくり返した。1667年のブレダの和約で、両国は"},{"id":"east-india-companies-t2","k":"war","f":"deep","kj":"深掘り｜戦術","t":"バタヴィア号の悲劇","l":"east-india-companies","x":"1629年6月、オランダ東インド会社の新造の大型船バタヴィア号は、処女航海の途中、オーストラリアの西の沖のサンゴ礁に乗り上げて難破した。乗っていた約340人の多くは、近くの小さな無"},{"id":"east-india-companies-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「戦争と商売は両立しない」――トマス・ローの忠告","l":"east-india-companies","x":"1615年、イギリス国王ジェームズ1世は、外交官トマス・ローを、ムガル帝国の皇帝ジャハーンギールのもとに大使として送った。ローは、4年近くインドに滞在し、皇帝の宮廷で、イギリスの商"},{"id":"east-india-companies-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"キャラコ熱","l":"east-india-companies","x":"イギリス東インド会社がインドから運んだ商品の中心は、香辛料ではなく、綿布であった。インドの職人が手で織り、色鮮やかに染め上げた薄くて軽い綿布は、インドの南西部の港カリカットの名にち"},{"id":"eastern-europe-1989-t1","k":"source","f":"src","kj":"史料｜記録","t":"勝利広場の説教","l":"eastern-europe-1989","x":"1979年6月2日、教皇となって初めて祖国を訪れたヨハネ・パウロ2世は、ワルシャワの中心の勝利広場で、数十万の群衆を前にミサを捧げた。説教の最後に、教皇は、こう祈った。「聖霊よ、降"},{"id":"eastern-europe-1989-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「この地の面を新たにせよ」――ヨハネ・パウロ2世のワルシャワのミサ","l":"eastern-europe-1989","x":"1979年6月2日、前年にポーランド出身者として初めてローマ教皇に選ばれたヨハネ・パウロ2世は、故郷のポーランドに帰り、ワルシャワの勝利広場で、数十万人の人々を前にミサを行った。共"},{"id":"eastern-europe-1989-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"国境のピクニック","l":"eastern-europe-1989","x":"1989年8月19日、ハンガリー西部の町ショプロンの郊外の、オーストリアとの国境で、「汎ヨーロッパ・ピクニック」という催しが開かれた。国境の門を、3時間だけ象徴的に開き、両国の人々"},{"id":"eastern-europe-1989-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「私の知るかぎり、ただちに、遅滞なく」――シャボウスキーの記者会見","l":"eastern-europe-1989","x":"1989年11月9日の夕方、東ベルリンで、東ドイツの社会主義統一党の広報担当の政治局員ギュンター・シャボウスキーは、テレビで生中継されていた記者会見の終わり近くに、手元のメモを読み"},{"id":"eastern-europe-1989-t5","k":"source","f":"src","kj":"史料｜記録","t":"バルコニーの演説","l":"eastern-europe-1989","x":"1989年12月16日、西部の都市ティミショアラで、政府に批判的な牧師の強制退去に抗議する人々に、軍が発砲した。12月21日、チャウシェスクは、首都ブカレストの共産党本部のバルコニ"},{"id":"eastern-europe-1989-t6","k":"view","f":"think","kj":"考える｜別の視点","t":"日本と東欧革命","l":"eastern-europe-1989","x":"東ヨーロッパの激変は、日本にとっても、遠い出来事ではなかった。1990年1月、海部俊樹首相は、日本の首相として初めて、ポーランドとハンガリーを訪問し、民主化と市場経済への移行を支え"},{"id":"eastern-europe-1989-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"eastern-europe-1989","x":"映画『善き人のためのソナタ』（2006年、ドイツ）：東ドイツの秘密警察（シュタージ）の盗聴担当の将校が、監視していた劇作家の生き方に心を動かされていく物語。映画『グッバイ、レーニン"},{"id":"eastern-question-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「われわれの手には、病人がいる」――ニコライ1世の言葉","l":"eastern-question","x":"1853年1月、ロシア皇帝ニコライ1世は、サンクトペテルブルクの宮廷で、イギリス大使シーモアと話し合い、オスマン帝国について、こう語った。シーモアがイギリス政府に送った報告によれば"},{"id":"eastern-question-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"スープ鍋をひっくり返せ","l":"eastern-question","x":"イェニチェリの部隊は、もともとスルタンの「台所」で養われる兵士たちという考え方で組織されていた。部隊の指揮官は「スープ係（チョルバジュ）」と呼ばれ、ほかにも「料理長」「パン焼き係」"},{"id":"eastern-question-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"写真のアルバムを贈ったスルタン","l":"eastern-question","x":"アブデュルハミト2世は、宮殿からほとんど外に出ず、暗殺を恐れて、イスタンブルの丘の上のユルドゥズ宮殿にこもっていた。その彼が熱心に用いたのが、写真であった。彼は、写真家たちに、帝国"},{"id":"egypt-life-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"同じ「神権政治」でも","l":"egypt-life","x":"メソポタミアのシュメール人の都市国家も、エジプトも、「神権政治」の国と説明される。しかし、その中身は少し違う。シュメールの王（ルガル）は、都市の守り神に仕え、神の代理として都市を治"},{"id":"egypt-life-t2","k":"source","f":"src","kj":"史料｜記録","t":"オシリスの死と復活","l":"egypt-life","x":"オシリスはエジプトを治める善良な王だった。しかし、弟のセトにねたまれて殺され、体はばらばらにされてエジプト中にまき散らされた。オシリスの妻イシスは、各地を探し回って夫の体を集め、つ"},{"id":"egypt-life-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"動物のミイラ","l":"egypt-life","x":"ミイラにされたのは人間だけではなかった。猫・トキ・ハヤブサ・ワニ・犬などの動物も、神の使いとして大量にミイラにされ、神殿に奉納された。サッカラのトキの地下墓地からは、数百万体ものト"},{"id":"egypt-life-t4","k":"source","f":"src","kj":"史料｜記録","t":"死者の書の「否定告白」から","l":"egypt-life","x":"私は人に悪を行わなかった。私は家畜を虐げなかった。私は神殿の供え物を奪わなかった。私は飢えさせなかった。私は泣かせなかった。私は殺さなかった。私は畑の境を動かさなかった。私は天秤の"},{"id":"egypt-life-t5","k":"confuse","f":"confuse","kj":"混同注意","t":"ヒエログリフと楔形文字","l":"egypt-life","x":"ヒエログリフ楔形文字地域エジプトメソポタミアを中心に西アジア一帯書き方石に刻む、パピルスにインクで書く粘土板に葦のペンを押しつける使った言語エジプト語のみシュメール語、アッカド語、"},{"id":"egypt-life-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"「やったぞ！」と叫んで気絶した","l":"egypt-life","x":"伝えられるところでは、1822年9月、ヒエログリフの解読に確信を得たシャンポリオンは、兄のいる研究所に駆け込み、「やったぞ！（ジュ・ティアン・ラフェール）」と叫んで、そのまま気を失"},{"id":"egypt-life-t7","k":"source","f":"src","kj":"史料｜記録","t":"「12キュビトなら飢饉」","l":"egypt-life","x":"1世紀のローマの博物学者プリニウス（大プリニウス）は、ナイル川の増水の高さと、その年の暮らしの関係を次のように記している。12キュビトの増水では飢饉となり、13キュビトでは飢えが残"},{"id":"egypt-life-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「縄張り師」は3・4・5の縄を使ったか","l":"egypt-life","x":"古代エジプトでは、神殿の基礎を定める儀式で、王と女神が杭と縄を使って建物の位置を決める「縄を張る」場面が描かれている。また、前5世紀ごろのギリシアの哲学者デモクリトスは、「線を描い"},{"id":"egypt-life-t9","k":"confuse","f":"confuse","kj":"混同注意","t":"太陽暦と太陰暦","l":"egypt-life","x":"太陽暦太陰暦もとにする天体太陽（季節のめぐり）月（満ち欠け）1年365日約354日（12か月）生まれた地域エジプトメソポタミア長所季節とずれない。農業に便利月の形で日付が分かるメソ"},{"id":"egypt-life-t10","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"欠勤届の理由","l":"egypt-life","x":"ある職人の出勤簿には、欠勤した日とその理由がずらりと書き込まれている。「病気」「目が悪い」といったもっともな理由のほかに、「サソリに刺された」「兄弟のミイラ作りのため」「ビールを造"},{"id":"egypt-life-t11","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"世界最古のストライキ","l":"egypt-life","x":"ラメス3世の治世第29年（前12世紀前半）、デル＝エル＝メディナの職人たちへの給料（穀物）の支給が遅れた。職人たちは仕事を放棄して持ち場を離れ、王の葬祭殿の裏に座り込んだ。記録に残"},{"id":"egypt-life-t12","k":"source","f":"src","kj":"史料｜記録","t":"「書記ほどよい仕事はない」","l":"egypt-life","x":"中王国時代に書かれた『職業の風刺』（ドゥアケティの教訓）は、父親が息子を書記の学校に連れていく道すがら、ほかの職業がいかにつらいかを説いて聞かせる、という形の作品である。鍛冶屋は炉"},{"id":"egypt-life-t13","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"egypt-life","x":"細川智栄子あんど芙～みん『王家の紋章』（漫画、1976年〜）：古代エジプトにタイムスリップした少女キャロルと、若きファラオのメンフィスの物語。半世紀近くにわたって連載が続く長寿作品"},{"id":"egypt-muhammad-ali-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"スフィンクスの前の侍","l":"egypt-muhammad-ali","x":"1864年、フランスに向かう途中の江戸幕府の使節団が、エジプトに立ち寄った。当時は、まだスエズ運河が開通しておらず、一行は、紅海のスエズで船を下り、鉄道でカイロを経てアレクサンドリ"},{"id":"egypt-muhammad-ali-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「アイーダ」は運河の開通を祝ったのか","l":"egypt-muhammad-ali","x":"ヴェルディのオペラ「アイーダ」は、スエズ運河の開通を記念してつくられた、とよく言われる。しかし、これは正確ではない俗説。運河の開通に合わせて、カイロには、新しいオペラ劇場が建てられ"},{"id":"egypt-muhammad-ali-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"日本人が見たウラービー","l":"egypt-muhammad-ali","x":"エジプトの運命は、同じ時代に不平等条約に苦しんでいた日本の人々にとって、他人事ではなかった。1880年代、ヨーロッパの視察に向かった政治家の谷干城は、その途中、セイロンで流刑中のウ"},{"id":"egypt-new-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"中王国の都は「テーベ」か","l":"egypt-new","x":"教科書では、中王国の都はテーベ、新王国の都もテーベと説明されることが多い。テーベが中王国を興した王家の本拠地で、王家の守り神アメンの信仰の中心だったからである。ただし、中王国の第1"},{"id":"egypt-new-t2","k":"source","f":"src","kj":"史料｜記録","t":"『シヌヘの物語』――故郷に葬られたい","l":"egypt-new","x":"中王国時代の物語『シヌヘの物語』の主人公シヌヘは、第12王朝の王アメンエムハト1世に仕える役人だった。遠征中に王の暗殺を知ったシヌヘは、なぜか恐ろしくなって逃げ出し、シリア・パレス"},{"id":"egypt-new-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「カバがうるさくて眠れない」","l":"egypt-new","x":"新王国時代に書かれた物語の断片に、こんな話がある。ヒクソスの王アペピが、テーベの王セケンエンラーに使者を送り、「おまえの町の池のカバが、夜うるさく鳴くので眠れない。なんとかせよ」と"},{"id":"egypt-new-t4","k":"war","f":"deep","kj":"深掘り｜戦術","t":"メギドの戦い――狭い山道を選んだ王","l":"egypt-new","x":"前1457年ごろ、トトメス3世は、パレスチナ北部の要衝メギドに集まったシリア・パレスチナの諸侯の連合軍と戦った。カルナック神殿の壁に刻まれた『トトメス3世年代記』によれば、メギドへ"},{"id":"egypt-new-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"つけひげの女王――消された記憶","l":"egypt-new","x":"ハトシェプストの像には、女性の姿で表されたものと、王の頭巾をかぶり、あごに儀式用のつけひげをつけた男性の王の姿で表されたものがある。ファラオは本来男性であるという考えが強かったため"},{"id":"egypt-new-t6","k":"source","f":"src","kj":"史料｜記録","t":"王たちの手紙――「わが兄弟よ」","l":"egypt-new","x":"アマルナ文書の大国の王たちは、互いに「わが兄弟」と呼び合っている。対等な大国どうしであることを示す呼び方だった。一方、シリア・パレスチナの小国の王たちは、エジプト王を「わが主、わが"},{"id":"egypt-new-t7","k":"view","f":"think","kj":"考える｜別の視点","t":"「国際社会」はヨーロッパで生まれたのではない","l":"egypt-new","x":"主権を持つ国々が互いを対等と認め、外交使節を送り合い、条約を結ぶ――こうした「国際社会」のしくみは、近代ヨーロッパで生まれたものと説明されることが多い。しかし、アマルナ文書に見られ"},{"id":"egypt-new-t8","k":"confuse","f":"confuse","kj":"混同注意","t":"アメンホテプ4世＝イクナートン","l":"egypt-new","x":"同じ人物が二つの名前で呼ばれるので注意したい。即位したときの名がアメンホテプ4世（「アメンは満足する」の意味）で、改革の途中でイクナートン（アクエンアテン）と改名した。試験では、ど"},{"id":"egypt-new-t9","k":"now","f":"now","kj":"いま","t":"ネフェルティティの胸像はどこにあるべきか","l":"egypt-new","x":"アマルナ美術の傑作として名高いのが、王妃ネフェルティティの彩色胸像である。1912年にドイツの調査隊がアマルナの彫刻家の工房跡で発見し、現在はベルリンの新博物館に展示されている。画"},{"id":"egypt-new-t10","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「ファラオの呪い」","l":"egypt-new","x":"墓の発掘を資金面で支えたカーナヴォン卿が、発見の翌年に急死したことから、「王の眠りを妨げた者には死が訪れる」という「ファラオの呪い」の噂が新聞をにぎわせた。俗説しかし、カーナヴォン"},{"id":"egypt-new-t11","k":"source","f":"src","kj":"史料｜記録","t":"夫を失った王妃の手紙","l":"egypt-new","x":"ヒッタイト王シュッピルリウマ1世の業績を、息子のムルシリ2世がまとめた記録に、不思議な話が残っている。エジプトの王が亡くなったころ、エジプトの王妃からヒッタイト王に手紙が届いたとい"},{"id":"egypt-new-t12","k":"trivia","f":"side","kj":"こぼれ話","t":"パスポートを持ったミイラ","l":"egypt-new","x":"1976年、カイロの博物館に保管されていたラメス2世のミイラが、カビによる傷みの治療のため、飛行機でパリに運ばれることになった。このとき、エジプト政府はミイラのためにパスポートを発"},{"id":"egypt-new-t13","k":"trivia","f":"side","kj":"こぼれ話","t":"引っ越したアブ＝シンベル神殿","l":"egypt-new","x":"ラメス2世は、エジプト各地に巨大な神殿や像を建てた。その代表が、ヌビアの岩山を掘り抜いて造られたアブ＝シンベル神殿である。入口には高さ約20mのラメス2世の座像が4体並ぶ。神殿の最"},{"id":"egypt-new-t14","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"王を殺した後宮の陰謀","l":"egypt-new","x":"ラメス3世の最期については、裁判の記録（「後宮陰謀パピルス」）が残っている。王の側室の一人が、自分の息子を王位につけようと、後宮の女性や役人たちと陰謀をめぐらせたのである。陰謀にか"},{"id":"egypt-new-t15","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"egypt-new","x":"細川智栄子あんど芙〜みん『王家の紋章』（漫画、1976年〜連載）：古代エジプトの王子の墓を発掘した一家の娘キャロルが、古代エジプトにタイムスリップする物語。ヒッタイトやアッシリアな"},{"id":"egypt-old-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"増水を測る「ナイロメーター」","l":"egypt-old","x":"ナイル川の増水の高さは、その年の収穫を、そして税の額を決める重要な情報だった。増水が少なすぎれば畑に水が行き渡らず飢饉になり、多すぎれば村や堤防が流される。そこでエジプトでは、川の"},{"id":"egypt-old-t2","k":"relic","f":"src","kj":"史料｜遺物","t":"ナルメルのパレット","l":"egypt-old","x":"上エジプトの古都ヒエラコンポリスの神殿跡から見つかった、高さ64センチの石の板である。化粧用の顔料をすりつぶすパレットの形をしているが、実用品ではなく、神殿に奉納された記念品だった"},{"id":"egypt-old-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"メソポタミアの王とエジプトの王","l":"egypt-old","x":"メソポタミアの王は、基本的に「神に選ばれた人間」であり、神の代理人として都市を治めた（アッカドのナラム＝シンのように自らを神とした王は例外である）。これに対してエジプトの王は、生ま"},{"id":"egypt-old-t4","k":"source","f":"src","kj":"史料｜記録","t":"4500年前の業務日誌――メレルのパピルス","l":"egypt-old","x":"2013年、紅海に面したワディ・アル＝ジャルフという古代の港の跡で、フランスとエジプトの調査隊が、パピルスの束を発見した。世界最古の文字の書かれたパピルスである。そのなかに、クフ王"},{"id":"egypt-old-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ピラミッドは奴隷が造った？","l":"egypt-old","x":"ピラミッドは、王に鞭打たれた何十万人もの奴隷が造らされた――。このイメージは、ヘロドトスが「10万人が3か月交代で20年かけて造った」と書いたことや、映画などの影響で広まった。しか"},{"id":"egypt-old-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ピラミッドは何のために造られたのか","l":"egypt-old","x":"ピラミッドは王の墓である、というのが一般的な考え方である。王の遺体を納めるための墓室があり、周囲には王の魂をまつる葬祭殿が設けられた。ピラミッドの形は、太陽の光が天から地上に降り注"},{"id":"egypt-old-t7","k":"source","f":"src","kj":"史料｜記録","t":"少年王の手紙――「踊る小人」を早く連れて来い","l":"egypt-old","x":"ペピ2世が即位して間もないころの、ほほえましい手紙が残っている。南方のヌビアへの遠征隊を率いた役人ハルクフが、遠い南の国から「神の踊りを踊る小人（ピグミー）」を連れて帰る、と王に報"},{"id":"egypt-old-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"egypt-old","x":"映画『ハムナプトラ 失われた砂漠の都』（1999年）：よみがえったミイラと戦う冒険映画。悪役の神官の名「イムホテップ」は、古王国のジェセル王の階段ピラミッドを設計した実在の人物に由"},{"id":"elizabethan-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ボウリングをするドレーク","l":"elizabethan","x":"1588年7月、アルマダがイギリスの南西の沖に現れたという知らせが、プリマスに届いた。そのとき、ドレークは、仲間たちとボウリング（芝生の上で球を転がす遊び）をしていた。知らせを聞い"},{"id":"elizabethan-t2","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"elizabethan","x":"映画『エリザベス』（シェカール・カプール監督、1998年）：ケイト・ブランシェットが、王位について「国家と結婚した」女王となっていくエリザベス1世を演じた。映画『恋におちたシェイク"},{"id":"england-france-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"二人の王の妃アリエノール","l":"england-france","x":"アリエノール（英語名エレノア、1122ごろ〜1204年）は、15歳で南フランスの大貴族アキテーヌ公の地位を受け継ぎ、フランス王ルイ7世と結婚した。彼女は、夫とともに第2回十字軍に加"},{"id":"england-france-t2","k":"source","f":"src","kj":"史料｜記録","t":"大聖堂の殺人","l":"england-france","x":"ヘンリ2世は、教会の聖職者を国王の裁判所で裁こうとして、親友であったカンタベリー大司教トマス・ベケットと激しく対立した。1170年、王が怒りにまかせて、「あの厄介な坊主を始末してく"},{"id":"england-france-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「英語を話せない王子」","l":"england-france","x":"エドワード1世は、1283年にウェールズを征服すると、ウェールズの人々の反発を和らげるため、「ウェールズで生まれ、英語を一言も話さない王子を、おまえたちの君主にしよう」と約束し、ウ"},{"id":"england-france-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"沼に沈んだ王の財宝","l":"england-france","x":"「欠地王」ジョンは、マグナ・カルタを認めた翌年の1216年、反乱を起こした諸侯や、彼らが招いたフランス王子ルイの軍と戦いながら、イングランド東部を移動していた。年代記作者ロジャー・"},{"id":"england-france-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"王冠よりも高い「茨の冠」","l":"england-france","x":"1239年、ルイ9世は、資金に困っていたコンスタンティノープルのラテン帝国の皇帝から、キリストが十字架にかけられる前にかぶらされたとされる「茨の冠」などの聖遺物を買い取った（→「十"},{"id":"england-france-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"england-france","x":"映画『冬のライオン』（1968年）：イングランド王ヘンリ2世と、王妃アリエノール・ダキテーヌ、そして後継ぎの座を争うリチャード（獅子心王）やジョンらの、愛憎に満ちた家族の争いを描く"},{"id":"english-revolution-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"火薬陰謀事件","l":"english-revolution","x":"1605年11月5日の未明、ロンドンの国会議事堂の地下室で、一人の男が捕らえられた。ガイ・フォークスである。地下室には、36樽もの火薬が隠されていた。この日、国会の開会式が行われ、"},{"id":"english-revolution-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「これまで聞いたことのないうめき声」――国王の処刑","l":"english-revolution","x":"1649年1月30日の午後、ロンドンのホワイトホールの宮殿の前に設けられた処刑台で、国王チャールズ1世の首がはねられた。群衆の中にいた17歳の学生フィリップ・ヘンリーは、その瞬間を"},{"id":"english-revolution-t3","k":"voice","f":"src","kj":"史料｜証言","t":"ドロヘダの虐殺（1649年）","l":"english-revolution","x":"国王を処刑した後、クロムウェルは、王党派とカトリックの拠点となっていたアイルランドに遠征した。1649年9月、東部の港町ドロヘダを攻め落としたクロムウェルの軍は、降伏を拒んだ守備兵"},{"id":"english-revolution-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"さらされたクロムウェルの首","l":"english-revolution","x":"1658年、クロムウェルは病死し、ウェストミンスター寺院に、国王のように盛大に葬られた。しかし、王政復古の後の1661年1月30日、チャールズ1世の処刑からちょうど12年目のその日"},{"id":"english-revolution-t5","k":"voice","f":"src","kj":"史料｜証言","t":"ピープスの日記――ペストと大火","l":"english-revolution","x":"王政復古期の海軍の役人サミュエル・ピープスは、日々の出来事を暗号のような速記で詳しく日記に書いた。1665年、ロンドンをペストが襲った。原文But, Lord! how empty"},{"id":"english-revolution-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"english-revolution","x":"映画『クロムウェル』（1970年）：ピューリタン革命を率いたクロムウェルと、処刑された国王チャールズ1世の対立を描いた映画。作品は史実をもとにした創作を含むことが多い。史実との違い"},{"id":"enlightenment-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「むすんでひらいて」とルソー","l":"enlightenment","x":"ルソーは、作曲家でもあった。1752年、彼の作曲したオペラ『村の占い師』は、フォンテーヌブローの宮廷で上演されて大成功を収め、国王ルイ15世も、そのアリアを口ずさんだという。日本の"},{"id":"enlightenment-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ヴォルテールの名言？","l":"enlightenment","x":"「私はあなたの意見には反対だ。だが、あなたがそれを主張する権利は、命をかけて守る」。言論の自由を語る時に、よく引用される言葉である。しかし、この言葉は、ヴォルテール自身が書いたもの"},{"id":"enlightenment-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"女帝に本を売った哲学者","l":"enlightenment","x":"ディドロは、娘の結婚の持参金に困って、自分の蔵書を売りに出したことがある。それを知ったロシアの女帝エカチェリーナ2世は、蔵書を高値で買い取ったうえで、「ディドロが生きている間は、彼"},{"id":"enlightenment-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"理性の時代の女性たち","l":"enlightenment","x":"啓蒙思想の担い手のほとんどは男性であった。しかし、その中で、ひときわ輝いた女性がいる。ヴォルテールの恋人であったエミリー・デュ・シャトレである。数学と物理学に秀でた彼女は、ニュート"},{"id":"enlightenment-t5","k":"war","f":"deep","kj":"深掘り｜戦術","t":"リスボン大地震と啓蒙の時代","l":"enlightenment","x":"1755年11月1日、カトリックの祝日である諸聖人の日の朝9時40分ごろ、ポルトガルの首都リスボンを巨大な地震が襲った。マグニチュードは8.5〜9と推定されている。教会で祈りをささ"},{"id":"enlightenment-t6","k":"voice","f":"src","kj":"史料｜証言","t":"「すべては善である、と叫ぶ哲学者たちよ」――ヴォルテール「リスボンの災厄についての詩」","l":"enlightenment","x":"リスボンの地震の知らせを聞いたヴォルテールは、すぐに長い詩を書いた。この世界は神がつくった最善の世界であり、起こることはすべて善である、という当時の楽観的な考え方に、彼は廃墟と死者"},{"id":"enlightenment-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"enlightenment","x":"ヴォルテール『カンディード』（小説、1759年）：「この世界はありうる中で最善の世界である」と信じる若者カンディードが、戦争、リスボン大地震、異端審問などの災難に次々と遭う物語。楽"},{"id":"eu-expansion-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「私はポーランドに残ります」","l":"eu-expansion","x":"東への拡大は、西ヨーロッパの人々に、不安も呼び起こした。賃金の安い東の国々から、労働者が大量に流れ込んでくるのではないか。2005年、フランスでは、EUの「憲法条約」の批准をめぐる"},{"id":"eu-expansion-t2","k":"source","f":"src","kj":"史料｜記録","t":"「何でもする」","l":"eu-expansion","x":"2012年7月26日、ロンドンで開かれた投資家の会議で、ヨーロッパ中央銀行（ECB）の総裁ドラギは、こう語った。「私たちの権限の範囲内で、ECBは、ユーロを守るためなら、何でもする"},{"id":"eu-expansion-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「何でもする用意がある。そして、それで十分だ」――ドラギの演説","l":"eu-expansion","x":"2012年、ギリシアの財政危機に始まったユーロの危機は、スペインやイタリアにまで広がり、市場では、ユーロが崩壊するのではないかという不安が高まっていた。7月26日、ロンドンで開かれ"},{"id":"eu-expansion-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「私たちはやり遂げられる」――メルケルの記者会見","l":"eu-expansion","x":"2015年の夏、シリアの内戦などから逃れた何十万人もの難民が、地中海やバルカン半島を越えて、ヨーロッパに押し寄せた（→「アラブの春とシリア内戦」の回）。8月31日、ドイツのメルケル"},{"id":"eu-expansion-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"日本からのメッセージ","l":"eu-expansion","x":"ブレグジットは、日本の企業にとっても、大きな問題であった。1980年代から、日本の自動車会社や電機会社は、英語が通じ、EUの市場に関税なしで輸出できるイギリスを、ヨーロッパの拠点と"},{"id":"europe-integration-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"選挙に一度も出なかった「ヨーロッパの父」","l":"europe-integration","x":"ジャン・モネは、1888年、フランス西部の町コニャックで、ブランデーの商家に生まれた。16歳で学校をやめ、家業のコニャックを売るために、イギリスやカナダ、アメリカを渡り歩いた。モネ"},{"id":"europe-integration-t2","k":"source","f":"src","kj":"史料｜記録","t":"「ダラムの炭鉱夫が承知しない」","l":"europe-integration","x":"シューマン宣言が出された時、イギリスの労働党の政府は、石炭と鉄鋼の産業を国有化したばかりであった。その管理を、外国と共同の機関に委ねるなど、とうてい考えられなかった。閣議で、副首相"},{"id":"europe-integration-t3","k":"source","f":"src","kj":"史料｜記録","t":"「戦争が考えられないだけでなく、物理的に不可能となる」――シューマン宣言","l":"europe-integration","x":"1950年5月9日の夕方、フランスの外務大臣ロベール・シューマンは、パリの外務省の「時計の間」で、記者たちを前に、短い声明を読み上げた。原文L'Europe ne se fera "},{"id":"europe-integration-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"白紙に署名した？","l":"europe-integration","x":"ローマ条約の調印式をめぐっては、こんな話が伝えられている。条約の本文の印刷が、調印の日に間に合わなかった。そこで、首脳たちが署名した条約の書類は、最初のページと署名のページを除いて"},{"id":"europe-integration-t5","k":"source","f":"src","kj":"史料｜記録","t":"「イギリスは島国である」","l":"europe-integration","x":"1963年1月14日、ド＝ゴールは、記者会見で、イギリスの加盟に拒否を突きつけた。「イギリスは、実のところ、島国であり、海洋国である。その交易や市場や食料の供給によって、きわめて多"},{"id":"europe-integration-t6","k":"voice","f":"src","kj":"史料｜証言","t":"「言葉が役に立たないとき、人がすることをした」――ブラントの跪き","l":"europe-integration","x":"1970年12月7日、西ドイツの首相ヴィリー・ブラントは、ポーランドとの国交正常化の条約に署名するためにワルシャワを訪れ、第二次世界大戦中のワルシャワ・ゲットーの蜂起の記念碑に、花"},{"id":"europe-integration-t7","k":"person","f":"deep","kj":"深掘り｜人物","t":"アウシュヴィッツから議長席へ","l":"europe-integration","x":"直接選挙で選ばれた最初のヨーロッパ議会の議長に選ばれたのは、フランスのシモーヌ・ヴェイユであった。ヴェイユは、ユダヤ人の家庭に生まれ、16歳の時、家族とともにアウシュヴィッツに送ら"},{"id":"europe-integration-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"ポワティエの戦い、再び","l":"europe-integration","x":"1980年代、ヨーロッパの市場には、日本の自動車や家電製品があふれていた。とくに、ビデオデッキ（VTR）の輸入は急増し、ヨーロッパのメーカーは、苦境に立たされていた。1982年10"},{"id":"fall-west-rome-t1","k":"source","f":"src","kj":"史料｜記録","t":"「西のローマの帝国は滅びた」","l":"fall-west-rome","x":"原文Hesperium Romanae gentis imperium, quod septingentesimo nono urbis conditae anno primus "},{"id":"fall-west-rome-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"西ローマ帝国はいつ滅びたのか","l":"fall-west-rome","x":"476年の「滅亡」には、いくつもの留保がつく。476年に廃位されたロムルスは、東ローマ帝国からは正式な皇帝と認められていなかった。東ローマが認めていた西方の皇帝は、ダルマティアに逃"},{"id":"fall-west-rome-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"ローマ滅亡の原因は210通り","l":"fall-west-rome","x":"ローマ帝国（西ローマ帝国）がなぜ滅びたのかは、歴史学で最も多く論じられてきた問題の一つである。18世紀のイギリスの歴史家ギボンは、大著『ローマ帝国衰亡史』（1776〜1789年）で"},{"id":"fall-west-rome-t4","k":"source","f":"src","kj":"史料｜記録","t":"「この男には骨がない」","l":"fall-west-rome","x":"オドアケルが「神はどこにいるのか」と叫ぶと、テオドリックは剣を振り下ろし、鎖骨から腰まで切り裂いた。そして、こう言ったという。「まったく、この悪党には骨というものがなかった。」出典"},{"id":"fall-west-rome-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"ボエティウス――獄中の哲学者","l":"fall-west-rome","x":"ボエティウス（480年ごろ〜524年ごろ）は、ローマの名門貴族の出身で、テオドリックのもとで最高の官職にまで昇った。彼は、プラトンとアリストテレスの著作をすべてラテン語に翻訳する計"},{"id":"fall-west-rome-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"消された王の宮廷","l":"fall-west-rome","x":"ラヴェンナのサンタポリナーレ・ヌオーヴォ聖堂は、テオドリックが、アリウス派の宮廷教会として建てた聖堂である。その壁面には、テオドリックの宮殿を描いたモザイク画がある。画像はオンライ"},{"id":"fall-west-rome-t7","k":"works","f":"works","kj":"作品","t":"この時代にまつわる作品","l":"fall-west-rome","x":"ギボン『ローマ帝国衰亡史』（1776〜1789年）：五賢帝の時代から1453年のコンスタンティノープル陥落までを描いた大著。近代的な歴史叙述の古典とされ、「衰亡（デクライン＝アンド"},{"id":"fascism-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"「沈黙」から始まる演説――ヒトラーの話術と、その練習","l":"fascism","x":"ヒトラーの権力の最大の武器は、演説であった。同時代の人々の証言によれば、その演説には、いくつかのはっきりした特徴があった。沈黙で始める：演壇に立ったヒトラーは、すぐには話し始めなか"},{"id":"fascism-t2","k":"source","f":"src","kj":"史料｜記録","t":"『わが闘争』には何が書かれていたか","l":"fascism","x":"1923年のミュンヘン一揆に失敗して、ランツベルクの刑務所に入れられたヒトラーは、獄中で、自分の生い立ちと思想を口述し、側近のルドルフ・ヘスらに書き取らせた。こうしてできた『わが闘"},{"id":"fascism-t3","k":"source","f":"src","kj":"史料｜記録","t":"「名誉は奪えない」","l":"fascism","x":"1933年3月23日、全権委任法 が審議された国会の議場は、ベルリンのクロル・オペラ劇場に移されていた。焼けた議事堂は使えなかったからである。議場の周りを、褐色の制服の突撃隊と、黒"},{"id":"fascism-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「その瞬間から、私は身も心もアドルフ・ヒトラーのものになった」――ヒトラー・ユーゲントの少年","l":"fascism","x":"なぜ、多くの若者がナチスに熱狂したのだろうか。恐慌のさなかのドイツでは、失業者があふれ、将来に希望を持てない若者たちが多かった。ナチスは、若者たちに、制服と、行進と、キャンプファイ"},{"id":"fascism-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"誰も受け取らなかった「国民車」","l":"fascism","x":"1938年、ヒトラーは、すべてのドイツの家庭に車を、と宣言し、新しい「国民車（フォルクスワーゲン）」の工場の起工式を行った。設計したのは、技術者フェルディナント・ポルシェであった。"},{"id":"fascism-t6","k":"view","f":"think","kj":"考える｜別の視点","t":"ベルリン・オリンピック","l":"fascism","x":"1936年8月、ベルリンでオリンピックが開かれた。ナチスは、この大会を、新しいドイツの力と繁栄を世界に示す舞台とした。聖火リレーは、この大会で初めて行われた。アメリカの黒人の陸上選"},{"id":"fascism-t7","k":"person","f":"deep","kj":"深掘り｜人物","t":"総統の私生活――ヒトラーの家庭","l":"fascism","x":"ヒトラーの父アロイスは、オーストリアの税関の役人で、厳しく、しばしば息子に手を上げた。画家を夢見たヒトラーは、ウィーンの美術アカデミーを2度受験し、2度とも不合格となった。母クララ"},{"id":"fascism-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"カメラの前の暗殺――マルセイユ事件","l":"fascism","x":"1934年10月9日、フランスを公式に訪れたユーゴスラヴィアの国王アレクサンダル1世は、南フランスの港町マルセイユで、出迎えたフランスの外相バルトゥーとともに、オープンカーでパレー"},{"id":"fascism-t9","k":"person","f":"deep","kj":"深掘り｜人物","t":"スペインで死んだ日本人","l":"fascism","x":"国際旅団の義勇兵の中には、日本人もいた。北海道の出身で、若くしてアメリカに渡り、ニューヨークで料理人として働いていたジャック白井である。白井は、アメリカ人の義勇兵の部隊「エイブラハ"},{"id":"fascism-t10","k":"voice","f":"src","kj":"史料｜証言","t":"「ゲルニカは完全に破壊された」","l":"fascism","x":"1937年4月26日、スペイン北部のバスク地方の町ゲルニカは、フランコ側を支援するドイツの空軍部隊（コンドル軍団）とイタリア空軍の爆撃を受けた。月曜日の市の日で、町には多くの人々が"},{"id":"fascism-t11","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"fascism","x":"映画『独裁者』（チャールズ・チャップリン監督、1940年）：ヒトラーをモデルにした独裁者ヒンケルと、彼にそっくりなユダヤ人の床屋を、チャップリンが一人二役で演じた。アメリカがまだ参"},{"id":"fatimid-buyid-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「この三十年、私は多くの苦労をした」――フェルドウスィー『シャー・ナーメ』","l":"fatimid-buyid","x":"アラブの征服の後、イランでは、アラビア語が、宗教と学問と行政の言葉となった。しかし、9〜10世紀、中央アジアのサーマーン朝などのもとで、アラビア文字で書くペルシア語の文学が、再び花"},{"id":"fatimid-buyid-t2","k":"works","f":"works","kj":"作品","t":"イスラーム世界の分裂にまつわる作品","l":"fatimid-buyid","x":"ナーセル・ホスロウ『旅行記（サファル・ナーメ）』：11世紀半ばのペルシア人の旅行家が、ファーティマ朝のカイロの繁栄を記録した旅行記。日本語訳がある（森本一夫訳、法政大学出版局）。ナ"},{"id":"feudalism-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"閉じこもった修道女ヴィボラーダ","l":"feudalism","x":"926年、マジャール人が、スイスのザンクト・ガレン修道院に迫った。修道院の近くでは、ヴィボラーダという女性が、小さな庵に自ら閉じこもって、祈りの生活を送っていた。マジャール人の襲撃"},{"id":"feudalism-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"ソールズベリーの誓い","l":"feudalism","x":"ノルマン人に征服されたイングランドでは、事情が少し異なっていた。ウィリアム1世（→「ノルマン人の移動」の回）は、1086年、ソールズベリーに国中の主な土地保有者を集めて、自分の直接"},{"id":"feudalism-t3","k":"mech","f":"deep","kj":"深掘り｜しくみ","t":"騎士1人は牛15頭分――なぜ主従関係が必要だったのか","l":"feudalism","x":"8世紀ごろのフランク人の法典『リブアリア法典』は、損害賠償の基準として、さまざまな物の値段を定めている。それによれば、牛1頭がおよそ3ソリドゥス（金貨）、軍馬1頭が12ソリドゥス、"},{"id":"feudalism-t4","k":"source","f":"src","kj":"史料｜記録","t":"修道院の財産目録","l":"feudalism","x":"9世紀前半、パリのサン・ジェルマン・デ・プレ修道院の院長イルミノンは、修道院がパリ周辺の各地に持つ荘園の土地と農民、その負担を、詳しく記録させた。これが「イルミノンの所領明細帳」で"},{"id":"feudalism-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「初夜権」はあったのか","l":"feudalism","x":"中世ヨーロッパの領主は、農奴の結婚の際、花嫁と最初の夜を過ごす権利（初夜権）を持っていた、という話が、よく語られる。しかし、中世の西ヨーロッパで、こうした権利が実際に行使されたこと"},{"id":"feudalism-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「封建制」とは何か","l":"feudalism","x":"「封建制」という言葉は、実は、中世の人々が使った言葉ではない。17〜18世紀のヨーロッパの法学者や思想家たちが、中世の社会のしくみをまとめて呼ぶために作った言葉である。この言葉は、"},{"id":"feudalism-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"feudalism","x":"『ローランの歌』（11世紀末ごろ）：カール大帝の甥ローランが、スペインからの帰途、ピレネー山中で敵に襲われて戦死する物語をうたった武勲詩。主君への忠誠と騎士の名誉の観念を伝える。映"},{"id":"financial-crisis-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「音楽が鳴っている間は、踊り続けなければならない」――シティグループのプリンス","l":"financial-crisis","x":"2007年7月、アメリカの住宅バブルが崩れ始め、サブプライム・ローンの焦げつきが問題となりつつあったころ、アメリカ最大の銀行グループの一つ、シティグループの最高経営責任者チャールズ"},{"id":"financial-crisis-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"90億ドルの小切手","l":"financial-crisis","x":"危機のさなか、日本の銀行が、意外な役割を果たした。リーマン・ブラザーズの破綻の後、次に危ないとされたのが、同じ投資銀行のモルガン・スタンレーであった。2008年9月末、日本の三菱U"},{"id":"financial-crisis-t3","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"年越し派遣村","l":"financial-crisis","x":"2008年の大晦日、東京の霞が関の官庁街に面した日比谷公園に、テントが張られた。仕事と同時に、会社の寮などの住まいも失った人々のための、「年越し派遣村」である。労働組合やNPOの人"},{"id":"financial-crisis-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「私は、欠陥を見つけた」――グリーンスパンの議会証言","l":"financial-crisis","x":"2008年10月23日、アメリカ議会の下院の公聴会に、1987年から2006年まで、18年あまりにわたって連邦準備制度理事会（FRB）の議長を務めたアラン・グリーンスパンが呼ばれた"},{"id":"financial-crisis-t5","k":"source","f":"src","kj":"史料｜記録","t":"ビットコインの最初のブロック","l":"financial-crisis","x":"2009年1月3日、インターネットの上に、新しい「通貨」が誕生した。サトシ・ナカモトと名乗る正体不明の人物（あるいはグループ）がつくった暗号資産（仮想通貨）、ビットコインである。ビ"},{"id":"financial-crisis-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"financial-crisis","x":"映画『マネー・ショート 華麗なる大逆転』（2015年）：サブプライム・ローンの崩壊を予測し、市場の破綻に賭けた投資家たちを描いた映画。原作はマイケル・ルイスのノンフィクションである"},{"id":"first-villages-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"顔を塗り込めた頭骨","l":"first-villages","x":"イェリコなどの新石器時代の遺跡からは、不思議なものが見つかっている。死者の頭骨に石膏を塗って顔の肉付けをし、目の部分に貝殻をはめ込んだ「漆喰頭骨」である。家の床下に葬られた死者の頭"},{"id":"first-villages-t2","k":"source","f":"src","kj":"史料｜記録","t":"「城壁は崩れ落ちた」――聖書のイェリコ","l":"first-villages","x":"旧約聖書の『ヨシュア記』は、イスラエルの民が、約束の地カナンに入ったとき、最初に城壁の町イェリコを攻めた物語を伝えている。民は、7日間、契約の箱をかついで町の周りを回り、7日目に、"},{"id":"first-villages-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"平等な社会だったのか","l":"first-villages","x":"チャタル＝ヒュユクの家々は、大きさも作りもほとんど同じで、特別に大きな屋敷や神殿のような建物は見つかっていない。人骨の分析でも、男女の食べ物や体格に大きな差はなかったという。そのた"},{"id":"first-villages-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"発掘者は嘘をついていた？","l":"first-villages","x":"チャタル＝ヒュユクを最初に本格的に発掘したのは、イギリスの考古学者ジェームズ・メラートである。1960年代、彼が発表した壁画の模写や、「地母神」をまつったとされる神殿の復元は、世界"},{"id":"first-villages-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"世界最古の土器は日本と中国で生まれた","l":"first-villages","x":"土器は、農耕とともに西アジアで生まれたと思われがちだが、実は最古の土器は東アジアで見つかっている。中国江西省の仙人洞遺跡では約2万年前の、日本の青森県・大平山元遺跡では約1万600"},{"id":"first-villages-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"240キロ先から運ばれた石","l":"first-villages","x":"ストーンヘンジの内側に並ぶ「ブルーストーン」と呼ばれる石は、約240キロメートル離れたウェールズの山地から運ばれてきたことが、岩石の分析で分かっている。重さは1個あたり2〜4トンも"},{"id":"first-villages-t7","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"アイスマンの持ち物と最後の食事","l":"first-villages","x":"アイスマンは、身長160センチほど、40代半ばの男性だった。毛皮の帽子をかぶり、何種類もの動物の皮を縫い合わせた服を着て、干し草を詰めた革の靴を履いていた。持ち物は、銅の刃をつけた"},{"id":"first-villages-t8","k":"relic","f":"src","kj":"史料｜遺物","t":"殺人事件だった","l":"first-villages","x":"発見から10年後の2001年、エックス線写真の再調査で、アイスマンの左肩に石の矢じりが刺さっていたことが分かった。矢は背後から放たれ、肩の動脈を傷つけていた。彼は出血多量で、短い時"},{"id":"first-villages-t9","k":"relic","f":"src","kj":"史料｜遺物","t":"1万年前の虐殺の跡――ナタルク遺跡","l":"first-villages","x":"ケニアのトゥルカナ湖の西にあるナタルク遺跡では、約1万年前の、少なくとも27人の人骨が見つかっている。そのうち多くの骨には、頭を棍棒のようなもので殴られた跡や、矢じりが刺さった跡が"},{"id":"first-villages-t10","k":"trivia","f":"side","kj":"こぼれ話","t":"世界最古の金の宝飾品――ヴァルナの墓地","l":"first-villages","x":"ブルガリアの黒海沿岸の町ヴァルナでは、前4600〜前4200年ごろの墓地が見つかっている。その中のある墓には、金の腕輪や首飾り、王笏のような飾りなど、合わせて1キログラムを超える金"},{"id":"five-dynasties-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「野の花が咲いたから、ゆっくり帰っておいで」","l":"five-dynasties","x":"銭鏐の妻は、毎年春になると、杭州から故郷の臨安に里帰りした。ある年、妻がなかなか戻らないので、銭鏐は手紙を送った。その手紙には、ただ一行、次のように書かれていたという伝承。原文陌上"},{"id":"five-dynasties-t2","k":"source","f":"src","kj":"史料｜記録","t":"「十四万の兵が、そろって鎧を脱いだ」","l":"five-dynasties","x":"四川の後蜀は、965年、宋の軍にわずか2か月ほどで攻め落とされた。降伏した後蜀の君主孟昶の妃で、詩人として知られた花蕊夫人は、宋の太祖に召し出され、詩を作るよう命じられた。彼女は、"},{"id":"five-dynasties-t3","k":"source","f":"src","kj":"史料｜記録","t":"銅の仏像を銭にする","l":"five-dynasties","x":"世宗は、寺院から没収した銅の仏像を溶かして、銅銭を鋳造させた。当時は、銅銭が不足して、商業や税の取り立てに支障が出ていたのである。これに反対する者に、世宗は次のように答えたという。"},{"id":"five-dynasties-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「点検、天子と作る」","l":"five-dynasties","x":"『宋史』などによれば、959年、世宗が遼への遠征の途中、届けられた文書の袋の中に、長さ3尺ほどの木の札が入っていた。そこには、「点検、天子と作る」と書かれていたという伝承。当時、禁"},{"id":"five-dynasties-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"雪の夜の訪問","l":"five-dynasties","x":"ある大雪の夜、太祖は、弟の趙光義とともに、突然、側近の趙普の屋敷を訪ねた。驚いた趙普が迎え入れると、太祖は、炉に炭をおこして肉を焼き、酒を飲みながら、「眠れないのだ。わが寝床の外は"},{"id":"five-dynasties-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「杯酒、兵権を釈く」","l":"five-dynasties","x":"961年のある夜、太祖は、自分の即位を支えた石守信ら禁軍の将軍たちを招いて、酒宴を開いた。酒が回ったころ、太祖は人払いをして、こう言った。「私は、あなたたちのおかげで天子となった。"},{"id":"five-dynasties-t7","k":"person","f":"deep","kj":"深掘り｜人物","t":"馮道――5つの王朝、10人を超える君主に仕えた宰相","l":"five-dynasties","x":"五代の時代を生きた官僚の中で、ひときわ異色の人物が馮道（882〜954年）である。彼は、後唐・後晋・遼・後漢・後周と、次々に入れ替わる王朝に仕え、そのほとんどで宰相などの最高位に就"},{"id":"five-dynasties-t8","k":"works","f":"works","kj":"作品","t":"五代十国と宋の建国にまつわる作品","l":"five-dynasties","x":"欧陽脩『新五代史』：北宋の欧陽脩が、儒教の道徳を重んじる立場から書き直した五代の歴史書。李存勗の三本の矢の話を含む「伶官伝」の序文は、名文として知られる。『水滸伝』の冒頭：明代の長"},{"id":"former-han-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"少女の嘆願と肉刑の廃止","l":"former-han","x":"前167年、ある地方の役人が罪を犯して、肉刑（鼻を削ぐ、足を切るなど、体を傷つける刑罰）を受けることになった。その末娘の緹縈は、父とともに都の長安に行き、文帝に上書した。「死んだ者"},{"id":"former-han-t2","k":"source","f":"src","kj":"史料｜記録","t":"武帝が受け継いだ富","l":"former-han","x":"原文漢興七十餘年之間，國家無事，非遇水旱之災，民則人給家足，都鄙廩庾皆滿，而府庫餘貨財。京師之錢累巨萬，貫朽而不可校。太倉之粟陳陳相因，充溢露積於外，至腐敗不可食。現代語訳漢が興っ"},{"id":"former-han-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"武帝は儒学を「国教」にしたのか","l":"former-han","x":"教科書では、武帝が董仲舒の献策によって「儒学を官学化した」と説明される。しかし、近年の研究では、武帝の時代に儒学が他の学派を排除して国家の唯一の正統な学問になったわけではない、とす"},{"id":"former-han-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"元号のはじまり","l":"former-han","x":"「令和」「平成」のような元号（年号）も、武帝の時代に始まった。それまでは、皇帝の即位から何年目と数えていたが、武帝の時代に、「建元」「元光」など、めでたい言葉を年の名前につけるよう"},{"id":"former-han-t5","k":"now","f":"now","kj":"いま","t":"「滇王之印」と「漢委奴国王」","l":"former-han","x":"前109年、漢に服属した滇の王は、武帝から、「滇王之印」と刻まれた金印を授けられた（『史記』西南夷列伝）。1956年、雲南省の石寨山の古墓群から、この記述どおりの、蛇の形のつまみを"},{"id":"former-han-t6","k":"confuse","f":"confuse","kj":"混同注意","t":"武帝の財政政策","l":"former-han","x":"政策内容ねらい塩・鉄・酒の専売塩と鉄（前119年）、酒（前98年）の生産・販売を国家が独占大商人や豪族が得ていた莫大な利益を国家が吸収均輸法地方から税として納められる特産物を、国家"},{"id":"former-han-t7","k":"source","f":"src","kj":"史料｜記録","t":"塩鉄論――国家は民と利益を争うべきか","l":"former-han","x":"武帝の死後の前81年、朝廷では、塩・鉄の専売などの財政政策を続けるべきかどうかについて、大論争が行われた。その記録は、のちに桓寛によって『塩鉄論』にまとめられた。地方から推薦されて"},{"id":"former-han-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"former-han","x":"中島敦『李陵』（小説、1943年）：匈奴に降伏した武将李陵、匈奴に屈しなかった蘇武、そして李陵を弁護して宮刑に処されながら『史記』を書き上げた司馬遷の、3人の生き方を描いた短編。武"},{"id":"four-kingdoms-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"四王国を整理する","l":"four-kingdoms","x":"国名中心地都民族・王朝滅亡エジプト（サイス朝）ナイル川流域サイスエジプト人（第26王朝）前525年、アケメネス朝に征服されるリディア小アジア西部サルデスインド＝ヨーロッパ語系前54"},{"id":"four-kingdoms-t2","k":"confuse","f":"confuse","kj":"混同注意","t":"「最初の貨幣」はどこか","l":"four-kingdoms","x":"「リディアが最初の金属貨幣を作った」というのは、西アジア・地中海世界の硬貨についての話である。中国では、殷の時代から、南の海でとれる子安貝が貨幣として使われていた（「貨」「財」「買"},{"id":"four-kingdoms-t3","k":"source","f":"src","kj":"史料｜記録","t":"「大きな帝国が滅びるであろう」","l":"four-kingdoms","x":"前6世紀半ば、クロイソスは、東で急速に力をつけていたペルシアのキュロス2世を攻めるべきか迷い、ギリシアのデルフォイのアポロン神殿に、莫大な贈り物とともに使者を送って神託をうかがった"},{"id":"four-kingdoms-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"日食が終わらせた戦争","l":"four-kingdoms","x":"メディアとリディアの戦争は5年間続いた。ヘロドトスによれば、6年目の戦いの最中、突然、昼が夜に変わった。両軍は恐れおののいて戦いをやめ、和平を結んだ。ハリュス川を両国の国境とし、リ"},{"id":"four-kingdoms-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"バベルの塔と空中庭園","l":"four-kingdoms","x":"エテメンアンキは、「天と地の基礎の家」という意味で、高さ約90mの7層の塔だったと推定されている。旧約聖書の「バベルの塔」の物語――天に届く塔を建てようとした人間の傲慢さに怒った神"},{"id":"four-kingdoms-t6","k":"now","f":"now","kj":"いま","t":"ベルリンにあるイシュタル門","l":"four-kingdoms","x":"バビロンの遺跡は、1899年から1917年にかけてドイツの調査隊が発掘した。イシュタル門の彩釉煉瓦の破片は、ドイツに運ばれて組み立て直され、現在はベルリンのペルガモン博物館に、高さ"},{"id":"four-kingdoms-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"「最初の考古学者」","l":"four-kingdoms","x":"ナボニドゥスは、古い神殿を修理するとき、その土台を掘り返して、昔の王たちが埋めた建設記念の碑文を探させた。そして、見つかった碑文を読み、それが何年前の王のものかを書き記している。た"},{"id":"four-kingdoms-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"アブ＝シンベルに残るギリシア人の落書き","l":"four-kingdoms","x":"前592年ごろ、サイス朝の王プサメティコス2世は、南のヌビア（クシュ）に遠征した。この遠征に参加したギリシア人傭兵たちは、帰り道に立ち寄ったアブ＝シンベル神殿で、ラメス2世の巨大な"},{"id":"four-kingdoms-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"人類最初の言葉は何語か","l":"four-kingdoms","x":"ヘロドトスは、サイス朝の初代の王プサメティコス1世について、こんな話を伝えている。王は、人類で最も古い民族はどれかを知るために、生まれたばかりの赤ん坊二人を羊飼いに預け、誰も言葉を"},{"id":"four-kingdoms-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"four-kingdoms","x":"ヴェルディ『ナブッコ』（オペラ、1842年初演）：新バビロニアの王ネブカドネザル2世（ナブッコ）とバビロン捕囚を描いたオペラ。捕らわれのヘブライ人たちが故郷を思って歌う合唱「行け、"},{"id":"franks-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ナポレオンのミツバチ","l":"franks","x":"1653年、現在のベルギーのトゥルネーで、教会の工事をしていた職人が、古い墓を掘り当てた。中からは、金の装身具や剣、数百枚の金貨・銀貨、そして「キルデリク王の（印章）」（CHILD"},{"id":"franks-t2","k":"source","f":"src","kj":"史料｜記録","t":"ソワソンの壺","l":"franks","x":"トゥールのグレゴリウスは、クローヴィスについて、次のような話を伝えている。486年、ソワソンの戦いの後、フランクの兵士たちは、教会から奪った戦利品を分けることになった。その中に、美"},{"id":"franks-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"天から届いた聖油","l":"franks","x":"9世紀のランスの大司教ヒンクマールは、クローヴィスの洗礼の時、聖油を運ぶ役目の者が群衆にはばまれて間に合わなかったので、レミギウスが祈ると、白い鳩が、天から聖油の入った小瓶をくわえ"},{"id":"franks-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「キツネ」と呼んだら罰金","l":"franks","x":"サリカ法典には、悪口に対する罰金も定められている。人を「キツネ」や「ウサギ」と呼んだ場合は3ソリドゥス、戦場で盾を投げ捨てて逃げたと、根拠もなく言いふらした場合も3ソリドゥスであっ"},{"id":"franks-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"二人の王妃――ブルンヒルドとフレデグンド","l":"franks","x":"6世紀後半のフランク王国では、二人の王妃の争いが、40年以上にわたって王国を揺るがした。アウストラシア王シギベルト1世の妃ブルンヒルドは、西ゴート王国の王女で、教養が高く、気性の激"},{"id":"franks-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「ヨーロッパを救った戦い」だったのか","l":"franks","x":"18世紀のイギリスの歴史家ギボンは、『ローマ帝国衰亡史』の中で、もしフランク軍が敗れていたら、と想像して、次のように書いた。原文Perhaps the interpretation"},{"id":"franks-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「コンスタンティヌスの寄進状」","l":"franks","x":"ピピンの寄進と同じころ、ローマ教会では、1通の文書が作られたと考えられている。それは、4世紀のローマ皇帝コンスタンティヌス1世が、重い病気を治してくれた教皇シルウェステル1世に感謝"},{"id":"franks-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"franks","x":"トゥールのグレゴリウス『歴史十書（フランク史）』：メロヴィング朝の歴史を知るための最も重要な史料。日本語訳に、兼岩正夫・臺幸夫訳（東海大学出版会）、杉本正俊訳（新評論）がある。オー"},{"id":"french-revolution-1-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「何もなし」と「革命でございます」","l":"french-revolution-1","x":"この日、ヴェルサイユのルイ16世は、日記に一言、「何もなし」と書いたという話が知られている。これは本当のことである。ただし、ルイ16世の日記は、主に狩りの記録であり、「何もなし」と"},{"id":"french-revolution-1-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「パンがなければお菓子を食べればいい」","l":"french-revolution-1","x":"王妃マリー・アントワネットは、民衆がパンがなくて困っていると聞いて、「パンがなければ、お菓子（ブリオッシュ）を食べればいいのに」と言ったという話が、広く知られている。しかし、これは"},{"id":"french-revolution-1-t3","k":"music","f":"music","kj":"音楽","t":"「サ・イラ」――うまくいくさ","l":"french-revolution-1","x":"連盟祭の準備のために、シャン・ド・マルスで土を運ぶパリの人々が、口々に歌ったのが、「サ・イラ（うまくいくさ）」である。もとは、流行していた陽気な舞曲の旋律に、新しい歌詞をつけたもの"},{"id":"french-revolution-1-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"french-revolution-1","x":"池田理代子『ベルサイユのばら』（漫画、1972〜1973年連載）：男装の麗人オスカルと、王妃マリー・アントワネットを中心に、フランス革命を描いた漫画。宝塚歌劇の舞台でも知られ、日本"},{"id":"french-revolution-2-t1","k":"music","f":"music","kj":"音楽","t":"「ラ・マルセイエーズ」の誕生","l":"french-revolution-2","x":"1792年4月、宣戦の知らせが届いた東部の国境の町ストラスブールで、工兵大尉ルージェ・ド・リールは、一晩で一つの軍歌をつくった。「ライン軍のための軍歌」である。画像はオンライン時に"},{"id":"french-revolution-2-t2","k":"now","f":"now","kj":"いま","t":"瀕死のライオン","l":"french-revolution-2","x":"スイスのルツェルンの町には、岩壁に刻まれた、矢に射抜かれて死にかけたライオンの彫刻がある。「瀕死のライオン」と呼ばれるこの像は、1792年8月10日に、テュイルリー宮殿でルイ16世"},{"id":"french-revolution-2-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「自由よ、汝の名において」――恐怖政治の犠牲者たち","l":"french-revolution-2","x":"1793年11月、ジロンド派の中心人物の一人であったロラン夫人は、革命広場の断頭台に向かった。処刑の直前、広場に立つ自由の女神の像を見上げて、こう叫んだと伝えられる。原文Ô Lib"},{"id":"french-revolution-2-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"人道的な処刑機械","l":"french-revolution-2","x":"ギロチンの名は、医師で国民議会の議員であったギヨタンに由来する。しかし、ギヨタンが発明したわけではない。旧体制の時代、死刑の方法は身分によって違い、貴族は剣で首をはねられたが、平民"},{"id":"french-revolution-2-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"french-revolution-2","x":"ユゴー『九十三年』（小説、1874年）：1793年、恐怖政治の時代のフランス西部のヴァンデの反乱を舞台に、革命と人間の良心の対立を描いた、ユゴーの最後の長編小説。作品は史実をもとに"},{"id":"french-revolution-3-t1","k":"source","f":"src","kj":"史料｜記録","t":"「フランス革命は、もっと大きな革命の先触れにすぎない」――『平等派宣言』","l":"french-revolution-3","x":"バブーフの仲間で、詩人のシルヴァン・マレシャルが書いた『平等派宣言』（1796年）は、こう宣言している。原文La Révolution française n'est que l'"},{"id":"french-revolution-3-t2","k":"now","f":"now","kj":"いま","t":"メートル法の誕生","l":"french-revolution-3","x":"フランス革命が世界に残した、最も身近な遺産の一つが、メートル法である。革命前のフランスでは、長さや重さの単位が、地方ごとにばらばらで、その数は数百種類にも及んだという。1792年、"},{"id":"french-revolution-3-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"フランス革命をどう評価するか","l":"french-revolution-3","x":"フランス革命は、身分制と封建的な特権を廃止し、人権と国民主権の原理を打ち立てた。それは、近代の市民社会の出発点となった。しかし、その評価は、200年以上にわたって、激しく争われてき"},{"id":"gaza-war-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"なぜ10月7日だったのか","l":"gaza-war","x":"ハマースが、なぜ2023年の10月に、これほどの規模の攻撃に踏み切ったのか。その理由については、さまざまな見方がある諸説。その一つは、中東の外交の大きな変化である。2020年、アラ"},{"id":"gaza-war-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「ガザは子どもたちの墓場になりつつある」――国連事務総長の言葉","l":"gaza-war","x":"2023年10月7日、ハマースなどの戦闘員がイスラエル南部を襲い、音楽祭の会場やキブツ（集団農場）で、約1200人を殺し、約250人を人質としてガザに連れ去った。イスラエルは、ただ"},{"id":"gaza-war-t3","k":"now","f":"now","kj":"いま","t":"人質広場","l":"gaza-war","x":"イスラエルの最大の都市テルアビブの美術館の前の広場は、戦争が始まってから、「人質広場」と呼ばれるようになった。広場には、ガザに連れ去られた人質たちの顔写真が並べられ、家族たちが毎週"},{"id":"gaza-war-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"紅海と日本の船","l":"gaza-war","x":"2023年11月19日、紅海を航行していた自動車運搬船「ギャラクシー・リーダー」に、イエメンのフーシ派の武装した男たちが、ヘリコプターから降り立ち、船を乗っ取った。この船は、日本の"},{"id":"german-unification-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"描き直された「歴史の瞬間」","l":"german-unification","x":"アントン・フォン・ヴェルナーは、実際に皇帝宣言の場に立ち会った画家であった。しかし、彼が描いた有名な絵は、事実のとおりではない。最初の版は、壁画のような大作であったが、1885年、"},{"id":"german-unification-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"ドイツはなぜ「遅れてきた国民」だったのか","l":"german-unification","x":"イギリスやフランスが、早くから一つの国家としてまとまっていたのに対し、ドイツが統一国家となったのは、1871年のことであった。ドイツの哲学者プレスナーは、ドイツを「遅れてきた国民」"},{"id":"germanic-migration-t1","k":"source","f":"src","kj":"史料｜記録","t":"タキトゥス『ゲルマニア』が描くゲルマン人","l":"germanic-migration","x":"原文De minoribus rebus principes consultant, de maioribus omnes …… ut turbae placuit, consid"},{"id":"germanic-migration-t2","k":"voice","f":"src","kj":"史料｜証言","t":"犬と引き換えの子どもたち","l":"germanic-migration","x":"原文…… turpe commercium duces invisissimi cogitarunt et quantos undique insatiabilitas colli"},{"id":"germanic-migration-t3","k":"voice","f":"src","kj":"史料｜証言","t":"ヒエロニムスの嘆き","l":"germanic-migration","x":"原文capitur Urbs quae totum cepit orbem.…… postquam vero clarissimum terrarum omnium lumen e"},{"id":"germanic-migration-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"川の底に眠る王","l":"germanic-migration","x":"アラリックは、ローマを略奪した後、さらに南へ進んでアフリカへ渡ろうとしたが、船団が嵐で失われ、まもなく南イタリアのコゼンツァで病死した。6世紀のゴート人の歴史家ヨルダネスによれば、"},{"id":"germanic-migration-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「ヴァンダリズム」の誕生","l":"germanic-migration","x":"英語やフランス語で、公共物や文化財を破壊する行為を「ヴァンダリズム」という。これは、1794年、フランス革命のさなかに、聖職者で政治家のグレゴワールが、革命派の民衆による教会や美術"},{"id":"germanic-migration-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"地名に残るゲルマン人","l":"germanic-migration","x":"ゲルマン人の部族の名前は、ヨーロッパの地名に残っている。フランス：「フランク人の国」に由来する。イングランド：「アングル人の土地」に由来する。ロンバルディア（北イタリアの州）：ラン"},{"id":"germanic-migration-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"アーサー王は実在したのか","l":"germanic-migration","x":"アングロ＝サクソン人の侵入に抵抗したブリトン人の英雄として語られるのが、アーサー王である。円卓の騎士や聖剣エクスカリバーの物語で知られる。しかし、アーサー王の名は、同時代の史料には"},{"id":"germanic-migration-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「大移動」か「変容」か","l":"germanic-migration","x":"ドイツ語では、この時代のゲルマン人の移動を「民族の移動（フェルカーヴァンデルング）」と呼び、フランス語やイタリア語では「蛮族の侵入」と呼ぶ。同じ出来事が、ゲルマン人の子孫を自認する"},{"id":"germanic-migration-t9","k":"works","f":"works","kj":"作品","t":"この時代にまつわる作品","l":"germanic-migration","x":"『ニーベルンゲンの歌』（13世紀初め）：ドイツの英雄叙事詩。後半では、ブルグンド人の王たちが、フン人の王エッツェルの宮廷で滅ぼされる。437年に、ブルグンド王国が、ローマの将軍アエ"},{"id":"globalization-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"NAFTAの日の蜂起","l":"globalization","x":"1994年1月1日、NAFTAが発効したその日の未明、メキシコの南部のチアパス州で、覆面をした先住民の武装集団が、町々を占拠した。「サパティスタ民族解放軍」である。メキシコ革命の英"},{"id":"globalization-t2","k":"source","f":"src","kj":"史料｜記録","t":"上司のメモ","l":"globalization","x":"1989年3月、CERNで働いていた33歳のバーナーズ＝リーは、上司に、一つの提案書を提出した。題名は「情報管理――一つの提案」。研究所の膨大な情報を、ハイパーテキストでつなぐしく"},{"id":"globalization-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「あいまいだが、面白い」――バーナーズ＝リーの提案書","l":"globalization","x":"1989年3月、スイスの欧州原子核研究機構（CERN）で働いていた34歳のイギリスの研究者ティム・バーナーズ＝リーは、上司に、一つの提案書を提出した。題名は「情報管理――一つの提案"},{"id":"globalization-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"絵文字の誕生","l":"globalization","x":"1999年2月、日本のNTTドコモは、携帯電話でインターネットのサービスを利用できる「iモード」を始めた。携帯電話で、メールを送り、ニュースや天気予報を読み、銀行の振り込みや、列車"},{"id":"globalization-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「これは三つの別々の機械ではない」――ジョブズのiPhone発表","l":"globalization","x":"2007年1月9日、サンフランシスコで開かれた発表会で、アップル社の最高経営責任者スティーブ・ジョブズは、舞台の上で、こう切り出した。原文An iPod, a phone, and"},{"id":"globalization-t6","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"金を集める運動","l":"globalization","x":"1998年の初め、韓国では、「国を救うための金集め運動」が全国に広がった。国が外国への借金を返すためのドルを稼ごうと、人々が、家にしまってあった金の指輪やネックレス、子どもの1歳の"},{"id":"globalization-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"globalization","x":"映画『ソーシャル・ネットワーク』（デヴィッド・フィンチャー監督、2010年）：ハーヴァード大学の学生マーク・ザッカーバーグが、フェイスブックを立ち上げる過程と、その後の訴訟を描いた"},{"id":"goryeo-japan-t1","k":"source","f":"src","kj":"史料｜記録","t":"「王侯将相、いずくんぞ種あらんや」","l":"goryeo-japan","x":"武臣の乱の後、社会の秩序が揺らぐ中で、各地で農民や奴婢の反乱が相次いだ。1198年、崔忠献の家の奴婢であった万積は、開京の北の山で、ほかの奴婢たちを集めて、次のように呼びかけたとい"},{"id":"goryeo-japan-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"刀伊の入寇――女真の海賊が九州を襲う","l":"goryeo-japan","x":"1019年の春、50隻余りの船に乗った海賊の一団が、対馬・壱岐を襲い、さらに九州の博多湾に上陸した。日本の人々が「刀伊」と呼んだこの海賊は、朝鮮半島の北東の沿海地方に住んでいた女真"},{"id":"goryeo-japan-t3","k":"works","f":"works","kj":"作品","t":"高麗と平安・鎌倉の日本にまつわる作品","l":"goryeo-japan","x":"『源氏物語』：11世紀の初めに紫式部が書いた長編物語。世界最古の長編小説の一つとして、多くの言語に翻訳されている。『平家物語』：平氏の栄華と滅亡を描いた鎌倉時代の軍記物語。琵琶法師"},{"id":"gracchi-t1","k":"source","f":"src","kj":"史料｜記録","t":"「野の獣にさえ穴がある」","l":"gracchi","x":"プルタルコスは、ティベリウスが民衆に向かって行った演説を、次のように伝えている。原文τὰ μὲν θηρία τὰ τὴν Ἰταλίαν νεμόμενα καὶ φωλεὸν "},{"id":"gracchi-t2","k":"confuse","f":"confuse","kj":"混同注意","t":"閥族派と平民派","l":"gracchi","x":"閥族派（オプティマテス）平民派（ポプラレス）意味「最良の人々」「民衆の側に立つ人々」基盤元老院民会・護民官、無産市民主張元老院の伝統的な権威を守る土地分配・穀物配給など民衆の利益主"},{"id":"gracchi-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"改革がもたらしたもの――「将軍の軍隊」","l":"gracchi","x":"マリウスの改革は、ローマ軍を強くしたが、同時に、共和政を内側から壊す危険な種もまいた。兵士たちにとって、退役後に土地をもらえるかどうかは、自分を率いる将軍が、その約束を元老院に認め"},{"id":"gracchi-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"若きカエサルとスッラ","l":"gracchi","x":"スッラの公敵宣告のとき、まだ18歳ほどの若者だったカエサルも、命を狙われた。カエサルは、マリウスの妻の甥であり、マリウス派の有力者キンナの娘を妻としていた。スッラはカエサルに妻との"},{"id":"gracchi-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"英雄としてのスパルタクス","l":"gracchi","x":"スパルタクスは、のちの時代に、抑圧された人々の解放の象徴として語られるようになった。マルクスは、スパルタクスを「古代の歴史全体の中で最も素晴らしい人物」と評した。第一次世界大戦の末"},{"id":"gracchi-t6","k":"voice","f":"src","kj":"史料｜証言","t":"アッピア街道の6000の十字架","l":"gracchi","x":"前71年、スパルタクスの反乱軍は、クラッススの軍に敗れた。スパルタクスは戦場で倒れたが、その遺体は見つからなかった。歴史家アッピアノスによれば、捕らえられた奴隷6000人が、カプア"},{"id":"gracchi-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"gracchi","x":"映画『スパルタカス』（スタンリー・キューブリック監督、1960年）：前73年に始まった剣闘士スパルタクスの反乱を描いた大作。塩野七生『ローマ人の物語』第3巻「勝者の混迷」（1994"},{"id":"great-depression-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ウォール街の窓から、人々は飛び降りたのか","l":"great-depression","x":"株価の大暴落の後、破産した投資家たちが、次々にウォール街のビルの窓から飛び降りた――という話は、よく知られている。しかし、アメリカの経済学者ガルブレイスは、著書『大暴落1929』の"},{"id":"great-depression-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"靴磨きの少年","l":"great-depression","x":"1929年の夏、アメリカの大富豪ジョゼフ・ケネディ（のちのケネディ大統領の父）は、ウォール街で靴を磨いてもらっていた。すると、靴磨きの少年が、どの株が上がるかについて、彼に「投資の"},{"id":"great-depression-t3","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"ボーナス・アーミー","l":"great-depression","x":"1932年の夏、首都ワシントンに、第一次世界大戦に従軍した元兵士たちとその家族、2万人近くが集まってきた。政府は、元兵士たちに、1945年に支払う約束で、従軍の「ボーナス」の証書を"},{"id":"great-depression-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"ローズヴェルト政権を倒すクーデター計画？――「ビジネス・プロット」","l":"great-depression","x":"1934年11月、2度の名誉勲章を受けた退役海兵隊少将スメドリー・バトラーは、下院の特別委員会で、驚くべき証言をした。ニューディールに反発する財界の一部の人々の代理人から、50万人"},{"id":"great-depression-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"great-depression","x":"スタインベック『怒りの葡萄』（小説、1939年、映画1940年）：砂嵐と恐慌で土地を失ったオクラホマの農民一家が、カリフォルニアを目指して旅をする物語（この回の「怒りの葡萄」の項を"},{"id":"greek-culture-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"オリンポスの主な神々（ローマの神々との対応）","l":"greek-culture","x":"ギリシアの神つかさどるものローマの神英語ゼウス天空・最高神ユピテルジュピター（木星）ヘラ結婚・ゼウスの妻ユノジュノー（June）ポセイドン海ネプトゥヌスネプチューン（海王星）アテナ"},{"id":"greek-culture-t2","k":"confuse","f":"confuse","kj":"混同注意","t":"「万物の根源（アルケー）」を探した人々","l":"greek-culture","x":"哲学者出身万物の根源タレスミレトス水アナクシマンドロスミレトス無限なもの（ト＝アペイロン）アナクシメネスミレトス空気ヘラクレイトスエフェソス火。「万物は流転する」ピタゴラスサモス（"},{"id":"greek-culture-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"日食を予言し、井戸に落ちた哲学者","l":"greek-culture","x":"タレスには、さまざまな逸話が伝えられている。前585年の日食を予言したという話（2-11）のほか、エジプトでピラミッドの影の長さを測り、自分の影の長さと身長の比を使ってピラミッドの"},{"id":"greek-culture-t4","k":"source","f":"src","kj":"史料｜記録","t":"「無知の知」と「よく生きること」","l":"greek-culture","x":"デルフォイの神託は、「ソクラテスより知恵のある者はいない」と告げた。驚いたソクラテスは、知恵があると評判の政治家や詩人、職人を訪ねて問答し、彼らが、本当は知らないことを知っていると"},{"id":"greek-culture-t5","k":"source","f":"src","kj":"史料｜記録","t":"「吟味されない生は、生きるに値しない」","l":"greek-culture","x":"裁判で、ソクラテスは、哲学をやめれば釈放してやると言われても、こう答えたとプラトンは伝えている。原文ἕωσπερ ἂν ἐμπνέω καὶ οἷός τε ὦ, οὐ μὴ πα"},{"id":"greek-culture-t6","k":"source","f":"src","kj":"史料｜記録","t":"最期の言葉――「アスクレピオスにニワトリを」","l":"greek-culture","x":"前399年、死刑の判決を受けたソクラテスは、牢獄で毒ニンジンの杯を飲み干した。弟子たちは泣き崩れたが、ソクラテスは静かに歩き回り、足が重くなると横たわった。プラトンは、最期の瞬間を"},{"id":"greek-culture-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"1万人に届く声","l":"greek-culture","x":"ペロポネソス半島のエピダウロスには、前4世紀に造られた野外劇場が、ほぼ完全な形で残っている。約1万4000人を収容できるこの劇場は、音響のよさで有名で、舞台の中央で落としたコインの"},{"id":"greek-culture-t8","k":"view","f":"think","kj":"考える｜別の視点","t":"ギリシア彫刻は白かったか","l":"greek-culture","x":"大理石のギリシア彫刻やパルテノン神殿は、白く輝く美しさで知られる。18世紀のドイツの美術史家ヴィンケルマンは、その「高貴な単純と静かな偉大」をたたえ、白い大理石の彫刻こそが美の理想"},{"id":"greek-culture-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"greek-culture","x":"アリストファネス『雲』（喜劇、前423年初演）：ソクラテスを、怪しげな理屈で若者を惑わす詭弁家として笑いものにした喜劇。プラトンは、こうした悪評がソクラテスの裁判の背景にあったと考"},{"id":"greek-life-t1","k":"source","f":"src","kj":"史料｜記録","t":"「女性の名誉は、話題にされないこと」","l":"greek-life","x":"ペリクレスは、トゥキディデスが伝える葬送演説の最後で、戦死者の妻たちに次のように語りかけている。原文τῆς τε γὰρ ὑπαρχούσης φύσεως μὴ χείροσι "},{"id":"greek-life-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"自由と奴隷制は矛盾しなかったのか","l":"greek-life","x":"現代の私たちから見ると、「自由」と「平等」を掲げる民主政が、多数の奴隷の存在と両立していたことは、大きな矛盾に見える。しかし、多くのギリシア人にとって、それは矛盾ではなかった。哲学"},{"id":"greek-life-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"陶器に描かれた暮らし","l":"greek-life","x":"私たちがギリシア人の暮らしをよく知ることができるのは、陶器の絵のおかげである。アテネの陶器には、神話の場面だけでなく、酒宴、運動競技、学校の授業、機織り、市場の買い物、結婚式など、"},{"id":"greek-life-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"死者への渡し賃","l":"greek-life","x":"ギリシア人は、死者の魂は冥界に行き、冥界の川（ステュクス川・アケロン川）を渡し守カロンの舟で渡ると考えた。そのため、死者の口の中に、渡し賃として1オボロスの硬貨を入れて葬る習慣があ"},{"id":"gulf-war-t1","k":"source","f":"src","kj":"史料｜記録","t":"「アラブどうしの対立には意見を持たない」","l":"gulf-war","x":"1990年7月25日、フセインは、アメリカの駐イラク大使グラスピーを呼び出し、会談した。会談の記録によれば、グラスピーは、こう述べた。「我々は、アラブどうしの対立、たとえばクウェー"},{"id":"gulf-war-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「このクウェートへの侵略を、許しはしない」――ブッシュ大統領の言葉","l":"gulf-war","x":"1990年8月2日、イラクの軍隊が、隣国クウェートに侵攻し、わずか数時間で全土を占領した。3日後の8月5日、休暇先から急いでワシントンに戻ったアメリカのジョージ・H・W・ブッシュ大"},{"id":"gulf-war-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"バグダードのプロレスラー","l":"gulf-war","x":"侵攻の後、イラクは、クウェートとイラクにいた欧米人や日本人を出国させず、軍事施設などに分散させて、多国籍軍の攻撃を防ぐ「人間の盾」とした。その中には、200人を超える日本人も含まれ"},{"id":"gulf-war-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「すべての戦いの母」――サッダーム・フセイン","l":"gulf-war","x":"1991年1月17日、多国籍軍の空爆が始まった（「砂漠の嵐」作戦）。その日、イラクのサッダーム・フセイン大統領は、ラジオで、国民に、こう呼びかけた。原文أُمّ المعارك現代"},{"id":"gulf-war-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"感謝広告に「日本」の名はなかった","l":"gulf-war","x":"1991年3月11日、クウェート政府は、アメリカの新聞『ワシントン・ポスト』などに、全面の広告を出した。クウェートの解放に協力した国々への感謝を表すもので、30か国の国旗と国名が並"},{"id":"gulf-war-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"ためらいの握手","l":"gulf-war","x":"調印の後、アメリカのクリントン大統領は、両手を広げて、ラビンとアラファトの背中をそっと押し、二人を近づけた。アラファトが、手を差し出した。ラビンは、一瞬ためらい、それから、その手を"},{"id":"gulf-war-t7","k":"voice","f":"src","kj":"史料｜証言","t":"「もうたくさんだ」――ラビンのホワイトハウスでの演説","l":"gulf-war","x":"1993年9月13日、ワシントンのホワイトハウスの庭で、イスラエルのラビン首相と、パレスチナ解放機構（PLO）のアラファト議長が、パレスチナの暫定自治に関する合意（オスロ合意）に調"},{"id":"gulf-war-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"gulf-war","x":"映画『ジャーヘッド』（サム・メンデス監督、2005年）：湾岸戦争に派遣されたアメリカの若い海兵隊員の、退屈と緊張に満ちた日々を描いた映画。作品は史実をもとにした創作を含むことが多い"},{"id":"gupta-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"鉄柱に背中を向けて抱きつくと……","l":"gupta","x":"デリーの鉄柱には、柱に背中をつけて両腕を後ろに回し、手と手を結ぶことができれば願いがかなう、という言い伝えがあった俗説。多くの観光客が試したため、柱の下の部分は人々の手でこすられて"},{"id":"gupta-t2","k":"source","f":"src","kj":"史料｜記録","t":"アラーハーバード石柱碑文","l":"gupta","x":"碑文は、サムドラグプタの征服を、地域ごとに異なる扱いをしたものとして描いている。原文Rudradeva-Matila-Nāgadatta-……-anekāryāvarta-rāja"},{"id":"gupta-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"兄の妃を救った王――ラーマグプタの伝説","l":"gupta","x":"6世紀ごろに書かれた戯曲『デーヴィーチャンドラグプタム』（現在は断片だけが伝わる）は、次のような物語を伝えている伝承。サムドラグプタの死後、王位を継いだのは、チャンドラグプタ2世の"},{"id":"gupta-t4","k":"source","f":"src","kj":"史料｜記録","t":"法顕『仏国記』が記すインド","l":"gupta","x":"法顕は、ガンジス川流域の「中国」（インドの中心の地方の意味）について、次のように記している。原文民人殷樂，無戶籍官法，唯耕王地者乃輸地利，欲去便去，欲住便住。王治不用刑罔，有罪者但"},{"id":"gupta-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"800年間修理され続けたダム","l":"gupta","x":"インド西部のグジャラート地方のジュナーガドには、大きな岩に3つの時代の碑文が刻まれている。1つ目は、前3世紀のアショーカ王の詔勅である。2つ目は、150年ごろ、西クシャトラパの王ル"},{"id":"gupta-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"フーナとエフタル","l":"gupta","x":"日本の世界史の教科書では、グプタ朝を衰退させた遊牧民を「エフタル」と記すことが多い。エフタルは、5世紀に中央アジアのアフガニスタン北部を中心に大国を築き、ササン朝と争った遊牧民であ"},{"id":"gupta-t7","k":"source","f":"src","kj":"史料｜記録","t":"『マヌ法典』が説く女性の地位","l":"gupta","x":"『マヌ法典』には、次のような一節がある。原文bālayā vā yuvatyā vā vṛddhayā vāpi yoṣitāna svātantryeṇa kartavyaṃ k"},{"id":"gupta-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"東南アジアに広がった『ラーマーヤナ』","l":"gupta","x":"『ラーマーヤナ』の物語は、インドから東南アジアに伝わり、各地で独自の形に作り変えられた。タイでは『ラーマキエン』、インドネシアのジャワ島では影絵芝居（ワヤン・クリ）や舞踊劇の題材と"},{"id":"gupta-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"燃え続けた図書館","l":"gupta","x":"ナーランダー僧院には、「ダルマガンジャ」（法の市場）と呼ばれる図書館があり、9階建ての建物を含む3つの大きな建物に、膨大な経典が収められていたと伝えられる伝承。12世紀末、イスラー"},{"id":"gupta-t10","k":"source","f":"src","kj":"史料｜記録","t":"ゲーテとシャクンタラー","l":"gupta","x":"『シャクンタラー』は、18世紀末に英語に翻訳され、ヨーロッパで大きな反響を呼んだ。ドイツの詩人ゲーテは、1791年、この作品をたたえて次のような短い詩を書いた。原文Willst d"},{"id":"gupta-t11","k":"debate","f":"think","kj":"考える｜諸説あり","t":"最古の「ゼロ」はどれか","l":"gupta","x":"ゼロの記号がいつ生まれたのかについては、はっきりしたことはわかっていない。インド国内で、年代が確実な最古のゼロの例は、中部インドのグワーリヤルの寺院の碑文（876年）に刻まれた「2"},{"id":"gupta-t12","k":"trivia","f":"side","kj":"こぼれ話","t":"法隆寺の壁画の焼失と文化財保護法","l":"gupta","x":"奈良の法隆寺の金堂には、7世紀末から8世紀初めに描かれた仏教の壁画があった。その中の観音菩薩の姿は、アジャンターの蓮華手菩薩とよく似ており、インドのグプタ様式の影響が、シルクロード"},{"id":"gupta-t13","k":"term","f":"deep","kj":"深掘り｜ことば","t":"グプタ文字と日本の梵字","l":"gupta","x":"グプタ朝の時代に使われたグプタ文字は、アショーカ王の碑文のブラーフミー文字から発達した文字である。グプタ文字から、6世紀ごろに「シッダマートリカー文字」（悉曇文字）が生まれ、さらに"},{"id":"gupta-t14","k":"trivia","f":"side","kj":"こぼれ話","t":"天空の宮殿シーギリヤ","l":"gupta","x":"スリランカ中部のシーギリヤには、高さ約200mの巨大な岩山がそびえ、その頂上に宮殿の遺跡がある。5世紀後半、父王を殺して王位を奪ったカッサパ1世が、弟の報復を恐れて、この岩山の上に"},{"id":"gupta-t15","k":"now","f":"now","kj":"いま","t":"現代インドとグプタ朝","l":"gupta","x":"グプタ朝の時代は、20世紀前半のインドの独立運動の時代に、インドの歴史家たちによって「インドの古典時代」「黄金時代」として高く評価された。イギリスの支配に対抗して、インド人が自らの"},{"id":"gupta-t16","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"gupta","x":"カーリダーサ『シャクンタラー姫』（辻直四郎訳、岩波文庫）：カーリダーサの代表作の日本語訳。『マハーバーラタ』（ピーター・ブルック演出）：イギリスの演出家ピーター・ブルックが、叙事詩"},{"id":"habsburg-spain-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"「レパントの片腕」セルバンテス","l":"habsburg-spain","x":"レパントの海戦に、スペインの一人の若い兵士が加わっていた。24歳のミゲル・デ・セルバンテスである。戦いの日、セルバンテスは、熱病で寝込んでいた。しかし、彼は、船の安全な場所にいるよ"},{"id":"habsburg-spain-t2","k":"now","f":"now","kj":"いま","t":"最後のスペイン・ハプスブルク家の王","l":"habsburg-spain","x":"1665年に即位したカルロス2世は、スペイン・ハプスブルク家の最後の王となった。画像はオンライン時に表示される（Wikimedia Commonsで見る）カルロス2世（フアン・カレ"},{"id":"habsburg-spain-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"「呪われた王」の日々","l":"habsburg-spain","x":"カルロス2世は、4歳まで話すことができず、8歳まで一人で歩けなかったと伝えられる。舌が大きく、言葉ははっきりしなかったという。2度結婚したが、子どもは生まれなかった。跡継ぎができな"},{"id":"habsburg-spain-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"habsburg-spain","x":"セルバンテス『ドン・キホーテ』（前編1605年、後編1615年）：騎士道物語を読みすぎて、自分を騎士だと思い込んだ郷士の冒険を描いた小説。スペインの「黄金の世紀」の最高傑作とされる"},{"id":"haiti-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ハイチに残ったポーランド人","l":"haiti","x":"ナポレオンがサン・ドマングに送った軍には、約5000人のポーランド兵が含まれていた。祖国の独立をナポレオンの力で取り戻すことを夢見て、フランス軍に加わった人々であった（→「ポーラン"},{"id":"haiti-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「砂糖も、コーヒーも、植民地も、くそくらえ」","l":"haiti","x":"ハイチでの敗北によって、ナポレオンは、アメリカ大陸に帝国を築くという夢を捨てた。1803年、ナポレオンは、北アメリカの広大なルイジアナを、わずか1500万ドルでアメリカ合衆国に売り"},{"id":"haiti-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"「沈黙させられた革命」","l":"haiti","x":"ハイチ革命は、アメリカ独立革命やフランス革命と並ぶ、「大西洋革命」の一つである。それどころか、人権宣言の理念を、肌の色にかかわらず、すべての人間に当てはめようとしたという意味では、"},{"id":"hammurabi-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"「最古の法典」ではない","l":"hammurabi","x":"ハンムラビ法典は、長い間「世界最古の法典」と紹介されてきた。しかし、前回見たウル＝ナンム法典（前21世紀）をはじめ、それより古い法典がいくつか見つかっており、現在では最古の法典では"},{"id":"hammurabi-t2","k":"source","f":"src","kj":"史料｜記録","t":"ハンムラビ法典の条文から","l":"hammurabi","x":"第196条「もし人が、アヴィールム（自由人）の目をつぶしたならば、その人の目をつぶす」（原文：šumma awīlum īn mār awīlim uḫtappid īnšu uḫ"},{"id":"hammurabi-t3","k":"source","f":"src","kj":"史料｜記録","t":"「虐げられた者は、わが像の前に来たれ」――法典の結び","l":"hammurabi","x":"ハンムラビ法典の石碑の最後には、長い結びの言葉（後書き）が刻まれている。そこで、ハンムラビは、この石碑を立てた目的を、こう語っている。原文awīlum ḫablum ša awat"},{"id":"hammurabi-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"手抜き工事は死刑","l":"hammurabi","x":"建築に関する条文は、とくに厳しい。第229条「もし大工が人のために家を建て、その工事が堅固でなかったために家が倒れ、家の主人を死なせたならば、その大工は殺される」第230条「もし家"},{"id":"hammurabi-t5","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"ビールの水増しは水に投げ込まれる","l":"hammurabi","x":"酒場（ビール店）の主人に関する条文もある。主人は多くの場合、女性だった。第108条では、ビールの代金を受け取るとき、麦で受け取るべきところを銀で受け取り、その際にビールの量をごまか"},{"id":"hammurabi-t6","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"結婚と離婚――女性の権利","l":"hammurabi","x":"ハンムラビ法典には、結婚・離婚・相続についての条文も多い。結婚は、花婿の家が花嫁の家に結納金を払い、花嫁は実家から持参金を持って嫁ぐという形だった。注目すべきは、女性にも一定の権利"},{"id":"hammurabi-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"借金帳消しの「徳政令」","l":"hammurabi","x":"古代メソポタミアでは、不作の年などに借金を返せなくなり、自分や家族を奴隷として差し出す人が少なくなかった。ハンムラビ法典第117条では、借金のために妻や子を売ったり、人質に入れたり"},{"id":"hammurabi-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"世界最古の「苦情の手紙」","l":"hammurabi","x":"大英博物館には、前1750年ごろの粘土板の手紙がある。差出人はナンニという男で、宛先は銅の商人エア＝ナシルである。ナンニは、エア＝ナシルから質の悪い銅を売りつけられたことに腹を立て"},{"id":"han-society-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"儒学の五経","l":"han-society","x":"経典内容『易経』（『易』）占いの書。陰陽の組み合わせで世界の変化を説く『書経』（『尚書』）古代の帝王の言葉や記録『詩経』（『詩』）周代の歌謡を集めた詩集。孔子が編集したと伝えられる"},{"id":"han-society-t2","k":"source","f":"src","kj":"史料｜記録","t":"「任安に報ずるの書」","l":"han-society","x":"司馬遷は、友人の任安に宛てた手紙の中で、宮刑を受けてもなお生き続けた理由を語っている。原文人固有一死，或重於泰山，或輕於鴻毛，用之所趨異也。 ……現代語訳人は、もとより一度は死ぬも"},{"id":"han-society-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"紀伝体と編年体","l":"han-society","x":"紀伝体編年体書き方人物の伝記（本紀・列伝など）を中心に、制度史（書・志）や年表（表）を組み合わせる出来事を年月の順に記す長所人物の生き方や、制度の移り変わりが分かりやすい同時に起き"},{"id":"han-society-t4","k":"now","f":"now","kj":"いま","t":"馬王堆が語る漢代の暮らし","l":"han-society","x":"馬王堆の3つの墓からは、3000点を超える副葬品が出土した。中でも驚かされるのは、1号墓から出土した絹の衣服である。そのうちの1着の「素紗襌衣」は、身丈128cm、両袖を広げた長さ"},{"id":"harsha-t1","k":"source","f":"src","kj":"史料｜記録","t":"バーナ『ハルシャチャリタ』――燃え盛る火の前で","l":"harsha","x":"ハルシャ王の宮廷詩人バーナ（バーナバッタ）は、王の前半生を描いた伝記的な物語『ハルシャチャリタ』（ハルシャ王の事績）を、技巧を凝らした華麗なサンスクリット語の散文で書いた。バーナに"},{"id":"harsha-t2","k":"source","f":"src","kj":"史料｜記録","t":"『大唐西域記』が記すハルシャ王の征服","l":"harsha","x":"原文於是東征西伐，遠賓邇肅，象不解鞍，人不釋甲，於六年中，臣五印度。既廣其地，更增甲兵，象軍六萬，馬軍十萬。垂三十年，兵戈不起，政教和平。現代語訳王は東に征し西に討ち、従わない者を"},{"id":"harsha-t3","k":"source","f":"src","kj":"史料｜記録","t":"アイホーレ碑文――「歓喜」が溶けた王","l":"harsha","x":"プラケーシン2世の宮廷詩人ラヴィキールティは、634年、チャールキヤ朝の古い都アイホーレのジャイナ教寺院（メーグティ寺院）の壁に、王の功績をたたえるサンスクリット語の詩を刻んだ。こ"},{"id":"harsha-t4","k":"source","f":"src","kj":"史料｜記録","t":"すべてを与えた王","l":"harsha","x":"643年、玄奘は、ハルシャ王に招かれて、プラヤーガでの6回目の無遮大会に参加した。玄奘の伝記によれば、この大会は75日間にわたって続いた。初日にはブッダの像が、2日目には太陽神の像"},{"id":"harsha-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"鳥の王に身を捧げた王子――『ナーガーナンダ』","l":"harsha","x":"ハルシャ王の作とされる戯曲『ナーガーナンダ』（竜たちの喜び）は、仏教の説話をもとにした作品である。主人公の王子ジームータヴァーハナは、神鳥ガルダが、毎日1匹ずつ竜（ナーガ、蛇の一族"},{"id":"harsha-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"太宗の陵墓に並んだインドの王","l":"harsha","x":"太宗の陵墓である昭陵（陝西省）には、太宗に従った周辺の国々の君主たち14人の石像が並べられた。突厥の可汗や、吐蕃のソンツェン＝ガンポ、新羅の真徳女王などと並んで、そこには、王玄策が"},{"id":"harsha-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"砂糖の作り方を学ぶ","l":"harsha","x":"『新唐書』によれば、647年、太宗は、インドのマガダ国に使者を送り、サトウキビの汁を煮詰めて砂糖を作る方法（熬糖法）を学ばせた。そして、揚州（長江下流）から献上させたサトウキビで作"},{"id":"harsha-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"玄奘はいつ出発したのか","l":"harsha","x":"玄奘自身が太宗に提出した上表文や、伝記『大慈恩寺三蔵法師伝』は、出発を貞観3年（629年）としている。日本の教科書なども、629年の出発とすることが多い。一方、玄奘は、旅の途中で、"},{"id":"harsha-t9","k":"source","f":"src","kj":"史料｜記録","t":"玄奘が見たバーミヤーン","l":"harsha","x":"原文王城東北山阿，有立佛石像，高百四五十尺，金色晃曜，寶飾煥爛。……城東二三里伽藍中，有佛入涅槃臥像，長千餘尺。現代語訳王城の東北の山の斜面に、石の立仏の像がある。高さは140〜1"},{"id":"harsha-t10","k":"trivia","f":"side","kj":"こぼれ話","t":"3年間待っていた師","l":"harsha","x":"玄奘の伝記によれば、戒賢は、このとき100歳を超える高齢であった伝承。戒賢は、数年前から重い病に苦しみ、命を絶とうとまで考えていたが、夢の中に金色に輝く3人の天人が現れて、「東の大"},{"id":"harsha-t11","k":"trivia","f":"side","kj":"こぼれ話","t":"インドで歌われていた唐の歌","l":"harsha","x":"カーマルーパの王は、玄奘にこう語ったという。「いまインドの国々では、マハーチーナ国（大唐）の『秦王破陣楽』を歌う者が多い。久しく聞いてきたが、それはあなたの国のことか」（『大唐西域"},{"id":"harsha-t12","k":"source","f":"src","kj":"史料｜記録","t":"燃え上がる楼閣と刺客","l":"harsha","x":"『大唐西域記』は、この大法会の時に起こった事件を記している。王は、ガンジス川の西に大きな寺を建て、その東に高さ100尺余りの宝の楼閣を建てて、王の背丈と同じ高さの金の仏像を安置した"},{"id":"harsha-t13","k":"person","f":"deep","kj":"深掘り｜人物","t":"太宗と玄奘","l":"harsha","x":"帰国した玄奘は、洛陽で太宗に会った。太宗は、ちょうど高句麗への遠征の準備のため、洛陽に来ていたのである（→「唐の成立と貞観の治」の回）。太宗は、玄奘がたどった西域やインドの国々の地"},{"id":"harsha-t14","k":"trivia","f":"side","kj":"こぼれ話","t":"玄奘の遺骨の旅","l":"harsha","x":"玄奘の遺骨は、長安の郊外に葬られた後、唐末の戦乱の中で掘り出され、のちに南京に移されて寺に納められたと伝えられる。1942年、日中戦争中の南京で、日本軍が神社を建てるための工事をし"},{"id":"harsha-t15","k":"trivia","f":"side","kj":"こぼれ話","t":"玄奘の記録で遺跡を掘り当てる","l":"harsha","x":"19世紀、フランスの東洋学者スタニスラス・ジュリアンが『大唐西域記』をフランス語に翻訳すると、それはインドの考古学に大きな影響を与えた。イギリス領インドの考古調査局の初代局長となっ"},{"id":"harsha-t16","k":"works","f":"works","kj":"作品","t":"『西遊記』――玄奘の旅から生まれた物語","l":"harsha","x":"玄奘の旅は、のちに多くの伝説を生んだ。宋の時代には、猿の行者が玄奘の旅を助ける物語『大唐三蔵取経詩話』が作られ、元の時代には劇として演じられた。こうした物語が、明の時代の16世紀に"},{"id":"harsha-t17","k":"trivia","f":"side","kj":"こぼれ話","t":"上から掘り下げた寺院","l":"harsha","x":"エローラのカイラーサナータ寺院は、シヴァ神が住むとされるヒマラヤのカイラーサ山を表した寺院である。普通の建物は、下から石を積み上げて造る。しかし、この寺院は、玄武岩の崖を、上から下"},{"id":"harsha-t18","k":"now","f":"now","kj":"いま","t":"現代のインドと中国と玄奘","l":"harsha","x":"玄奘は、現代のインドと中国の両国で、両国の交流の象徴として語られることが多い。ナーランダー僧院の遺跡の近くには、中国とインドの協力によって建てられた「玄奘記念館」があり、玄奘の遺骨"},{"id":"harsha-t19","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"harsha","x":"玄奘『大唐西域記』（水谷真成訳、平凡社東洋文庫・中国古典文学大系）：玄奘の旅行記の日本語の全訳。慧立・彦悰『玄奘三蔵――西域・インド紀行』（長澤和俊訳、講談社学術文庫）：玄奘の伝記"},{"id":"hebrews-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"ヘブライ人・イスラエル人・ユダヤ人","l":"hebrews","x":"同じ民族が、三つの名前で呼ばれる。ヘブライ人：主に周りの民族が彼らを呼んだ名。「（川の）向こうから来た者」の意味ともいわれるが、はっきりしない。イスラエル人：彼ら自身の呼び名。祖先"},{"id":"hebrews-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"出エジプトは史実か","l":"hebrews","x":"出エジプトの物語が史実かどうかは、長く議論されてきた諸説。エジプト側の記録には、ヘブライ人の大規模な脱出を記したものは見つかっていない。シナイ半島でも、数十万人もの人々が40年間さ"},{"id":"hebrews-t3","k":"source","f":"src","kj":"史料｜記録","t":"聖書の外に現れた「イスラエル」","l":"hebrews","x":"聖書以外の史料に「イスラエル」の名が初めて現れるのは、ラメス2世の息子メルエンプタハの戦勝碑（前1208年ごろ）である。王がパレスチナで打ち破った相手を並べた中に、こう書かれている"},{"id":"hebrews-t4","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ダヴィデとソロモンの「大王国」","l":"hebrews","x":"旧約聖書は、ダヴィデとソロモンの王国を、エジプトの国境からユーフラテス川にまで及ぶ大王国として描いている。しかし、考古学の成果からは、当時のエルサレムは小さな町にすぎず、王国もずっ"},{"id":"hebrews-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「失われた10部族」と日本","l":"hebrews","x":"連れ去られた北の10部族は、その後、各地の住民と混じり合い、独自の集団としては歴史から姿を消した。そのため、彼らは「失われた10部族」と呼ばれ、後世さまざまな伝説を生んだ。世界の各"},{"id":"hebrews-t6","k":"source","f":"src","kj":"史料｜記録","t":"トンネルに残された碑文","l":"hebrews","x":"アッシリア軍の攻撃に備えて、ユダ王ヒゼキヤは、エルサレムの城壁の外にあった泉から、城内まで水を引くトンネルを掘らせた。包囲されても水に困らないようにするためである。1880年、この"},{"id":"hebrews-t7","k":"source","f":"src","kj":"史料｜記録","t":"「バビロンの川のほとりに座り」","l":"hebrews","x":"原文עַל נַהֲרוֹת בָּבֶל שָׁם יָשַׁבְנוּ גַּם בָּכִינוּ בְּזָכְרֵנוּ אֶת צִיּוֹן現代語訳バビロンの川のほと"},{"id":"hebrews-t8","k":"voice","f":"src","kj":"史料｜証言","t":"エルサレム陥落（前587年）――見張りの兵士と、子を煮た母","l":"hebrews","x":"前588年、新バビロニアのネブカドネザル2世の軍がユダ王国に攻め込み、町々を次々に落としていった。ユダ王国の要塞ラキシュの門の跡からは、前線の兵士が守備隊長に送った手紙が、陶器のか"},{"id":"hebrews-t9","k":"view","f":"think","kj":"考える｜別の視点","t":"一神教はどう生まれたか","l":"hebrews","x":"ヘブライ人も、はじめから唯一の神だけを信じていたわけではなかったようである。旧約聖書には、預言者たちが、民が周りの民族の神々（豊穣の神バアルなど）を拝むことを繰り返し非難する場面が"},{"id":"hebrews-t10","k":"now","f":"now","kj":"いま","t":"エルサレム――三つの宗教の聖地","l":"hebrews","x":"エルサレムの旧市街は、1km四方ほどの小さな区域に、ユダヤ教・キリスト教・イスラームの聖地が集まっている。ユダヤ教の聖地「嘆きの壁」は、捕囚の後に再建され、のちにヘロデ王が大改築し"},{"id":"hebrews-t11","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"hebrews","x":"映画『十戒』（セシル・B・デミル監督、1956年）：モーセに率いられたヘブライ人の出エジプトを描いた大作。紅海が二つに割れる場面は、映画史に残る特撮として知られる。映画『プリンス・"},{"id":"hellenistic-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"ヘレニズム三国と、その後","l":"hellenistic","x":"王国建国者中心地・都滅亡アンティゴノス朝マケドニアアンティゴノス2世マケドニア・ギリシア（都ペラ）前168年、ローマに敗れる（前148年に属州化）セレウコス朝シリアセレウコス1世シ"},{"id":"hellenistic-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"大図書館を焼いたのは誰か","l":"hellenistic","x":"アレクサンドリアの大図書館は、いつ、どのように失われたのか。これについては、さまざまな話が伝えられている。前48年、カエサルがアレクサンドリアで戦ったとき（3-17）、港の火事が燃"},{"id":"hellenistic-t3","k":"mech","f":"deep","kj":"深掘り｜しくみ","t":"アリスタルコスの太陽中心説","l":"hellenistic","x":"アリスタルコス（前3世紀前半）は、月が半月のときの太陽・月・地球の角度などから、太陽は地球よりはるかに大きいと計算した。そして、大きな太陽が小さな地球の周りを回るのは不自然だと考え"},{"id":"hellenistic-t4","k":"source","f":"src","kj":"史料｜記録","t":"「われに支点を与えよ」","l":"hellenistic","x":"アルキメデスには、多くの逸話が伝えられている。シラクサの王から、新しく作らせた王冠に、金細工師が銀を混ぜてごまかしていないか調べるよう頼まれたアルキメデスは、公衆浴場の湯船に入った"},{"id":"hellenistic-t5","k":"confuse","f":"confuse","kj":"混同注意","t":"ストア派とエピクロス派","l":"hellenistic","x":"ストア派エピクロス派創始者ゼノン（キプロス島出身）エピクロス理想理性によって情念を抑え、心を乱されないこと（アパテイア＝不動心）心の平静（アタラクシア）を得ること幸福自然＝理性（ロ"},{"id":"hellenistic-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"「日陰にしないでくれ」","l":"hellenistic","x":"ヘレニズム時代の少し前、アテネやコリントスに、樽（実際には大きな甕）の中に住み、ほとんど何も持たずに暮らした哲学者ディオゲネスがいた。社会の慣習や富を軽蔑し、自然のままに生きること"},{"id":"hellenistic-t7","k":"now","f":"now","kj":"いま","t":"アフガニスタンのギリシア都市","l":"hellenistic","x":"1964年、アフガニスタン北部の、アム川（オクサス川）とコクチャ川の合流点にある遺跡アイ＝ハヌムで、フランスの調査隊が発掘を始めた。そこには、劇場、体育場（ギュムナシオン）、コリン"},{"id":"hellenistic-t8","k":"works","f":"works","kj":"作品","t":"この時代とつながる作品","l":"hellenistic","x":"魚豊『チ。―地球の運動について―』（漫画、2020〜2022年連載、手塚治虫文化賞マンガ大賞受賞、2024〜2025年アニメ化）：15世紀の「P王国」（ポーランドを思わせる架空の国"},{"id":"hittite-iron-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"「語族」は人種や民族ではない","l":"hittite-iron","x":"「インド＝ヨーロッパ語族」「セム語族」などの「語族」は、言葉の系統によるグループ分けであって、人種や血筋のまとまりではない。同じ語族の言葉を話していても、人々の祖先や見た目はさまざ"},{"id":"hittite-iron-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「パンを食べ、水を飲むであろう」","l":"hittite-iron","x":"ヒッタイト人の言葉は、楔形文字で書かれていたため、文字は読めた。しかし、それがどんな言葉なのかは長いあいだ分からなかった。1915年、チェコの学者フロズニーは、次の一文に注目した。"},{"id":"hittite-iron-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"馬の調教マニュアルと、インドの神々","l":"hittite-iron","x":"ヒッタイトの文書の中に、キックリという人物が書いた、戦車用の馬の調教の手引きがある。約180日にわたって馬を走らせ、水を飲ませ、休ませる方法が細かく記されている。キックリは、ヒッタ"},{"id":"hittite-iron-t4","k":"source","f":"src","kj":"史料｜記録","t":"「よい鉄は、今はない」","l":"hittite-iron","x":"あなたが手紙で求めてきたよい鉄は、キズワトナにある私の倉には、今はない。鉄を作るのによくない時期であると、私は書いた。よい鉄は作らせているが、まだ仕上がっていない。仕上がったら、あ"},{"id":"hittite-iron-t5","k":"now","f":"now","kj":"いま","t":"日本の調査隊とアナトリアの鉄","l":"hittite-iron","x":"トルコ中部のカマン＝カレホユック遺跡では、1986年から日本の中近東文化センター（のちにアナトリア考古学研究所）の調査隊が発掘を続けている。この遺跡では、ヒッタイト以前の前2千年紀"},{"id":"hittite-iron-t6","k":"source","f":"src","kj":"史料｜記録","t":"ラメス2世の「詩」","l":"hittite-iron","x":"ラメス2世は、この戦いを自分の大勝利として、カルナック・ルクソール・アビドス・アブ＝シンベル・ラメセウムなど各地の神殿の壁に、浮き彫りと長い詩で刻ませた。詩の中で、敵に囲まれた王は"},{"id":"hittite-iron-t7","k":"now","f":"now","kj":"いま","t":"国連本部に飾られた条約","l":"hittite-iron","x":"この条約は、両国で別々の形で残っている。エジプトではヒエログリフでカルナック神殿などの壁に刻まれ、ヒッタイトではハットゥシャの文書庫から、アッカド語で書かれた粘土板が見つかった。も"},{"id":"hittite-iron-t8","k":"source","f":"src","kj":"史料｜記録","t":"最後の手紙――ウガリト王の叫び","l":"hittite-iron","x":"シリアの港町ウガリトの遺跡からは、町が滅びる直前のものとみられる手紙が見つかっている。ウガリトの王アンムラピが、キプロス（アラシア）の王に書いた手紙である。わが父よ、ご覧ください。"},{"id":"hittite-iron-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"「パレスチナ」の名の由来","l":"hittite-iron","x":"海の民の一つに、エジプトの記録で「ペレセト」と呼ばれる集団がいる。彼らはその後、パレスチナの南の海岸地帯に住み着いた。『旧約聖書』に、イスラエル人の宿敵として登場するペリシテ人であ"},{"id":"hittite-iron-t10","k":"confuse","f":"confuse","kj":"混同注意","t":"鉄器の「使用」と「普及」","l":"hittite-iron","x":"試験では、次の二つを区別しておきたい。鉄器を早くから使用した国 → ヒッタイト（前17〜前12世紀）鉄器が西アジアから地中海一帯に広く普及した時期 → ヒッタイト滅亡後の前12世紀"},{"id":"hittite-iron-t11","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"hittite-iron","x":"篠原千絵『天は赤い河のほとり』（漫画、1995〜2002年連載）：現代の日本の少女が、古代ヒッタイト帝国にタイムスリップする物語。ムルシリ2世の時代を舞台に、ヒッタイトとエジプト、"},{"id":"holocaust-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"閉ざされた扉","l":"holocaust","x":"ナチスは、はじめ、ユダヤ人を国外に追い出そうとしていた。しかし、逃げようとするユダヤ人を受け入れる国は、ほとんどなかった。1938年7月、ユダヤ人の難民の問題を話し合うため、フラン"},{"id":"holocaust-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「すべてのユダヤ人をヨーロッパから」――幻のマダガスカル計画","l":"holocaust","x":"ナチスは、最初から、ヨーロッパのユダヤ人をすべて殺すという計画を持っていたわけではなかった。戦争の初めの時期、ナチスの指導者たちが真剣に検討していたのは、ユダヤ人をヨーロッパの外の"},{"id":"holocaust-t3","k":"voice","f":"src","kj":"史料｜証言","t":"加害者の証言と、目撃者の証言","l":"holocaust","x":"戦後のニュルンベルク裁判には、ホロコーストを証言する数多くの文書が提出された。この音声は、お使いのブラウザでは再生できない場合がある。出典のページで再生する音声ニュルンベルク裁判で"},{"id":"holocaust-t4","k":"source","f":"src","kj":"史料｜記録","t":"アンネの日記","l":"holocaust","x":"アムステルダムに住んでいたユダヤ人の少女 アンネ・フランク は、13歳の誕生日に、父から日記帳を贈られた。1942年7月、一家は、父の会社の建物の裏にある隠れ家に身を潜めた。アンネ"},{"id":"holocaust-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「あの夜を、私は決して忘れない」――生き残った人々と、解放した兵士たち","l":"holocaust","x":"当時はハンガリー領で、現在はルーマニア北部にある町シゲトに住んでいた15歳のユダヤ人の少年エリ・ヴィーゼルは、1944年、家族とともにアウシュヴィッツに送られた。母と妹は、到着した"},{"id":"holocaust-t6","k":"person","f":"deep","kj":"深掘り｜人物","t":"命のビザ","l":"holocaust","x":"1940年7月、ソ連に併合されようとしていたリトアニアの臨時の首都カウナス。日本領事館の前に、何百人ものユダヤ人の難民が詰めかけた。ナチスに占領されたポーランドから逃れてきた人々で"},{"id":"holocaust-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"holocaust","x":"ヴィクトール・フランクル『夜と霧』（1946年）：アウシュヴィッツなどの強制収容所を生き延びた精神科医が、極限状態の中での人間の心のあり方を記録した本。映画『シンドラーのリスト』（"},{"id":"homo-sapiens-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「アフリカ単一起源説」と「多地域進化説」","l":"homo-sapiens","x":"私たちの起源をめぐっては、長い論争があった。一つは、ホモ＝サピエンスはアフリカで生まれ、その後世界中に広がって、各地にいた原人や旧人と入れ替わったとするアフリカ単一起源説。もう一つ"},{"id":"homo-sapiens-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「われわれの祖先は、アフリカ大陸に住んでいた」――ダーウィンの予言","l":"homo-sapiens","x":"1871年、イギリスの博物学者チャールズ・ダーウィンは、『人間の由来』の中で、人類の起源について、こう推測した。当時、人類の祖先の化石は、ほとんど見つかっていなかった。原文It i"},{"id":"homo-sapiens-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"世界最古級の「釣り針」は沖縄で見つかった","l":"homo-sapiens","x":"沖縄県南城市のサキタリ洞遺跡では、約2万3000年前の貝殻で作った釣り針が見つかっている。世界最古級の釣り針である。この遺跡からは、モクズガニなどを食べた跡も多数見つかっており、旧"},{"id":"homo-sapiens-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「新しい人の谷」で見つかった古い人類","l":"homo-sapiens","x":"1856年、ドイツのデュッセルドルフの近くのネアンデル谷の石灰岩の採石場で、作業員たちが、洞窟の土の中から古い骨を掘り出した。石灰岩を切り出す邪魔になるので、骨は一度は捨てられかけ"},{"id":"homo-sapiens-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"花を手向けた？――シャニダール洞窟の埋葬","l":"homo-sapiens","x":"1950〜60年代、イラクのシャニダール洞窟で、ネアンデルタール人の埋葬人骨が見つかった。遺体の周りの土からは大量の花粉が検出され、「ネアンデルタール人は死者に花を手向けていた」と"},{"id":"homo-sapiens-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"私たちの中のネアンデルタール人","l":"homo-sapiens","x":"2010年、スウェーデン出身の遺伝学者スヴァンテ＝ペーボらの研究チームは、ネアンデルタール人の骨から取り出したDNAを解読し、驚くべき結果を発表した。アフリカ以外の現代人のDNAに"},{"id":"homo-sapiens-t7","k":"confuse","f":"confuse","kj":"混同注意","t":"「人種」と人類の多様性","l":"homo-sapiens","x":"ホモ＝サピエンスが世界中に広がる過程で、それぞれの土地の環境に合わせて、肌の色などの見た目が変わっていった。たとえば、紫外線の強い地域では肌の色が濃く、弱い地域では薄くなった。しか"},{"id":"homo-sapiens-t8","k":"confuse","f":"confuse","kj":"混同注意","t":"「クロマニョン人」は人種や種の名前ではない","l":"homo-sapiens","x":"「クロマニョン人」は、私たちと別の種の人類のように聞こえるが、そうではない。クロマニョン人は、ヨーロッパの後期旧石器時代に暮らしたホモ＝サピエンス、つまり私たちと同じ種の人々の呼び"},{"id":"homo-sapiens-t9","k":"debate","f":"think","kj":"考える｜諸説あり","t":"7万4000年前の巨大噴火は人類を絶滅寸前に追い込んだ？","l":"homo-sapiens","x":"約7万4000年前、インドネシアのスマトラ島にあるトバ火山が、過去数百万年で最大級の噴火を起こした。噴き出した火山灰はインドにまで厚く降り積もり、その後、地球は数年にわたって寒冷化"},{"id":"homo-sapiens-t10","k":"trivia","f":"side","kj":"こぼれ話","t":"行商の青年が見つけた日本の旧石器時代――岩宿遺跡","l":"homo-sapiens","x":"かつて、日本列島には旧石器時代の人類はいなかったと考えられていた。関東地方の赤土（関東ローム層）は、火山灰が積もった地層で、そのころは火山活動が激しく人は住めなかったと思われていた"},{"id":"homo-sapiens-t11","k":"now","f":"now","kj":"いま","t":"旧石器捏造事件","l":"homo-sapiens","x":"日本の旧石器時代の研究には、大きな汚点もある。1970年代から、宮城県などで、ある考古学研究者が次々に「日本最古」の石器を発見し、日本列島の人類の歴史は60万年前、70万年前とさか"},{"id":"homo-sapiens-t12","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"homo-sapiens","x":"ユヴァル・ノア・ハラリ『サピエンス全史』（2011年、日本語訳2016年）：ホモ＝サピエンスが、虚構を信じる力（認知革命）によって大集団で協力できるようになり、他の人類を圧倒した、"},{"id":"hre-italy-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「神聖でもなく、ローマ的でもなく、帝国でもない」","l":"hre-italy","x":"「神聖ローマ帝国」という名前は、はじめからあったわけではない。10世紀には、単に「帝国」あるいは「ローマ帝国」と呼ばれていた。12世紀、フリードリヒ1世は、教皇に対抗して、帝国も神"},{"id":"hre-italy-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"山の中で眠る皇帝","l":"hre-italy","x":"フリードリヒ1世の死後、ドイツでは、皇帝は本当は死んでおらず、ドイツ中部のキフホイザー山の地下で眠っているという伝説が生まれた。皇帝は、石のテーブルの前に座って眠り続けており、その"},{"id":"hre-italy-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ウィリアム・テル","l":"hre-italy","x":"スイスの独立の英雄として名高いのが、弓の名人ウィリアム・テル（ヴィルヘルム・テル）である。伝説によれば、ハプスブルク家の代官ゲスラーは、広場に立てた竿の上に自分の帽子を掛け、通る者"},{"id":"hre-italy-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"シチリアの晩祷","l":"hre-italy","x":"1282年3月30日、復活祭の翌日の月曜日、シチリア島のパレルモの教会の前で、夕べの祈り（晩祷）の鐘が鳴るころ、一人のフランス兵が、シチリアの女性に無礼な振る舞いをした。怒ったシチ"},{"id":"hre-italy-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"hre-italy","x":"シラー『ヴィルヘルム・テル』（戯曲、1804年）、ロッシーニ『ウィリアム・テル』（オペラ、1829年）：ハプスブルク家の代官の支配に抵抗したスイスの伝説の英雄テルの物語。息子の頭の"},{"id":"human-origins-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"日本人研究者も発見に加わった「ラミダス猿人」","l":"human-origins","x":"1990年代、エチオピアで約440万年前の人類の化石が見つかり、アルディピテクス＝ラミダス（ラミダス猿人）と名づけられた。調査チームには東京大学の諏訪元も加わっており、最初の歯の化"},{"id":"human-origins-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「ルーシー」の名はビートルズの曲から","l":"human-origins","x":"1974年、エチオピアのアファール地方で、アウストラロピテクス＝アファレンシスの全身の約40パーセントにあたる骨が見つかった。約318万年前の若い女性の骨である。発見を祝ってキャン"},{"id":"human-origins-t3","k":"relic","f":"src","kj":"史料｜遺物","t":"366万年前の足跡――ラエトリ","l":"human-origins","x":"1978年、タンザニアのラエトリで、イギリスの考古学者メアリー＝リーキーの調査隊が、火山灰の上に残された人類の足跡の列を発見した。約366万年前、近くの火山が噴火して降り積もった灰"},{"id":"human-origins-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"「失われた環」を探しに軍医になった男――デュボワ","l":"human-origins","x":"ジャワ原人を見つけたのは、オランダの若い解剖学者ウジェーヌ・デュボワである。彼は、人類と類人猿をつなぐ「失われた環（ミッシング・リンク）」は、熱帯のアジアで見つかるはずだと信じてい"},{"id":"human-origins-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"北京原人の化石は戦争で行方不明になった","l":"human-origins","x":"北京原人の化石は、1920年代から30年代にかけて、北京郊外の周口店の洞窟で見つかった。頭骨や歯など40体分以上の骨が発掘され、世界的な大発見となった。ところが、日中戦争のさなかの"},{"id":"human-origins-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"人類はいつ火を使い始めたのか","l":"human-origins","x":"火を使うことは、人類の歴史で最も大きな出来事の一つである。火は、夜の闇と寒さ、猛獣から身を守り、食べ物を加熱して消化しやすくした。加熱した食べ物から多くのエネルギーをとれるようにな"},{"id":"human-origins-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"洞窟の奥の「地底の宇宙飛行士」","l":"human-origins","x":"2013年、南アフリカのライジング・スター洞窟の奥深くで、洞窟探検家たちが大量の人骨を見つけた。ところが、骨のある部屋に行くには、幅がわずか18センチほどしかない岩の割れ目を通り抜"},{"id":"human-origins-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"身長1メートルの「ホビット」","l":"human-origins","x":"2003年、インドネシアのフローレス島で、身長1メートルほど、脳の容積も400cc程度という小さな人類の化石が見つかった。ホモ＝フロレシエンシスと名づけられ、映画『ロード・オブ・ザ"},{"id":"human-origins-t9","k":"confuse","f":"confuse","kj":"混同注意","t":"猿人・原人・旧人・新人は「分類」ではない","l":"human-origins","x":"日本の教科書では、人類の進化を「猿人→原人→旧人→新人」の4段階で説明することが多い。分かりやすい区分だが、注意も必要だ。これは生物学上の正式な分類ではなく、進化の段階をおおまかに"},{"id":"human-origins-t10","k":"trivia","f":"side","kj":"こぼれ話","t":"道具は人類だけのものではなかった","l":"human-origins","x":"石器を作ることは、長い間「ヒト属（ホモ属）の証」とされてきた。ところが2015年、ケニアのトゥルカナ湖のほとりのロメクウィ遺跡で、約330万年前の石器が見つかったと発表された。ホモ"},{"id":"human-origins-t11","k":"trivia","f":"side","kj":"こぼれ話","t":"40年間見破られなかった偽の化石――ピルトダウン人","l":"human-origins","x":"1912年、イギリスのピルトダウンで、アマチュア考古学者のドーソンが「人類と類人猿をつなぐ化石」を発見したと発表した。頭骨は人間のように大きいのに、あごは類人猿のようだったので、「"},{"id":"human-origins-t12","k":"trivia","f":"side","kj":"こぼれ話","t":"「タウング・チャイルド」と猛禽類","l":"human-origins","x":"1924年、南アフリカのタウングの石灰岩採石場で、幼い子どもの頭骨の化石が見つかった。解剖学者ダートは、これを人類の祖先と考え、アウストラロピテクス＝アフリカヌス（「アフリカの南の"},{"id":"human-origins-t13","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"human-origins","x":"映画『人類創世』（ジャン＝ジャック・アノー監督、1981年）：火を絶やしてしまった原始人の部族の若者たちが、火を求めて旅に出る物語。せりふはほとんどなく、言語学者がつくった架空の原"},{"id":"hundred-schools-t1","k":"source","f":"src","kj":"史料｜記録","t":"『論語』のことば","l":"hundred-schools","x":"原文子曰：道之以政，齊之以刑，民免而無恥；道之以德，齊之以禮，有恥且格。現代語訳先生（孔子）は言われた。「法令で民を導き、刑罰で民を統制すれば、民は刑罰をうまく免れようとして、恥を"},{"id":"hundred-schools-t2","k":"source","f":"src","kj":"史料｜記録","t":"孟子の性善説","l":"hundred-schools","x":"原文所以謂人皆有不忍人之心者，今人乍見孺子將入於井，皆有怵惕惻隱之心。非所以內交於孺子之父母也，非所以要譽於鄉黨朋友也，非惡其聲而然也。現代語訳人が、幼い子どもが今にも井戸に落ちそ"},{"id":"hundred-schools-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"孟子と荀子","l":"hundred-schools","x":"孟子荀子人間の本性性善説（生まれつき善の芽生えをもつ）性悪説（生まれつき利己的で争う）重視したもの内にある善の芽生えを育てること。王道政治外からの礼による矯正と学習。礼治主義政治思"},{"id":"hundred-schools-t4","k":"source","f":"src","kj":"史料｜記録","t":"墨子、戦争を止める","l":"hundred-schools","x":"楚の王が、名工の公輸盤がつくった雲梯（城攻めの長いはしご）を使って、小国の宋を攻めようとしているという知らせを聞いた墨子は、10日10晩歩き続けて楚の都に駆けつけた。原文子墨子解帶"},{"id":"hundred-schools-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"老子は実在したか","l":"hundred-schools","x":"『史記』は、老子を、孔子が礼について教えを受けた、周の王室の記録係であったと記している。しかし、司馬遷自身も、老子が誰であったかについて、いくつかの異なる説を併記しており、老子が実"},{"id":"hundred-schools-t6","k":"source","f":"src","kj":"史料｜記録","t":"胡蝶の夢","l":"hundred-schools","x":"原文昔者莊周夢為胡蝶，栩栩然胡蝶也，自喻適志與！不知周也。俄然覺，則蘧蘧然周也。不知周之夢為胡蝶與，胡蝶之夢為周與？現代語訳昔、荘周（荘子）は、夢の中で蝶になった。ひらひらと楽しく"},{"id":"hundred-schools-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"『韓非子』から生まれた故事成語","l":"hundred-schools","x":"「矛盾」：楚の人が、「この盾はどんな矛でも突き通せない」「この矛はどんな盾でも突き通す」と自慢した。ある人が「では、その矛でその盾を突いたらどうなるか」と尋ねると、答えられなかった"},{"id":"hundred-schools-t8","k":"confuse","f":"confuse","kj":"混同注意","t":"諸子百家の主な学派","l":"hundred-schools","x":"学派主な思想家主な主張主な書物儒家孔子・孟子・荀子仁と礼、徳治主義。孟子は性善説、荀子は性悪説『論語』『孟子』『荀子』道家老子・荘子無為自然、万物斉同『老子』『荘子』墨家墨子兼愛・"},{"id":"hundred-schools-t9","k":"now","f":"now","kj":"いま","t":"2000年ぶりに出てきた『孫子』","l":"hundred-schools","x":"かつて、『孫子』の作者については、春秋時代の孫武とする説と、その子孫で戦国時代の斉に仕えた孫臏とする説があり、決着がついていなかった。1972年、山東省の銀雀山にある前漢の墓から、"},{"id":"hundred-schools-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"hundred-schools","x":"酒見賢一『墨攻』（小説、1991年、中島敦記念賞）：墨家の革離が、たった一人で小国の城の守りを任され、大軍の攻撃から城を守る物語。のちに森秀樹によって漫画化され、2006年には香港"},{"id":"hundred-years-war-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"誰が王に負けを伝えるか","l":"hundred-years-war","x":"1340年6月、フランドルの沖のスロイスの港で、イングランドの艦隊がフランスの艦隊を打ち破った。フランス側の船は、ほとんどが沈められるか奪われ、数千人の兵士が海に落ちて死んだ。立体"},{"id":"hundred-years-war-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「思い邪なる者に災いあれ」――ガーター勲章","l":"hundred-years-war","x":"クレシーの勝利の後、エドワード3世は、1348年ごろ、イングランド最高の騎士の団体として「ガーター騎士団」を創設した。その標語は、フランス語で「Honi soit qui mal "},{"id":"hundred-years-war-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「フラン」の誕生と、約束を守った王","l":"hundred-years-war","x":"1360年、ジャン2世は、身代金の一部を払い、息子たちを人質として差し出すことを条件に、いったんフランスに帰ることを許された。この年、王の身代金を支払うために、新しい金貨が造られた"},{"id":"hundred-years-war-t4","k":"voice","f":"src","kj":"史料｜証言","t":"リモージュの「慈悲を」","l":"hundred-years-war","x":"1370年、黒太子エドワードは、フランス側に寝返った町リモージュを攻め落とした。病に冒され、輿に乗って指揮をとっていた黒太子の怒りは激しかった。年代記作者フロワサールは、こう書いて"},{"id":"hundred-years-war-t5","k":"works","f":"works","kj":"作品","t":"シェイクスピア『ヘンリー五世』","l":"hundred-years-war","x":"アザンクールの戦いは、およそ180年後、シェイクスピアの戯曲『ヘンリー五世』（1599年ごろ）によって、イギリスの人々の記憶に深く刻まれた。戦いの前、数に劣る兵士たちを前に、王はこ"},{"id":"hundred-years-war-t6","k":"source","f":"src","kj":"史料｜記録","t":"「天の王の使いの乙女」――イングランド王への手紙","l":"hundred-years-war","x":"1429年3月、ジャンヌは、オルレアンを包囲するイングランド軍に、手紙を送った。字の読み書きのできなかったジャンヌが口述したこの手紙は、こう始まっている。原文JHESUS MARI"},{"id":"hundred-years-war-t7","k":"source","f":"src","kj":"史料｜記録","t":"「もし私が神の恵みの中にいないのなら」","l":"hundred-years-war","x":"裁判の記録には、ジャンヌと裁判官たちのやりとりが残されている。ある日、裁判官は、ジャンヌに、こう尋ねた。「おまえは、自分が神の恵みの中にいると思うか」。これは、恐ろしい罠であった。"},{"id":"hundred-years-war-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"百年戦争は何を変えたのか","l":"hundred-years-war","x":"百年戦争は、両国の社会を大きく変えた。騎士の時代の終わり クレシーやアザンクールでは、身分の低い長弓兵が、貴族の騎士を打ち破った。さらに戦争の終わりには、大砲が城壁や騎士の隊列を打"},{"id":"hundred-years-war-t9","k":"now","f":"now","kj":"いま","t":"駐車場の下から見つかった王","l":"hundred-years-war","x":"ボズワースで戦死したリチャード3世の遺体は、レスターの町のフランシスコ会の修道院に、ひっそりと葬られた。しかし、16世紀の修道院の解散の際に修道院は壊され、墓の場所は分からなくなっ"},{"id":"huns-attila-t1","k":"source","f":"src","kj":"史料｜記録","t":"ローマ人の目に映ったフン人","l":"huns-attila","x":"原文…… ut neque igni neque saporatis indigeant cibis, sed radicibus herbarum agrestium et se"},{"id":"huns-attila-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"フン人と匈奴","l":"huns-attila","x":"フン人と匈奴を結びつける説には、次のような根拠が挙げられている。4世紀初めに中央アジアのソグド人の商人が書いた手紙で、中国の洛陽を攻めた匈奴が「フン（xwn）」と呼ばれている。フン"},{"id":"huns-attila-t3","k":"source","f":"src","kj":"史料｜記録","t":"アッティラの宴","l":"huns-attila","x":"原文τοῖς μὲν γὰρ ἄλλοις βαρβάροις καὶ ἡμῖν ἐπεσκεύαστο δεῖπνα πολυτελῆ ἐν πίναξι κυκλοτερέσι"},{"id":"huns-attila-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"「最後のローマ人」アエティウス","l":"huns-attila","x":"アエティウス（390年ごろ〜454年）は、ドナウ川沿いの属州出身の軍人の子であった。少年時代、西ローマ帝国と西ゴート人・フン人との和平のための人質として、アラリックのもとで、さらに"},{"id":"huns-attila-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"アッティラはなぜ引き返したのか","l":"huns-attila","x":"教会の伝説では、アッティラは、レオ1世の威厳に打たれ、あるいはレオ1世の背後に剣を持った聖ペテロと聖パウロが現れたのを見て、恐れて引き返したとされる。しかし、これは後世の教会の伝承"},{"id":"huns-attila-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"ヴェネツィアの誕生","l":"huns-attila","x":"アッティラがアクイレイアなどの北イタリアの都市を破壊すると、多くの人々が、アドリア海の沿岸の干潟に浮かぶ小さな島々に逃れたという。陸地から離れた干潟は、騎馬の軍隊が近づけない安全な"},{"id":"huns-attila-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"三重の棺","l":"huns-attila","x":"ヨルダネスによれば、フン人たちは、アッティラの遺体を、金・銀・鉄の三重の棺に納め、夜の闇の中でひそかに葬った。そして、財宝を奪われないよう、墓を掘った者たちを殺したという。アッティ"},{"id":"huns-attila-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"ハンガリーはフン人の国？","l":"huns-attila","x":"ハンガリー（ハンガリー語ではマジャロルサーグ）の国名は、フン人とは関係がない。ハンガリーの人々の祖先であるマジャル人は、アッティラの時代から400年以上たった9世紀末に、東方から現"},{"id":"huns-attila-t9","k":"works","f":"works","kj":"作品","t":"この時代にまつわる作品","l":"huns-attila","x":"ヴェルディのオペラ『アッティラ』（1846年初演）：アクイレイアを滅ぼしたアッティラと、復讐をねらう娘オダベッラ、ローマの将軍エツィオ（アエティウス）らの物語。イタリアの統一運動（"},{"id":"ice-age-t1","k":"mech","f":"deep","kj":"深掘り｜しくみ","t":"なぜ氷期はくり返すのか――捕虜の数学者の計算","l":"ice-age","x":"氷期という考え方そのものが、19世紀の発見である。1837年、スイスの博物学者アガシーは、アルプスから遠く離れた平野に転がる巨大な岩（迷子石）や、岩に刻まれた引っかき傷は、かつてヨ"},{"id":"ice-age-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"北海の海底から見つかる石器","l":"ice-age","x":"北海の底を引き網で漁をすると、ときどきマンモスの骨や、人類が使った石器、骨角器が網にかかる。これらは、海に沈んだドッガーランドに人々が暮らしていた証拠である。ドッガーランドは、氷期"},{"id":"ice-age-t3","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"マンモスの骨で作った家","l":"ice-age","x":"ウクライナのメジリチ遺跡では、約1万5000年前の、マンモスの骨を組み上げて作った住居の跡が見つかっている。直径5メートルほどの円形の住居で、土台にはマンモスの頭骨や下あごの骨をず"},{"id":"ice-age-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"服を着始めたのはいつか――シラミが教えてくれる","l":"ice-age","x":"人類がいつから服を着るようになったのかは、服そのものが残らないので分かりにくい。そこで研究者が目をつけたのが、人間に寄生するシラミだった。人間のシラミには、髪に住むアタマジラミと、"},{"id":"ice-age-t5","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"狩猟採集民はどのくらい働いていたのか","l":"ice-age","x":"狩猟採集民の生活というと、飢えと隣り合わせの厳しい暮らしを想像しがちだ。しかし、20世紀にアフリカのカラハリ砂漠の狩猟採集民（サン人）を調べた人類学者たちは、彼らが食料を得るために"},{"id":"ice-age-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"最後のマンモス","l":"ice-age","x":"マンモスの多くは約1万年前までに絶滅したが、北極海に浮かぶロシアのウランゲリ島では、約4000年前まで小型のマンモスが生き残っていた。約4000年前といえば、エジプトではすでにピラ"},{"id":"ice-age-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"野尻湖のナウマンゾウ","l":"ice-age","x":"長野県の野尻湖の湖底からは、1948年以来、ナウマンゾウの化石が数多く見つかっている。ナウマンゾウは、明治時代に日本の地質学の基礎を築いたドイツ人の地質学者ナウマンにちなんで名づけ"},{"id":"ice-age-t8","k":"confuse","f":"confuse","kj":"混同注意","t":"「中石器時代」とは","l":"ice-age","x":"旧石器時代と新石器時代の間を、とくにヨーロッパでは「中石器時代」と呼ぶことがある。氷期が終わり、大型動物が減って森が広がった環境の中で、人々が弓矢で中小の動物を狩り、魚や貝をとり、"},{"id":"ice-age-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"ice-age","x":"園山俊二『はじめ人間ギャートルズ』（漫画、1965年〜、アニメ1974年）：マンモスを追う原始人たちの暮らしを描いたギャグ漫画。骨つきの「マンガ肉」のイメージを広めた。映画『アイス"},{"id":"imjin-war-t1","k":"war","f":"deep","kj":"深掘り｜戦術","t":"なぜ朝鮮水軍は強かったのか","l":"imjin-war","x":"日本の水軍の戦法は、敵の船に近づいて鉄砲を撃ちかけ、乗り移って刀で斬り込むものであった。日本の船は、速さを重んじた細長い船で、大砲はほとんど積んでいなかった。これに対して、朝鮮の板"},{"id":"imjin-war-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"幸州山城と「前掛け」","l":"imjin-war","x":"幸州山城の戦いでは、城の中の女性たちも、石を運んで戦いを助けたと伝えられる。韓国語で女性の前掛けを「幸州チマ」というのは、このとき女性たちが前掛けに石を包んで運んだからだ、という話"},{"id":"imjin-war-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"秀吉は明の国書を破り捨てた？","l":"imjin-war","x":"このとき、怒った秀吉が、明の皇帝の文書（誥命）や冠を投げ捨て、文書を引き裂いた、という話がよく知られている。しかし、このとき秀吉に与えられた明の皇帝の誥命の原本は、現在、大阪歴史博"},{"id":"imjin-war-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「親は子を嘆き、子は親を尋ね」――従軍僧の日記","l":"imjin-war","x":"1597年の丁酉再乱（慶長の役）で、豊後の大名太田一吉の医僧として朝鮮に渡った浄土真宗の僧慶念は、目にした光景を、和歌をまじえた日記に書きとめた。原文野も山も、城は申すに及ばず皆々"},{"id":"imjin-war-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"連れて来られた人々と日本の文化","l":"imjin-war","x":"戦争の中で、多くの朝鮮の人々が、日本に連れ去られた。その中には、陶磁器をつくる陶工たちも多く含まれていた。肥前（佐賀県）の鍋島氏に連れて来られた陶工の李参平は、有田の泉山で、磁器の"},{"id":"imjin-war-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"imjin-war","x":"映画『バトル・オーシャン 海上決戦』（2014年、韓国、原題『鳴梁』）：わずか12隻の船で日本の大艦隊を迎え撃った、李舜臣の鳴梁の海戦を描いた映画。韓国の歴代の観客動員数の記録を打"},{"id":"imperialism-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"帝国主義を批判した人々","l":"imperialism","x":"帝国主義の時代に、それを鋭く批判する人々もいた。1902年、イギリスの経済学者ホブソンは、『帝国主義論』を著した。彼は、国内の労働者の賃金が低く抑えられているために、国内で商品が売"},{"id":"imperialism-t2","k":"music","f":"music","kj":"音楽","t":"「希望と栄光の国」――『威風堂々』","l":"imperialism","x":"1901年、イギリスの作曲家エルガーは、行進曲『威風堂々』第1番を発表した。その中間部の雄大な旋律に、翌年、エドワード7世の戴冠を祝う頌歌のために歌詞がつけられたのが、「希望と栄光"},{"id":"imperialism-t3","k":"source","f":"src","kj":"史料｜記録","t":"「惑星も併合したい」","l":"imperialism","x":"南アフリカで、ダイヤモンドと金の鉱山で巨万の富を築き、ケープ植民地の首相として、アフリカでのイギリスの勢力拡大を推し進めたセシル・ローズ（→「アフリカ分割」の回）。彼の言葉として伝"},{"id":"inca-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"海の魚を食べた山の皇帝","l":"inca","x":"インカ道の中継所には、2〜3km（半日の行程ともいわれる）ごとに、若い飛脚たちが待機していた。飛脚は、知らせを口で伝え、キープを持って、次の中継所まで全速力で走った。そして、次の飛"},{"id":"inca-t2","k":"source","f":"src","kj":"史料｜記録","t":"「クスコとは、大地のへそである」――インカ・ガルシラーソの『インカ皇統記』","l":"inca","x":"インカ帝国の征服からおよそ70年後の1609年、スペインのリスボンで、一冊の歴史書が出版された。著者は、スペイン人の征服者の父と、インカの王族の血をひく母との間にクスコで生まれた、"},{"id":"inca-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"なぜ170人が勝ったのか","l":"inca","x":"カハマルカで、なぜ、わずか170人のスペイン人が、インカ皇帝を捕らえることができたのだろうか。鉄の剣や鎧、鉄砲や大砲、そして馬は、アンデスの人々が初めて目にする武器であった。とくに"},{"id":"inca-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"inca","x":"エルジェ『タンタンの冒険 ななつの水晶球』『太陽の神殿』（漫画、1948〜1949年）：インカの王のミイラの呪いと、アンデスの山中に生き残るインカの人々をめぐる冒険。ベルギーの漫画"},{"id":"india-buddhism-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ブッダはいつの人か","l":"india-buddhism","x":"ブッダが80歳で亡くなったことは、どの伝承でも一致している。しかし、その年代については、大きく2つの説がある。スリランカに伝わる年代記などに基づく説では、ブッダの生涯は、前563年"},{"id":"india-buddhism-t2","k":"source","f":"src","kj":"史料｜記録","t":"ブッダのことば","l":"india-buddhism","x":"ブッダの言葉は、はじめは弟子たちによって暗唱で伝えられ、のちに文字に記された。最も古い層に属するとされる経典から、いくつか紹介しよう。原文na hi verena verāni s"},{"id":"india-buddhism-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"日本語の中の仏教のことば","l":"india-buddhism","x":"仏教は、中国を経て6世紀に日本に伝わり、日本語の中に多くの言葉を残した。「我慢」：もとは、自分に執着して思い上がる心（我への慢心）を意味する、悪い意味の言葉だった。「醍醐味」：醍醐"},{"id":"india-buddhism-t4","k":"now","f":"now","kj":"いま","t":"ガンディーと不殺生","l":"india-buddhism","x":"ジャイナ教の不殺生の思想は、インドの文化に深く根づいた。20世紀のインド独立運動の指導者ガンディーは、ジャイナ教徒の多いグジャラート地方に生まれ、若いころには、ジャイナ教の在家の思"},{"id":"india-buddhism-t5","k":"confuse","f":"confuse","kj":"混同注意","t":"バラモン教・仏教・ジャイナ教","l":"india-buddhism","x":"バラモン教仏教ジャイナ教開祖なし（ヴェーダの宗教）ガウタマ＝シッダールタ（ブッダ）ヴァルダマーナ（マハーヴィーラ）開祖の出身―クシャトリヤ（シャーキャ族の王子）クシャトリヤヴェーダ"},{"id":"india-buddhism-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"india-buddhism","x":"手塚治虫『ブッダ』（漫画、1972〜1983年連載）：ゴータマ＝シッダールタの生涯を、多くの架空の人物を交えて描いた大作。ヴァルナ制に苦しむ人々の姿や、生と死をめぐる問いが、壮大な"},{"id":"india-colonial-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ティプーの虎","l":"india-colonial","x":"シュリーランガパトナの宮殿で、イギリス軍は、奇妙なからくり人形を見つけた。等身大の木彫りの虎が、あおむけに倒れたヨーロッパ人の兵士に襲いかかっている。虎の脇腹のハンドルを回すと、中"},{"id":"india-colonial-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「光の山」の旅","l":"india-colonial","x":"パンジャーブ地方が併合された1849年、イギリスは、シク王国の宝物の中から、一つのダイヤモンドを手に入れた。「コーヒヌール（光の山）」と呼ばれる、世界最大級のダイヤモンドである。そ"},{"id":"india-colonial-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「サグ」の撲滅","l":"india-colonial","x":"1830年代、インド総督ベンティンクのもとで、イギリスの官吏スリーマンは、「サギー（サグ）」と呼ばれる強盗団の摘発に乗り出した。彼らは、旅人の一行に仲間のふりをして加わり、夜になる"},{"id":"india-colonial-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"india-colonial","x":"キプリング『少年キム』（小説、1901年）：イギリス領インドで育った少年キムが、チベットのラマ僧と旅をしながら、英露の諜報戦（グレート・ゲーム）に関わっていく物語。映画『RRR』（"},{"id":"india-partition-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"なぜ8月15日だったのか","l":"india-partition","x":"マウントバッテンが、独立の日を8月15日に選んだのには、理由があった。8月15日は、2年前に日本が降伏を受け入れた日である。マウントバッテンは、第二次世界大戦中、東南アジア連合軍の"},{"id":"india-partition-t2","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"象のインディラ","l":"india-partition","x":"戦争中の1943年、東京の上野動物園では、空襲で檻が壊れて猛獣が逃げ出すことを恐れた東京都の命令で、ゾウやライオンなどの動物が殺された。3頭のゾウは、毒入りのエサを受けつけず、餓死"},{"id":"india-partition-t3","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"india-partition","x":"映画『ガンジー』（リチャード・アッテンボロー監督、1982年）：南アフリカでの差別との闘いから、塩の行進、分離独立、暗殺までのガンディーの生涯を描き、アカデミー賞作品賞を受賞した。"},{"id":"indian-ocean-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"インドに運ばれた馬","l":"indian-ocean","x":"南インドの王たちは、戦争のために、アラビアやペルシアの馬を高い値段で買い求めた。インドの暑く湿った気候では、良い馬が育ちにくかったからである。マルコ＝ポーロは、南インドのマアバル（"},{"id":"indian-ocean-t2","k":"source","f":"src","kj":"史料｜記録","t":"カイロの物置に眠っていた手紙――ゲニザ文書","l":"indian-ocean","x":"19世紀の末、エジプトのカイロの古いユダヤ教の会堂（シナゴーグ）の物置部屋から、数十万点にのぼる古い文書の断片が見つかった。ユダヤ教では、神の名が書かれているかもしれない紙は捨てず"},{"id":"indian-ocean-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"東南アジアのイスラームはどこから来たのか","l":"indian-ocean","x":"東南アジアに伝わったイスラームが、どこから来たのかについては、いくつもの説がある。アラビア半島から直接伝わったとする説、インドのグジャラートやベンガル、南インドから伝わったとする説"},{"id":"indian-ocean-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"ガジャ・マダの「パラパの誓い」","l":"indian-ocean","x":"マジャパヒト王国の宰相ガジャ・マダは、1336年ごろ、宰相に任じられたときに、次のように誓ったと、のちの歴史書『パララトン』は伝えている。「ヌサンタラ（周辺の島々）を征服したならば"},{"id":"indian-ocean-t5","k":"source","f":"src","kj":"史料｜記録","t":"「マラッカを制する者は、ヴェネツィアののどを押さえる」","l":"indian-ocean","x":"1511年にマラッカがポルトガルに占領された直後、この町に滞在したポルトガル人の薬種商トメ・ピレスは、『東方諸国記』という本に、マラッカの繁栄のありさまを書き残している。ピレスによ"},{"id":"indian-rebellion-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"村から村へ渡るチャパティ","l":"indian-rebellion","x":"反乱が起こる数か月前の1857年の初め、北インドの各地で、奇妙なことが起こっていた。村の見張り番のもとに、どこからか何枚かのチャパティ（小麦粉を練って焼いた薄いパン）が届けられる。"},{"id":"indian-rebellion-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"「インドのジャンヌ・ダルク」","l":"indian-rebellion","x":"反乱の指導者の中で、今もインドで最も愛されているのが、ジャーンシー藩王国の王妃 ラクシュミー・バーイー である。画像はオンライン時に表示される（Wikimedia Commonsで"},{"id":"indian-rebellion-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「愛する人のそばに、2ガズの土地さえ得られなかった」――バハードゥル・シャー2世","l":"indian-rebellion","x":"1857年の反乱で、反乱軍に担ぎ出されたムガル帝国の最後の皇帝バハードゥル・シャー2世は、82歳の老人であった。デリーが陥落すると、彼は捕らえられ、反逆の罪で裁かれて、1858年、"},{"id":"indian-rebellion-t4","k":"source","f":"src","kj":"史料｜記録","t":"「インドの臣民にも、他のすべての臣民と同じ義務を負う」――ヴィクトリア女王の布告","l":"indian-rebellion","x":"1858年11月1日、インドの各地で、イギリスのヴィクトリア女王の布告が読み上げられた。東インド会社のインド統治は終わり、インドは、イギリス国王の直接の支配下に置かれることになった"},{"id":"indian-rebellion-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「シパーヒーの反乱」か、「第一次独立戦争」か","l":"indian-rebellion","x":"1857年の出来事を、何と呼ぶべきか。この問いは、今も議論の的である。イギリスでは、長い間、これは軍の一部の兵士による「反乱（ミューティニー）」、すなわち「セポイの反乱」と呼ばれて"},{"id":"indian-rebellion-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"indian-rebellion","x":"映画『マニカルニカ ジャーンシーの女王』（2019年、インド）：インド大反乱で、イギリス軍と戦って戦死したジャーンシー藩王国の王妃ラクシュミー・バーイーの生涯を描いた映画。作品は史"},{"id":"indus-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"「インダス文明」の時代は、アーリヤ人の時代ではない","l":"indus","x":"インドの古代史で混同しやすいのが、インダス文明とアーリヤ人の関係である。インダス文明アーリヤ人のヴェーダ時代時代前2600〜前1900年ごろ前1500年ごろ〜中心地インダス川流域（"},{"id":"indus-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「大浴場」と「穀物倉」","l":"indus","x":"モエンジョ＝ダーロの城塞の上には、「大浴場」と呼ばれる施設がある。長さ約12m、幅約7m、深さ約2.4mの長方形のプールで、底と壁には煉瓦がすき間なく並べられ、水が漏れないようにア"},{"id":"indus-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"世界最古の木綿","l":"indus","x":"インダス文明の人々は、世界で最も早く木綿を栽培し、布を織った人々の一つである。モエンジョ＝ダーロからは、木綿の布の切れ端が銀の器にくっついた状態で見つかっている。のちのギリシア人や"},{"id":"indus-t4","k":"source","f":"src","kj":"史料｜記録","t":"「メルッハの船」","l":"indus","x":"アッカド王国のサルゴン（前24〜前23世紀）は、碑文の中で、自分の都の岸壁に遠い国々の船を停泊させたと誇っている。メルッハの船、マガンの船、ディルムンの船を、彼はアッカドの岸壁に停"},{"id":"indus-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"「四大文明」という言い方","l":"indus","x":"日本では、メソポタミア・エジプト・インダス・中国（黄河）の四つの文明を「四大文明」と呼ぶことが多い。しかし、この呼び方は、主に日本や中国で使われてきたもので、欧米の歴史学では一般的"},{"id":"indus-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「アーリヤ人がインダス文明を滅ぼした」","l":"indus","x":"20世紀半ば、モエンジョ＝ダーロを発掘したイギリスの考古学者ウィーラーは、遺跡の最上層の通りや家の中から、埋葬されずに放置されたような人骨がいくつか見つかったことに注目した。そして"},{"id":"indus-t7","k":"now","f":"now","kj":"いま","t":"遺伝子が語る人々の歴史","l":"indus","x":"2019年、インドのラーキーガリー遺跡で見つかった、インダス文明の時代の女性の人骨から、DNAの解析結果が発表された。その結果、この女性の祖先には、イラン方面の古い狩猟採集民と、南"},{"id":"indus-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"indus","x":"映画『モヘンジョ・ダロ』（アシュトーシュ・ゴーワリケール監督、2016年、インド）：インダス文明の都市を舞台にした歴史ロマン。未解読のインダス文字の時代を、大胆な想像で描いている。"},{"id":"industrial-revolution-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「ジェニー」とはだれか","l":"industrial-revolution","x":"ジェニー紡績機の「ジェニー」は、発明者ハーグリーヴズの妻や娘の名前だという話が広く知られている。娘が糸車を倒してしまった時、横倒しになっても糸車が回り続けるのを見て、発明を思いつい"},{"id":"industrial-revolution-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「私がここで売っているのは、世界中の人がほしがるもの――力です」","l":"industrial-revolution","x":"ワットの蒸気機関を製造し、売り込んだのは、バーミンガムの実業家マシュー・ボールトンであった。1776年、作家ボズウェルは、バーミンガム郊外のボールトンのソーホー工場を見学した。その"},{"id":"industrial-revolution-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"時間が変わった","l":"industrial-revolution","x":"鉄道は、人々の時間の感覚まで変えた。それまで、イギリスの各地の町は、太陽の動きにもとづいて、それぞれ独自の時刻を使っていた。ロンドンとブリストルでは、10分ほどの時差があった。しか"},{"id":"industrial-revolution-t4","k":"now","f":"now","kj":"いま","t":"人新世のはじまり？","l":"industrial-revolution","x":"人間の活動が、地球の環境や地層にまで大きな影響を与えるようになった現代を、地質学の新しい時代「人新世（アントロポセン）」と呼ぼうという提案がある。この言葉を広めたノーベル化学賞受賞"},{"id":"industrial-revolution-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"industrial-revolution","x":"ディケンズ『ハード・タイムズ』（小説、1854年）：架空の工業都市「コークタウン」を舞台に、事実と数字だけを重んじる功利主義の教育と、工場で働く人々の暮らしを描いた小説。作品は史実"},{"id":"industrial-society-t1","k":"source","f":"src","kj":"史料｜記録","t":"ブロード・ストリートのポンプ","l":"industrial-society","x":"19世紀のヨーロッパの都市を何度も襲ったのが、インドから広がった感染症コレラであった。激しい下痢と脱水で、発病から数時間で死に至ることもある恐ろしい病気である。当時は、コレラは、汚"},{"id":"industrial-society-t2","k":"voice","f":"src","kj":"史料｜証言","t":"6歳から、朝5時から夜9時まで――工場で働いた少女の証言","l":"industrial-society","x":"1832年、イギリス議会の委員会（委員長の名からサドラー委員会と呼ばれる）は、繊維工場で働く子どもたちの実態を調べるため、多くの労働者から証言を聞いた。23歳のエリザベス・ベントリ"},{"id":"industrial-society-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"豊かになったのか、貧しくなったのか","l":"industrial-society","x":"産業革命は、労働者の生活を豊かにしたのか、それとも貧しくしたのか。これは、歴史家たちの間で、長く続いてきた論争である（「生活水準論争」）。楽観的な立場の歴史家は、統計を示して、19"},{"id":"industrial-society-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"industrial-society","x":"ゾラ『ジェルミナール』（小説、1885年）：北フランスの炭鉱を舞台に、過酷な労働とストライキを描いた小説。映画『モダン・タイムス』（チャールズ・チャップリン監督、1936年）：工場"},{"id":"interwar-1920s-t1","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"札束の暮らし","l":"interwar-1920s","x":"インフレーションが頂点に達した1923年の秋、ドイツの人々の暮らしは、まるで悪い夢のようであった。買い物に行く人は、札束を、手提げかばんや、乳母車や、手押し車に積んで出かけた。泥棒"},{"id":"interwar-1920s-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"日本国憲法第9条のルーツ","l":"interwar-1920s","x":"不戦条約の言葉は、どこかで聞いたことがないだろうか。原文The High Contracting Parties solemnly declare in the names of "},{"id":"interwar-1920s-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"大西洋を越えた25歳","l":"interwar-1920s","x":"1927年5月20日の朝、ニューヨークの郊外の飛行場から、1機の小さな単葉機が、ガソリンを満載して、よろめくように飛び立った。操縦席には、25歳の郵便飛行士、チャールズ・リンドバー"},{"id":"interwar-1920s-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"カポネを捕まえたもの","l":"interwar-1920s","x":"数々の殺人に関わったとされながら、アル・カポネは、なかなか罪に問われなかった。証人たちは脅され、警察や役人は買収されていたからである。最後にカポネを刑務所に送ったのは、殺人の罪でも"},{"id":"interwar-1920s-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"「国辱の日」","l":"interwar-1920s","x":"排日移民法は、日本の人々に強い衝撃を与えた。日本は、パリ講和会議で人種差別の撤廃を訴えて退けられたばかりであった（→「ヴェルサイユ体制とワシントン体制」の回）。今度は、友好国と信じ"},{"id":"interwar-1920s-t6","k":"voice","f":"src","kj":"史料｜証言","t":"「嘘だよ、君」――関東大震災と流言","l":"interwar-1920s","x":"1923年9月1日、関東地方を大地震が襲った。東京と横浜では大火災が起こり、死者・行方不明者は10万人を超えた。混乱の中、「朝鮮人が井戸に毒を入れた」「朝鮮人が放火している」といっ"},{"id":"interwar-1920s-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"interwar-1920s","x":"フィッツジェラルド『グレート・ギャツビー』（小説、1925年）：好景気にわく1920年代のニューヨークの郊外を舞台に、毎夜豪華なパーティーを開く謎の富豪ギャツビーの、かなわぬ恋を描"},{"id":"intro-calendar-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ナイル川の洪水とシリウス星","l":"intro-calendar","x":"古代エジプトでは、毎年夏にナイル川が増水し、上流から肥えた土を運んできた。この増水の始まりと、明け方の東の空に恒星シリウスが初めて見える日がほぼ一致することに、エジプト人は気づいて"},{"id":"intro-calendar-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"イエスは「紀元前」に生まれた？","l":"intro-calendar","x":"ディオニシウスの計算には誤りがあったと考えられている。新約聖書の福音書によれば、イエスが生まれたのはユダヤのヘロデ王の時代である。ところがヘロデ王は、ほかの史料から前4年に死んだこ"},{"id":"intro-calendar-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"「0年」は存在しない","l":"intro-calendar","x":"西暦には「0年」がない。前1年の次の年が後1年である。ディオニシウスの時代のヨーロッパには、数としての「0」の考え方がまだなかったからだ（0はインドで生まれ、イスラーム世界を経て1"},{"id":"intro-calendar-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"シェイクスピアとセルバンテスは同じ日に死んだ？","l":"intro-calendar","x":"1616年4月23日、イギリスの劇作家シェイクスピアと、スペインの作家セルバンテスが亡くなったとされる。この偶然にちなんで、4月23日はユネスコの「世界本の日」に定められている。し"},{"id":"intro-calendar-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「11日を返せ」暴動","l":"intro-calendar","x":"イギリスがグレゴリウス暦に切り替えた1752年には、9月2日の翌日が9月14日になり、11日間が消えた。このとき、「寿命を11日も盗まれた」と怒った民衆が「われわれの11日を返せ！"},{"id":"intro-calendar-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"2月30日があった国","l":"intro-calendar","x":"暦の切り替えに一番苦労したのは、スウェーデンかもしれない。スウェーデンは1700年から、閏年を40年間抜くことで、少しずつグレゴリウス暦に近づける計画を立てた。ところが、1700年"},{"id":"intro-calendar-t7","k":"confuse","f":"confuse","kj":"混同注意","t":"「十月革命」は11月に起きた","l":"intro-calendar","x":"1917年のロシアの「十月革命」は、私たちの暦では11月7日に起きている。当時のロシアはまだユリウス暦を使っていて、その暦では10月25日だったからだ。同じように、1917年の「二"},{"id":"intro-calendar-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"明治政府の改暦と「12月分の給料」","l":"intro-calendar","x":"日本は明治5年の11月、突然、翌月から太陽暦に切り替えると発表した。そして、明治5年12月2日の翌日が、明治6年1月1日とされた。12月はわずか2日で終わってしまったのである。この"},{"id":"intro-calendar-t9","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「マヤ暦では2012年に世界が終わる」","l":"intro-calendar","x":"2012年12月21日に世界が終わる、という噂が世界中で話題になったことがある。古代マヤの「長期暦」が、この日に一つの大きな区切り（13バクトゥン）を迎えることから広まった説だった"},{"id":"intro-calendar-t10","k":"trivia","f":"side","kj":"こぼれ話","t":"「日月火水木金土」は空海が持ち帰った？","l":"intro-calendar","x":"日本の曜日の名前（日・月・火・水・木・金・土）も、同じ7つの天体に由来する。曜日の考え方は、平安時代の初めに、唐に渡った空海が持ち帰った仏教の占星術の経典『宿曜経』などを通じて伝わ"},{"id":"intro-history-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"年代はどうやって測るのか","l":"intro-history","x":"遺跡や遺物の年代を調べる方法として有名なのが、放射性炭素年代測定である。生物は生きている間、大気中の炭素を体に取り込んでいる。その中にはごくわずかに放射性の炭素14が含まれていて、"},{"id":"intro-history-t2","k":"source","f":"src","kj":"史料｜記録","t":"ヘロドトスの「ペルシア軍170万人」","l":"intro-history","x":"古代ギリシアの歴史家ヘロドトスは、前480年にギリシアに攻め込んだペルシア王クセルクセスの陸軍を、170万人と書いている。さらに海軍や従者まで数えて、総勢は500万人を超えたという"},{"id":"intro-history-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"金を掘る巨大アリ","l":"intro-history","x":"ヘロドトスの『歴史』には、にわかには信じがたい話も少なくない。中でも有名なのが、インドの北の砂漠にすむという「金を掘るアリ」の話である。原文ἐν δὴ ὦν τῇ ἐρημίῃ τ"},{"id":"intro-history-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"偽の文書を見破った男――ロレンツォ＝ヴァッラ","l":"intro-history","x":"中世ヨーロッパでは、「コンスタンティヌスの寄進状」という文書が大きな意味を持っていた。4世紀のローマ皇帝コンスタンティヌスが、病気を治してくれたお礼に、ローマ教皇にローマ市と西方の"},{"id":"intro-history-t5","k":"now","f":"now","kj":"いま","t":"20世紀の偽史料事件","l":"intro-history","x":"偽の史料は昔の話ではない。1983年、西ドイツの週刊誌『シュテルン』は、発見されたばかりの「ヒトラーの日記」60冊余りを大々的に発表した。高名な歴史家も一時は本物と認めたが、間もな"},{"id":"intro-history-t6","k":"view","f":"think","kj":"考える｜別の視点","t":"征服された側の記録を残した人々","l":"intro-history","x":"それでも、征服された側の声が残されたこともある。16世紀、メキシコに渡ったスペインの修道士サアグンは、アステカの人々から話を聞き取り、ナワトル語とスペイン語で百科事典のような記録を"},{"id":"intro-history-t7","k":"source","f":"src","kj":"史料｜記録","t":"司馬遷の手紙――「死は泰山より重く、鴻毛より軽い」","l":"intro-history","x":"司馬遷は、匈奴に降伏した将軍李陵を武帝の前で弁護したため、武帝の怒りを買い、宮刑（男性器を切除する刑）に処せられた。死を選ぶこともできたが、父から託された歴史書を完成させるため、屈"},{"id":"intro-history-t8","k":"confuse","f":"confuse","kj":"混同注意","t":"「史料」と「資料」","l":"intro-history","x":"このサイトでは「史料」という言葉を使っている。一般的な「資料」と同じ意味のように見えるが、歴史学で「史料」というときは、過去を知る手がかりとなる、その時代に作られたもの（または伝え"},{"id":"intro-history-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"ロゼッタ＝ストーンとシャンポリオン","l":"intro-history","x":"1799年、エジプトに遠征していたナポレオンの軍隊が、ナイル川河口の町ロゼッタ（ラシード）の近くで、文字の刻まれた黒い石碑を見つけた。ロゼッタ＝ストーンである。そこには同じ内容の文"},{"id":"intro-history-t10","k":"confuse","f":"confuse","kj":"混同注意","t":"「先史時代」と「歴史時代」","l":"intro-history","x":"文字による記録が残る以前の時代を先史時代、文字の記録がある時代を歴史時代という。ただし、その境目は地域によって大きく違う。メソポタミアやエジプトでは前3000年ごろに歴史時代に入る"},{"id":"intro-maps-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「上」は東だった――中世ヨーロッパのTO図","l":"intro-maps","x":"中世ヨーロッパでは、「TO図」と呼ばれる図式的な世界地図が広く描かれた。円（O）の中にT字形の水路があり、世界を三つの大陸に分けている。上半分がアジア、左下がヨーロッパ、右下がアフ"},{"id":"intro-maps-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"地球を「小さく」見積もったコロンブス","l":"intro-maps","x":"エラトステネスの計算はかなり正確だったが、その後、地球をもっと小さく見積もる説も広まった。プトレマイオスは、地球の全周をエラトステネスより3割近くも小さく考え、しかもユーラシア大陸"},{"id":"intro-maps-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"南が上――イスラーム世界の地図","l":"intro-maps","x":"12世紀、シチリア王ロジェール2世に仕えたイスラーム教徒の地理学者イドリーシーは、各地の旅行者や商人から情報を集め、1154年に大きな世界地図とその解説書を完成させた。「ロジェール"},{"id":"intro-maps-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"1402年、朝鮮で描かれたアフリカ","l":"intro-maps","x":"1402年、朝鮮王朝で「混一疆理歴代国都之図」という世界地図が作られた。元の時代の中国の地図をもとに、朝鮮と日本を書き加えたものである。驚くべきことに、この地図にはアフリカの南端が"},{"id":"intro-maps-t5","k":"source","f":"src","kj":"史料｜記録","t":"「アメリカ」と名づけた地図","l":"intro-maps","x":"1507年、ドイツの地図製作者ヴァルトゼーミュラーは、12枚の版木で刷った大きな世界地図を作った。その地図の南の大陸に、初めて「America」という名前が書き込まれた。地図に添え"},{"id":"intro-maps-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"地図は「中立」か","l":"intro-maps","x":"1970年代、ドイツの歴史家ペータースは、メルカトル図法がヨーロッパを大きく、アフリカや南アメリカを小さく見せ、ヨーロッパ中心の世界観を植えつけてきたと批判し、面積を正しく表す図法"},{"id":"intro-maps-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"中国を真ん中に置いた宣教師","l":"intro-maps","x":"1602年、明の北京で、イエズス会の宣教師マテオ・リッチが、中国の学者の協力を得て、漢文の大きな世界地図「坤輿万国全図」を刊行した。南北アメリカ大陸を含む五大陸が描かれた、中国で初"},{"id":"intro-maps-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"日本を「歩いて」測った伊能忠敬","l":"intro-maps","x":"日本では、江戸時代後期の伊能忠敬が、1800年から1816年にかけて全国を測量して回った。50歳で隠居してから天文学と測量を学び、歩幅で距離を測りながら、17年間で約4万キロメート"},{"id":"intro-maps-t9","k":"confuse","f":"confuse","kj":"混同注意","t":"「帝国」の範囲と実際の支配","l":"intro-maps","x":"地図の上では、モンゴル帝国やローマ帝国が巨大な一色で塗られていることが多い。しかし、たとえばモンゴル帝国の中には、それぞれ独立性の強いいくつものウルス（国家）があり、さらに服属して"},{"id":"intro-maps-t10","k":"confuse","f":"confuse","kj":"混同注意","t":"変わる地名","l":"intro-maps","x":"歴史の地図を見るときに戸惑うのが、地名の変化である。同じ場所でも、時代によって呼び名が違う。現在の名かつての名イスタンブルビザンティオン → コンスタンティノープル（コンスタンティ"},{"id":"intro-worldhistory-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"王朝の盛衰に法則を見いだしたイブン＝ハルドゥーン","l":"intro-worldhistory","x":"14世紀、北アフリカのチュニス出身の歴史家イブン＝ハルドゥーンは、大著『歴史序説（ムカッディマ）』で、王朝が興っては滅びるのはなぜかを論じた。彼によれば、厳しい砂漠や山地で暮らす遊"},{"id":"intro-worldhistory-t2","k":"confuse","f":"confuse","kj":"混同注意","t":"「発見」という言葉の問題","l":"intro-worldhistory","x":"世界史の用語にも、ヨーロッパ中心の見方の名残がある。かつての教科書では、15〜16世紀のヨーロッパ人の航海を「地理上の発見」と呼んでいた。しかし、アメリカ大陸には何千万もの人々がす"},{"id":"intro-worldhistory-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"「オリエント」「極東」は誰から見た方角か","l":"intro-worldhistory","x":"「オリエント」は、ラテン語で「日の昇る方角」、つまり東を意味する。古代ローマから見た東方、すなわちエジプトや西アジアを指す言葉だった。「中東」「近東」「極東」という地域の呼び方も、"},{"id":"intro-worldhistory-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"捕虜収容所で書かれた『地中海』","l":"intro-worldhistory","x":"ブローデルの『地中海』は、驚くべき状況の中で書かれた。1940年、フランス軍の将校として出征したブローデルは、ドイツ軍の捕虜となった。それから5年間、彼はドイツのマインツやリューベ"},{"id":"intro-worldhistory-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「東洋史」を生んだ日本の歴史学","l":"intro-worldhistory","x":"「東洋史」という学問の分野は、実は明治時代の日本で生まれたものである。1894年ごろ、歴史家の那珂通世が、中国を中心にアジア全体の歴史を扱う科目として「東洋史」を提唱した。これは、"},{"id":"investiture-t1","k":"source","f":"src","kj":"史料｜記録","t":"『教皇訓令書』","l":"investiture","x":"1075年、グレゴリウス7世の書簡集の中に、27か条からなる短い命題の一覧が書き込まれた。これを『教皇訓令書（ディクタトゥス・パパエ）』という。その一部を見てみよう。原文II. Q"},{"id":"investiture-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"教皇はなぜ強かったのか","l":"investiture","x":"教皇は、自分の軍隊をほとんど持たなかった。それにもかかわらず、王や皇帝が教皇を恐れたのはなぜか。その最大の武器は、破門であった。破門されると、教会の儀式に加わることができず、死後に"},{"id":"investiture-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"小鳥に説教する聖者","l":"investiture","x":"フランチェスコについては、多くの伝説が残っている。彼は、動物や自然を「兄弟」「姉妹」と呼んで愛し、小鳥たちに神の愛を説いたところ、小鳥たちは静かに耳を傾けたという。また、亡くなる2"},{"id":"investiture-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「すべて殺せ。神はご自分の者を知っておられる」――ベジエの虐殺","l":"investiture","x":"1209年7月、教皇インノケンティウス3世が呼びかけたアルビジョワ十字軍は、南フランスの町ベジエを攻め落とした。町には、異端とされたカタリ派の信者と、カトリックの住民がともに暮らし"},{"id":"investiture-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"investiture","x":"フジテレビ『カノッサの屈辱』（テレビ番組、1990〜1991年）：現代の消費文化やヒット商品の歴史を、大学の歴史の講義のような形式で、中世ヨーロッパの歴史などになぞらえて解説した深"},{"id":"iran-central-asia-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"ブハラの穴蔵の囚人","l":"iran-central-asia","x":"1838年、イギリスの将校チャールズ・ストッダートは、中央アジアのブハラ・ハン国の君主（アミール）に、ロシアに対抗するための同盟を持ちかけるために送り込まれた。しかし、彼は礼儀を欠"},{"id":"iran-central-asia-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「グレート・ゲームを演じに」――キプリング『キム』","l":"iran-central-asia","x":"19世紀、中央アジアの覇権をめぐって、南下するロシアと、インドを守ろうとするイギリスとが繰り広げた、スパイと探検家と外交官の駆け引きは、「グレート・ゲーム」と呼ばれた。この言葉を有"},{"id":"iran-central-asia-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"劇作家の死とダイヤモンド","l":"iran-central-asia","x":"トルコマンチャーイ条約の実施のためにテヘランに送り込まれたロシアの公使は、アレクサンドル・グリボエードフであった。彼は、外交官であると同時に、ロシア文学の古典となった喜劇『知恵の悲"},{"id":"iran-central-asia-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"処刑された預言者","l":"iran-central-asia","x":"19世紀のイランでは、新しい宗教運動も生まれた。1844年、シーラーズの商人の青年アリー・ムハンマドは、自分は、シーア派の人々が待ち望む隠れイマームに通じる「門（バーブ）」であると"},{"id":"iran-central-asia-t5","k":"source","f":"src","kj":"史料｜記録","t":"「今日、タバコを吸うことは、隠れイマームへの戦いに等しい」――タバコ・ボイコットのファトワー","l":"iran-central-asia","x":"1890年、カージャール朝のシャー、ナーセロッディーンは、イギリス人の商人に、イランのタバコの栽培から販売、輸出までのすべてを独占する権利を、50年間与えた。タバコは、イランの人々"},{"id":"iran-central-asia-t6","k":"person","f":"deep","kj":"深掘り｜人物","t":"戦争を嫌った従軍画家","l":"iran-central-asia","x":"ロシアの画家ヴェレシチャーギンは、ロシア軍の中央アジア遠征に従軍し、自ら銃を取って戦ったこともあった。しかし、彼が描いたのは、ロシア軍の輝かしい勝利ではなかった。敵に首を切り取られ"},{"id":"iran-central-asia-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"中央アジアを旅した日本人外交官","l":"iran-central-asia","x":"1880年、ロシアの首都サンクトペテルブルクの日本公使館に勤めていた外交官の西徳二郎は、帰国の際に、わざわざ中央アジアを通る道を選んだ。彼は、ロシアに征服されたばかりのタシケントや"},{"id":"iran-revolution-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"日章丸、アバダンへ","l":"iran-revolution","x":"世界がイランの石油を買い控える中、それに挑んだのが、日本の石油会社の出光興産であった。1953年3月、出光のタンカー日章丸は、行き先を秘密にしたまま、神戸港を出航した。乗組員たちが"},{"id":"iran-revolution-t2","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"砂漠のテント都市","l":"iran-revolution","x":"1971年10月、国王は、ペルシア帝国の建国2500年を祝う盛大な祝典を開いた（→「アケメネス朝ペルシア」の回）。会場は、アケメネス朝の都ペルセポリスの遺跡の前の砂漠であった。画像"},{"id":"iran-revolution-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"国境を越えたカセットテープ","l":"iran-revolution","x":"国外にいたホメイニの声を、イランの人々に届けたのは、カセットテープであった。ホメイニの説教は、ナジャフ、のちにはパリの郊外のノーフル・ル・シャトーで録音され、国際電話やカセットテー"},{"id":"iran-revolution-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「この政府の口をなぐりつけてやる」――ベヘシュテ・ザフラーの演説","l":"iran-revolution","x":"1979年2月1日、テヘランの空港に降り立ったホメイニは、群衆をかき分けて、まず市の南の墓地ベヘシュテ・ザフラーに向かった。そこには、革命の中で国王の軍隊に殺された人々が葬られてい"},{"id":"iran-revolution-t5","k":"source","f":"src","kj":"史料｜記録","t":"毒杯を飲む","l":"iran-revolution","x":"1988年7月、イランは、ついに、国連の安全保障理事会の停戦の決議を受け入れた。ホメイニは、国民に向けた声明で、こう述べた。「この決定を受け入れることは、私にとって、毒の杯を飲むよ"},{"id":"iran-revolution-t6","k":"view","f":"think","kj":"考える｜別の視点","t":"テヘランの48時間","l":"iran-revolution","x":"1985年3月17日、イラクのフセイン大統領は、48時間の猶予の後、イランの上空を飛ぶすべての航空機を、民間機であっても撃墜すると宣言した。テヘランには、200人を超える日本人が取"},{"id":"iran-revolution-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"iran-revolution","x":"マルジャン・サトラピ『ペルセポリス』（漫画、2000〜2003年、アニメ映画2007年）：イラン革命とイラン＝イラク戦争の時代のテヘランで育った少女の自伝的な物語。映画『アルゴ』（"},{"id":"islam-faith-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"『クルアーン』の中のイエスとマリア","l":"islam-faith","x":"『クルアーン』には、イエスとその母マリアが、たびたび登場する。第19章は、マリアの名をとって「マルヤム章」と呼ばれ、マリアが男性に触れることなくイエスを身ごもり、ナツメヤシの木の下"},{"id":"islam-faith-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"楽園を焼き、地獄の火を消す――ラービア","l":"islam-faith","x":"8世紀のバスラ（イラク）に生きた女性ラービア・アダウィーヤ（717ごろ〜801年）は、神への純粋な愛を説いた神秘主義者（スーフィー）として知られる。もとは奴隷の身であったが、夜通し"},{"id":"islam-faith-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"ブハーリー――60万のハディースから選ぶ","l":"islam-faith","x":"ムハンマドの死後、時代がたつにつれて、ハディースの数は膨大になり、その中には、後の時代の人々が自分たちの都合のよいように作り出したものも数多く含まれるようになった。9世紀、中央アジ"},{"id":"islam-faith-t4","k":"term","f":"deep","kj":"深掘り｜ことば","t":"「ハラール」と「ハラーム」","l":"islam-faith","x":"シャリーアで許されたものを「ハラール」、禁じられたものを「ハラーム」という。食べ物では、豚肉と、その脂やエキスなどを含むもの、酒などのアルコール、動物の血、自然に死んだ動物の肉など"},{"id":"islam-faith-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"日本人で最初の巡礼者","l":"islam-faith","x":"日本人として初めてメッカへの巡礼を果たしたのは、山岡光太郎であるとされる。1909年、ロシアから亡命していたタタール人のイスラーム学者アブデュルレシト・イブラヒムとともにインドに渡"},{"id":"islam-faith-t6","k":"now","f":"now","kj":"いま","t":"ラマダーンと現代社会","l":"islam-faith","x":"ラマダーン月の時期は、毎年約11日ずつ早まっていくため、夏の暑い時期にあたることもある。日の長い北ヨーロッパの国々では、夏のラマダーンには、断食の時間が18時間以上になることもある"},{"id":"islam-faith-t7","k":"works","f":"works","kj":"作品","t":"イスラーム教を知るための作品","l":"islam-faith","x":"井筒俊彦『イスラーム文化――その根底にあるもの』（岩波文庫）：イスラーム学者の井筒俊彦が、イスラームの宗教・法・内面の信仰を、一般向けに語った講演録。映画『ハッジ』（Le Gran"},{"id":"islamic-science-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"本の重さと同じ黄金","l":"islamic-science","x":"後世の伝承によれば、カリフのマームーンは、フナインが翻訳した書物の重さと同じ重さの黄金を、報酬として与えたという伝承。そのため、フナインは、わざと厚い紙に、大きな文字で、行の間を広"},{"id":"islamic-science-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「知恵の館」は何だったのか","l":"islamic-science","x":"「知恵の館」は、学者たちが集まって翻訳と研究を行う、一種のアカデミーであったと説明されることが多い。しかし、実際の姿については、わからないことが多い諸説。近年の研究では、「知恵の館"},{"id":"islamic-science-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"暗号解読の祖キンディー","l":"islamic-science","x":"キンディーは、哲学だけでなく、数学・医学・音楽など、あらゆる学問について書いた。その中に『暗号文を解読することについての書』という論文がある。この中でキンディーは、文章の中で、それ"},{"id":"islamic-science-t4","k":"source","f":"src","kj":"史料｜記録","t":"ビールーニー『インド誌』","l":"islamic-science","x":"ビールーニーは、インドの人々の学問への態度について、次のように書いている。原文…… يعتقدون في الأرض أنها أرضهم، وفي الناس أنهم جنسه"},{"id":"islamic-science-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"肉をつるして病院の場所を選ぶ","l":"islamic-science","x":"ラーズィーには、次のような逸話が伝えられている。カリフから、バグダードに新しい病院を建てる場所を選ぶよう命じられたラーズィーは、町のあちこちに生の肉をつるした。そして、肉が最も腐り"},{"id":"islamic-science-t6","k":"person","f":"deep","kj":"深掘り｜人物","t":"イブン＝シーナーの自伝","l":"islamic-science","x":"イブン＝シーナーは、弟子に口述した自伝を残している。その中で、若いころの学問について、次のように語っている。私はアリストテレスの『形而上学』を読んだが、その内容が理解できなかった。"},{"id":"islamic-science-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"狂人のふりをした科学者","l":"islamic-science","x":"イブン＝ハイサムについては、次のような話が伝えられている。イラクのバスラに生まれたイブン＝ハイサムは、ナイル川の洪水を、堤防によって調節することができる、と語っていた。これを聞いた"},{"id":"islamic-science-t8","k":"person","f":"deep","kj":"深掘り｜人物","t":"神への愛――ラービアとハッラージュ","l":"islamic-science","x":"8世紀のバスラの女性ラービアは、スーフィズムの先駆者の一人とされる。ある日、ラービアは、片手にたいまつ、片手に水の入った桶を持って、町を走っていた。人々がそのわけを尋ねると、ラービ"},{"id":"islamic-science-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"「アラジン」と「アリババ」はどこから来たか","l":"islamic-science","x":"『千夜一夜物語』で最も有名な「アラジンと魔法のランプ」と「アリババと40人の盗賊」は、実は、アラビア語の古い写本には含まれていない。18世紀初め、フランスの東洋学者アントワーヌ・ガ"},{"id":"islamic-science-t10","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"金貨と銀貨","l":"islamic-science","x":"12世紀の文人ニザーミー・アルーズィーの伝えるところでは、フィルドゥシーは、完成した『シャー・ナーメ』を、ガズナ朝のマフムードにささげた。ところが、マフムードは、約束の金貨ではなく"},{"id":"islamic-science-t11","k":"source","f":"src","kj":"史料｜記録","t":"『ルバイヤート』より","l":"islamic-science","x":"原文Here with a Loaf of Bread beneath the Bough,A Flask of Wine, a Book of Verse—and ThouBes"},{"id":"islamic-science-t12","k":"now","f":"now","kj":"いま","t":"月に刻まれた名前","l":"islamic-science","x":"月のクレーターには、科学に貢献した人々の名前がつけられている。その中には、イスラーム世界の学者たちの名前も数多い。月の表側には、バッターニー（ラテン名アルバテグニウス）、マームーン"},{"id":"islamic-science-t13","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"islamic-science","x":"『千夜一夜物語』（アラビアン・ナイト）：アラビア語からの日本語訳には、前嶋信次・池田修訳（平凡社東洋文庫）がある。ガランのフランス語訳からの日本語訳や、19世紀のイギリスのバートン"},{"id":"israel-arab-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"4度の中東戦争","l":"israel-arab","x":"中東戦争は、4度にわたって起こった。年代と、それぞれのきっかけ・結果を整理しておこう。年きっかけ結果第1次（パレスチナ戦争）1948〜49年イスラエルの建国イスラエルが支配地を拡大"},{"id":"israel-arab-t2","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"テルアビブ空港の日本人","l":"israel-arab","x":"パレスチナのゲリラ組織は、1960年代の末から、世界の注目を集めるために、旅客機のハイジャックや、テロ攻撃をくり返すようになった。その中には、日本人もかかわっていた。1972年5月"},{"id":"israel-arab-t3","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"israel-arab","x":"映画『栄光への脱出』（オットー・プレミンジャー監督、1960年）：1947年、ホロコーストを生き延びたユダヤ人たちを乗せた船「エクソダス号」の事件と、イスラエル建国を描いた映画。作"},{"id":"italian-unification-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「私が与えられるのは、飢えと渇きと、戦いと死だ」――ローマを去るガリバルディ","l":"italian-unification","x":"1849年、ローマ共和国は、教皇を助けるために送られたフランス軍に包囲された。ガリバルディは、1か月近く必死に防戦したが、ついに力尽きた。7月2日、ローマを脱出するにあたって、ガリ"},{"id":"italian-unification-t2","k":"music","f":"music","kj":"音楽","t":"「ヴィーヴァ・ヴェルディ！」","l":"italian-unification","x":"1840年代以降、イタリアの各地の壁に、「ヴィーヴァ・ヴェルディ！（ヴェルディ万歳！）」という落書きが現れた。ヴェルディは、オペラ『ナブッコ』などで知られる、イタリアの国民的な作曲"},{"id":"italian-unification-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"デュナンと赤十字","l":"italian-unification","x":"1859年6月、スイスのジュネーヴの実業家アンリ・デュナンは、事業の許可をナポレオン3世に願い出るために、北イタリアの戦場を訪れた。そこで彼が見たのは、ソルフェリーノの戦場に置き去"},{"id":"italian-unification-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"italian-unification","x":"映画『山猫』（ルキノ・ヴィスコンティ監督、1963年）：ガリバルディの千人隊がシチリアに上陸した時代、没落していくシチリアの貴族を描いた映画。原作はランペドゥーサの小説（1958年"},{"id":"japan-postwar-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"22歳の起草者","l":"japan-postwar","x":"GHQの憲法草案の作成に加わったスタッフの中に、一人の22歳の女性がいた。ベアテ・シロタである。ベアテは、オーストリア出身のユダヤ人のピアニストの娘として、5歳から15歳までの10"},{"id":"japan-postwar-t2","k":"source","f":"src","kj":"史料｜記録","t":"「永久にこれを放棄する」――日本国憲法第9条","l":"japan-postwar","x":"1946年11月3日に公布され、翌1947年5月3日に施行された日本国憲法は、その第9条で、戦争の放棄と戦力の不保持を定めた。原文日本国民は、正義と秩序を基調とする国際平和を誠実に"},{"id":"japan-postwar-t3","k":"source","f":"src","kj":"史料｜記録","t":"「憎しみは憎しみによってやまず」","l":"japan-postwar","x":"講和会議では、日本に厳しい賠償や制限を課すべきだという意見も出た。フィリピンやオーストラリアは、日本軍による被害の大きさを訴えた。その中で、セイロン（スリランカ）の代表のジャヤワル"},{"id":"japan-postwar-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"北へ渡った人々","l":"japan-postwar","x":"1959年から、日本に住む朝鮮人とその家族を、北朝鮮に送り出す「帰国事業」が始まった。北朝鮮は、自国を「地上の楽園」と宣伝し、日本の新聞の多くも、この事業を人道的なものとして好意的"},{"id":"japan-postwar-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「ご迷惑」とパンダ","l":"japan-postwar","x":"北京に着いた日の夜の歓迎の宴会で、田中角栄は、あいさつの中で、日本が過去に中国の人々に「多大のご迷惑をおかけした」と述べた。中国語に通訳されたこの言葉――「添了很大的麻烦」――は、"},{"id":"japan-postwar-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"japan-postwar","x":"映画『ALWAYS 三丁目の夕日』（2005年）：建設中の東京タワーが見える下町を舞台に、高度経済成長が始まったころの人々の暮らしを描いた映画。原作は西岸良平の漫画『三丁目の夕日』"},{"id":"jin-sixteen-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"屯田制・占田課田法・均田制","l":"jin-sixteen","x":"魏晋南北朝時代から隋唐にかけての土地制度は、名前が似ていて紛らわしい。制度王朝始まった年内容屯田制魏（曹操）196年戦乱で荒れた土地に流民や兵士を集めて耕作させ、収穫の5〜6割を国"},{"id":"jin-sixteen-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"石崇と王愷の富くらべ","l":"jin-sixteen","x":"西晋の貴族たちのぜいたくぶりは、のちの時代まで語り草となった。『世説新語』は、大富豪の石崇と、武帝の母方のおじ王愷の富くらべの逸話を伝えている伝承。王愷が飴（麦芽糖）で釜を洗わせる"},{"id":"jin-sixteen-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「肉のかゆを食べればよいのに」","l":"jin-sixteen","x":"恵帝については、能力の乏しさを示す逸話が、『晋書』恵帝紀に記されている伝承。あるとき、天下に飢饉が起こり、多くの民が餓死しているという報告を受けた恵帝は、「どうして肉のかゆを食べな"},{"id":"jin-sixteen-t4","k":"source","f":"src","kj":"史料｜記録","t":"江統『徙戎論』（299年）","l":"jin-sixteen","x":"晋の官僚江統は、八王の乱の最中の299年、華北に住む異民族を、もとの土地に帰らせるべきだと主張する意見書を朝廷に提出した。原文且關中之人百餘萬口，率其少多，戎狄居半。……怨恨之氣，"},{"id":"jin-sixteen-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「青い衣を着て酒をつげ」","l":"jin-sixteen","x":"捕らえられた懐帝は、平陽で、劉聡から「会稽郡公」という称号を与えられた。313年の元日、劉聡は、宴会の席で、懐帝に召使いの青い衣を着させ、客たちに酒をつがせた。かつての晋の皇帝が、"},{"id":"jin-sixteen-t6","k":"person","f":"deep","kj":"深掘り｜人物","t":"石勒――奴隷から皇帝へ","l":"jin-sixteen","x":"石勒（274〜333年）は、羯という、匈奴の別部とされる人々の出身であった。羯は、中央アジアの出身ではないかとする説もある諸説。若いころ、飢饉の中で晋の役人に捕らえられて山東に売ら"},{"id":"jin-sixteen-t7","k":"now","f":"now","kj":"いま","t":"永嘉の乱と客家","l":"jin-sixteen","x":"中国の広東・福建・江西などの山地や、台湾・東南アジアの各地に住む客家（ハッカ）と呼ばれる人々は、独自の言語（客家語）と文化を持つ漢民族の一集団である。客家の多くの家の族譜（家系の記"},{"id":"jin-sixteen-t8","k":"view","f":"think","kj":"考える｜別の視点","t":"「五胡」という呼び名を考える","l":"jin-sixteen","x":"「五胡」や「乱華」（中華を乱す）という言葉は、漢人の側から見た呼び名である。中国の伝統的な歴史書は、この時代を、異民族によって中華が乱された暗黒時代として描いてきた。しかし、近年の"},{"id":"jin-sixteen-t9","k":"term","f":"deep","kj":"深掘り｜ことば","t":"「風声鶴唳」と「草木皆兵」","l":"jin-sixteen","x":"淝水の戦いからは、現在も使われる四字熟語が二つ生まれた。草木皆兵（そうもくかいへい）：戦いの前、寿陽の城壁から八公山を眺めた苻堅が、山の草木までが東晋の兵に見えて恐れたという話から"},{"id":"jin-sixteen-t10","k":"source","f":"src","kj":"史料｜記録","t":"下駄の歯が折れたのにも気づかず――謝安の囲碁","l":"jin-sixteen","x":"冒頭に紹介した、勝報を受けた謝安の逸話は、『晋書』謝安伝に記されている。原文安方對客圍棊，看書既竟，便攝放牀上，了無喜色，棊如故。客問之，徐答云：「小兒輩遂已破賊。」既罷，還內，過"},{"id":"jin-sixteen-t11","k":"debate","f":"think","kj":"考える｜諸説あり","t":"あぶみが封建制を生んだ？","l":"jin-sixteen","x":"1962年、アメリカの歴史家リン＝ホワイトは、あぶみの普及によって、ヨーロッパで重装の騎士による突撃戦術が可能になり、高価な騎士の装備をまかなうために、騎士に土地を与える封建制が生"},{"id":"jin-sixteen-t12","k":"trivia","f":"side","kj":"こぼれ話","t":"統万城――錐が1寸入れば工人を殺す","l":"jin-sixteen","x":"匈奴の赫連勃勃が、オルドス（現在の陝西省北部）に築いた夏の都が、統万城である。「天下を統一し、万国に君臨する」という意味の名をつけられたこの城は、413年から約6年をかけて、10万"},{"id":"jin-sixteen-t13","k":"works","f":"works","kj":"作品","t":"この時代にまつわる作品と言葉","l":"jin-sixteen","x":"劉義慶『世説新語』（5世紀、南朝の宋）：後漢末から東晋までの貴族や名士たちの逸話を集めた書物。石崇の富くらべ、謝安や王導の逸話など、魏晋の貴族社会の雰囲気を生き生きと伝える。日本で"},{"id":"jin-southern-song-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"『水滸伝』の宋江","l":"jin-southern-song","x":"同じころ、華北でも、宋江という人物が、36人の仲間とともに各地を荒らし回り、1121年に宋に降伏したと記録されている。この宋江たちの話がもとになって、のちに、梁山泊に集まった108"},{"id":"jin-southern-song-t2","k":"source","f":"src","kj":"史料｜記録","t":"五国城の二人の皇帝","l":"jin-southern-song","x":"捕らえられた徽宗と欽宗は、金の都会寧を経て、さらに北の五国城（現在の黒竜江省依蘭）に送られた。徽宗は、金の皇帝から「昏徳公（道理に暗い公）」、欽宗は「重昏侯（さらに道理に暗い侯）」"},{"id":"jin-southern-song-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"太鼓を打つ梁紅玉","l":"jin-southern-song","x":"1130年、江南の略奪を終えて北へ帰ろうとした完顔宗弼の軍は、長江の黄天蕩で、韓世忠の率いる宋の水軍に退路をふさがれた。宋軍はわずか8000人であったが、金軍を48日間にわたって閉"},{"id":"jin-southern-song-t4","k":"source","f":"src","kj":"史料｜記録","t":"「莫須有」","l":"jin-southern-song","x":"岳飛の投獄に納得できなかった同僚の武将韓世忠は、秦檜に、岳飛の罪の証拠は何かと問いただした。秦檜は、「その事実は、莫須有（あったかもしれない）」と答えた。韓世忠は、「『あったかもし"},{"id":"jin-southern-song-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"背中の四文字と「満江紅」","l":"jin-southern-song","x":"岳飛の背中には、「尽忠報国（忠義を尽くして国に報いる）」の四文字が刻まれていたと伝えられる。『宋史』岳飛伝によれば、取り調べを受けた岳飛は、服を脱いで、背中の文字を役人に見せたとい"},{"id":"jin-southern-song-t6","k":"voice","f":"src","kj":"史料｜証言","t":"国を失った女性詩人――李清照","l":"jin-southern-song","x":"北宋の末、李清照（1084〜1155年ごろ）は、夫で金石学者の趙明誠とともに、書画や古い銅器の収集に情熱を注いでいた。靖康の変の後、二人は江南へ逃れたが、集めた品々の多くは戦乱の中"},{"id":"jin-southern-song-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"西湖に立つ馬","l":"jin-southern-song","x":"海陵王は、ある時、南宋に送った使者に、ひそかに臨安の町と西湖の景色を描かせて持ち帰らせた。その絵の中に、呉山の頂に馬にまたがって立つ自分の姿を描き加えさせ、次のような詩を書きつけた"},{"id":"jin-southern-song-t8","k":"works","f":"works","kj":"作品","t":"金と南宋にまつわる作品","l":"jin-southern-song","x":"『水滸伝』：北宋末を舞台に、梁山泊に集まった108人の豪傑の活躍を描く。明代の長編小説で、『三国志演義』『西遊記』『金瓶梅』とともに「四大奇書」と呼ばれる。『説岳全伝』：清代に成立"},{"id":"joseon-t1","k":"source","f":"src","kj":"史料｜記録","t":"「史官に知らせるな」――朝鮮王朝実録","l":"joseon","x":"朝鮮王朝は、国王の一日一日の言動や政治の出来事を、史官に細かく記録させた。国王が亡くなると、その記録をもとに、その国王の時代の歴史がまとめられた。これが『朝鮮王朝実録』である。初代"},{"id":"joseon-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"奴婢から王の技術者へ――蔣英実","l":"joseon","x":"蔣英実は、慶尚道の東莱（現在の釜山）の役所に属する奴婢（身分の低い使用人）の出身であったといわれる。父は中国から来た人で、母は役所の妓生であったと伝えられる。しかし、その技術の才能"},{"id":"joseon-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"ハングルのしくみ","l":"joseon","x":"ハングルは、世界の文字の中でも、きわめて独創的な文字である。子音の文字は、その音を出すときの、口や舌、のどの形をかたどってつくられた。たとえば、「ㄱ（k）」は、舌の根がのどをふさぐ"},{"id":"joseon-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"joseon","x":"ドラマ『宮廷女官チャングムの誓い』（韓国、2003〜2004年）：16世紀の朝鮮王朝の宮廷の料理人から、王の主治医にまでなった女性の物語。『朝鮮王朝実録』にわずかに名前の見える医女"},{"id":"justinian-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"二つの顔をもつ歴史家プロコピオス","l":"justinian","x":"ユスティニアヌスの時代について最も詳しい記録を残したのは、名将ベリサリウスの秘書として遠征に同行した歴史家プロコピオスである。彼は、戦争の経過を記した『戦史』と、皇帝の建築事業をた"},{"id":"justinian-t2","k":"source","f":"src","kj":"史料｜記録","t":"テオドラの演説","l":"justinian","x":"原文…… εἰ μὲν οὖν σώζεσθαι βούλει, βασιλεῦ, οὐδὲν πρᾶγμα. χρήματά τε γὰρ πολλὰ ἔχομεν, καὶ θ"},{"id":"justinian-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「ソロモンよ、我は汝に勝てり」","l":"justinian","x":"後世の伝説によれば、537年の献堂式の日、完成した聖堂に足を踏み入れたユスティニアヌスは、「ソロモンよ、我は汝に勝てり」と叫んだという。古代イスラエルのソロモン王がイェルサレムに建"},{"id":"justinian-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"日本の民法の遠い祖先","l":"justinian","x":"『ローマ法大全』は、中世の西ヨーロッパでは長く忘れられていた。しかし、11世紀末、北イタリアで『学説彙纂』の写本が再発見されると、ボローニャ大学で研究が始まり、ヨーロッパ各地から学"},{"id":"justinian-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"竪琴とパンとスポンジ","l":"justinian","x":"ヴァンダル王ゲリメルは、敗れて山中に逃れ、ベリサリウスの軍に包囲された。冬の山中で飢えに苦しんだゲリメルは、包囲軍の将校に使者を送り、3つの物を求めた。竪琴とパンとスポンジである。"},{"id":"justinian-t6","k":"source","f":"src","kj":"史料｜記録","t":"ユスティニアヌスの疫病","l":"justinian","x":"原文ἡ μὲν οὖν νόσος ἐν Βυζαντίῳ ἐς τέσσαρας διῆλθε μῆνας, ἤκμασε δὲ ἐς τρεῖς μάλιστα …… ἐς π"},{"id":"justinian-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"絹の秘密を盗んだ修道士","l":"justinian","x":"ローマ帝国の人々にとって、絹は、ササン朝ペルシアの商人を通じて中国から買うしかない高価な品であった。ササン朝とは戦争が絶えなかったため、ユスティニアヌスは、ペルシアを通らずに絹を手"},{"id":"justinian-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"「ビザンツ帝国」は後世の呼び名","l":"justinian","x":"「ビザンツ帝国」という呼び名は、この国の人々自身が使っていたものではない。彼らは、1453年に滅びるまで、自分たちの国を「ローマ人の帝国」、自分たちを「ローマ人（ロマイオイ）」と呼"},{"id":"justinian-t9","k":"now","f":"now","kj":"いま","t":"ハギア＝ソフィアの1500年","l":"justinian","x":"ハギア＝ソフィアは、537年の完成から900年以上にわたって、キリスト教世界最大の聖堂であった。1453年、オスマン帝国がコンスタンティノープルを征服すると、モスク（アヤソフィア）"},{"id":"justinian-t10","k":"works","f":"works","kj":"作品","t":"この時代にまつわる作品","l":"justinian","x":"プロコピオス『秘史』（6世紀）：ユスティニアヌスとテオドラを痛烈に批判した、生前には公表されなかった書物。17世紀にヴァチカンの図書館で写本が発見され、大きな反響を呼んだ。日本語訳"},{"id":"kievan-rus-t1","k":"source","f":"src","kj":"史料｜記録","t":"「われらの土地は広く豊かだが、秩序がない」――ヴァリャーグの招致","l":"kievan-rus","x":"12世紀の初めにキエフの修道士がまとめたとされるロシア最古の年代記『過ぎし年月の物語（原初年代記）』は、ルーシの国家の始まりを、こう語っている。862年、互いに争い合っていた北方の"},{"id":"kievan-rus-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「ヨーロッパの義父」","l":"kievan-rus","x":"ヤロスラフ賢公は、子どもたちを、ヨーロッパ各地の王家と結婚させた。娘のアンナはフランス王アンリ1世の妃となり、エリザヴェータはノルウェー王ハーラル3世の、アナスタシアはハンガリー王"},{"id":"kievan-rus-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"『イーゴリ遠征物語』","l":"kievan-rus","x":"1185年、ノヴゴロド・セヴェルスキー公イーゴリは、草原のポロヴェツ人の討伐に出かけたが、大敗して捕虜となった。この遠征を描いた叙事詩が『イーゴリ遠征物語』である。ルーシの諸公が争"},{"id":"kievan-rus-t4","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ハン国に頭を下げた英雄","l":"kievan-rus","x":"アレクサンドル・ネフスキーは、西の騎士団とは戦ったが、東のモンゴルとは戦わなかった。彼は、モンゴルのキプチャク・ハン国（ジョチ・ウルス）の都サライや、さらに遠くのモンゴル高原の都カ"},{"id":"kievan-rus-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「剣をもって来る者は、剣によって滅びる」は、アレクサンドル・ネフスキーの言葉か","l":"kievan-rus","x":"1242年、ノヴゴロドの公アレクサンドル・ネフスキーは、凍ったチュド湖（ペイプス湖）の上で、ドイツ騎士団の軍を打ち破った（氷上の戦い）。この英雄について、ロシアでは、こんな言葉がよ"},{"id":"kievan-rus-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"kievan-rus","x":"ボロディン『イーゴリ公』（オペラ、1890年初演）：12世紀のルーシの諸侯イーゴリが、草原の遊牧民ポロヴェツに遠征して捕らわれる物語。『イーゴリ遠征物語』をもとにしている。劇中の「"},{"id":"korea-japan-state-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"広開土王碑の「辛卯年」条","l":"korea-japan-state","x":"広開土王碑の第1面には、次のような一節がある。原文百殘新羅舊是屬民，由來朝貢。而倭以辛卯年來渡海破百殘□□新羅，以爲臣民。現代語訳百残（百済）・新羅は、もとは（高句麗の）属民で、朝"},{"id":"korea-japan-state-t2","k":"source","f":"src","kj":"史料｜記録","t":"七支刀の銘文","l":"korea-japan-state","x":"七支刀の銘文は、さびのため読めない字が多いが、おおよそ次のように読まれている。原文（表）泰■四年■月十六日丙午正陽，造百練鐵七支刀。出辟百兵，宜供供侯王。■■■■作（裏）先世以來未"},{"id":"korea-japan-state-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"武寧王陵の墓誌と日本のコウヤマキ","l":"korea-japan-state","x":"武寧王陵から出土した墓誌には、「寧東大将軍の百済の斯麻王は、年62歳で、癸卯の年（523年）5月7日に亡くなった」と刻まれていた。「寧東大将軍」は、梁の皇帝から与えられた称号である"},{"id":"korea-japan-state-t4","k":"source","f":"src","kj":"史料｜記録","t":"「東は毛人を征すること五十五国」――倭の五王","l":"korea-japan-state","x":"5世紀、倭の王たちは、中国の南朝の宋に、たびたび使いを送った。中国の歴史書『宋書』は、讃・珍・済・興・武という5人の倭王の名を記している（倭の五王）。478年、倭王武は、宋の皇帝に"},{"id":"korea-japan-state-t5","k":"term","f":"deep","kj":"深掘り｜ことば","t":"加耶と「任那」","l":"korea-japan-state","x":"朝鮮半島の南端の洛東江の流域には、4〜6世紀、金官加耶（金海）・大加耶（高霊）などの小国が分立していた。これを加耶（伽耶）という。加耶は、良質の鉄の産地で、鉄を求めて倭とも密接に交"},{"id":"korea-japan-state-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"鬱陵島と于山国","l":"korea-japan-state","x":"512年、新羅の将軍異斯夫は、日本海に浮かぶ鬱陵島の于山国を服属させた。異斯夫は、木で獅子の像を作って船に積み、「降伏しなければこの猛獣を放つ」と脅したところ、島の人々は恐れて降伏"},{"id":"korea-japan-state-t7","k":"source","f":"src","kj":"史料｜記録","t":"世俗五戒","l":"korea-japan-state","x":"7世紀初め、僧の円光は、花郎の若者に、次の5つの戒め（世俗五戒）を授けたと伝えられる。原文一曰事君以忠，二曰事親以孝，三曰交友以信，四曰臨戰無退，五曰殺生有擇。現代語訳一に、忠をも"},{"id":"korea-japan-state-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"太宗と安市城の城主","l":"korea-japan-state","x":"『資治通鑑』によれば、唐軍が撤退する時、安市城の城主は城壁に登って、太宗に別れの礼をした。太宗は、城を固く守り抜いた城主の忠誠をほめたたえ、絹100匹を与えたという。敵の将をたたえ"},{"id":"korea-japan-state-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"瞻星台の石の数","l":"korea-japan-state","x":"瞻星台は、花崗岩の石を27段に積み上げて造られている。27段は、善徳女王が新羅の第27代の王であることを表すとか、使われた石の数は約362個で、1年の日数を表すといった説明がよく見"},{"id":"korea-japan-state-t10","k":"trivia","f":"side","kj":"こぼれ話","t":"亀と兎の話","l":"korea-japan-state","x":"高句麗に捕らえられた金春秋は、高句麗の臣下の先道解に、ひそかに贈り物をした。すると先道解は、酒の席で次のような話をした。竜王の娘が病気になり、「兎の肝を飲めば治る」と言われた。亀は"},{"id":"korea-japan-state-t11","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"落花岩と「三千宮女」","l":"korea-japan-state","x":"扶余の町の北、白馬江（錦江）に臨む扶蘇山の断崖を、落花岩という。泗沘城が落ちた時、敵に辱められることを拒んだ宮女たちが、ここから次々に川に身を投げ、その姿が花の散るようであったこと"},{"id":"korea-japan-state-t12","k":"source","f":"src","kj":"史料｜記録","t":"『旧唐書』が記す白村江の戦い","l":"korea-japan-state","x":"唐の側の記録は、戦いの結末を次のように記している。原文仁軌遇倭兵於白江之口，四戰捷，焚其舟四百艘，煙焰漲天，海水皆赤，賊衆大潰。現代語訳劉仁軌は、倭の兵と白江の河口で出会い、4度戦"},{"id":"korea-japan-state-t13","k":"person","f":"deep","kj":"深掘り｜人物","t":"文武王――海の龍になった王","l":"korea-japan-state","x":"文武王は、681年に亡くなる前、次のような遺言を残したと伝えられる。原文屬纊之後十日，便於庫門外庭，依西國之式，以火燒葬。服輕重，自有常科；喪制度，務從儉約。現代語訳私が死んだ後は"},{"id":"korea-japan-state-t14","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「聖徳太子」はどこまで実在したか","l":"korea-japan-state","x":"厩戸王（574〜622年）が実在の人物であることは確かである。しかし、『日本書紀』に描かれた「聖徳太子」の業績――一度に10人の訴えを聞き分けた、憲法十七条を自ら作った、などがどこ"},{"id":"korea-japan-state-t15","k":"source","f":"src","kj":"史料｜記録","t":"「日出づる処の天子」","l":"korea-japan-state","x":"原文大業三年，其王多利思比孤遣使朝貢。……其國書曰：「日出處天子致書日沒處天子無恙」云云。帝覽之不悅，謂鴻臚卿曰：「蠻夷書有無禮者，勿復以聞。」現代語訳大業3年（607年）、その王"},{"id":"korea-japan-state-t16","k":"debate","f":"think","kj":"考える｜諸説あり","t":"改新の詔は書き換えられたのか――郡評論争","l":"korea-japan-state","x":"『日本書紀』の改新の詔には、地方の行政単位として「郡」という言葉が使われている。ところが、7世紀後半の金石文などには「評」という字が使われているものがあった。そのため、改新の詔は、"},{"id":"korea-japan-state-t17","k":"source","f":"src","kj":"史料｜記録","t":"防人の歌","l":"korea-japan-state","x":"防人は、主に東国の農民から集められ、3年交代で九州の防備にあたった。食料や武器は自分で用意しなければならず、重い負担であった。8世紀の『万葉集』には、防人やその家族が詠んだ歌が10"},{"id":"korea-japan-state-t18","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"日本に渡った百済と高句麗の人々","l":"korea-japan-state","x":"百済の滅亡と白村江の敗戦の後、多くの百済の人々が日本列島に渡った。『日本書紀』によれば、665年には百済の男女400余人が近江国の神前郡に、666年には2000余人が東国に移された"},{"id":"korea-japan-state-t19","k":"trivia","f":"side","kj":"こぼれ話","t":"長安とは違った藤原京","l":"korea-japan-state","x":"藤原京は、唐の長安にならって、碁盤の目のように道路を区画した都城（条坊制）であった。しかし、発掘の結果、藤原京は、東西・南北ともに約5.3kmの正方形で、その中央に宮殿（藤原宮）が"},{"id":"korea-japan-state-t20","k":"source","f":"src","kj":"史料｜記録","t":"「倭」から「日本」へ――外国の史書の記録","l":"korea-japan-state","x":"原文倭國更號日本，自言近日所出，以爲名。現代語訳倭国が、国号を日本と改めた。自ら言うには、日の出る所に近いので、それを国の名としたという。出典：『三国史記』新羅本紀 文武王10年（"},{"id":"korea-japan-state-t21","k":"trivia","f":"side","kj":"こぼれ話","t":"年号「大宝」と対馬の金","l":"korea-japan-state","x":"701年、対馬から金が献上されたことを祝って、年号が「大宝」と定められた。日本の年号は、大宝以降、現在の「令和」まで途切れることなく続いている（大化の後は、年号が使われない時期があ"},{"id":"korea-japan-state-t22","k":"view","f":"think","kj":"考える｜別の視点","t":"「小中華」をめざした日本","l":"korea-japan-state","x":"律令国家となった日本は、唐に対しては朝貢の使者を送りつつも、冊封は受けなかった。そして国内では、自らを中国にならった「中華」の国とみなし、新羅や渤海を「蕃国」（日本に従う国）、東北"},{"id":"korea-japan-state-t23","k":"now","f":"now","kj":"いま","t":"古代史をめぐる現代の論争","l":"korea-japan-state","x":"古代の朝鮮半島の歴史は、現代の国家どうしの対立とも結びついている。中国は、2002年から2007年にかけて、国家の研究事業「東北工程」を進め、高句麗を「中国の地方政権」とする見解を"},{"id":"korea-japan-state-t24","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"korea-japan-state","x":"手塚治虫『火の鳥 太陽編』（1986〜1988年）：白村江の戦いで敗れた百済の王族の青年が、倭に渡って壬申の乱に巻き込まれていく。古代と未来の二つの物語が並行して進む漫画。里中満智"},{"id":"korean-war-t1","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"奇跡の船","l":"korean-war","x":"1950年12月、中国軍に追われた国連軍は、北朝鮮の東海岸の港町の興南から、船で撤退した。港には、北の共産主義の支配を逃れようとする避難民が、10万人近く押し寄せた。撤退の最後の日"},{"id":"korean-war-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「日本人は12歳の少年」","l":"korean-war","x":"帰国したマッカーサーは、1951年5月、解任をめぐるアメリカ上院の公聴会で証言した。日本の占領について聞かれたマッカーサーは、日本人を、ドイツ人と比べて、次のように述べた。原文If"},{"id":"korean-war-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"朝鮮の海に出た日本の掃海艇","l":"korean-war","x":"1950年10月、国連軍は、北朝鮮の東海岸の元山への上陸を計画した。しかし、元山の港には、ソ連製の機雷が大量に敷設されていた。機雷を取り除く掃海艇が足りなかったアメリカ軍は、日本の"},{"id":"korean-war-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"korean-war","x":"映画『ブラザーフッド』（カン・ジェギュ監督、2004年、韓国）：朝鮮戦争に巻き込まれた兄弟の運命を描いた映画。『M*A*S*H』（映画1970年、ドラマ1972〜1983年、アメリ"},{"id":"kush-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「弓の国」","l":"kush","x":"エジプト人はヌビアを「タ＝セティ（弓の国）」とも呼んだ。ヌビアの人々は、すぐれた弓の射手として知られ、エジプトの軍隊にも傭兵としてたびたび雇われていた。中王国時代の墓からは、ヌビア"},{"id":"kush-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"「エジプトの総督の墓」とされたケルマ","l":"kush","x":"20世紀の初め、アメリカの考古学者ライスナーは、ケルマの遺跡を初めて本格的に発掘した。しかしライスナーは、これほど大規模な遺跡を、ヌビアの人々自身が築いたとは考えなかった。彼は、ケ"},{"id":"kush-t3","k":"source","f":"src","kj":"史料｜記録","t":"奪われた密書――ヒクソスとクシュの同盟","l":"kush","x":"テーベの王カーメスは、ヒクソスとの戦いの記録を石碑に残している。その中に、カーメスの兵が砂漠の道で捕らえた使者が持っていた手紙の内容がある。ヒクソスの王アペピが、クシュの王に宛てた"},{"id":"kush-t4","k":"source","f":"src","kj":"史料｜記録","t":"「馬を飢えさせたことが、何よりも許せぬ」","l":"kush","x":"ピイは、遠征の経過を大きな石碑（ピイの戦勝碑）に刻ませた。その中に、王の人柄をうかがわせる場面がある。中部エジプトの町ヘルモポリスを攻め落としたピイは、降伏した町の王ニムロトの宮殿"},{"id":"kush-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"石臼にされた神学書","l":"kush","x":"大英博物館に、表面の中央部分が丸くすり減った黒い石板がある。第25王朝の王シャバカが、メンフィスの神殿にあった古い文書を写させて刻ませたもので、「シャバカ石」と呼ばれる。メンフィス"},{"id":"kush-t6","k":"now","f":"now","kj":"いま","t":"読めるのに意味が分からない文字","l":"kush","x":"メロエ文字には、ヒエログリフの形を借りた神聖な書体と、それをくずした筆記体の2種類がある。1909年、イギリスの学者グリフィスは、エジプト語とメロエ語の両方で書かれた王の名などを手"},{"id":"kush-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"踏みつけられた皇帝の首","l":"kush","x":"1910年、メロエの遺跡を発掘していたイギリスの考古学者ガースタングは、小さな神殿の入口の階段の下から、ブロンズ製の人の頭部を掘り出した。それは、ガラスと石をはめこんだ目が生き生き"},{"id":"kush-t8","k":"confuse","f":"confuse","kj":"混同注意","t":"ヌビア・クシュ・エチオピア・アクスム","l":"kush","x":"名称指すもの注意点ヌビアナイル川の急流地帯を中心とする地方（現在のエジプト南部〜スーダン北部）地方名クシュヌビアに栄えた王国（ケルマ、ナパタ、メロエ）。エジプト人の呼び名時代によっ"},{"id":"kush-t9","k":"now","f":"now","kj":"いま","t":"内戦にさらされる遺産","l":"kush","x":"メロエのピラミッド群を含む「メロエ島の古代遺跡群」は、2011年にユネスコの世界遺産に登録された。また、ゲベル＝バルカルとナパタ地方の遺跡群も、2003年に世界遺産となっている。メ"},{"id":"kush-t10","k":"debate","f":"think","kj":"考える｜諸説あり","t":"アフリカの鉄はどこから来たか","l":"kush","x":"メロエのほかにも、サハラ以南のアフリカでは古くから鉄が作られていた。ナイジェリアのノク文化は、独特の素焼きの人物像で知られるが、前1千年紀の半ばには鉄を作っていた。アフリカの製鉄技"},{"id":"kush-t11","k":"source","f":"src","kj":"史料｜記録","t":"「エチオピアの女王カンダケの高官」――『使徒言行録』","l":"kush","x":"キリスト教の『新約聖書』の『使徒言行録』には、イエスの弟子フィリポが、エルサレムからガザへ下る道で、ある旅人に出会う場面が描かれている。原文καὶ ἰδοὺ ἀνὴρ Αἰθίοψ"},{"id":"kushan-t1","k":"source","f":"src","kj":"史料｜記録","t":"ミリンダ王の問い","l":"kushan","x":"仏典『ミリンダ王の問い』（パーリ語）は、ギリシア人の王ミリンダ（メナンドロス）と、インドの仏僧ナーガセーナとの問答の形で、仏教の教えを説いた書物である。ギリシアの哲学的な問いと、イ"},{"id":"kushan-t2","k":"source","f":"src","kj":"史料｜記録","t":"『後漢書』が記すクシャーナ朝の成立","l":"kushan","x":"原文月氏自為匈奴所滅，遂遷於大夏，分其國為休密、雙靡、貴霜、肸頓、都密，凡五部翖侯。 ……現代語訳月氏は、匈奴に滅ぼされてから、大夏（バクトリア）に移り住み、その国を休密・双靡・貴"},{"id":"kushan-t3","k":"now","f":"now","kj":"いま","t":"ベグラムの宝物","l":"kushan","x":"1937年と1939年、フランスの考古学者たちは、アフガニスタンのカーブルの北のベグラム（古代のカーピシー、クシャーナ朝の夏の都とされる）で、封印された二つの部屋を発見した。中から"},{"id":"kushan-t4","k":"source","f":"src","kj":"史料｜記録","t":"中国の仏典が記す「四天子」","l":"kushan","x":"4世紀末に漢訳された仏典『十二遊経』には、当時の世界を4人の「天子」が分け合っているという、興味深い記述がある。原文閻浮提中有四天子：東有晉天子，人民熾盛；南有天竺國天子，土地多名"},{"id":"kushan-t5","k":"confuse","f":"confuse","kj":"混同注意","t":"上座部仏教と大乗仏教","l":"kushan","x":"上座部仏教大乗仏教目指すもの出家者が修行して、自らが悟りを開く（解脱）菩薩の慈悲の行いによって、多くの人々を救う（衆生救済）理想の人間像修行を完成した聖者（阿羅漢）菩薩在家信者の救"},{"id":"kushan-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"最初の仏像はどこでつくられたのか","l":"kushan","x":"仏像が、ガンダーラとマトゥラーのどちらで先につくられたのかについては、20世紀の初めから論争が続いている。ヨーロッパの研究者の多くは、ギリシア人の影響を受けたガンダーラで仏像が生ま"},{"id":"kushan-t7","k":"confuse","f":"confuse","kj":"混同注意","t":"ガンダーラ美術・マトゥラー美術・グプタ様式","l":"kushan","x":"ガンダーラ美術マトゥラー美術グプタ様式時代1〜5世紀ごろ（最盛期は2〜3世紀）1〜3世紀ごろ（クシャーナ朝期）4〜6世紀（グプタ朝）地域西北インド（現パキスタン北部・アフガニスタン"},{"id":"kushan-t8","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"法隆寺の柱はギリシアから来た？","l":"kushan","x":"奈良の法隆寺の柱は、中ほどがわずかにふくらんでいる。これがギリシアのパルテノン神殿の柱のふくらみ（エンタシス）と同じであり、ギリシアの建築の技法がシルクロードを通って日本に伝わった"},{"id":"late-medieval-crisis-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"グリーンランドの最後の結婚式","l":"late-medieval-crisis","x":"寒冷化の影響を最も強く受けたのは、北の果ての人々であった。10世紀の末、ヴァイキングの赤毛のエイリークがグリーンランドに入植して以来、その南西の海岸には、ノルウェー系の人々の村が営"},{"id":"late-medieval-crisis-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「14世紀の危機」は世界的だったのか","l":"late-medieval-crisis","x":"14世紀に危機を迎えたのは、ヨーロッパだけではなかった。中国では、元が天災や財政難に苦しみ、1351年に紅巾の乱が起こった（→「元の衰退と紅巾の乱」の回）。西アジアではイル＝ハン国"},{"id":"late-medieval-crisis-t3","k":"source","f":"src","kj":"史料｜記録","t":"年代記作者の目","l":"late-medieval-crisis","x":"ジャックリーの乱について、最もよく知られた記録を残したのは、フランドル出身の年代記作者フロワサールである。フロワサールは、農民たちの残虐さを、言葉を尽くして書いている。「彼らは、騎"},{"id":"late-medieval-crisis-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「パンとチーズ」と言ってみろ","l":"late-medieval-crisis","x":"ロンドンに入った反乱者たちの怒りは、思いがけない人々にも向けられた。フランドルから来た織物職人や商人たちである。彼らはイングランドの職人の仕事を奪う者として憎まれており、反乱の混乱"},{"id":"late-medieval-crisis-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"反乱は失敗だったのか","l":"late-medieval-crisis","x":"ジャックリーの乱も、ワット＝タイラーの乱も、短い期間で鎮圧され、指導者たちは処刑された。その意味では、反乱は失敗に終わった。しかし、イングランドでは、反乱の後、議会は二度と人頭税を"},{"id":"late-medieval-crisis-t6","k":"now","f":"now","kj":"いま","t":"600年後の「人頭税」","l":"late-medieval-crisis","x":"1989〜90年、イギリスのサッチャー政権は、地方税として、収入にかかわらず一人あたりほぼ同じ額を課す「コミュニティ・チャージ」を導入した。人々はこれを「ポール・タックス（人頭税）"},{"id":"late-medieval-crisis-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"late-medieval-crisis","x":"チョーサー『カンタベリー物語』（14世紀末）：カンタベリーへ巡礼に向かう騎士、粉屋、修道女、商人など、さまざまな身分の人々が、道中で物語を語り合う。14世紀のイングランドの社会を映"},{"id":"late-ming-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"定陵の悲劇","l":"late-ming","x":"万暦帝は、まだ20代の初めであった1584年から、北京の北の天寿山のふもとに、自分の墓の建設を始めさせた。6年の歳月と、800万両ともいわれる銀をつぎ込んで完成したのが、明の十三陵"},{"id":"late-ming-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"失業した駅卒・李自成","l":"late-ming","x":"明の財政難は、思わぬところに火をつけた。1629年、明は、経費を減らすため、全国の駅站（公用の通信・交通のための宿場）を削減し、多くの駅卒（宿場の人夫）を解雇した。その中に、陝西の"},{"id":"late-ming-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「冠を衝く一怒は紅顔の為なり」","l":"late-ming","x":"なぜ、呉三桂は清に降ったのか。後の世には、ある恋物語が語られた。呉三桂には、陳円円という、美しい愛妾がいた。北京を占領した李自成の部下が、この陳円円を奪った。それを知った呉三桂は、"},{"id":"late-ming-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「クラーク磁器」の名の由来","l":"late-ming","x":"明の時代、江西の景徳鎮では、白い磁器に青い模様を描いた染付（青花）や、赤や緑などの色を加えた赤絵（五彩）の磁器が、大量に焼かれた。これらは、ポルトガル人やオランダ人の手で、ヨーロッ"},{"id":"late-ming-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"マテオ・リッチ――儒者の服を着た宣教師","l":"late-ming","x":"明の末期、中国の知識人たちは、まったく新しい学問に出会った。それをもたらしたのが、イエズス会の宣教師マテオ・リッチ（中国名は利瑪竇）である（→「対抗宗教改革とイエズス会」の回）。1"},{"id":"late-ming-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"late-ming","x":"呉承恩とされる『西遊記』、『金瓶梅』（16世紀）：明代の後半に完成した長編小説。『三国志演義』『水滸伝』とあわせて「四大奇書」と呼ばれる。都市の庶民の文化の発展が、こうした小説の流"},{"id":"later-han-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"王莽の主な政策","l":"later-han","x":"政策内容結果王田制全国の土地を「王田」として国有とし、売買を禁止。8人以下の家で土地が1井（約900畝）を超えれば、余分を親族や村人に分け与えさせた豪族の激しい反発で3年後に撤回奴"},{"id":"later-han-t2","k":"now","f":"now","kj":"いま","t":"日本で出土する王莽の貨幣","l":"later-han","x":"王莽の時代に発行された「貨泉」という銅銭は、日本の弥生時代の遺跡からも数多く出土している。貨泉は、新の滅亡後まもなく使われなくなったため、出土した地層の年代を知る手がかりにもなる。"},{"id":"later-han-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"王莽は「悪人」だったのか","l":"later-han","x":"王莽は、長い間、漢の帝位を奪った「簒奪者」として、儒学者たちから厳しく非難されてきた。後漢の歴史家班固の『漢書』も、王莽を偽善者として描いている。しかし、20世紀になると、王莽の土"},{"id":"later-han-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「隴を得て蜀を望む」と青年劉秀の夢","l":"later-han","x":"光武帝は、西方の隴西（甘粛）を平定したのち、さらに四川の蜀を攻める将軍に、「人は足ることを知らないのに苦しむものだ。隴を平定すると、また蜀を望む」と書き送った。一つの望みがかなうと"},{"id":"later-han-t5","k":"source","f":"src","kj":"史料｜記録","t":"『後漢書』東夷伝の倭の記事","l":"later-han","x":"原文建武中元二年，倭奴國奉貢朝賀，使人自稱大夫，倭國之極南界也。光武賜以印綬。現代語訳建武中元2年（57年）、倭の奴国が貢ぎ物を奉じて朝賀した。使者は自ら大夫と称した。倭国の最も南"},{"id":"later-han-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「跋扈将軍」梁冀","l":"later-han","x":"2世紀半ば、外戚の梁冀は、20年近くにわたって権力をほしいままにした。8歳で即位した質帝は、朝廷の会議で梁冀を見て、「これは跋扈将軍（のさばり将軍）だ」と言った。これを聞いた梁冀は"},{"id":"later-han-t7","k":"source","f":"src","kj":"史料｜記録","t":"「蒼天すでに死す」","l":"later-han","x":"原文蒼天已死，黃天當立，歲在甲子，天下大吉。書き下し蒼天すでに死す、黄天まさに立つべし。歳は甲子に在り、天下大吉。現代語訳青い天（漢）はすでに死んだ。黄色い天（太平道）が立つべき時"},{"id":"later-han-t8","k":"confuse","f":"confuse","kj":"混同注意","t":"太平道と五斗米道","l":"later-han","x":"太平道五斗米道創始者張角張陵（張道陵）地域華北（河北・山東・河南など）四川・漢中教え病気は罪の報い。懺悔と符水で治る病気治療と懺悔。入信者は米5斗を納める行動184年、黄巾の乱を起"},{"id":"later-han-t9","k":"voice","f":"src","kj":"史料｜証言","t":"「白骨、野に露わる」――後漢末の詩人たちが見たもの","l":"later-han","x":"黄巾の乱の後、後漢の末には、群雄の争いと飢饉、疫病が中国を荒廃させた。この時代を生きた詩人たちは、目の前の惨状を詩に刻んでいる。のちに魏の基礎を築いた曹操自身も、こう詠んだ。原文鎧"},{"id":"later-han-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"later-han","x":"『三国志演義』：明代に書かれた歴史小説で、黄巾の乱から始まり、魏・呉・蜀の三国の興亡を描く。日本では吉川英治『三国志』（1939〜1943年連載）、横山光輝の漫画『三国志』、ゲーム"},{"id":"latin-america-cold-war-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"申告額の代償","l":"latin-america-cold-war","x":"アルベンスの政府は、収用する土地の代金を、ユナイテッド・フルーツ社が、それまで税金を納めるために自ら申告していた土地の評価額で支払うと提案した。会社は、税金を安くするため、土地の価"},{"id":"latin-america-cold-war-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「歴史は私に無罪を宣告するだろう」――カストロの法廷弁論","l":"latin-america-cold-war","x":"1953年7月26日、27歳の弁護士フィデル・カストロは、仲間たちとともに、キューバのバティスタ独裁政権を倒すために、サンティアゴ・デ・クーバのモンカダ兵営を襲撃した。襲撃は失敗し"},{"id":"latin-america-cold-war-t3","k":"source","f":"src","kj":"史料｜記録","t":"「経済に悲鳴をあげさせよ」","l":"latin-america-cold-war","x":"アジェンデの当選が決まった直後の1970年9月15日、アメリカのニクソン大統領は、ホワイトハウスで、CIAのヘルムズ長官らと会談した。ヘルムズが、その場で書き留めたメモが、のちに公"},{"id":"latin-america-cold-war-t4","k":"source","f":"src","kj":"史料｜記録","t":"最後の演説","l":"latin-america-cold-war","x":"「私は、辞任しない。……歴史の転換点に立って、私は、人民への忠誠を、私の命で償うだろう。……チリの労働者たちよ、私は、チリとその未来を信じている。ほかの人々が、この暗く苦い時を乗り"},{"id":"latin-america-cold-war-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"ワールドカップの陰で","l":"latin-america-cold-war","x":"1978年、アルゼンチンで、サッカーのワールドカップが開かれた。軍事政権は、大会を、国の威信を世界に示す機会と考えた。アルゼンチンは、決勝でオランダを破り、初優勝を果たした。ブエノ"},{"id":"latin-america-cold-war-t6","k":"person","f":"deep","kj":"深掘り｜人物","t":"ミサの最中の銃声","l":"latin-america-cold-war","x":"首都サンサルバドルの大司教オスカル・ロメロは、もともとは保守的な聖職者とみられていた。しかし、親しい神父が殺されたことをきっかけに、貧しい人々の側に立って、軍の暴力を公然と批判する"},{"id":"latin-america-cold-war-t7","k":"now","f":"now","kj":"いま","t":"日本とラテンアメリカ","l":"latin-america-cold-war","x":"ラテンアメリカは、日本と意外に深いつながりを持つ地域である。1908年、最初の移民船の笠戸丸がブラジルのサントス港に着いて以来、多くの日本人が、ブラジルやペルーなどに移住し、コーヒ"},{"id":"latin-america-cold-war-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"latin-america-cold-war","x":"映画『モーターサイクル・ダイアリーズ』（ウォルター・サレス監督、2004年）：医学生だった若きエルネスト・ゲバラが、友人とオートバイで南アメリカを旅し、貧しい人々や鉱山の労働者たち"},{"id":"latin-america-independence-t1","k":"now","f":"now","kj":"いま","t":"今も鳴り響く「叫び」","l":"latin-america-independence","x":"イダルゴが住民を集めるために鳴らしたドロレスの教会の鐘は、現在、メキシコシティの国立宮殿のバルコニーに掛けられている。毎年9月15日の夜11時、メキシコの大統領は、このバルコニーに"},{"id":"latin-america-independence-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"グアヤキル会談で何があったのか","l":"latin-america-independence","x":"グアヤキルの会談の内容については、さまざまな説がある。独立後の国の形をめぐって、君主制を考えていたサン・マルティンと、共和制を主張するボリバルが対立したという説。ペルーの残るスペイ"},{"id":"latin-america-independence-t3","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"latin-america-independence","x":"ガルシア＝マルケス『迷宮の将軍』（小説、1989年）：独立の英雄シモン・ボリーバルが、権力を失い、病に侵されて、マグダレナ川を下っていく最後の旅を描いた小説。作品は史実をもとにした"},{"id":"louis-xiv-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ヴェルサイユにトイレはなかったのか","l":"louis-xiv","x":"「ヴェルサイユ宮殿にはトイレがなく、人々は庭や廊下の隅で用を足していた。ハイヒールや香水は、そのために生まれた」――。こんな話を聞いたことがあるかもしれない。実際には、ヴェルサイユ"},{"id":"louis-xiv-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「彼らは、実は人間なのである」――ラ・ブリュイエールの見た農民","l":"louis-xiv","x":"ヴェルサイユの華やかな宮廷の外では、フランスの人口の大部分を占める農民たちが、重い税と地代に苦しんでいた。ルイ14世の時代の作家ラ・ブリュイエールは、人間の性格や風俗を鋭く描いた『"},{"id":"louis-xiv-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"鉄仮面の囚人","l":"louis-xiv","x":"ルイ14世の時代、フランスの監獄に、顔を仮面で覆われた、名前のわからない一人の囚人がいた。彼は、各地の監獄を移された末に、パリのバスティーユ牢獄に入れられ、1703年にそこで亡くな"},{"id":"louis-xiv-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"louis-xiv","x":"デュマ『ブラジュロンヌ子爵』（小説、1847〜1850年）：『三銃士』の続編で、ルイ14世の時代を描く。その一部の「鉄仮面」の物語は、映画『仮面の男』（1998年）の原作となった。"},{"id":"macedonia-t1","k":"now","f":"now","kj":"いま","t":"マケドニアは誰のものか","l":"macedonia","x":"古代のマケドニア人が「ギリシア人」だったのかどうかは、学問上の問題であるだけでなく、現代の国際問題とも結びついてきた。1991年、ユーゴスラヴィアから独立した国が「マケドニア共和国"},{"id":"macedonia-t2","k":"source","f":"src","kj":"史料｜記録","t":"「フィリッポス弾劾演説」","l":"macedonia","x":"アテネの弁論家デモステネスは、フィリッポスをギリシアの自由を奪う独裁者とみなし、民会でたびたび演説して、マケドニアへの抵抗を訴えた。これらの演説は「フィリッピカ（フィリッポス弾劾演"},{"id":"macedonia-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"カイロネイアの獅子","l":"macedonia","x":"テーベの神聖隊は、150組300人の男性どうしの恋人たちで編成された精鋭部隊で、恋人の前で臆病な姿は見せられないと、互いに命がけで戦ったという。カイロネイアの戦いで、神聖隊はほぼ全"},{"id":"macedonia-t4","k":"now","f":"now","kj":"いま","t":"ヴェルギナの王墓","l":"macedonia","x":"1977年、ギリシアの考古学者アンドロニコスは、ギリシア北部のヴェルギナで、盗掘を免れた王の墓を発見した。墓の中からは、黄金の箱に納められた遺骨が見つかった。箱のふたには、マケドニ"},{"id":"macedonia-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"macedonia","x":"岩明均『ヒストリエ』（漫画、2003年〜）：フィリッポス2世とアレクサンドロスに仕えた書記官エウメネスの生涯を描く。マケドニアの宮廷や、カイロネイアの戦いへの道が、緻密に描かれてい"},{"id":"mali-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"スンジャタ叙事詩","l":"mali","x":"グリオたちが語る『スンジャタ叙事詩』によれば、スンジャタは、マリンケ人の小さな国の王の息子として生まれたが、生まれつき足が不自由で、7歳になっても立つことができなかった。人々は彼を"},{"id":"mali-t2","k":"now","f":"now","kj":"いま","t":"クルカン・フガ憲章","l":"mali","x":"グリオたちの伝承によれば、スンジャタは勝利の後、クルカン・フガという場所に各地の首長たちを集めて、新しい国の決まりを定めた。そこでは、さまざまな氏族の役割や、人々の間の関係、他人の"},{"id":"mali-t3","k":"source","f":"src","kj":"史料｜記録","t":"大西洋に船出した王","l":"mali","x":"「私の前の王は、大洋（大西洋）の果てに何があるのかを知ろうとした。王は、200隻の船に人を乗せ、それと同じ数の船に、何年分もの金と水と食糧を積ませて、送り出した。そして、『大洋の果"},{"id":"mali-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「史上最も裕福な人」？","l":"mali","x":"インターネットなどでは、マンサ＝ムーサは「人類史上最も裕福な人物」で、その資産は現在の価値で4000億ドルを超えた、などと紹介されることがある。しかし、700年前の一人の王の財産を"},{"id":"mali-t5","k":"source","f":"src","kj":"史料｜記録","t":"パン3つと牛肉ひと切れ","l":"mali","x":"イブン＝バットゥータは、遠い国から来た学者として、王からの贈り物を楽しみに待っていた。ところが、届けられたのは、パン3つと、シアバターで揚げた牛肉ひと切れ、ひょうたんに入ったヨーグ"},{"id":"mali-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"鳥の仮面をかぶった語り部","l":"mali","x":"イブン＝バットゥータは、マリの王宮の祭りで、不思議な光景を見た。祭りの日、王の前に、羽根で作られた鳥の仮面と衣装を身につけた語り部たちが進み出て、王の前で詩を語ったのである。「あな"},{"id":"mali-t7","k":"now","f":"now","kj":"いま","t":"写本を救った人々","l":"mali","x":"トンブクトゥの町の家々には、何百年もの間、代々受け継がれてきた数十万点もの写本が眠っていた。2012年、マリ北部をイスラーム過激派の武装勢力が占領した。武装勢力は、トンブクトゥの聖"},{"id":"manchuria-t1","k":"mech","f":"deep","kj":"深掘り｜しくみ","t":"なぜ関東軍は「暴走」できたのか","l":"manchuria","x":"政府が「不拡大」を決めても、関東軍は止まらなかった。出先の軍隊が、本国の政府の方針を無視して戦争を広げる――なぜ、そのようなことが可能だったのだろうか。統帥権の独立：大日本帝国憲法"},{"id":"manchuria-t2","k":"source","f":"src","kj":"史料｜記録","t":"「宣戦布告なしに、中国の領土が奪われた」――リットン報告書","l":"manchuria","x":"1932年10月、国際連盟が満州事変の調査のために派遣したリットン調査団の報告書が公表された。報告書は、満州における日本の特殊な権益や、中国の排日運動などにも理解を示しつつ、満州事"},{"id":"manchuria-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"爆弾三勇士","l":"manchuria","x":"1932年2月、第1次上海事変の戦闘で、日本軍の3人の工兵が、点火した爆弾を抱えて中国軍の鉄条網に突入し、爆死した。新聞は、彼らを、自らの命を捨てて突破口を開いた「肉弾三勇士（爆弾"},{"id":"manchuria-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"減刑嘆願の手紙","l":"manchuria","x":"五・一五事件の裁判で、首相を殺害した将校たちに下された判決は、驚くほど軽いものであった。首謀者の刑も、禁錮15年にとどまり、死刑になった者は一人もいなかった。裁判の間、全国から、被"},{"id":"manchuria-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"manchuria","x":"映画『ラストエンペラー』（1987年）：満州国の皇帝となった溥儀が、関東軍の傀儡として扱われる姿を描いている。甘粕正彦を坂本龍一が演じ、音楽も担当した。作品は史実をもとにした創作を"},{"id":"manchuria-t6","k":"source","f":"src","kj":"史料｜記録","t":"「今からでも遅くはない」――二・二六事件の「兵に告ぐ」","l":"manchuria","x":"1936年2月26日の早朝、陸軍の皇道派の青年将校たちが、約1500人の兵士を率いて、首相官邸などを襲い、高橋是清蔵相、斎藤実内大臣らを殺害した。二・二六事件である。昭和天皇は、重"},{"id":"maurya-t1","k":"source","f":"src","kj":"史料｜記録","t":"ギリシア人が見たパータリプトラ","l":"maurya","x":"和平ののち、セレウコスは、メガステネスを大使としてチャンドラグプタの宮廷に送った。メガステネスは、インドでの見聞を『インド誌』にまとめた。原本は失われたが、のちのギリシア・ローマの"},{"id":"maurya-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"『実利論』とカウティリヤ","l":"maurya","x":"インドの伝承では、チャンドラグプタが王位につくのを助けた宰相は、バラモンのカウティリヤ（チャーナキヤ）であったとされる。そして、カウティリヤが、国家の統治の技術について記した書物が"},{"id":"maurya-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"断食して亡くなった王","l":"maurya","x":"ジャイナ教の伝承によれば、チャンドラグプタは、晩年に王位を息子に譲って、ジャイナ教の修行者となり、南インドのシュラヴァナベラゴラで、断食によって生涯を終えたという伝承。シュラヴァナ"},{"id":"maurya-t4","k":"source","f":"src","kj":"史料｜記録","t":"カリンガ征服の後悔――磨崖碑第13章","l":"maurya","x":"天愛喜見王（アショーカ王）が即位して8年がたったとき、カリンガ国が征服された。15万の人々がそこから連れ去られ、10万の人々がそこで殺され、さらにその何倍もの人々が死んだ。それから"},{"id":"maurya-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"アショーカは「平和主義者」だったのか","l":"maurya","x":"アショーカは、戦争を放棄した平和の王として、しばしば理想化されて語られる。しかし、碑文を詳しく読むと、それとは異なる面も見えてくる。たとえば、磨崖碑第13章は、帝国の周辺の森に住む"},{"id":"maurya-t6","k":"source","f":"src","kj":"史料｜記録","t":"ルンビニーの石柱碑","l":"maurya","x":"1896年、ネパール南部で、地中に半ば埋もれた石柱が発見された。そこには、次のように刻まれていた。原文devānapiyena piyadasina lājina vīsativa"},{"id":"maurya-t7","k":"now","f":"now","kj":"いま","t":"インドの国章とアショーカ王","l":"maurya","x":"ブッダが初めて説法を行ったサールナートに、アショーカが建てた石柱の頂上には、4頭のライオンが背中合わせに座る、見事な彫刻（柱頭）がのせられていた。1950年、インド共和国は、このラ"},{"id":"maurya-t8","k":"confuse","f":"confuse","kj":"混同注意","t":"インドの古代の主な王朝と宗教","l":"maurya","x":"王朝時代中心主な王宗教・文化マウリヤ朝前4世紀末〜前2世紀初めガンジス川流域（都パータリプトラ）チャンドラグプタ、アショーカアショーカが仏教を保護。ダルマの政治、磨崖碑・石柱碑クシ"},{"id":"maurya-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"maurya","x":"映画『アショーカ』（2001年、インド、シャー・ルク・カーン主演）：若き日のアショーカ王の恋と戦いを、カリンガ征服までを中心に描いたインド映画。王の若い時代については史料がほとんど"},{"id":"maya-classic-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ゴムのボールと球技","l":"maya-classic","x":"マヤをはじめとするメソアメリカの人々は、ゴムの木の樹液から作った、重いゴムのボールを使って球技を行った。選手は、ボールを手で触れることを許されず、主に腰で打ち返したと考えられている"},{"id":"maya-classic-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「血の池ができ、頭蓋骨が山と積まれた」","l":"maya-classic","x":"ドス・ピラスの「神聖文字の階段」には、679年に、ドス・ピラスの王がティカルの王を打ち破ったことが記されている。その記録は、戦いの様子を、「血の池ができ、（ティカルの人々の）頭蓋骨"},{"id":"maya-classic-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"「6つの空の女王」","l":"maya-classic","x":"682年、ドス・ピラスの王バフラフ・チャン・カウィールの娘が、東の都市ナランホに到着した。碑文で「6つの空の女王（イシュ・ワク・チャン・アハウ）」と呼ばれる女性である。ナランホは、"},{"id":"maya-classic-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「パレンケの宇宙飛行士」","l":"maya-classic","x":"1968年、スイスの作家エーリッヒ・フォン・デニケンは、著書『未来の記憶』の中で、パカルの石棺の蓋の浮き彫りは、宇宙船の操縦席に座り、操縦かんを握る宇宙飛行士を描いたものだと主張し"},{"id":"maya-classic-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「野蛮人に、これらの建物を建てることはできない」――コパンを「買った」アメリカ人","l":"maya-classic","x":"1839年、アメリカの外交官で旅行家のジョン・ロイド・スティーヴンズは、イギリスの画家フレデリック・キャザウッドとともに、中央アメリカのジャングルに分け入り、ホンジュラスのコパンの"},{"id":"maya-classic-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「崩壊」か「変容」か","l":"maya-classic","x":"「マヤ文明の崩壊」という言葉は、マヤ文明がこの時に滅び去ったかのような印象を与える。しかし、実際に放棄されたのは、主に南部の低地の都市と、その王を中心とする政治のしくみであった諸説"},{"id":"maya-classic-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"一夜で建てられたピラミッド","l":"maya-classic","x":"ウシュマルの「魔法使いのピラミッド」には、次のような伝説が語り伝えられている伝承。子のない老婆（魔女ともいわれる）が、卵をかえして、一人の小人を育てた。ある日、小人が鳴らした銅鑼の"},{"id":"maya-classic-t8","k":"person","f":"deep","kj":"深掘り｜人物","t":"二人のスペイン人漂流者","l":"maya-classic","x":"1511年、パナマから船出したスペイン人の一行が難破し、ユカタン半島の海岸に流れ着いた。生き残った者の多くは死んだが、二人のスペイン人が、マヤの人々の間で生き延びた。1519年、メ"},{"id":"maya-classic-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"神になった馬","l":"maya-classic","x":"南部の熱帯低地には、その後も長く、スペイン人に従わないマヤの国が残った。ペテン湖の島の都ノフペテンを拠点とするイツァの王国である。1525年、ホンジュラスに向かう途中のコルテスは、"},{"id":"maya-classic-t10","k":"now","f":"now","kj":"いま","t":"現在のマヤの人々","l":"maya-classic","x":"マヤ文明は「消えた文明」と呼ばれることがあるが、マヤの人々は消えてはいない。現在も、メキシコ南部、グアテマラ、ベリーズ、ホンジュラスなどには、30ほどのマヤ系の言語を話す、数百万の"},{"id":"maya-classic-t11","k":"works","f":"works","kj":"作品","t":"マヤの古典期にまつわる作品","l":"maya-classic","x":"映画『スター・ウォーズ』（1977年）：反乱軍の秘密基地がある惑星のシーンで、ティカルの1号神殿などがジャングルの中から突き出す風景が、そのまま使われている。マイケル・D・コウ『マ"},{"id":"maya-teotihuacan-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"チョコレートはマヤから","l":"maya-teotihuacan","x":"チョコレートの原料のカカオは、中央アメリカ原産の植物である。マヤの人々は、カカオの豆をすりつぶし、水やトウモロコシの粉、トウガラシなどを混ぜて、泡立てた飲み物にして飲んだ。甘くはな"},{"id":"maya-teotihuacan-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"スペイン人が焼いたマヤの書物","l":"maya-teotihuacan","x":"マヤの人々は、イチジク科の木の樹皮からつくった紙に、文字や絵を書いて、屏風のように折りたたんだ書物（コデックス）をつくった。しかし、16世紀にユカタン半島に来たスペインの修道士ディ"},{"id":"maya-teotihuacan-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"2012年人類滅亡説","l":"maya-teotihuacan","x":"2012年12月21日は、長期暦の「13.0.0.0.0」、つまり、神話上の世界の始まりから13バクトゥンが完了する日にあたった。これを根拠に、「マヤの予言では2012年に世界が終"},{"id":"maya-teotihuacan-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"地下の水銀の湖","l":"maya-teotihuacan","x":"2003年、テオティワカンの「羽毛のある蛇の神殿」の前で、大雨の後に地面に穴があいた。調査すると、その下には、地下約17mの深さを100m以上にわたって神殿の下まで続く、人工のトン"},{"id":"maya-teotihuacan-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"征服か、同盟か","l":"maya-teotihuacan","x":"378年の出来事を、テオティワカンによるティカルの軍事的な征服とみる研究者は多い。王の死と新しい王の即位が、よそ者の到来と同時に起こっていること、テオティワカンの戦士の姿が強調され"},{"id":"maya-teotihuacan-t6","k":"now","f":"now","kj":"いま","t":"レーザーで見つかった「森の下の都市」","l":"maya-teotihuacan","x":"近年、マヤ文明の研究は、新しい技術によって大きく変わりつつある。航空機から地上にレーザー光線を照射して、木々の下の地形を測る「ライダー（LiDAR）」の技術を使うと、熱帯雨林におお"},{"id":"maya-teotihuacan-t7","k":"works","f":"works","kj":"作品","t":"マヤ・メソアメリカにまつわる作品","l":"maya-teotihuacan","x":"『ポポル・ヴフ』：16世紀に、グアテマラ高地のキチェ・マヤの人々が、ラテン文字を使って書き残した神話と歴史の書。神々が、泥や木で人間をつくろうとして失敗し、最後にトウモロコシから人"},{"id":"medieval-life-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「ああ、旦那さま、ひどくつらいのです」――農夫の一日","l":"medieval-life","x":"1000年ごろ、イングランドの修道院長エルフリックは、修道院の少年たちがラテン語を学ぶための教材として、さまざまな職業の人々との問答をつくった。のちに、そのラテン語の文の行間に、古"},{"id":"medieval-life-t2","k":"now","f":"now","kj":"いま","t":"消えた村ウォラム・パーシー","l":"medieval-life","x":"イングランド北部のヨークシャーには、ウォラム・パーシーという、中世に人が住まなくなった村の跡がある。1950年から40年にわたって行われた発掘調査によって、中世の農民の暮らしが詳し"},{"id":"medieval-life-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"裁判にかけられたブタ","l":"medieval-life","x":"中世ヨーロッパでは、人を傷つけたり殺したりした動物が、人間と同じように裁判にかけられることがあった。1386年、ノルマンディーの町ファレーズで、1頭の雌ブタが、赤ん坊の顔と腕を食い"},{"id":"medieval-life-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"ビンゲンのヒルデガルト","l":"medieval-life","x":"ドイツのライン川のほとりの女子修道院長ヒルデガルト（1098〜1179年）は、中世で最も多才な女性の一人である。8歳で修道院に預けられた彼女は、幼いころから神秘的な幻を見たといわれ"},{"id":"medieval-life-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"medieval-life","x":"ウンベルト・エーコ『薔薇の名前』（小説、1980年、映画1986年）：14世紀の北イタリアの修道院で起こる連続殺人の謎を、修道士ウィリアムが解き明かす。修道院の暮らしや写本、異端審"},{"id":"medieval-towns-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「都市の空気は自由にする」","l":"medieval-towns","x":"ドイツには、「都市の空気は（人を）自由にする」ということわざがある。領主のもとから逃げてきた農奴が、都市に1年と1日住み続ければ、領主は彼を連れ戻すことができず、自由な身分になれる"},{"id":"medieval-towns-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"町と大学の戦争","l":"medieval-towns","x":"大学の学生たちは、町の人々とたびたび衝突した。学生は聖職者の身分を持ち、町の裁判所ではなく大学や教会の裁判を受けたため、町の人々の反感を買った。1355年2月10日、聖スコラスティ"},{"id":"medieval-towns-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"「黙りこくった牛」","l":"medieval-towns","x":"トマス・アクィナスは、南イタリアの貴族の家に生まれた。家族は、彼が托鉢修道会のドミニコ会に入ることに猛反対し、兄たちは彼を誘拐して、1年以上も城に閉じ込めたという。トマスは、体が大"},{"id":"medieval-towns-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"medieval-towns","x":"阿部謹也『ハーメルンの笛吹き男――伝説とその世界』（1974年）：1284年に、ドイツの町ハーメルンから130人の子どもが消えたという伝説を手がかりに、中世の都市の人々の暮らしと心"},{"id":"medieval-trade-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"胡椒の値段","l":"medieval-trade","x":"中世のヨーロッパでは、胡椒は「黒い黄金」とも呼ばれ、少量でも高い価値を持っていた。そのため、胡椒は、お金の代わりにも使われた。408年に西ゴート人のアラリックが初めてローマを包囲し"},{"id":"medieval-trade-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"「神と利益の名において」――プラートの商人ダティーニ","l":"medieval-trade","x":"トスカーナ地方の町プラートの商人フランチェスコ・ディ・マルコ・ダティーニ（1335ごろ〜1410年）は、ペストで両親を失った孤児から身を起こし、アヴィニョン、フィレンツェ、ジェノヴ"},{"id":"medieval-trade-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「バンク」と「バンクラプト」","l":"medieval-trade","x":"「銀行」を意味する英語の「バンク（bank）」は、両替商が市場で商売をした「机・長いす」を意味するイタリア語の「バンコ（banco）」に由来するといわれる。また、「破産」を意味する"},{"id":"medieval-trade-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"medieval-trade","x":"支倉凍砂『狼と香辛料』（ライトノベル、2006年〜、アニメ2008年・2024年）：中世ヨーロッパ風の世界を舞台に、行商人ロレンスと狼の化身ホロが旅をする。貨幣の両替や為替、ギルド"},{"id":"meiji-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"金が流れ出した","l":"meiji","x":"貿易が始まると、日本からは生糸や茶が大量に輸出され、国内では品不足から物価が上がった。そして、思いもよらない問題が起こった。当時の日本では、金と銀の交換の比率が、およそ1対5であっ"},{"id":"meiji-t2","k":"source","f":"src","kj":"史料｜記録","t":"「天は人の上に人を造らず」――福沢諭吉『学問のすゝめ』","l":"meiji","x":"1872年、福沢諭吉は、『学問のすゝめ』の初編を刊行した。それは、こう書き出されている。原文天は人の上に人を造らず人の下に人を造らずと云へり。されば天より人を生ずるには、万人は万人"},{"id":"meiji-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"6歳の留学生","l":"meiji","x":"岩倉使節団には、43人の留学生が同行していた。その中に、5人の少女がいた。最年少は、わずか6歳の津田梅子であった。梅子は、アメリカのワシントン近郊の家庭に預けられ、11年間をアメリ"},{"id":"meiji-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"なぜ日本は「成功」したのか","l":"meiji","x":"同じように欧米の圧力にさらされながら、日本は、清やオスマン帝国よりも早く近代国家をつくり、不平等条約の改正にこぎつけた。それはなぜだったのか。歴史家たちは、さまざまな理由を挙げてき"},{"id":"meiji-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"meiji","x":"司馬遼太郎『竜馬がゆく』（小説、1962〜1966年連載）：坂本龍馬の生涯を描いた歴史小説。今日の「坂本龍馬」の英雄像の多くは、この小説によってつくられた。和月伸宏『るろうに剣心』"},{"id":"mesopotamia-unification-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"「セム語系」とは","l":"mesopotamia-unification","x":"アッカド人、のちのアムル人、アラム人、フェニキア人、ヘブライ人、アラブ人などは、言語の系統から「セム語系」の民族と呼ばれる。旧約聖書でノアの息子セムの子孫とされたことにちなむ、19"},{"id":"mesopotamia-unification-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"名前の分かる世界最初の作家――エンヘドゥアンナ","l":"mesopotamia-unification","x":"サルゴンは、娘のエンヘドゥアンナを、シュメールの古都ウルの月神ナンナの最高神官に任じた。征服者アッカド人の王女を、シュメール人の宗教の中心に送り込んだわけで、シュメール人を宗教の面"},{"id":"mesopotamia-unification-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"アッカドはなぜ滅んだのか","l":"mesopotamia-unification","x":"アッカド王国は、前2200年ごろから急速に衰え、東の山地から侵入してきたグティ人などによって滅ぼされた。後世のメソポタミアの人々は、ナラム＝シンがニップルのエンリル神殿を破壊したた"},{"id":"mesopotamia-unification-t4","k":"source","f":"src","kj":"史料｜記録","t":"「目には目を」ではなかった最古の法典","l":"mesopotamia-unification","x":"ウル＝ナンム法典の特徴は、多くの罪に対して、銀による賠償を定めていることである。たとえば、「もし人が、他人の目を〔武器で〕損なったならば、銀2分の1ミナを支払わなければならない」「"},{"id":"mesopotamia-unification-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"1日で160キロ走った王？","l":"mesopotamia-unification","x":"ウル＝ナンムの子シュルギ王は、48年間にわたって王国を治め、自らをたたえる讃歌をいくつも作らせた。その一つでは、シュルギがニップルとウルの間、約160キロメートルを1日で走って往復"},{"id":"mesopotamia-unification-t6","k":"source","f":"src","kj":"史料｜記録","t":"「ウル滅亡哀歌」","l":"mesopotamia-unification","x":"ウル第3王朝の滅亡の後、シュメール人はその悲劇を哀歌に詠んだ。そこでは、都を見捨てた神々を責めながら、荒廃した町の様子がこう描かれている。「都の城壁には、壊れた土器のかけらのように"},{"id":"mesopotamia-unification-t7","k":"source","f":"src","kj":"史料｜記録","t":"マリ文書――古代の外交官たちの手紙","l":"mesopotamia-unification","x":"ハンムラビの時代の国際関係を生き生きと伝えるのが、ユーフラテス川中流の王国マリの宮殿跡から見つかった、約2万5000枚の粘土板文書（マリ文書）である。その中には、各地に派遣されたマ"},{"id":"mesopotamia-unification-t8","k":"confuse","f":"confuse","kj":"混同注意","t":"年代の数字は確かなのか――「中年代説」","l":"mesopotamia-unification","x":"この回に出てきた「ハンムラビの在位：前1792〜前1750年」「バビロン陥落：前1595年」といった年代は、実はかなり不確かなものである。メソポタミアの年代は、王名表などから相対的"},{"id":"middle-east-mandates-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"定規で引いた国境","l":"middle-east-mandates","x":"中東の地図を見ると、砂漠の中に、まっすぐな国境線が何本も引かれていることに気づく。イラクとシリア、ヨルダンとサウジアラビア、シリアとヨルダン――これらの直線の多くは、この時代に、イ"},{"id":"middle-east-mandates-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"黒板の前の大統領","l":"middle-east-mandates","x":"1928年、トルコでは、わずか数か月のうちに、文字がすっかり変えられた。それまでトルコ語は、アラビア文字で書かれていた。しかし、アラビア文字は、母音の多いトルコ語を書き表すのに向い"},{"id":"middle-east-mandates-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"東京のモスク","l":"middle-east-mandates","x":"1938年5月、東京の代々木上原に、日本で最初の本格的なモスクの一つ、「東京回教礼拝堂」（東京ジャーミイ）が完成した。このモスクを建てたのは、ロシア革命の後に、シベリアや満州を経て"},{"id":"migration-century-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"マリア・ルス号事件","l":"migration-century","x":"1872年7月、ペルーの帆船マリア・ルス号が、修理のために横浜港に入った。船には、マカオからペルーへ送られる230人ほどの中国人の苦力が乗せられていた。ある夜、虐待に耐えかねた一人"},{"id":"migration-century-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「疲れた人々を、貧しい人々を、私に与えよ」――自由の女神の詩","l":"migration-century","x":"1886年、フランスから贈られた「自由の女神像」が、ニューヨーク港の入口に完成した。その台座に、のちの1903年、ユダヤ系アメリカ人の詩人エマ・ラザラスの詩「新しい巨像」を刻んだ銘"},{"id":"migration-century-t3","k":"source","f":"src","kj":"史料｜記録","t":"「中国人労働者の来航は、この国の秩序を危うくする」――中国人排斥法","l":"migration-century","x":"1882年5月、アメリカ議会は、中国人の労働者の入国を10年間禁止する法律を定めた。アメリカの歴史上、特定の民族の移民を、名指しで禁止した最初の法律である。その前文は、こう述べてい"},{"id":"migration-century-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"「からゆきさん」","l":"migration-century","x":"明治から大正にかけて、九州の天草や島原などの貧しい農村や漁村から、多くの若い女性たちが、東南アジアや中国、シベリアなどへ渡った。その多くは、だまされたり、親に売られたりして、売春を"},{"id":"migration-century-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"migration-century","x":"映画『ゴッドファーザー PART II』（フランシス・フォード・コッポラ監督、1974年）：シチリアから一人でニューヨークに渡った少年ヴィトーが、エリス島の入国管理所を通る場面から"},{"id":"ming-founding-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"名前入りのれんが","l":"ming-founding","x":"南京の城壁には、数億個ともいわれる大量のれんがが使われた。れんがは、長江の流域の各地の役所に割り当てて焼かせ、南京に運ばせた。そのれんがの一つ一つには、焼いた地方の役所の名前、責任"},{"id":"ming-founding-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"江戸の寺子屋で学ばれた六諭","l":"ming-founding","x":"六諭は、清の時代にも受け継がれ、その意味をやさしく解説した『六諭衍義』という本がつくられた。18世紀の初め、琉球の学者程順則が、中国からこの本を持ち帰った。それが薩摩藩を通じて、8"},{"id":"ming-founding-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「文字の獄」はあったのか","l":"ming-founding","x":"洪武帝については、こんな話がよく知られている。役人たちが皇帝をたたえるために書いた文章の中に、「光」「禿」「僧」などの字があると、洪武帝は、自分が昔、僧であったことを皮肉っていると"},{"id":"mongol-baghdad-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"図書館を調べた歴史家ジュワイニー","l":"mongol-baghdad","x":"アラムートの城には、ニザール派が長年かけて集めた、有名な図書館があった。フレグは、そこを部下の書記アターマリク・ジュワイニーに調べさせた。ジュワイニーは、モンゴル帝国の歴史『世界征"},{"id":"mongol-baghdad-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「母が私を産まなければよかったのに」――イブン・アル＝アシールの嘆き","l":"mongol-baghdad","x":"バグダードが陥落する40年近く前の1220年代、モンゴル軍は、中央アジアのホラズム＝シャー朝を滅ぼし、イランの諸都市を次々と破壊していた。イラク北部のモスルに住んでいた歴史家イブン"},{"id":"mongol-baghdad-t3","k":"source","f":"src","kj":"史料｜記録","t":"占星術師の警告と、トゥースィーの答え","l":"mongol-baghdad","x":"ラシード＝アッディーンは、フレグがバグダードに向かう前の、こんな話を伝えている。フレグに仕えていた占星術師のフサームッディーンは、こう警告した。「カリフの家を攻めて、その都に兵を進"},{"id":"mongol-baghdad-t4","k":"war","f":"deep","kj":"深掘り｜戦術","t":"中国から来た攻城技術","l":"mongol-baghdad","x":"モンゴル軍の強さを支えたのは、騎兵だけではなかった。中国の金や西夏との戦いで、モンゴル軍は、中国の攻城の技術を身につけた。そして、それを扱う技術者たちを、軍の一部として組み込んだ。"},{"id":"mongol-baghdad-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"町はどれだけ破壊されたのか","l":"mongol-baghdad","x":"バグダードの略奪は、約1週間続いた。死者の数は、のちのイスラームの歴史家たちの記録では80万人から200万人、フレグ自身がフランス王ルイ9世にあてた手紙では20万人以上とされる。い"},{"id":"mongol-baghdad-t6","k":"person","f":"deep","kj":"深掘り｜人物","t":"キリスト教徒の王妃ドクズ・ハトゥン","l":"mongol-baghdad","x":"バグダードの略奪のとき、キリスト教徒たちは教会に集められて守られ、命を助けられた。その背後にいたのが、フレグの第一の妃ドクズ・ハトゥンである。ドクズ・ハトゥンは、モンゴル高原の有力"},{"id":"mongol-baghdad-t7","k":"source","f":"src","kj":"史料｜記録","t":"「モンゴルの剣で、モンゴルが殺される」","l":"mongol-baghdad","x":"フレグがシリアから引き返したのには、もう一つの理由があった。北のジョチ＝ウルスのハン、ベルケとの対立である。ベルケは、バトゥの弟で、モンゴルの王族の中で早くからイスラームに改宗した"},{"id":"mongol-baghdad-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"トゥースィーの天文台","l":"mongol-baghdad","x":"1259年、フレグは、学者ナスィールッディーン・トゥースィーのために、マラーガの丘の上に大きな天文台を建てさせた。フレグは、自分の運命を占うために、正確な星の観測を求めたのである。"},{"id":"mongol-japan-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"国書は脅しだったのか","l":"mongol-japan","x":"この国書は、日本では長い間、武力をちらつかせて服従を迫る、無礼な脅迫状として理解されてきた。たしかに、最後の「兵を用いるに至るは、それ誰か好む所ぞ」という言葉は、従わなければ攻める"},{"id":"mongol-japan-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「手をとをして船に結い付け」――対馬・壱岐の人々","l":"mongol-japan","x":"1274年10月、モンゴル（元）と高麗の軍は、博多に向かう前に、対馬と壱岐を襲った。対馬の守護代宗助国は、わずかな手勢で戦って討ち死にした。島の人々の運命について、日蓮は、伝え聞い"},{"id":"mongol-japan-t3","k":"source","f":"src","kj":"史料｜記録","t":"竹崎季長と『蒙古襲来絵詞』","l":"mongol-japan","x":"文永の役で、鳥飼潟に真っ先に駆け込んだ竹崎季長は、肥後（熊本県）の御家人である。一族の中で所領争いに敗れて、土地をほとんど持たない「無足の御家人」であった季長は、手柄を立てて恩賞を"},{"id":"mongol-japan-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"絵巻に描き加えられた兵士たち","l":"mongol-japan","x":"『蒙古襲来絵詞』の中で最も有名な、てつはうが炸裂する場面には、季長に向かって弓を引く3人の元軍の兵士が描かれている。ところが、研究者たちが絵を詳しく調べたところ、この3人の兵士は、"},{"id":"mongol-japan-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"文永の役の撤退をめぐる諸説","l":"mongol-japan","x":"嵐で壊滅した説 かつては、元軍の船団は、博多湾の中で一夜の大嵐にあって壊滅した、と説明されることが多かった。しかし、旧暦の10月20日は、現在の暦では11月の終わりにあたり、台風の"},{"id":"mongol-japan-t6","k":"person","f":"deep","kj":"深掘り｜人物","t":"「莫煩悩」――時宗と無学祖元","l":"mongol-japan","x":"北条時宗は、禅宗に深く帰依していた。1279年、時宗は、南宋から高僧無学祖元を鎌倉に招いた。無学祖元は、かつて南宋の温州の寺で元軍の兵士に取り囲まれ、首に刀を突きつけられたとき、静"},{"id":"mongol-japan-t7","k":"now","f":"now","kj":"いま","t":"海の底の元軍の船","l":"mongol-japan","x":"長崎県松浦市の鷹島の沖の海底からは、1980年代以降、元軍の船の残骸や、てつはう、刀剣、陶磁器、銅銭、パクパ文字が刻まれた印などが、次々に見つかってきた。2011年には、竜骨（船底"},{"id":"mongol-japan-t8","k":"now","f":"now","kj":"いま","t":"新安沖の沈没船","l":"mongol-japan","x":"1975年、韓国の南西部、全羅南道の新安郡の沖で、漁師の網に中国の陶磁器が引っかかった。調査の結果、海の底から、14世紀の大型の貿易船の残骸が見つかった。船の中からは、中国の陶磁器"},{"id":"mongol-japan-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"mongol-japan","x":"たかぎ七彦『アンゴルモア 元寇合戦記』（漫画、2015年〜、アニメ2018年）：文永の役の対馬を舞台に、流刑の武士たちがモンゴル・高麗の大軍と戦う物語。ゲーム『Ghost of T"},{"id":"mongol-rise-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"遊牧は「さまよう」ことではない","l":"mongol-rise","x":"遊牧民というと、あてもなく草原をさまよう人々を想像しがちだが、実際は違う。夏営地・冬営地などの宿営地はおおむね決まっていて、毎年ほぼ同じ経路を回る。冬営地は風を避けられる山の南斜面"},{"id":"mongol-rise-t2","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"遊牧民は何を食べていたか","l":"mongol-rise","x":"主食は肉と乳である。南宋の使節の報告書『黒韃事略』には「其の食は肉にして粒（穀物）にあらず」とあり、狩りで得たウサギ・シカ・野生のヒツジのほか、家畜では羊を常食とし、馬は大きな宴会"},{"id":"mongol-rise-t3","k":"source","f":"src","kj":"史料｜記録","t":"『元朝秘史』とはどんな本か","l":"mongol-rise","x":"『元朝秘史』は、チンギス＝カンの祖先の伝説からオゴデイの治世までを描いた、モンゴル人自身による最古の歴史書である。もとはウイグル文字のモンゴル語で書かれたが、その原本は残っていない"},{"id":"mongol-rise-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"テムジンは犬が苦手だった？","l":"mongol-rise","x":"秘史には、父イェスゲイがテムジンを婚家に預ける際、「この子は犬を怖がるから、犬に驚かさないでやってくれ」と頼んだという一節がある（§66）伝承。遊牧民の宿営地には番犬がいて、見知ら"},{"id":"mongol-rise-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"ジェルメとジェベ――二人の部下の逸話","l":"mongol-rise","x":"秘史には、テムジンと部下の結びつきを示す有名な場面がいくつもある。タイチウト氏との戦いで、テムジンは首に矢を受けて倒れた。部下のジェルメは一晩中その傷口から血を吸い出し、さらに「喉"},{"id":"mongol-rise-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"ナイマンの金印とウイグル文字","l":"mongol-rise","x":"ナイマン部を破ったとき、モンゴル軍は印章を大事そうに抱えて逃げる男を捕らえた。ウイグル人の書記タタトゥンガ（塔塔統阿）である。問いただすと、これは王の命令を伝えるときに押す印で、文"},{"id":"mongol-rise-t7","k":"confuse","f":"confuse","kj":"混同注意","t":"「ハン」「カン」「ハーン」の違い","l":"mongol-rise","x":"教科書でも「チンギス＝ハン」「チンギス＝カン」と表記が揺れている。もとのモンゴル語の称号はカン（qan）で、のちにこれを日本語では「ハン」と書くことが多かった。最近の山川の教科書は"},{"id":"mongol-rise-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"「長いひげの男」耶律楚材","l":"mongol-rise","x":"耶律楚材は遼の王族の子孫で、金に仕えていた。チンギスは「遼を滅ぼした金は、お前の一族の仇だろう」と声をかけて召し抱えた。楚材が「私の父祖は金に仕えておりました。どうして主君を仇と思"},{"id":"mongol-rise-t9","k":"debate","f":"think","kj":"考える｜諸説あり","t":"事件の責任は誰にあったのか","l":"mongol-rise","x":"オトラル事件の責任がどこにあったかは、史料によって書き方が違う。ホラズム側の書記官だったナサウィーは、総督イナルチュクの欲に原因を求めているが、スルタンのムハンマド2世が事件を黙認"},{"id":"mongol-rise-t10","k":"voice","f":"src","kj":"史料｜証言","t":"征服された側の声――イブン＝アル＝アシールの嘆き","l":"mongol-rise","x":"モンゴルの侵攻を同時代に記録したアラブの歴史家イブン＝アル＝アシールは、この出来事を書き始める前に、こう記している。原文لقد بقيت عدة سنين معرضاً عن ذك"},{"id":"mongol-rise-t11","k":"voice","f":"src","kj":"史料｜証言","t":"「我は神の罰である」――ブハラの演説","l":"mongol-rise","x":"ペルシアの歴史家ジュワイニーは、ブハラに入城したチンギスが、町の有力者たちを集めて「お前たちは大きな罪を犯した。もしそうでなければ、神が私のような罰をお前たちの上に下すはずがない」"},{"id":"mongol-rise-t12","k":"war","f":"deep","kj":"深掘り｜戦術","t":"偽装退却――逃げると見せて誘い込む","l":"mongol-rise","x":"カルカ河畔の戦いは、モンゴル軍が得意とした「偽装退却」の典型例として知られる。ルーシとキプチャクの連合軍が迫ると、モンゴル軍は戦わずに後退を始めた。連合軍はこれを敗走と考え、9日間"},{"id":"mongol-rise-t13","k":"voice","f":"src","kj":"史料｜証言","t":"「どこから来て、どこへ消えたのか」――ノヴゴロド年代記","l":"mongol-rise","x":"ノヴゴロド第一年代記は、1224年（実際は1223年）の項にこう記している。「この年、我らの罪のために、見知らぬ民がやって来た。彼らが何者で、どんな言葉を話し、どんな種族で、どんな"},{"id":"mongol-rise-t14","k":"source","f":"src","kj":"史料｜記録","t":"プラノ・カルピニが見たモンゴル兵の装備","l":"mongol-rise","x":"1245年、ローマ教皇の使節としてモンゴルを訪れた修道士プラノ・カルピニは、報告書にモンゴル軍の装備や戦い方を細かく書き残した。モンゴルの再来に備えるため、敵を知ろうとしたのである"},{"id":"mongol-rise-t15","k":"trivia","f":"side","kj":"こぼれ話","t":"巻狩りは軍事演習だった","l":"mongol-rise","x":"モンゴルでは冬になると、大規模な巻狩り（ネルゲ）が行われた。数千の騎兵が広い範囲に輪を作り、何日もかけて輪を少しずつ縮めて、獲物を中央に追い込む。合図に従って隊列を保ち、勝手に獲物"},{"id":"mongol-rise-t16","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「マングダイ」「絹の肌着」――広まっている俗説","l":"mongol-rise","x":"モンゴル軍の偽装退却を「マングダイ」という戦術名で紹介する本やサイトがあるが、これは当時の用語ではない。マングトは秘史に出てくる部族の名前で、戦術名としての用法はおもに近年の歴史ゲ"},{"id":"mongol-rise-t17","k":"debate","f":"think","kj":"考える｜諸説あり","t":"気候がモンゴルを後押しした？","l":"mongol-rise","x":"2014年、樹木の年輪を調べた研究チームが、興味深い説を発表した。モンゴル高原では1180年代に厳しい干ばつが続いたが、1211年から1225年にかけては、過去千年あまりで例を見な"},{"id":"mongol-rise-t18","k":"now","f":"now","kj":"いま","t":"現代から見たチンギス＝カン","l":"mongol-rise","x":"チンギス＝カンの評価は、立場によって大きく違う。モンゴル国では「建国の父」として敬われ、首都の空港や紙幣にもその名や肖像が使われている。ただ、ソ連の影響下にあった時代には、民族主義"},{"id":"mongol-rise-t19","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「1600万人がチンギスの子孫」説","l":"mongol-rise","x":"2003年、ある遺伝学の研究が話題になった。アジアの広い範囲で、男性の約8パーセント、世界の男性の約0.5パーセントが同じY染色体の型を持ち、その起源は約1000年前のモンゴル高原"},{"id":"mongol-rise-t20","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"mongol-rise","x":"井上靖『蒼き狼』（小説、1960年）：『元朝秘史』などをもとに、テムジンがチンギス＝カンとなるまでの生涯を描いた歴史小説。映画『モンゴル』（セルゲイ・ボドロフ監督、2007年）：浅"},{"id":"mongol-west-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「地獄から来た者たち」――マシュー・パリスの記録","l":"mongol-west","x":"マシュー・パリスは、1240年の項に、モンゴルの襲来をこう書いている。「この年、人々の喜びが長く続かぬように……サタンの忌まわしき民、すなわちタルタル人の数えきれぬ軍勢が、山に囲ま"},{"id":"mongol-west-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"「ひげの生えた婆さん」――宴席の大げんか","l":"mongol-west","x":"長子たちの遠征は、決して一枚岩ではなかった。『元朝秘史』によれば、遠征の途中の宴で、バトゥが年長者として先に杯を飲んだことに、グユクとブリが激しく怒った。ブリは「ひげの生えた婆さん"},{"id":"mongol-west-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"勇士コロヴラトと、塔から身を投げた公妃","l":"mongol-west","x":"『リャザン滅亡の物語』には、心を打つ二つの話が語られている。一つは、リャザンの公子フョードルの妻、エウプラクシアの話である。バトゥは、和平を求めて来たフョードルに「お前の妻の美しさ"},{"id":"mongol-west-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"敵将をたたえたバトゥ","l":"mongol-west","x":"キエフの守将ドミトルは、深い傷を負って捕らえられた。しかしバトゥは、その勇敢さに感心して、彼を殺さずに手元に置いたと年代記は伝えている。その後、ドミトルは、バトゥにこう勧めたという"},{"id":"mongol-west-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"途切れるラッパの音","l":"mongol-west","x":"ポーランドの古都クラクフでは、毎正時になると、聖マリア教会の塔の上からラッパの曲（ヘイナウ）が演奏される。この曲は、なぜか途中で、ぷつりと途切れて終わる。画像はオンライン時に表示さ"},{"id":"mongol-west-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"「ワールシュタット」とは何か","l":"mongol-west","x":"日本の教科書では、この戦いを「ワールシュタットの戦い」と呼ぶことが多い。ワールシュタット（Wahlstatt）は、戦場の近くの村のドイツ語の名前で、「戦場」「死者の野」を意味する古"},{"id":"mongol-west-t7","k":"voice","f":"src","kj":"史料｜証言","t":"「家に住むお前が、どうして逃げられよう」","l":"mongol-west","x":"ユリアヌスの報告に記された、ハンガリー王への手紙は、次のようなものであった。「我はハンである。天の王の使者であり、天の王は我に、我に従う者を高め、我に逆らう者を打ち倒す力を与えた。"},{"id":"mongol-west-t8","k":"war","f":"deep","kj":"深掘り｜戦術","t":"わざと開けておいた逃げ道","l":"mongol-west","x":"モンゴル軍は、敵を完全に包囲せず、わざと逃げ道を一つ開けておくことがあった。中国の兵法書『孫子』にも「囲師には必ず闕く（包囲する時は必ず一方を開けておけ）」という言葉がある。完全に"},{"id":"mongol-west-t9","k":"now","f":"now","kj":"いま","t":"「第二の建国者」ベーラ4世","l":"mongol-west","x":"モンゴル軍が去った後、ハンガリーに戻ったベーラ4世は、国の立て直しに全力を注いだ。モンゴルの騎兵の前では、平原の村々も、土や木の砦も、まったく役に立たなかった。しかし、石造りの城や"},{"id":"mongol-west-t10","k":"debate","f":"think","kj":"考える｜諸説あり","t":"撤退の理由をめぐる諸説","l":"mongol-west","x":"1. オゴデイの死最もよく知られているのは、1241年12月にカアンのオゴデイが亡くなり、その知らせを受けたバトゥが、次のカアンを選ぶクリルタイに備えて引き返した、という説である。"},{"id":"mongol-west-t11","k":"source","f":"src","kj":"史料｜記録","t":"「地獄へ押し返すか、天国へ送られるか」","l":"mongol-west","x":"モンゴル軍の西進の知らせは、フランスの宮廷にも届いた。マシュー・パリスによれば、フランス王ルイ9世の母ブランシュが「タルタル人が来たら、私たちはどうなるのでしょう」と泣いて嘆いたと"},{"id":"mongol-west-t12","k":"source","f":"src","kj":"史料｜記録","t":"「日の出る所から日の沈む所まで」","l":"mongol-west","x":"1920年、ヴァチカンの文書館で、一通の古い手紙が見つかった。それは、グユクがカルピニに託して教皇インノケンティウス4世に送った手紙の原本であった。手紙はペルシア語で書かれ、モンゴ"},{"id":"mughal-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"命を引き換えにした父","l":"mughal","x":"バーブルの死については、感動的な伝説が残されている。1530年、バーブルの最愛の息子フマーユーンが、重い病にかかった。医者たちも、もう助からないと言った。そのとき、バーブルは、病床"},{"id":"mughal-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"ペルシア語に訳された『マハーバーラタ』","l":"mughal","x":"アクバルの宮廷では、ヒンドゥー教の聖典や叙事詩が、宮廷の言葉であるペルシア語に翻訳された。インドの大叙事詩『マハーバーラタ』も翻訳され、『ラズム・ナーマ（戦いの書）』と名づけられて"},{"id":"mughal-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「黒いタージ」の伝説","l":"mughal","x":"タージ・マハルの対岸、ヤムナー川の向こう岸には、もう一つの霊廟が建てられる予定だった――という伝説がある。シャー・ジャハーンは、自分自身のために、黒い大理石で、白いタージ・マハルと"},{"id":"mughal-t4","k":"source","f":"src","kj":"史料｜記録","t":"「もし地上に楽園があるならば」――デリー城の碑文","l":"mughal","x":"1648年、ムガル皇帝シャー・ジャハーンは、デリーに、赤い砂岩の巨大な城（ラール・キラー）を完成させた。その中の、白大理石の謁見の間（ディーワーネ・ハース）の壁には、ペルシア語で、"},{"id":"mughal-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"果物かごで逃げたシヴァージー","l":"mughal","x":"マラーター王国の建国者シヴァージーは、ムガル帝国に対するゲリラ戦の名手であった。山の上の砦を拠点に、すばやく出撃し、ムガル帝国の軍を悩ませた。1666年、シヴァージーは、和平の交渉"},{"id":"mughal-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"mughal","x":"映画『ジョーダー・アクバル』（アシュトーシュ・ゴーワリケール監督、2008年、インド）：ムガル皇帝アクバルと、ヒンドゥー教徒のラージプートの王女ジョーダーの結婚を描いた歴史ロマン。"},{"id":"muhammad-t1","k":"term","f":"deep","kj":"深掘り｜ことば","t":"「イスラーム」「ムスリム」「アッラー」","l":"muhammad","x":"「イスラーム」は、アラビア語で「（神に）身をゆだねること、服従すること」を意味する。イスラーム教を信じる人々を「ムスリム」（身をゆだねた者）と呼ぶ。日本では「イスラム教」「回教」と"},{"id":"muhammad-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"なぜムハンマドの肖像はないのか","l":"muhammad","x":"この講義では、ムハンマドの肖像画を掲載していない。イスラーム教では、偶像崇拝につながることを避けるため、預言者ムハンマドの姿を描くことは、一般にきびしく戒められているからである。た"},{"id":"muhammad-t3","k":"source","f":"src","kj":"史料｜記録","t":"最古のアラビア語の碑文","l":"muhammad","x":"シリア南部のナマーラで、1901年に、1枚の石の墓碑が発見された。そこには、次のように刻まれていた。これは、すべてのアラブの王、アムルの子のイムルウルカイスの墓碑である。……彼はシ"},{"id":"muhammad-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"カーバ神殿に掛けられた詩","l":"muhammad","x":"6世紀のアラブの代表的な詩人たちの長い詩を集めたものが、『ムアッラカート』である。「ムアッラカート」とは「掛けられたもの」という意味で、ウカーズの市で優勝した詩が、金の文字で布に書"},{"id":"muhammad-t5","k":"source","f":"src","kj":"史料｜記録","t":"『クルアーン』第106章「クライシュ族」","l":"muhammad","x":"原文لِإِيلَافِ قُرَيْشٍإِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِفَلْيَعْبُدُوا رَبَّ هَٰذ"},{"id":"muhammad-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"メッカは国際商業の中心だったのか","l":"muhammad","x":"「メッカは、東西の国際交易の中継地として栄え、富の集中によって貧富の差が拡大し、部族の伝統的な絆が崩れた。その社会の矛盾の中から、イスラーム教が生まれた」――このような説明は、20"},{"id":"muhammad-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"黒石をめぐる争いと1枚の布","l":"muhammad","x":"605年ごろ、メッカのカーバ神殿は、洪水で傷んだため、建て直されることになった。工事が進み、神聖な黒石を壁にはめこむ段になって、クライシュ族の諸家の間で、誰がその名誉ある役を担うか"},{"id":"muhammad-t8","k":"person","f":"deep","kj":"深掘り｜人物","t":"ビラール――「唯一の神！唯一の神！」","l":"muhammad","x":"初期の信者の中には、奴隷や貧しい人々が多かった。アビシニア（エチオピア）出身の黒人の奴隷ビラールも、その一人であった。ビラールの主人は、彼をイスラームから離れさせようとして、真昼の"},{"id":"muhammad-t9","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"夜の旅と昇天","l":"muhammad","x":"イスラームの伝承によれば、620年ごろのある夜、ムハンマドは、天使ジブリールに導かれ、ブラークと呼ばれる翼を持つ不思議な獣に乗って、メッカからエルサレムの神殿の丘へと一夜のうちに旅"},{"id":"muhammad-t10","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"洞窟の入口のクモの巣","l":"muhammad","x":"伝承によれば、ムハンマドとアブー＝バクルが隠れていたサウル山の洞窟の前まで、追っ手がやってきた。ところが、洞窟の入口には、クモが巣を張り、ハトが巣をつくって卵を産んでいた。それを見"},{"id":"muhammad-t11","k":"source","f":"src","kj":"史料｜記録","t":"メディナ憲章","l":"muhammad","x":"メディナ憲章は、ムハンマドとメディナの諸部族の間で結ばれた取り決めで、イブン・イスハークの『預言者伝』にその内容が伝えられている。原文إِنَّهُمْ أُمَّةٌ وَاحِ"},{"id":"muhammad-t12","k":"source","f":"src","kj":"史料｜記録","t":"『クルアーン』が語るバドルの戦い","l":"muhammad","x":"『クルアーン』第8章「戦利品」は、バドルの戦いを、次のように振り返っている。原文إِذْ أَنْتُمْ بِالْعُدْوَةِ الدُّنْيَا وَهُمْ بِال"},{"id":"muhammad-t13","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"皇帝たちへの手紙","l":"muhammad","x":"イスラームの伝承によれば、フダイビーヤの和約の後、ムハンマドは、周辺の国々の支配者たちに、イスラームへの改宗を呼びかける手紙を送った。ビザンツ皇帝ヘラクレイオス、ササン朝の王ホスロ"},{"id":"muhammad-t14","k":"source","f":"src","kj":"史料｜記録","t":"別離の説教","l":"muhammad","x":"伝承によれば、ムハンマドは、別離の巡礼の際に、次のように説いたという。原文يَا أَيُّهَا النَّاسُ، أَلَا إِنَّ رَبَّكُمْ وَاحِدٌ،"},{"id":"muhammad-t15","k":"trivia","f":"side","kj":"こぼれ話","t":"最古の『クルアーン』写本","l":"muhammad","x":"2015年、イギリスのバーミンガム大学は、図書館が所蔵していた『クルアーン』の写本の2枚の羊皮紙について、放射性炭素による年代測定の結果、95％以上の確率で568年から645年の間"},{"id":"muhammad-t16","k":"now","f":"now","kj":"いま","t":"現代の巡礼と二つの聖地","l":"muhammad","x":"現在、メッカとメディナは、サウジアラビアの領内にあり、ムスリムでない者が立ち入ることは禁じられている。毎年、ヒジュラ暦の第12月（巡礼月）には、世界中から約200万人のムスリムが、"},{"id":"muhammad-t17","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"muhammad","x":"映画『ザ・メッセージ』（1976年、ムスタファ・アッカド監督）：ムハンマドの生涯を描いた映画。イスラーム教の教えに従い、ムハンマド本人の姿や声は一度も画面に登場せず、カメラがムハン"},{"id":"napoleon-empire-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「ネルソンの血」","l":"napoleon-empire","x":"ネルソンの遺体は、イギリス本国まで運ぶために、ブランデーの樽に漬けて保存された（ラム酒であったという説もある）。のちに、水兵たちが樽にこっそり穴を開けて、中の酒を飲んでしまったとい"},{"id":"napoleon-empire-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"書店主パルムの処刑","l":"napoleon-empire","x":"1806年の夏、ドイツで、『どん底に落ちたドイツ』という匿名の小冊子が出回った。フランス軍の占領と横暴を非難する内容であった。ナポレオンは激怒し、作者を突き止めるよう命じた。作者は"},{"id":"napoleon-empire-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"大陸封鎖が生んだもの――テンサイの砂糖","l":"napoleon-empire","x":"大陸封鎖で、カリブ海の植民地から運ばれていた砂糖やコーヒーが、ヨーロッパ大陸に入らなくなった。砂糖の値段は高騰した。そこで、ナポレオンが力を入れたのが、テンサイ（砂糖大根）から砂糖"},{"id":"napoleon-empire-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"ゲーテとナポレオン","l":"napoleon-empire","x":"1808年、ナポレオンは、ドイツのエアフルトで、ロシア皇帝アレクサンドル1世と再び会談した。この時、ナポレオンは、ドイツの文豪ゲーテを招いて会見した。59歳のゲーテを迎えたナポレオ"},{"id":"napoleon-empire-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"捕らわれた教皇","l":"napoleon-empire","x":"1801年に宗教協約を結んでナポレオンと和解し、1804年の戴冠式にも出席した教皇ピウス7世は、やがて、ナポレオンとの対立を深めていった。教皇が大陸封鎖への協力を拒むと、ナポレオン"},{"id":"napoleon-empire-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"napoleon-empire","x":"ゴヤ『1808年5月3日』（絵画、1814年）：ナポレオンの軍に抵抗したマドリードの市民が、フランス兵に銃殺される場面を描いた絵。映画『ナポレオン』（リドリー・スコット監督、202"},{"id":"napoleon-fall-t1","k":"music","f":"music","kj":"音楽","t":"大砲が鳴る序曲――チャイコフスキー『1812年』","l":"napoleon-fall","x":"1880年、ロシアの作曲家チャイコフスキーは、ナポレオンに対する勝利を記念するモスクワの救世主キリスト大聖堂の完成に合わせて、祝典序曲『1812年』を作曲した。曲の中では、フランス"},{"id":"napoleon-fall-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「冬将軍」がナポレオンを破ったのか","l":"napoleon-fall","x":"ナポレオンのロシア遠征の失敗は、しばしば「冬将軍」、つまりロシアの厳しい冬のせいだとされる。ナポレオン自身も、のちに、敗北の原因を寒さに帰した。しかし、大陸軍の兵力は、冬が来る前の"},{"id":"napoleon-fall-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「皇帝陛下のご健康は、これほどよかったことはない」――ベレジナの後で","l":"napoleon-fall","x":"1812年11月末、ロシアから退却する大陸軍は、ベレジナ川で追いつかれた。工兵たちは、氷の浮かぶ川に胸まで浸かって橋を架け、その多くが凍えて死んだ。橋に殺到した兵士と避難民の群れは"},{"id":"napoleon-fall-t4","k":"now","f":"now","kj":"いま","t":"祖国戦争の記憶","l":"napoleon-fall","x":"ロシアでは、1812年の戦争は、「祖国戦争」と呼ばれる。ナポレオンを退けた勝利は、ロシアの人々の誇りとなった。モスクワには、勝利を神に感謝するため、救世主ハリストス大聖堂が建てられ"},{"id":"napoleon-fall-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"鉄十字章と黒・赤・金の旗","l":"napoleon-fall","x":"1813年3月10日、プロイセン国王は、身分を問わず、勇敢な兵士に与える新しい勲章を定めた。建築家シンケルがデザインした「鉄十字章」である。この日は、亡き王妃ルイーゼの誕生日であっ"},{"id":"napoleon-fall-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"新聞の見出しの変化","l":"napoleon-fall","x":"ナポレオンのパリへの帰還について、こんな話が伝えられている。パリの新聞は、毎日、ナポレオンの進軍を報じたが、その見出しが、日ごとに変わっていったというのである。「食人鬼が、隠れ家を"},{"id":"napoleon-fall-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「近衛軍は死す、されど降伏せず」","l":"napoleon-fall","x":"ワーテルローの戦いの最後に、敗走するフランス軍の中で、近衛軍の一部隊が、方陣を組んで踏みとどまった。指揮官のカンブロンヌ将軍は、イギリス軍に降伏を勧められると、「近衛軍は死す、され"},{"id":"napoleon-fall-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ナポレオンは毒殺されたのか","l":"napoleon-fall","x":"ナポレオンの死因は、解剖の結果、胃癌とされた。彼の父も、胃の病気で亡くなっている。しかし、1960年代、スウェーデンの歯科医フォースフヴッドが、ナポレオンの遺髪から高い濃度のヒ素が"},{"id":"napoleon-fall-t9","k":"debate","f":"think","kj":"考える｜諸説あり","t":"英雄か、暴君か","l":"napoleon-fall","x":"ナポレオンの評価は、200年たった今も、大きく分かれている。ある人々にとって、彼は、フランス革命の成果を守り、近代的な法と行政をヨーロッパに広めた天才的な英雄である。別の人々にとっ"},{"id":"napoleon-fall-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"napoleon-fall","x":"トルストイ『戦争と平和』（小説、1865〜1869年）：ナポレオンのロシア遠征の時代を舞台に、ロシアの貴族たちの運命を描いた大長編。歴史を動かすのは英雄ではなく、無数の人々の意志の"},{"id":"napoleon-iii-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"動物園の象を食べたクリスマス","l":"napoleon-iii","x":"包囲されたパリでは、食糧が日に日に乏しくなった。馬、犬、猫、そしてネズミまでが、食卓に上った。肉屋の店先には、ネズミが並んで売られたという。ついには、パリ植物園の動物園の動物たちも"},{"id":"napoleon-iii-t2","k":"now","f":"now","kj":"いま","t":"「さくらんぼの実る頃」","l":"napoleon-iii","x":"「さくらんぼの実る頃」というフランスのシャンソンがある。恋の喜びと失恋の痛みを歌った、甘く切ない歌である。作詞者のクレマンは、パリ・コミューンに加わった活動家であった。歌そのものは"},{"id":"napoleon-iii-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"ドレフュス事件とシオニズム","l":"napoleon-iii","x":"1895年1月、パリの陸軍士官学校の中庭で、有罪となったドレフュスの軍籍剥奪の儀式が行われた。将校の肩章や記章をはぎ取られ、剣を折られるドレフュスに向かって、群衆は「ユダヤ人に死を"},{"id":"napoleon-iii-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"嫌われたエッフェル塔","l":"napoleon-iii","x":"1889年、フランス革命の100周年を記念して、パリで万国博覧会が開かれた。その目玉として建てられたのが、高さ300mの鉄の塔、エッフェル塔であった。建設の最中、作家のモーパッサン"},{"id":"napoleon-iii-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"napoleon-iii","x":"オッフェンバック『地獄のオルフェ（天国と地獄）』（オペレッタ、1858年初演）：ギリシア神話をもじって、第二帝政の上流社会を風刺した喜歌劇。劇中の「カンカン」の曲は、運動会の音楽と"},{"id":"napoleon-rise-t1","k":"now","f":"now","kj":"いま","t":"ロゼッタ・ストーン","l":"napoleon-rise","x":"1799年7月、ナイル川の河口の町ロゼッタ（ラシード）で、フランス軍の兵士たちが、要塞の工事中に、文字が刻まれた黒い石の板を掘り出した。石には、同じ内容の文章が、古代エジプトの神聖"},{"id":"napoleon-rise-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"鶏のマレンゴ風","l":"napoleon-rise","x":"フランス料理には、「鶏のマレンゴ風」という料理がある。鶏肉を、トマトやニンニク、オリーブ油、白ワインなどで煮込んだものである。マレンゴの戦いの夜、食料の補給が途絶えた中で、ナポレオ"},{"id":"napoleon-rise-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ナポレオンは小男だったのか","l":"napoleon-rise","x":"ナポレオンは、背が低かったというイメージが広く知られている。「ナポレオン・コンプレックス」という言葉まである。しかし、ナポレオンの身長は、約169cmで、当時のフランス人の男性とし"},{"id":"napoleon-rise-t4","k":"music","f":"music","kj":"音楽","t":"「出陣の歌」――帝国のもう一つの国歌","l":"napoleon-rise","x":"1794年、作曲家メユールが、革命戦争の兵士たちのためにつくった「出陣の歌」は、ナポレオンの時代に、「ラ・マルセイエーズ」に代わる帝国の公式の歌として、さかんに演奏された。革命の熱"},{"id":"napoleon-rise-t5","k":"music","f":"music","kj":"音楽","t":"破られた献辞","l":"napoleon-rise","x":"ドイツの作曲家ベートーヴェンは、フランス革命の理念を体現する英雄として、ナポレオンを尊敬していた。1804年、彼は、新しい交響曲を書き上げ、その表紙に、「ボナパルト」と記した。しか"},{"id":"napoleon-rise-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"napoleon-rise","x":"ベートーヴェン『交響曲第3番「英雄」』（1804年）：ナポレオンにささげるつもりで作曲されたが、ナポレオンが皇帝になったことを知ったベートーヴェンが、怒って献辞を消したという話が伝"},{"id":"neolithic-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"神殿が先か、農耕が先か――ギョベクリ＝テペ","l":"neolithic","x":"トルコ南東部のギョベクリ＝テペ遺跡は、考古学の常識を覆した遺跡として知られる。約1万1600年前（前9600年ごろ）にさかのぼるこの遺跡には、高さ5メートルを超えるT字形の石柱が円"},{"id":"neolithic-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"トウモロコシの祖先は似ても似つかない雑草だった","l":"neolithic","x":"トウモロコシの祖先は、メキシコの「テオシント」という野生の草である。テオシントの穂は親指ほどの大きさしかなく、硬い殻に包まれた実が10個ほどついているだけだった。現在のトウモロコシ"},{"id":"neolithic-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「人類史上最悪の過ち」？","l":"neolithic","x":"アメリカの地理学者ダイアモンドは、農耕の始まりを「人類史上最悪の過ち」と呼んで話題を呼んだ。原文the adoption of agriculture, supposedly ou"},{"id":"neolithic-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"世界最古のパン","l":"neolithic","x":"2018年、ヨルダン北東部の砂漠にあるシュバイカ1という遺跡の炉の跡から、黒く焦げた小さなかけらが24個見つかった。顕微鏡で調べると、それは野生の大麦やヒトツブコムギ、さらに植物の"},{"id":"neolithic-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"パンよりビールが先？","l":"neolithic","x":"麦を育て始めた理由は、パンを作るためではなく、ビールを作るためだったのではないか――そんな説が、半ば冗談まじりに、しかし真剣に議論されてきた。2018年、イスラエルのラケフェト洞窟"},{"id":"neolithic-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"猫は「勝手に」家畜になった","l":"neolithic","x":"犬が人間の狩りのパートナーとして家畜になったのに対し、猫は少し違う経緯をたどった。農耕が始まり、村に穀物が蓄えられると、それを狙ってネズミが集まる。そのネズミを狙って、野生のヤマネ"},{"id":"neolithic-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"neolithic","x":"ジャレド・ダイアモンド『銃・病原菌・鉄』（1997年、ピュリッツァー賞）：なぜヨーロッパの人々が世界を征服する側になったのかを、農耕の始まった地域の地理や、栽培化・家畜化できる動植"},{"id":"northern-southern-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「子貴ければ母死す」","l":"northern-southern","x":"北魏には、皇太子が決まると、その生母を殺すという、ほかに例のない制度があった。「子貴母死」（子が貴くなれば母は死ぬ）と呼ばれる。道武帝は、長男の拓跋嗣（のちの明元帝）を後継者と定め"},{"id":"northern-southern-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"柔然――「うごめく虫」と呼ばれた遊牧国家","l":"northern-southern","x":"柔然は、4世紀末から6世紀半ばにかけて、モンゴル高原を支配した遊牧国家である。402年ごろ、君主の社崙は「可汗」の称号を名乗った。可汗（カガン）は、のちに突厥やモンゴルの君主も用い"},{"id":"northern-southern-t3","k":"term","f":"deep","kj":"深掘り｜ことば","t":"北魏の均田制","l":"northern-southern","x":"485年に定められた均田制は、隋・唐に受け継がれ、日本の班田収授法の手本にもなった重要な制度である。区分給付される土地返還露田（穀物を作る畑）15歳以上の男子に40畝、女子に20畝"},{"id":"northern-southern-t4","k":"source","f":"src","kj":"史料｜記録","t":"鮮卑語の禁止","l":"northern-southern","x":"孝文帝は、鮮卑語の使用の禁止について、弟の咸陽王禧らに、次のように語ったという。原文今欲斷諸北語，一從正音。年三十以上，習性已久，容或不可卒革。三十以下，見在朝廷之人，語音不聽仍舊"},{"id":"northern-southern-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"漢化政策をどう評価するか","l":"northern-southern","x":"孝文帝の漢化政策については、さまざまな評価がある。積極的な評価：中国の伝統的な歴史家は、孝文帝を、「夷狄」の君主でありながら中華の文化を慕った名君としてたたえてきた。漢化政策によっ"},{"id":"northern-southern-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"永寧寺の九重塔","l":"northern-southern","x":"胡太后が516年に洛陽に建てた永寧寺には、高さ「90丈」（約270m）と記録される、木造の九重の塔がそびえていた。北魏の楊衒之が著した『洛陽伽藍記』は、この塔について、「都から10"},{"id":"northern-southern-t7","k":"source","f":"src","kj":"史料｜記録","t":"勅勒の歌","l":"northern-southern","x":"玉壁の敗戦の後、高歓は、将兵の士気を高めるため、宴会を開いた。その席で、遊牧民の勅勒（高車）出身の老将斛律金に歌を歌わせ、高歓も、これに唱和して涙を流したという。そのとき歌われたと"},{"id":"northern-southern-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"「快刀乱麻を断つ」と蘭陵王","l":"northern-southern","x":"北斉の文宣帝高洋は、若いころ、口数が少なく、兄弟からも愚か者と見られていた。あるとき、父の高歓は、息子たちの才能を試そうと、もつれた糸の束を一人ずつ渡して、ほどくように命じた。他の"},{"id":"northern-southern-t9","k":"source","f":"src","kj":"史料｜記録","t":"倭王武の上表文（478年）","l":"northern-southern","x":"南朝の宋には、東アジアの国々が使者を送った。日本列島の倭国からは、5世紀の約100年間に、讃・珍・済・興・武の5人の王（倭の五王）が使者を送り、宋の皇帝から称号を与えられた。478"},{"id":"northern-southern-t10","k":"voice","f":"src","kj":"史料｜証言","t":"「千里、煙絶ゆ」――侯景の乱","l":"northern-southern","x":"548年、侯景の軍は梁の都建康を包囲した。宮城（台城）の包囲は130日余りに及び、城内では飢えと疫病が広がった。原文初，城中積屍不暇埋瘞，又有已死而未斂，或將死而未絕，景悉聚而燒之"},{"id":"northern-southern-t11","k":"confuse","f":"confuse","kj":"混同注意","t":"北朝と南朝","l":"northern-southern","x":"北朝南朝王朝北魏→東魏・西魏→北斉・北周宋→斉→梁→陳都平城・洛陽（北魏）、鄴（東魏・北斉）、長安（西魏・北周）建康（現在の南京）支配者鮮卑系の皇室と軍人。漢人の名門も官僚として参"},{"id":"northern-southern-t12","k":"works","f":"works","kj":"作品","t":"南北朝にまつわる作品","l":"northern-southern","x":"「木蘭辞（木蘭詩）」（北朝の民歌）：年老いた父に代わって、男装して12年間戦場で戦った娘、木蘭の物語を歌った長編の詩。詩の中で、君主は「可汗」とも「天子」とも呼ばれており、遊牧民と"},{"id":"oil-shock-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"西部劇を押しのけて","l":"oil-shock","x":"ニクソンの演説のために、テレビ局は、日曜の夜の人気の西部劇ドラマ『ボナンザ』の放送を取りやめた。視聴者の反発を心配する声もあったが、ニクソンは、より多くの国民が演説を見るはずだと考"},{"id":"oil-shock-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"アスワン・ハイダムの技術者","l":"oil-shock","x":"エジプト軍が砂の壁を崩すのに使ったのは、なんと、水であった。この方法を思いついたのは、エジプト軍の工兵の将校バーキー・ザキー・ユースフであった。彼は、かつて、ナイル川のアスワン・ハ"},{"id":"oil-shock-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"「アラブ寄り」への転換","l":"oil-shock","x":"日本の政府は、追い詰められた。田中角栄内閣は、1973年11月22日、二階堂進官房長官の談話を発表し、イスラエルに、第3次中東戦争で占領した地域からの撤退を求め、パレスチナの人々の"},{"id":"oil-shock-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「信頼の危機」――カーター大統領の演説","l":"oil-shock","x":"1979年、イラン革命をきっかけに、第2次石油危機が起こった。アメリカでは、ガソリンスタンドの前に何kmもの車の列ができ、物価の上昇と景気の停滞が続いた。7月15日、カーター大統領"},{"id":"oil-shock-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「石器時代が終わったのは、石がなくなったからではない」――ヤマニの予言","l":"oil-shock","x":"1973年の石油危機のとき、サウジアラビアの石油相として、アラブ産油国の「石油戦略」の顔となったのが、アフマド・ザキ・ヤマニであった。のちに石油相を退いたヤマニは、2000年、イギ"},{"id":"oil-shock-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"ゴルフに行くふり","l":"oil-shock","x":"1985年9月22日、ニューヨークのプラザホテルに、アメリカ、日本、西ドイツ、フランス、イギリスの5か国の財務相と中央銀行の総裁が集まった（G5）。高すぎるドルを、各国が協調して引"},{"id":"olmec-chavin-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"メソアメリカとアンデスを比べる","l":"olmec-chavin","x":"メソアメリカアンデス地域メキシコ中部・南部〜中央アメリカ南米のアンデス山脈と太平洋岸（ペルー・ボリビアなど）主な作物トウモロコシ、豆、カボチャ、唐辛子、カカオジャガイモ、トウモロコ"},{"id":"olmec-chavin-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「人頭像はアフリカ人の顔」説","l":"olmec-chavin","x":"オルメカの巨石人頭像の顔立ちから、「古代にアフリカ人が大西洋を渡ってメキシコに来ていた証拠だ」とする説が、1970年代に唱えられ、一部で広まった。俗説この説の始まりは、最初の人頭像"},{"id":"olmec-chavin-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「ゴムの国の人々」と球技","l":"olmec-chavin","x":"「オルメカ」とは、オルメカ人自身の呼び名ではない。のちのアステカ人が、メキシコ湾岸に住む人々を「オルメカトル（ゴムの国の人々）」と呼んだことから、近代の研究者がこの名をつけたのであ"},{"id":"olmec-chavin-t4","k":"debate","f":"think","kj":"考える｜諸説あり","t":"アメリカ大陸最古の文字？","l":"olmec-chavin","x":"2006年、オルメカの中心地サン＝ロレンソの近くで見つかった石板（カスカハル石板）の研究が、アメリカの科学雑誌に発表された。前900年ごろのものとされる石板の表面には、62個の記号"},{"id":"olmec-chavin-t5","k":"now","f":"now","kj":"いま","t":"日本の調査団と「交差した手の神殿」","l":"olmec-chavin","x":"アンデス考古学は、日本の研究者が大きな役割を果たしてきた分野である。1960年、東京大学の泉靖一らの調査団は、ペルー中部の高地のコトシュ遺跡を発掘し、土器が使われる前の時代の神殿の"},{"id":"olmec-chavin-t6","k":"view","f":"think","kj":"考える｜別の視点","t":"「文明」の条件は一つではない","l":"olmec-chavin","x":"教科書では、文明の特徴として、農耕・都市・金属器・文字などが挙げられることが多い。しかし、アメリカ大陸の文明を見ると、この「条件」がそのまま当てはまらないことが分かる。アンデスの文"},{"id":"olmec-chavin-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"縄文土器は南米に渡ったか","l":"olmec-chavin","x":"エクアドルの太平洋岸のバルディビア遺跡からは、前3000年代のものとされる、アメリカ大陸でも最も古い部類の土器が見つかっている。1960年代、アメリカなどの研究者が、この土器の文様"},{"id":"olmec-chavin-t8","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"闇の中で響くほら貝","l":"olmec-chavin","x":"チャビン＝デ＝ワンタルの神殿の地下回廊は、ほとんど光が入らない。回廊には、外から空気や水を通す細い溝が張りめぐらされており、水が流れると、神殿全体がうなるような音を立てたともいわれ"},{"id":"opium-war-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"アヘンの書かれていない条約","l":"opium-war","x":"不思議なことに、アヘン戦争を終わらせた南京条約には、「アヘン」という言葉が一度も出てこない。戦争の原因となったアヘンの貿易をどうするのかは、条約では何も決められなかったのである。清"},{"id":"opium-war-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"『海国図志』を読んだ日本人","l":"opium-war","x":"林則徐は、広州にいた時、外国の新聞や書物を集めて翻訳させ、『四洲志』という世界地理書をまとめた。左遷される時、彼は、その資料を友人の学者魏源に託した。魏源は、これをもとに、1842"},{"id":"opium-war-t3","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"opium-war","x":"映画『阿片戦争』（謝晋監督、1997年、中国）：香港の返還の年に、中国で製作された大作。林則徐のアヘン没収から、南京条約の調印までを描く。作品は史実をもとにした創作を含むことが多い"},{"id":"ottoman-rise-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「トルコ行進曲」の起源","l":"ottoman-rise","x":"イェニチェリには、「メフテル」と呼ばれる軍楽隊がついていた。大太鼓、シンバル、ラッパ、ズルナ（チャルメラのような笛）などで、勇ましい音楽を演奏しながら行進し、味方の士気を高め、敵を"},{"id":"ottoman-rise-t2","k":"source","f":"src","kj":"史料｜記録","t":"征服者と都","l":"ottoman-rise","x":"5月29日の午後、メフメト2世は、白馬に乗って都に入った。彼は、まっすぐハギア・ソフィア大聖堂に向かった。ビザンツの歴史家ドゥーカスによれば、メフメト2世は、聖堂の床の大理石をはが"},{"id":"ottoman-rise-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「血は雨水のように流れた」――陥落の日","l":"ottoman-rise","x":"ヴェネツィアの船医ニコロ・バルバロは、包囲の間、日記をつけ続け、陥落の日に船で町を脱出した。彼は、5月29日の朝の光景をこう記している。オスマン軍の兵士たちは、城壁を越えて町になだ"},{"id":"ottoman-rise-t4","k":"now","f":"now","kj":"いま","t":"1453年は何を変えたのか","l":"ottoman-rise","x":"コンスタンティノープルの陥落は、ヨーロッパに大きな衝撃を与えた。ローマ帝国の最後の生き残りが滅んだのである。この出来事の影響については、さまざまなことがいわれてきた。ビザンツの学者"},{"id":"ottoman-rise-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「スルタン＝カリフ制」の伝説","l":"ottoman-rise","x":"カイロには、マムルーク朝に保護されたアッバース家のカリフの子孫がいた。セリム1世は、このカリフをイスタンブルに連れて帰った。後の時代には、このとき、カリフがセリム1世にカリフの位を"},{"id":"ottoman-rise-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"ottoman-rise","x":"塩野七生『コンスタンティノープルの陥落』（小説、1983年）：1453年のコンスタンティノープルの包囲と陥落を、ビザンツ側、オスマン側、ヴェネツィアやジェノヴァの商人など、さまざま"},{"id":"ottoman-society-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"兄弟殺しの掟","l":"ottoman-society","x":"オスマン帝国には、王位の継承について、厳しい慣行があった。新しいスルタンが即位すると、その兄弟たちは処刑されたのである。後継ぎ争いによる内乱を防ぐためであった。メフメト2世が定めた"},{"id":"ottoman-society-t2","k":"source","f":"src","kj":"史料｜記録","t":"スペインを追われたユダヤ人","l":"ottoman-society","x":"1492年、レコンキスタを完成させたスペインは、国内のユダヤ教徒に、改宗か国外退去かを迫った（→「イベリア半島のイスラーム世界とレコンキスタ」の回）。数万の人々が、故郷を追われた。"},{"id":"ottoman-society-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「トルコでは、地位は能力と功績への報酬である」――ビュスベックの手紙","l":"ottoman-society","x":"16世紀の半ば、神聖ローマ皇帝の大使としてイスタンブルに滞在したフランドル出身の外交官オジエ・ギスラン・ド・ビュスベックは、オスマン帝国の宮廷の様子を、ラテン語の手紙に詳しく書き残"},{"id":"ottoman-society-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"コーヒーハウスの誕生","l":"ottoman-society","x":"1554年、シリアのアレッポとダマスクスから来た二人の商人が、イスタンブルに初めてのコーヒーハウスを開いたといわれる。コーヒーは、もともとイエメンのイスラーム神秘主義者（スーフィー"},{"id":"ottoman-society-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「彼女たちは、実際には、私たちより多くの自由を持っている」――モンタギュー夫人の手紙","l":"ottoman-society","x":"1716年から1718年まで、イギリス大使の妻としてイスタンブルに滞在したメアリー・ウォートリー・モンタギューは、友人たちに書き送った手紙の中で、オスマン帝国の女性たちの暮らしを描"},{"id":"ottoman-society-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"チューリップの旅","l":"ottoman-society","x":"チューリップは、もともと中央アジアの山地に自生する花で、トルコ人とともに西へと伝わってきたと考えられている。オスマン帝国では、チューリップ（トルコ語で「ラーレ」）は特別に愛された花"},{"id":"pacific-imperialism-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"ハワイ王の夢","l":"pacific-imperialism","x":"1881年、ハワイ王国のカラーカウア王は、世界一周の旅に出た。最初の訪問国は日本であった。カラーカウアは、外国の元首として初めて明治天皇と会見し、二つの驚くべき提案をした。一つは、"},{"id":"pacific-imperialism-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「絵を送れ、戦争は私が用意する」","l":"pacific-imperialism","x":"ハーストは、キューバに画家のレミントンを特派員として送り込んだ。現地に着いたレミントンが、「ここは平穏で、戦争は起こりそうにありません。帰国したい」と電報を送ると、ハーストは、こう"},{"id":"pacific-imperialism-t3","k":"music","f":"music","kj":"音楽","t":"「星条旗よ永遠なれ」","l":"pacific-imperialism","x":"「マーチ王」と呼ばれたアメリカの作曲家スーザは、1896年の末、ヨーロッパからの帰りの船の上で、この行進曲の旋律を思いついたという。翌1897年に初演されたこの曲は、米西戦争の時代"},{"id":"pacific-imperialism-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"布引丸の沈没","l":"pacific-imperialism","x":"アギナルドたちは、アメリカと戦うための武器を、日本に求めた。日本でも、フィリピンの独立運動に共感する人々がいた。1899年、日本に亡命していた中国の革命家孫文や、その支援者の宮崎滔"},{"id":"pacific-imperialism-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"戦争を止めた台風","l":"pacific-imperialism","x":"1889年3月、南太平洋のサモアのアピア港では、サモアの支配をめぐって対立するドイツとアメリカの軍艦が、互いに砲口を向けてにらみ合っていた。イギリスの軍艦も1隻が停泊していた。一触"},{"id":"pacific-war-1-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"遅れた通告","l":"pacific-war-1","x":"日本政府は、攻撃の開始の30分前に、交渉の打ち切りを告げる文書（対米覚書）を、アメリカ側に手渡す予定であった。ところが、ワシントンの日本大使館では、東京から送られてきた長い暗号の電"},{"id":"pacific-war-1-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「われわれは勝ったのだ」","l":"pacific-war-1","x":"真珠湾攻撃の知らせを聞いたイギリスの首相チャーチルは、のちに回顧録にこう記している。原文…… to have the United States at our side was t"},{"id":"pacific-war-1-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「イエスか、ノーか」","l":"pacific-war-1","x":"シンガポールの陥落の日、市内のフォード社の工場で、日本の第25軍司令官の山下奉文中将と、イギリス軍の司令官パーシヴァル中将との降伏の交渉が行われた。交渉の中で、条件をあれこれと尋ね"},{"id":"pacific-war-1-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"pacific-war-1","x":"映画『トラ・トラ・トラ！』（1970年、日米合作）：真珠湾攻撃に至るまでの日米双方の動きを、それぞれの国の監督が分担して撮影した映画。題名は、奇襲の成功を伝えた暗号の電文からとられ"},{"id":"pacific-war-2-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「運命の5分間」","l":"pacific-war-2","x":"ミッドウェー海戦の敗北は、長い間、「運命の5分間」の物語として語られてきた。日本の空母は、兵装の転換を終え、甲板には攻撃隊がずらりと並び、あと5分で発艦を始めるところだった。まさに"},{"id":"pacific-war-2-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「生命判断」――ガダルカナルの陣中日記","l":"pacific-war-2","x":"1942年8月から翌年2月まで続いたガダルカナル島の戦いで、日本軍は補給を断たれた。島に送られた約3万人の兵士のうち、戦死者は約5000人であったのに対し、飢えと病気（マラリアや赤"},{"id":"pacific-war-2-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"インドの「ネタージ」","l":"pacific-war-2","x":"インドの国民会議派の指導者の一人、スバス・チャンドラ・ボースは、ガンディーの非暴力の運動に飽き足らず、武力でイギリスと戦う道を選んだ（→「中国・インド・東南アジアの民族運動」の回）"},{"id":"pacific-war-2-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「明日は自由主義者が一人この世から去って行きます」――特攻隊員の「所感」","l":"pacific-war-2","x":"1945年5月11日、陸軍の特別攻撃隊員として、鹿児島県の知覧の飛行場から沖縄の海に向けて出撃し、戦死した上原良司は、22歳であった。慶應義塾大学で学んでいた彼は、学徒出陣によって"},{"id":"pacific-war-2-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"pacific-war-2","x":"映画『硫黄島からの手紙』（クリント・イーストウッド監督、2006年）：硫黄島の戦いを、日本軍の側から描いた映画。栗林忠道中将らの手紙をもとにしている。同じ監督が、アメリカ側から描い"},{"id":"papal-schism-t1","k":"source","f":"src","kj":"史料｜記録","t":"「ローマ教皇に服従することは、救いのために絶対に必要である」――『ウナム・サンクタム』","l":"papal-schism","x":"1302年、フランス王フィリップ4世と、聖職者への課税などをめぐって激しく対立していた教皇ボニファティウス8世は、教皇の権威について述べた大勅書を発した。書き出しの言葉から『ウナム"},{"id":"papal-schism-t2","k":"source","f":"src","kj":"史料｜記録","t":"「西のバビロン」――ペトラルカの怒り","l":"papal-schism","x":"イタリアの詩人ペトラルカは、若いころ、アヴィニョンの教皇庁の近くで過ごした。しかし、彼はこの町を激しく嫌った。友人にあてた手紙の中で、ペトラルカは、アヴィニョンをこう呼んでいる。「"},{"id":"papal-schism-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"海へ流れた灰","l":"papal-schism","x":"1415年、コンスタンツ公会議は、亡くなってから30年がたっていたウィクリフを異端と宣告した。そして1428年、教皇の命令によって、イングランドのラタワースの教会の墓地に葬られてい"},{"id":"papal-schism-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「自分の13にとどまる」――最後まで降りなかった教皇","l":"papal-schism","x":"コンスタンツ公会議で廃位されたアヴィニョン系の教皇ベネディクトゥス13世（本名ペドロ・デ・ルナ）は、スペインのアラゴンの貴族の出身であった。彼は、自分こそが正しい教皇であるという主"},{"id":"papal-schism-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"公会議は教皇より上か","l":"papal-schism","x":"コンスタンツ公会議は、1415年、「公会議は、キリストから直接に権威を受けており、教皇を含むすべての人は、信仰の問題について、公会議に従わなければならない」という宣言を出した。教皇"},{"id":"papal-schism-t6","k":"now","f":"now","kj":"いま","t":"プラハの旧市街広場のフス像","l":"papal-schism","x":"現在、プラハの旧市街広場の中央には、ヤン・フスの大きな記念像が立っている。フスの死から500年後の1915年に建てられたこの像の台座には、フスの言葉とされる「互いに愛し合い、すべて"},{"id":"papal-schism-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"papal-schism","x":"大西巷一『乙女戦争 ディーヴチー・ヴァールカ』（漫画、2013〜2018年）：フスの処刑の後のボヘミアで起こったフス戦争を、戦乱に巻き込まれた少女の視点で描く。名将ジシュカの戦車の"},{"id":"parthia-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「パルティアン・ショット」","l":"parthia","x":"逃げながら振り返って後方に矢を射るパルティアの騎兵の戦法は、ローマ人に強烈な印象を与え、「パルティアン・ショット」と呼ばれた。英語には、立ち去り際に言い放つ痛烈な捨て台詞を意味する"},{"id":"parthia-t2","k":"source","f":"src","kj":"史料｜記録","t":"漢の使者を迎えたパルティア","l":"parthia","x":"前2世紀末、武帝の使者がパルティアを訪れた。『史記』は、その様子を次のように記している。原文漢使至安息，安息王令將二萬騎迎於東界。東界去王都數千里。行比至，過數十城，人民相屬甚多。"},{"id":"parthia-t3","k":"source","f":"src","kj":"史料｜記録","t":"クラッススの首","l":"parthia","x":"クラッススの首が宮廷の入り口に届けられたとき、食事は片づけられ、悲劇役者のイアソンが、エウリピデスの『バッコスの信女たち』のアガウエの場面を歌っていた。……イアソンは、劇中で（ペン"},{"id":"parthia-t4","k":"now","f":"now","kj":"いま","t":"隊商都市ハトラ","l":"parthia","x":"メソポタミア北部の砂漠の中にあったハトラは、パルティアの支配下で、アラブ人の王が治めた隊商都市であった。円形の二重の城壁に守られた町は、太陽神をまつる大神殿を中心に栄え、トラヤヌス"},{"id":"parthia-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「バグダードの電池」","l":"parthia","x":"1930年代、バグダード近郊のパルティア時代（ササン朝時代とも）の遺跡から、素焼きの壺の中に銅の筒と鉄の棒が入った、奇妙な器が見つかった。これが、2000年前の「電池」で、金めっき"},{"id":"parthia-t6","k":"confuse","f":"confuse","kj":"混同注意","t":"古代イランの3つの王朝","l":"parthia","x":"アケメネス朝パルティア（アルサケス朝）ササン朝時代前550〜前330年前247年ごろ〜後224年224（226）〜651年建国者キュロス2世アルサケスアルダシール1世担い手ペルシア"},{"id":"pax-mongolica-t1","k":"source","f":"src","kj":"史料｜記録","t":"「昼も夜も安全な道」","l":"pax-mongolica","x":"14世紀の前半、イタリアのフィレンツェの大商社バルディ家に勤めた商人ペゴロッティは、商人のための手引き書『商業の手引き』を書いた。その中には、黒海の北岸の港ターナ（現在のアゾフ）か"},{"id":"pax-mongolica-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"2か月で消えた紙幣――イル＝ハン国のチャーウ","l":"pax-mongolica","x":"元の紙幣の成功を見て、それをまねようとした国があった。イル＝ハン国である。1294年、財政に苦しんでいたイル＝ハン国のハン、ガイハトゥは、都タブリーズで、元にならった紙幣を発行した"},{"id":"pax-mongolica-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"カラコルムの銀の木","l":"pax-mongolica","x":"ルブルックは、カラコルムの町を「パリ近郊のサン＝ドニの村ほどの大きさもない」と書いている。草原の帝国の都は、思いのほか小さな町であった。しかし、その宮殿で、ルブルックは驚くべきもの"},{"id":"pax-mongolica-t4","k":"debate","f":"think","kj":"考える｜諸説あり","t":"パクス・モンゴリカ","l":"pax-mongolica","x":"モンゴル帝国の時代のユーラシアの安定と交流を、ローマ帝国の「パクス・ロマーナ（ローマの平和）」になぞらえて、「パクス・モンゴリカ（モンゴルの平和）」と呼ぶことがある。ただし、モンゴ"},{"id":"pax-mongolica-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"pax-mongolica","x":"ドラマ『マルコ・ポーロ』（Netflix、2014〜2016年）：クビライの宮廷に仕えたマルコ＝ポーロを主人公にしたドラマ。物語の多くは創作である。作品は史実をもとにした創作を含む"},{"id":"pax-romana-t1","k":"source","f":"src","kj":"史料｜記録","t":"戦場で書かれた哲学――『自省録』","l":"pax-romana","x":"マルクス＝アウレリウスは、ドナウ川の前線の陣営で、夜ごとに、自分自身に向けた覚え書きをギリシア語で書きつけた。それが『自省録』である。そこには、皇帝としての重い責任と、ストア派の哲"},{"id":"pax-romana-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"大秦王安敦の使者","l":"pax-romana","x":"中国の歴史書『後漢書』には、166年に、「大秦王安敦」の使者が、日南郡（現在のベトナム中部）に到着し、象牙・犀の角・べっ甲を献上した、という記録がある。「大秦」は中国でのローマ帝国"},{"id":"pax-romana-t3","k":"now","f":"now","kj":"いま","t":"ハドリアヌスの長城","l":"pax-romana","x":"ハドリアヌス帝の命令で122年ごろから築かれたハドリアヌスの長城は、ブリタニア（現在のイングランド北部）を東西に横切る、全長約118kmの石の壁である。壁に沿って、1ローマ・マイル"},{"id":"pax-romana-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"「平和」は誰にとっての平和か","l":"pax-romana","x":"ローマの歴史家タキトゥスは、ブリタニアの首長カルガクスが、ローマ軍との決戦を前に部下たちに語ったとする演説を、次のように書いている。原文auferre trucidare rape"},{"id":"pax-romana-t5","k":"voice","f":"src","kj":"史料｜証言","t":"ブーディカの反乱（60年）","l":"pax-romana","x":"ブリタンニア（現在のイギリス）の部族イケニ族の王が亡くなると、ローマの役人たちは王国を併合し、王妃ブーディカをむち打ち、2人の娘を辱めた。怒ったブーディカは、周辺の部族とともに立ち"},{"id":"pax-romana-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"pax-romana","x":"塩野七生『ローマ人の物語』（1992〜2006年、全15巻）：ローマの建国から西ローマ帝国の滅亡までを、指導者たちの人物像を中心に描いた歴史エッセイ。五賢帝の時代は第9〜11巻で扱"},{"id":"peloponnesian-war-t1","k":"source","f":"src","kj":"史料｜記録","t":"「本当の原因」――トゥキディデスの分析","l":"peloponnesian-war","x":"戦争の直接のきっかけは、コリントスとその植民市ケルキラ（コルフ島）の争いに、アテネが介入したことや、アテネがポテイダイアやメガラに圧力をかけたことだった。しかしトゥキディデスは、そ"},{"id":"peloponnesian-war-t2","k":"voice","f":"src","kj":"史料｜証言","t":"アテネの疫病――トゥキディデスの記録","l":"peloponnesian-war","x":"トゥキディデス自身もこの病にかかり、生き延びた。彼は、のちの人々が病を見分けられるようにと、その症状を詳しく書き残している。原文ἀλλ᾽ ἐξαίφνης ὑγιεῖς ὄντας"},{"id":"peloponnesian-war-t3","k":"source","f":"src","kj":"史料｜記録","t":"「強者はなしうることをなし、弱者は受け入れねばならぬことを受け入れる」","l":"peloponnesian-war","x":"原文δίκαια μὲν ἐν τῷ ἀνθρωπείῳ λόγῳ ἀπὸ τῆς ἴσης ἀνάγκης κρίνεται, δυνατὰ δὲ οἱ προύχοντες π"},{"id":"peloponnesian-war-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"エウリピデスの詩で救われた捕虜","l":"peloponnesian-war","x":"伝えられるところでは、シラクサの石切り場の捕虜のうち、アテネの悲劇作家エウリピデスの詩を暗唱できた者は、それを聞きたがったシラクサ人によって解放されたり、食べ物を与えられたりしたと"},{"id":"peloponnesian-war-t5","k":"confuse","f":"confuse","kj":"混同注意","t":"ペロポネソス戦争の流れ","l":"peloponnesian-war","x":"年出来事前431年スパルタのアッティカ侵攻で開戦前430〜前429年アテネで疫病が流行。ペリクレス死去前421年ニキアスの和約前416年アテネがメロスを征服（メロス対話）前415〜"},{"id":"peloponnesian-war-t6","k":"voice","f":"src","kj":"史料｜証言","t":"「戦争は暴力的な教師である」――ケルキュラの内乱","l":"peloponnesian-war","x":"前427年、アテネと結ぶ民主派と、スパルタと結ぶ寡頭派とが争ったケルキュラ（現在のコルフ島）では、市民どうしの殺し合いが7日間続いた。トゥキディデスはこう記す。原文…… καὶ γ"},{"id":"peloponnesian-war-t7","k":"view","f":"think","kj":"考える｜別の視点","t":"「ポリスの衰退」とは何だったのか","l":"peloponnesian-war","x":"前4世紀のポリスの変化は、しばしば「ポリスの衰退」と呼ばれる。その中身を見てみよう。戦争の長期化と農民の没落：長い戦争で畑は荒らされ、重装歩兵として戦ってきた中小の農民が没落した。"},{"id":"peloponnesian-war-t8","k":"now","f":"now","kj":"いま","t":"「トゥキディデスの罠」","l":"peloponnesian-war","x":"2010年代、アメリカの政治学者グレアム＝アリソンは、トゥキディデスの「アテネの台頭とスパルタの恐怖」という分析にちなんで、「トゥキディデスの罠」という言葉を広めた。台頭する新興国"},{"id":"peloponnesian-war-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"peloponnesian-war","x":"アリストファネス『女の平和』（喜劇、前411年）：ペロポネソス戦争に疲れたアテネとスパルタの女たちが手を組み、戦争をやめるまで夫を拒むという「ストライキ」で、男たちに和平を結ばせる"},{"id":"pericles-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"デロス同盟とペロポネソス同盟","l":"pericles","x":"デロス同盟ペロポネソス同盟盟主アテネスパルタ成立前478年前6世紀後半加盟国エーゲ海の島々、小アジア沿岸などのポリス（多くはイオニア人）ペロポネソス半島のポリス（コリントスなど）目"},{"id":"pericles-t2","k":"source","f":"src","kj":"史料｜記録","t":"ペリクレスの葬送演説","l":"pericles","x":"ペロポネソス戦争の1年目の冬、ペリクレスは、戦死者を弔う国葬の場で演説を行った。歴史家トゥキディデスが記録した（再構成した）この「葬送演説」は、アテネの民主政の理想を語った言葉とし"},{"id":"pericles-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"抽選のための機械","l":"pericles","x":"アテネ人は、役人や陪審員を選ぶのに、選挙よりも抽選を重んじた。選挙では、弁が立ち、金があり、名の知れた者が選ばれやすい。抽選なら、すべての市民に平等に機会がある。アリストテレスは、"},{"id":"pericles-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"赤いロープで民会へ","l":"pericles","x":"民会は、成立のために一定の数の出席者が必要な議題もあった。しかし、市民の中には、アゴラで買い物やおしゃべりをして、民会になかなか来ない者もいた。アリストファネスの喜劇によれば、民会"},{"id":"pericles-t5","k":"confuse","f":"confuse","kj":"混同注意","t":"アテネの民主政と現代の民主政","l":"pericles","x":"アテネの民主政現代の民主政（日本など）形態直接民主政（市民が民会に直接参加）間接民主政（選挙で代表を選ぶ）役人の選び方主に抽選主に選挙参政権成人男性市民のみ。女性・在留外人・奴隷は"},{"id":"pericles-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"まっすぐに見えるための曲線","l":"pericles","x":"パルテノン神殿は、まっすぐな直線でできているように見える。しかし実際には、ほとんどの線がわずかに曲がっている。床（基壇）は、中央が端より約10cm盛り上がっている。柱は、中ほどがわ"},{"id":"pericles-t7","k":"now","f":"now","kj":"いま","t":"パルテノン神殿の彫刻はどこにあるべきか","l":"pericles","x":"パルテノン神殿の彫刻の約半分は、現在、ロンドンの大英博物館にある。19世紀の初め、オスマン帝国の駐在イギリス大使だったエルギン伯爵が、オスマン帝国の許可を得たとして、神殿の彫刻を切"},{"id":"pericles-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"pericles","x":"アリストファネス『騎士』（喜劇、前424年）：ペリクレスの死後にアテネの民会を動かした政治家クレオンを、主人「民衆」をだます奴隷として痛烈に風刺した喜劇。作品は史実をもとにした創作"},{"id":"persian-wars-t1","k":"source","f":"src","kj":"史料｜記録","t":"「主君よ、アテネ人を忘れたもうな」","l":"persian-wars","x":"ヘロドトスによれば、サルデスが焼かれたと聞いたダレイオス1世は、まず「アテネ人とは何者か」と尋ねた。答えを聞くと、弓を取って天に向かって矢を放ち、「ゼウスよ、アテネ人に報復すること"},{"id":"persian-wars-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"悲劇『ミレトスの陥落』","l":"persian-wars","x":"ミレトスの陥落は、同じイオニア人のアテネ人に大きな衝撃を与えた。数年後、悲劇作家プリュニコスが、『ミレトスの陥落』という劇を上演すると、観客は皆泣き崩れた。アテネ人は、「同胞の不幸"},{"id":"persian-wars-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"マラソンの起源","l":"persian-wars","x":"マラトンの勝利を知らせるために、一人の兵士がアテネまで約40kmを走り続け、「喜べ、われらは勝った」と告げて息絶えた――。この話が、近代オリンピックの「マラソン」競技の起源となった"},{"id":"persian-wars-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"海をむち打った王","l":"persian-wars","x":"ヘロドトスによれば、ヘレスポントス海峡に最初にかけた船橋が嵐で壊れたとき、クセルクセスは怒り狂い、海を300回むちで打たせ、足かせを海に投げ込ませた。そして、むちを打つ者たちに、こ"},{"id":"persian-wars-t5","k":"source","f":"src","kj":"史料｜記録","t":"「木の壁」の神託","l":"persian-wars","x":"ペルシアの大軍が迫る中、アテネがデルフォイに送った使者は、恐ろしい神託を受け取った。アテネは焼かれ、すべてが滅びるであろう、というのである。使者が嘆願すると、二度目の神託が下った。"},{"id":"persian-wars-t6","k":"source","f":"src","kj":"史料｜記録","t":"「旅人よ、スパルタ人に伝えよ」","l":"persian-wars","x":"テルモピレーの戦いの後、戦死者を葬った丘には、詩人シモニデスの作とされる碑文が刻まれた。原文ὦ ξεῖν᾽, ἀγγέλλειν Λακεδαιμονίοις ὅτι τῇδεκε"},{"id":"persian-wars-t7","k":"view","f":"think","kj":"考える｜別の視点","t":"「300人」の物語の陰で","l":"persian-wars","x":"テルモピレーの戦いは、映画や漫画などで「300人のスパルタ兵が100万の大軍に立ち向かった」物語として描かれることが多い。しかし実際には、戦いの最初の2日間、隘路を守ったのは約70"},{"id":"persian-wars-t8","k":"person","f":"deep","kj":"深掘り｜人物","t":"女性の提督アルテミシア","l":"persian-wars","x":"ペルシア艦隊には、小アジアのハリカルナッソス（ヘロドトスの故郷）の女王アルテミシアが、自ら5隻の船を率いて加わっていた。ヘロドトスによれば、アルテミシアは海戦の前の作戦会議で、ただ"},{"id":"persian-wars-t9","k":"confuse","f":"confuse","kj":"混同注意","t":"ペルシア戦争の主な戦い","l":"persian-wars","x":"年戦いギリシア側の指揮官結果・意義前490年マラトンの戦いミルティアデス（アテネ）アテネの重装歩兵が勝利前480年テルモピレーの戦いレオニダス（スパルタ）ギリシア軍は全滅。ペルシア"},{"id":"persian-wars-t10","k":"view","f":"think","kj":"考える｜別の視点","t":"ペルシアから見たペルシア戦争","l":"persian-wars","x":"ペルシア戦争について、私たちが知っていることのほとんどは、ギリシア人、とくにヘロドトスの記録によっている。ペルシア側には、この戦争についての記録はほとんど残っていない。アケメネス朝"},{"id":"persian-wars-t11","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"persian-wars","x":"映画『300〈スリーハンドレッド〉』（2007年、原作はフランク・ミラーのグラフィック・ノベル）：テルモピュライの戦いを、劇画風の映像で描いた映画。スパルタ王レオニダスの300人の"},{"id":"phoenicia-aram-t1","k":"source","f":"src","kj":"史料｜記録","t":"『ウェンアメン旅行記』――落ちぶれたエジプトの使者","l":"phoenicia-aram","x":"エジプトの勢いが衰えたことをよく示すのが、前11世紀ごろの『ウェンアメン旅行記』という文書である。テーベのアメン神殿に仕えるウェンアメンは、神の聖なる船を造るための杉材を買いつける"},{"id":"phoenicia-aram-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「フェニキア」は紫の国","l":"phoenicia-aram","x":"フェニキア人の特産品として有名なのが、紫色の染料である。地中海にすむアクキガイ科の巻貝の分泌腺から取った染料で、色があせにくく、美しい赤紫色に染まった。しかし、1グラムの染料を得る"},{"id":"phoenicia-aram-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「バイブル」の語源","l":"phoenicia-aram","x":"フェニキアの港町ビブロスは、エジプトからパピルスを輸入して、ギリシアなどに売る中継地でもあった。そこでギリシア人は、パピルスや書物のことを、町の名にちなんで「ビブロス」と呼ぶように"},{"id":"phoenicia-aram-t4","k":"source","f":"src","kj":"史料｜記録","t":"牛の皮1枚分の土地","l":"phoenicia-aram","x":"カルタゴ建設については、こんな伝説が残っている。ティルスの王女エリッサ（ローマの詩人ウェルギリウスの作品ではディド）は、兄の王に夫を殺され、仲間とともにティルスを逃れて北アフリカに"},{"id":"phoenicia-aram-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"フェニキア人はアフリカを一周したか","l":"phoenicia-aram","x":"前5世紀のギリシアの歴史家ヘロドトスは、次のような話を記録している。前600年ごろ、エジプト王ネコ2世がフェニキア人の船団を紅海から南へ送り出した。船団は秋になると上陸して麦をまき"},{"id":"phoenicia-aram-t6","k":"confuse","f":"confuse","kj":"混同注意","t":"「植民市」「属州」「植民地」の違い","l":"phoenicia-aram","x":"世界史には「植民」のつく言葉がたくさん出てくるが、時代によって意味がまったく違う。用語時代・主体内容本国との関係フェニキア人の植民市前12〜前8世紀ごろ交易の拠点として建てた港町当"},{"id":"phoenicia-aram-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"「A」は牛の頭だった","l":"phoenicia-aram","x":"アルファベットの最初の文字「A」をさかさまにしてみよう。角の生えた牛の頭に見えないだろうか。フェニキア文字の最初の文字は「アレフ」といい、セム語で「牛」を意味した。もとは牛の頭の形"},{"id":"phoenicia-aram-t8","k":"confuse","f":"confuse","kj":"混同注意","t":"「最古のアルファベット」はどれか","l":"phoenicia-aram","x":"フェニキア文字より古い表音文字として、シリアの港町ウガリトで使われたウガリト文字がある。前14世紀ごろの文字で、楔形文字の形をしているが、約30の文字からなるアルファベットであった"},{"id":"phoenicia-aram-t9","k":"now","f":"now","kj":"いま","t":"イエスの言葉は今も話されている","l":"phoenicia-aram","x":"1世紀にパレスチナで活動したイエスが日常話していたのは、アラム語だったと考えられている。『新約聖書』はギリシア語で書かれているが、その中には、イエスが十字架の上で叫んだ「エロイ、エ"},{"id":"phoenicia-aram-t10","k":"view","f":"think","kj":"考える｜別の視点","t":"文字は誰のものか","l":"phoenicia-aram","x":"「アルファベット」というと、ギリシア・ローマに始まるヨーロッパの文化と考えがちである。しかし、その源流をたどると、エジプトの文字を借りたセム語系の人々、そしてそれを地中海と西アジア"},{"id":"phoenicia-aram-t11","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"phoenicia-aram","x":"フローベール『サランボー』（1862年）：フェニキア人の植民市カルタゴを舞台に、傭兵たちの反乱と、将軍ハミルカルの娘サランボーの悲恋を描いた歴史小説。作品は史実をもとにした創作を含"},{"id":"poland-partition-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"夜逃げした王","l":"poland-partition","x":"1573年、最初の選挙で王に選ばれたのは、フランス王シャルル9世の弟、アンジュー公アンリであった。ところが、翌1574年6月、クラクフの王のもとに、兄シャルル9世が亡くなったという"},{"id":"poland-partition-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"クロワッサンとコーヒー","l":"poland-partition","x":"ウィーンの包囲には、いくつもの有名な言い伝えがある。一つは、クロワッサンの起源である。包囲の際に、夜明け前から働いていたパン職人が、オスマン軍が坑道を掘る音に気づいて知らせた。その"},{"id":"poland-partition-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"二つの大陸の英雄","l":"poland-partition","x":"コシチューシコは、ポーランドが第1回分割の傷に苦しんでいた1776年、大西洋を渡ってアメリカ独立戦争に加わった（→「アメリカ独立革命」の回）。工兵の将校として、彼は、サラトガの戦い"},{"id":"poland-partition-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"なぜポーランドは消えたのか","l":"poland-partition","x":"ポーランドが滅んだ原因として、かつては、自由拒否権に象徴される貴族の「無政府状態」が強調された。貴族たちが自分たちの特権にしがみつき、強い国家をつくろうとしなかったから、国が滅んだ"},{"id":"polis-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"「ポリス」と「都市国家」と「国家」","l":"polis","x":"ポリスは、日本語では「都市国家」と訳されることが多い。シュメール人の都市国家（2-01）や、中世イタリアの都市国家と同じ言葉である。しかし、それぞれの性格は異なる。シュメールの都市"},{"id":"polis-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"盾は「隣の仲間を守る」もの","l":"polis","x":"ファランクスでは、重装歩兵は左手に大きな丸い盾（ホプロン）をもった。この盾は、自分の体の左半分と、左隣の仲間の体の右半分を守った。そのため、隊列の兵士たちは、無防備な右側を守ろうと"},{"id":"polis-t3","k":"source","f":"src","kj":"史料｜記録","t":"「人間は、生まれつきポリス的な動物である」――アリストテレス","l":"polis","x":"前4世紀の哲学者アリストテレスは、『政治学』の中で、ポリスという共同体と人間の本性について、こう論じた。原文ἐκ τούτων οὖν φανερὸν ὅτι τῶν φύσει "},{"id":"polis-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"世界のへそ、デルフォイ","l":"polis","x":"デルフォイは、ギリシア中部のパルナッソス山の中腹にある、アポロン神をまつる聖地である。神話によれば、ゼウスが世界の両端から2羽のワシを放ったところ、2羽はデルフォイで出会った。その"},{"id":"polis-t5","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"古代オリンピック","l":"polis","x":"オリンピアの祭典は、ゼウスをたたえる祭りで、伝承では前776年に始まり、4年ごとに開かれた。この最初の年は、のちにギリシア人が年代を数える基準にもなった。祭典の期間中は、ギリシア中"},{"id":"polis-t6","k":"source","f":"src","kj":"史料｜記録","t":"「池のまわりのカエルのように」","l":"polis","x":"原文ἡμᾶς οἰκεῖν τοὺς μέχρι Ἡρακλείων στηλῶν ἀπὸ Φάσιδος ἐν σμικρῷ τινι μορίῳ, ὥσπερ περὶ τέλ"},{"id":"polis-t7","k":"view","f":"think","kj":"考える｜別の視点","t":"「ギリシア＝ヨーロッパの源流」という見方","l":"polis","x":"古代ギリシアは、しばしば「ヨーロッパ文明の源流」と呼ばれる。しかし、当時のギリシア人の世界の中心は、エーゲ海であって、ヨーロッパ大陸ではなかった。ギリシア人のポリスは、小アジア（現"},{"id":"polis-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"polis","x":"ホメロス『イリアス』『オデュッセイア』（前8世紀ごろ）：トロイア戦争とその後の英雄の放浪をうたった叙事詩。ポリスが成立していく時代のギリシア人の、共通の古典となった。映画『トロイ』"},{"id":"portugal-exploration-t1","k":"mech","f":"deep","kj":"深掘り｜しくみ","t":"なぜ香辛料はそれほど求められたのか","l":"portugal-exploration","x":"「中世のヨーロッパ人が香辛料を求めたのは、腐りかけた肉の臭いをごまかすためだった」という説明が、よく聞かれる。しかし、これは誤りとされている。香辛料は、肉そのものよりもはるかに高価"},{"id":"portugal-exploration-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「航海学校」はあったのか","l":"portugal-exploration","x":"エンリケ航海王子は、サグレスに「航海学校」をつくり、ヨーロッパ中から地理学者や天文学者、地図製作者を集めて、航海術を研究させた――という話が、よく知られている。しかし、このような学"},{"id":"portugal-exploration-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"船に乗らなかった「航海王子」","l":"portugal-exploration","x":"「航海王子」と呼ばれるエンリケだが、実は、アフリカ西岸の探検の航海に、自ら出たことは一度もない。彼が海を渡ったのは、セウタ攻略（1415年）や、失敗に終わったタンジール遠征（143"},{"id":"portugal-exploration-t4","k":"source","f":"src","kj":"史料｜記録","t":"王を笑わせた贈り物","l":"portugal-exploration","x":"カリカットに着いたガマは、この地の王（ザモリン）に、ポルトガル王からの贈り物を差し出そうとした。用意されていたのは、縞模様の布12枚、赤い頭巾4つ、帽子6つ、珊瑚の首飾り4連、洗面"},{"id":"portugal-exploration-t5","k":"mech","f":"deep","kj":"深掘り｜しくみ","t":"通行証（カルタス）のしくみ","l":"portugal-exploration","x":"ポルトガルは、アジアの広大な陸地を征服したわけではなかった。小さな国ポルトガルには、そのような力はなかった。ポルトガルが支配したのは、要所の港と、そこに築いた要塞、そして海の上の航"},{"id":"portugal-exploration-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"portugal-exploration","x":"カモンイス『ウズ・ルジアダス（ルシタニアの人々）』（叙事詩、1572年）：ヴァスコ＝ダ＝ガマのインド航路の開拓を、ギリシア・ローマの叙事詩にならってうたったポルトガルの国民的叙事詩"},{"id":"prc-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「中国人民は立ち上がった」","l":"prc","x":"この日、毛沢東が天安門の上で「中国人民は、ここに立ち上がった（中国人民站起来了）」と叫んだ、という話が、広く信じられている俗説。中国の映画やテレビドラマでも、そのように描かれること"},{"id":"prc-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"長春の包囲","l":"prc","x":"三大戦役に先立つ1948年5月から10月にかけて、満州の中心都市の長春は、人民解放軍に完全に包囲された。共産党の軍は、国民党の守備軍を攻め落とすのではなく、兵糧攻めにする作戦をとっ"},{"id":"prc-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"台湾に渡った故宮の宝物","l":"prc","x":"台北の国立故宮博物院には、清朝の皇帝たちが集めた書画・陶磁器・青銅器などの宝物、約70万点が収められている。これらの宝物は、もともと、北京の紫禁城（故宮）にあったものである。193"},{"id":"prc-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"人民解放軍に空を教えた日本人","l":"prc","x":"1945年の日本の敗戦の後、中国には、数多くの日本人が、さまざまな理由で残された。その中には、国民党や共産党に、技術者や医師・看護師として「留用」された人々もいた。満州にいた日本陸"},{"id":"prc-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"prc","x":"映画『さらば、わが愛／覇王別姫』（陳凱歌監督、1993年）：京劇の二人の役者の50年にわたる人生を通して、軍閥の時代から日中戦争、人民共和国の成立、文化大革命までを描いた映画。カン"},{"id":"prussia-austria-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ポツダムの巨人連隊","l":"prussia-austria","x":"兵隊王には、一つだけ、お金を惜しまない「道楽」があった。背の高い兵士である。国王は、ヨーロッパ中から、身長が180cmを超えるような大男たちを集めて、「ポツダムの巨人連隊」をつくっ"},{"id":"prussia-austria-t2","k":"now","f":"now","kj":"いま","t":"犬たちのそばに眠る大王","l":"prussia-austria","x":"フリードリヒ大王は、晩年、サンスーシの宮殿で、愛犬のイタリアン・グレーハウンドたちに囲まれて暮らした。人間嫌いになった大王は、「人間を知れば知るほど、犬を愛するようになる」と言った"},{"id":"prussia-austria-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"6歳の天才とマリア・テレジア","l":"prussia-austria","x":"1762年、ウィーンのシェーンブルン宮殿に、ザルツブルクから一人の少年がやって来た。6歳のヴォルフガング・アマデウス・モーツァルトである。少年は、女帝マリア・テレジアと皇帝の前で、"},{"id":"prussia-austria-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"prussia-austria","x":"映画『アマデウス』（ミロス・フォアマン監督、1984年）：ヨーゼフ2世の宮廷楽長サリエリの目から、モーツァルトの天才と死を描いた映画。サリエリがモーツァルトを毒殺したという話は、根"},{"id":"punic-wars-t1","k":"source","f":"src","kj":"史料｜記録","t":"1隻の難破船から生まれた艦隊","l":"punic-wars","x":"歴史家ポリュビオスによれば、ローマ人は、浅瀬に乗り上げたカルタゴの五段櫂船（五段に漕ぎ手を配置した大型軍船）を手に入れ、それを手本にして、わずか60日ほどで100隻の五段櫂船を建造"},{"id":"punic-wars-t2","k":"source","f":"src","kj":"史料｜記録","t":"9歳の誓い","l":"punic-wars","x":"ポリュビオスによれば、晩年のハンニバルは、自らの少年時代について、次のように語ったという。9歳のとき、父ハミルカルがイベリア半島への遠征に出発する前に、神々にいけにえを捧げた。父は"},{"id":"punic-wars-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"酢で岩を砕いた？","l":"punic-wars","x":"リウィウスによれば、アルプスを下る途中、巨大な岩が道をふさいだ。ハンニバルは、岩の周りに大量の木を積んで火をつけ、真っ赤に熱した岩に酢をかけて、もろくなった岩を砕いて道を開いたとい"},{"id":"punic-wars-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"なぜローマは降伏しなかったのか","l":"punic-wars","x":"カンネーの大敗の後、南イタリアのカプアなど、多くの同盟市がローマを離れてハンニバルについた。ギリシアのマケドニア王も、ハンニバルと同盟を結んだ。しかし、ローマは降伏しなかった。ハン"},{"id":"punic-wars-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"ハンニバルのその後","l":"punic-wars","x":"敗戦後、ハンニバルはカルタゴの最高の役職に就き、政治を改革して財政を立て直した。しかし、ローマに危険視されて、カルタゴを追われた。セレウコス朝のアンティオコス3世のもとに亡命してロ"},{"id":"punic-wars-t6","k":"voice","f":"src","kj":"史料｜証言","t":"カンネーの翌朝","l":"punic-wars","x":"前216年8月、カンネーの戦いの翌朝、ハンニバルの兵士たちは、戦利品を集めるために戦場を歩いた。リウィウスは、その光景をこう描いている。原文Iacebant tot Romanor"},{"id":"punic-wars-t7","k":"source","f":"src","kj":"史料｜記録","t":"「カルタゴは滅ぼされねばならない」","l":"punic-wars","x":"ローマの政治家大カトーは、カルタゴを視察して、その繁栄ぶりに危機感を抱いた。プルタルコスによれば、カトーは元老院で、アフリカから持ち帰った大きく見事なイチジクを衣のひだから取り出し"},{"id":"punic-wars-t8","k":"voice","f":"src","kj":"史料｜証言","t":"燃えるカルタゴを見て泣いた将軍","l":"punic-wars","x":"前146年、3年の包囲の末、カルタゴはローマ軍に攻め落とされた。6日間続いた市街戦の後、町は17日間にわたって燃え続け、生き残った約5万人は奴隷として売られた。燃え落ちる町を見つめ"},{"id":"punic-wars-t9","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"カルタゴの土地に塩をまいた？","l":"punic-wars","x":"ローマ人はカルタゴを破壊した後、二度と作物が育たないように、その土地に塩をまいた――。この話は広く知られているが、古代の史料には見当たらない。この話が現れるのは、19世紀以降の書物"},{"id":"punic-wars-t10","k":"view","f":"think","kj":"考える｜別の視点","t":"カルタゴの側から見ると","l":"punic-wars","x":"カルタゴについて私たちが知っていることのほとんどは、ローマ人やギリシア人が書いたものである。カルタゴ自身の書物は、町の破壊とともにほとんど失われた（ローマはカルタゴの農学書だけはラ"},{"id":"punic-wars-t11","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"punic-wars","x":"カガノミハチ『アド・アストラ ―スキピオとハンニバル―』（漫画、2011〜2017年連載、全13巻）：第2次ポエニ戦争を、ハンニバルとスキピオの2人の天才の対決として描く。カンネー"},{"id":"qin-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"商鞅の変法の主な内容","l":"qin","x":"改革内容ねらい什伍の制民を5戸・10戸の組に編成し、犯罪を告発しない者も罰する連帯責任（連座）民衆の相互監視軍功爵制戦場で敵の首を取った数などに応じて、身分に関係なく爵位を与える兵"},{"id":"qin-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"自分の法に捕らえられた商鞅","l":"qin","x":"孝公が亡くなると、商鞅は、改革で特権を奪われた貴族たちに謀反の罪を着せられ、逃亡した。国境近くの宿屋に泊まろうとすると、宿の主人は、相手が商鞅とは知らずに言った。「商君の法では、身"},{"id":"qin-t3","k":"source","f":"src","kj":"史料｜記録","t":"李斯の「逐客を諫むるの書」","l":"qin","x":"前237年、鄭国がスパイであったことが発覚すると、秦の王族や大臣たちは、他国から来た者（客）をすべて国外に追放すべきだと主張し、政もこれを命じた。楚出身の李斯も、追放されることにな"},{"id":"qin-t4","k":"source","f":"src","kj":"史料｜記録","t":"荊軻の暗殺未遂","l":"qin","x":"秦の脅威にさらされた燕の太子丹は、刺客の荊軻を秦に送り込んだ。出発の日、易水のほとりで見送りの人々を前に、荊軻は歌った。原文風蕭蕭兮易水寒，壯士一去兮不復還。書き下し風は蕭々として"},{"id":"qin-t5","k":"source","f":"src","kj":"史料｜記録","t":"封建か、郡県か","l":"qin","x":"原文周文武所封子弟同姓甚眾，然後屬疏遠，相攻擊如仇讎，諸侯更相誅伐，周天子弗能禁止。 ……現代語訳周の文王・武王が封じた子弟や同姓の一族は、たいへん多かったが、その後、代を重ねるに"},{"id":"qin-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"1日30kgの書類","l":"qin","x":"『史記』によれば、始皇帝は、天下のことを、大小にかかわらずすべて自ら決裁した。毎日、決裁すべき文書の量を秤で量って定め、その量（1石＝120斤、約30kg）を処理し終えるまでは、昼"},{"id":"qin-t7","k":"confuse","f":"confuse","kj":"混同注意","t":"始皇帝の統一政策","l":"qin","x":"統一したもの内容度量衡長さ・容積・重さの単位と基準を統一。標準の分銅（権）や升（量）をつくり、統一の詔を刻んで全国に配った貨幣各国の刀銭・布銭・蟻鼻銭などを廃止し、円形で四角い穴の"},{"id":"qin-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"埋められたのは「儒者」だったのか","l":"qin","x":"『史記』によれば、坑儒のきっかけは、始皇帝のために不老不死の仙薬を探していた方士（神仙術の専門家）たちが、仙薬を得られずに皇帝を批判して逃亡したことにあった。そこで始皇帝は、咸陽の"},{"id":"qin-t9","k":"source","f":"src","kj":"史料｜記録","t":"鹿を馬と言う","l":"qin","x":"原文趙高欲為亂，恐群臣不聽，乃先設驗，持鹿獻於二世，曰：「馬也。」二世笑曰：「丞相誤邪？謂鹿為馬。」問左右，左右或默，或言馬以阿順趙高，或言鹿者，高因陰中諸言鹿者以法。後群臣皆畏高"},{"id":"qin-t10","k":"now","f":"now","kj":"いま","t":"睡虎地秦簡と里耶秦簡","l":"qin","x":"1975年、湖北省雲夢県の睡虎地で、秦の地方役人「喜」の墓から、1155枚の竹簡が発見された。そこには、秦の法律の条文や、法律の解釈を問答形式で示した文書、裁判の手引き、さらには日"},{"id":"qin-t11","k":"debate","f":"think","kj":"考える｜諸説あり","t":"もう一つの始皇帝伝『趙正書』","l":"qin","x":"2009年に北京大学に寄贈された前漢時代の竹簡の中に、『趙正書』と名づけられた文書があった。そこでは、始皇帝は「趙正」と呼ばれ、死の床で、自ら胡亥を後継者に指名したことになっており"},{"id":"qin-t12","k":"trivia","f":"side","kj":"こぼれ話","t":"「チャイナ」は「秦」から？","l":"qin","x":"英語の「チャイナ」（China）や、日本で使われた「支那」という呼び名は、「秦（チン）」が、インドで「チーナ」と呼ばれ、それがヨーロッパに伝わったものだとする説が広く知られている。"},{"id":"qin-t13","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"qin","x":"原泰久『キングダム』（漫画、2006年〜連載）：戦国時代末、のちの始皇帝となる秦王政（嬴政）と、天下の大将軍を目指す少年・信（のちの秦の将軍李信がモデル）を主人公に、秦の六国統一戦"},{"id":"qing-rise-t1","k":"war","f":"deep","kj":"深掘り｜戦術","t":"朝鮮軍の苦しい立場","l":"qing-rise","x":"サルフの戦いで後金に降伏した朝鮮軍の司令官姜弘立には、ひそかに国王光海君から「戦況をよく見て行動せよ」という指示が与えられていたといわれる諸説。光海君は、豊臣秀吉の侵攻の際に明が送"},{"id":"qing-rise-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"袁崇煥の悲劇","l":"qing-rise","x":"ヌルハチを破った袁崇煥は、明の救世主となるはずであった。しかし、その最期は悲劇的なものであった。1629年、ヌルハチの後を継いだホンタイジは、袁崇煥の守る山海関の正面を避け、モンゴ"},{"id":"qing-rise-t3","k":"voice","f":"src","kj":"史料｜証言","t":"『揚州十日記』――「血、水に入りて碧赭」","l":"qing-rise","x":"1645年、清軍は、明の遺臣史可法が守る揚州を攻め落とし、10日にわたって殺戮を続けた。生き延びた町人の王秀楚は、家族とともに逃げ回った日々を記録に残している。原文諸婦女長索繫頸，"},{"id":"qing-rise-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"国姓爺・鄭成功","l":"qing-rise","x":"南明を支えて、清に最も激しく抵抗したのが、鄭成功である。鄭成功は、1624年、日本の肥前の平戸で生まれた。父の鄭芝竜は、東シナ海を舞台に活躍した海商（海賊）の頭目で、母は平戸の日本"},{"id":"qing-society-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「天朝の棄民」","l":"qing-society","x":"海外に渡った中国の人々に対する清の態度は、冷たいものであった。清は、もともと民間人の海外への移住を禁じており、海外に渡った者は、国を捨てた者とみなした。1740年、オランダ東インド"},{"id":"qing-society-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"カンニングの肌着","l":"qing-society","x":"科挙は、人生をかけた試験であったから、不正も絶えなかった。受験生は、試験場の入り口で、衣服から持ち物まで厳しく調べられた。それでも、あの手この手で不正を試みる者がいた。現在、いくつ"},{"id":"qing-society-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"世界一の大富豪・伍秉鑑","l":"qing-society","x":"公行の商人の中には、莫大な富を築いた者もいた。その代表が、伍秉鑑（ハウクワ）である。伍秉鑑は、イギリス東インド会社やアメリカの商人たちと茶などの取り引きを行い、信用を重んじる誠実な"},{"id":"qing-society-t4","k":"source","f":"src","kj":"史料｜記録","t":"「紙いっぱいの荒唐な言葉」――『紅楼夢』の序の詩","l":"qing-society","x":"18世紀の半ば、没落した名家の出身の曹雪芹は、栄華を極めた大貴族の一族が衰えていく姿と、その中で生きる若い男女の恋と運命を描いた長編小説『紅楼夢』を書いた。中国の古典小説の最高傑作"},{"id":"qing-zenith-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ラテン語で書かれた条約","l":"qing-zenith","x":"ネルチンスクでの交渉の席には、清の側に、二人のイエズス会の宣教師が加わっていた。フランス人のジェルビヨン（中国名は張誠）と、ポルトガル人のペレイラ（徐日昇）である。清の満洲人の大臣"},{"id":"qing-zenith-t2","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"学問好きの皇帝","l":"qing-zenith","x":"康熙帝は、驚くほど学問好きの皇帝であった。儒学の古典を深く学び、自ら朱子学を重んじる一方で、イエズス会の宣教師たちを宮中に呼んで、ユークリッドの幾何学や、代数、天文学、解剖学を学ん"},{"id":"qing-zenith-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"「最盛期」のかげで","l":"qing-zenith","x":"乾隆帝の時代は、清の最盛期といわれる。しかし、その輝きのかげで、衰えはすでに始まっていた。人口は、18世紀の100年間に2倍以上に増えたが、耕地はそれほど増えず、人々の暮らしは苦し"},{"id":"qing-zenith-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"qing-zenith","x":"ドラマ『瓔珞〈エイラク〉～紫禁城に燃ゆる逆襲の王妃～』（2018年、中国）：乾隆帝の後宮を舞台に、宮女から皇后にまでなった女性を描いたドラマ。中国で大ヒットしたが、宮廷の豪華な暮ら"},{"id":"reform-china-t1","k":"source","f":"src","kj":"史料｜記録","t":"「鞭で追い立てられているようだ」","l":"reform-china","x":"滞在中、鄧小平は、新幹線に乗って東京から京都へ向かった。車内で、記者から乗り心地を尋ねられた鄧小平は、こう答えたと伝えられる。「速い。後ろから鞭で追い立てられているようだ。今の我々"},{"id":"reform-china-t2","k":"mech","f":"deep","kj":"深掘り｜しくみ","t":"鄧小平の「謳い文句」――なぜ言葉が必要だったのか","l":"reform-china","x":"社会主義の国で、市場経済を取り入れる――それは、毛沢東の時代には「資本主義の道」として攻撃された政策であった。鄧小平は、党の内部の反対を抑え、人々を動かすために、短く覚えやすい言葉"},{"id":"reform-china-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「来るのが遅すぎた」","l":"reform-china","x":"5月19日の未明、党の総書記の趙紫陽は、天安門広場を訪れ、ハンガー・ストライキで衰弱した学生たちの前に立った。趙紫陽は、目に涙を浮かべ、拡声器を手に、こう語りかけた。「私たちは、来"},{"id":"reformation-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"論題は扉に打ちつけられたのか","l":"reformation","x":"ルターが、ヴィッテンベルクの城教会の扉に、ハンマーで論題を打ちつけた――。この場面は、宗教改革の始まりを象徴する光景として、数多くの絵画に描かれてきた。しかし、この話を最初に書いた"},{"id":"reformation-t2","k":"music","f":"music","kj":"音楽","t":"「神はわがやぐら」――ルターの賛美歌","l":"reformation","x":"ルターは、礼拝で、聖職者だけでなく会衆の全員が、ドイツ語で神をたたえて歌うことを重んじた。そのために、彼は、自ら数多くの賛美歌（コラール）の歌詞を書き、旋律もつくった。その代表が、"},{"id":"reformation-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"悪魔に投げつけたインク壺","l":"reformation","x":"ヴァルトブルク城のルターの部屋の壁には、かつて、インクの染みがあった。翻訳に励むルターの前に悪魔が現れて誘惑したので、ルターはインク壺を悪魔に投げつけた。そのときの跡だ、というので"},{"id":"reformation-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"reformation","x":"映画『ルター』（2003年）：修道士ルターが、贖宥状を批判して教会と対立し、聖書をドイツ語に翻訳するまでを描いた映画。作品は史実をもとにした創作を含むことが多い。史実との違いにも注"},{"id":"renaissance-italy-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"ルネサンスは「中世の終わり」か","l":"renaissance-italy","x":"ブルクハルトの描いたルネサンス像には、その後、多くの批判が寄せられた。アメリカの歴史家ハスキンズは、1927年、『12世紀ルネサンス』を著し、12世紀のヨーロッパでも、イスラーム世"},{"id":"renaissance-italy-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"プラトンよりも先に","l":"renaissance-italy","x":"1460年ごろ、コジモのもとに、マケドニアの修道院から、一冊のギリシア語の写本が届けられた。それは、古代エジプトの神秘的な賢者ヘルメス・トリスメギストスが書いたとされる文書の写本で"},{"id":"renaissance-italy-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"サヴォナローラと「虚栄の焼却」","l":"renaissance-italy","x":"サヴォナローラの説教を聞くために、大聖堂には1万人以上の人々が詰めかけたという。彼は、こう呼びかけた。「誰もが、世のためではなく、神のために生きよ」。1497年2月、謝肉祭の日に、"},{"id":"renaissance-italy-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「モナ・リザ」盗難事件","l":"renaissance-italy","x":"1911年8月21日、パリのルーヴル美術館から、「モナ・リザ」が消えた。犯人は、美術館で働いたことのあるイタリア人の職人ペルッジャであった。彼は、閉館日に美術館に潜り込み、作品を額"},{"id":"renaissance-italy-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"renaissance-italy","x":"惣領冬実『チェーザレ 破壊の創造者』（漫画、2005年〜）：教皇アレクサンデル6世の子チェーザレ・ボルジアの若き日を、精密な時代考証で描いた漫画。マキァヴェッリの『君主論』の理想の"},{"id":"renaissance-north-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"「エラスムスが卵を産み、ルターがそれを孵した」","l":"renaissance-north","x":"宗教改革が始まると、当時の人々は、「エラスムスが産んだ卵を、ルターが孵した」と言った。エラスムスの教会批判が、ルターの宗教改革を生んだ、というのである。エラスムスは、これに対して、"},{"id":"renaissance-north-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"同じ日に亡くなった二人の文豪？","l":"renaissance-north","x":"シェイクスピアとセルバンテスは、どちらも1616年4月23日に亡くなったとされる。ユネスコは、この日にちなんで、4月23日を「世界図書・著作権の日」と定めている。しかし、実は、二人"},{"id":"renaissance-north-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"見たことのないサイ","l":"renaissance-north","x":"1515年5月、ポルトガルのリスボンの港に、インドから1頭のサイが到着した。インドのグジャラートのスルタンから、ポルトガルのインド総督アルブケルケに贈られたものであった（→「大航海"},{"id":"renaissance-north-t4","k":"mech","f":"deep","kj":"深掘り｜しくみ","t":"「大使たち」の謎の物体","l":"renaissance-north","x":"1533年、ホルバインは、ロンドンに滞在していた二人のフランス人、大使のダントヴィルと、友人の司教セルヴを描いた。「大使たち」と呼ばれるこの絵の二人の間の棚には、天球儀や地球儀、日"},{"id":"renaissance-north-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「悪貨は良貨を駆逐する」とコペルニクス","l":"renaissance-north","x":"「悪貨は良貨を駆逐する」という経済の法則は、16世紀のイギリスの財政家グレシャムの名をとって、「グレシャムの法則」と呼ばれる。品質の悪い貨幣と良い貨幣が、同じ価値のものとして出回る"},{"id":"revolutions-1830-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"洋ナシになった国王","l":"revolutions-1830","x":"七月王政は、出版の自由を約束していたが、国王を批判する新聞や風刺画は、次々に裁判にかけられた。1831年、風刺新聞の編集者フィリポンは、国王を侮辱した罪で法廷に立たされた。彼は、法"},{"id":"revolutions-1830-t2","k":"music","f":"music","kj":"音楽","t":"ショパンと「革命のエチュード」","l":"revolutions-1830","x":"ポーランドの若いピアニスト、ショパンは、蜂起の直前の1830年11月、演奏旅行のためにワルシャワを発っていた。旅先のシュトゥットガルトで、ショパンは、ワルシャワ陥落の知らせを聞いた"},{"id":"revolutions-1830-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"「自由主義」とは何か","l":"revolutions-1830","x":"七月革命の時代の「自由主義」とは、どのような考え方だったのだろうか。それは、個人の自由と権利を守るために、憲法によって国王の権力を制限し、議会を通じて政治を行おうとする考え方であっ"},{"id":"revolutions-1830-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"revolutions-1830","x":"ユゴー『レ・ミゼラブル』（小説、1862年）：七月王政の時代の1832年にパリで起こった六月暴動のバリケードの戦いが、物語の山場となる。ミュージカル（1980年初演）や映画でも広く"},{"id":"revolutions-1848-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「われわれは火山の上で眠っている」――トクヴィルの予言","l":"revolutions-1848","x":"1848年1月27日、二月革命の1か月ほど前、フランスの下院で、議員のアレクシ・ド・トクヴィル――『アメリカのデモクラシー』の著者として知られる政治思想家――は、こう警告した。原文"},{"id":"revolutions-1848-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ハンガリー人はビールで乾杯しない？","l":"revolutions-1848","x":"ハンガリーには、ビールのジョッキを打ち合わせて乾杯してはいけない、という言い伝えがある。1849年、アラドで13人の将軍が処刑された時、オーストリアの将校たちが、ビールのジョッキを"},{"id":"revolutions-1848-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「ラデツキー行進曲」","l":"revolutions-1848","x":"1848年、ウィーンの作曲家ヨハン・シュトラウス1世は、北イタリアでの勝利をたたえて、81歳の老将軍ラデツキーにささげる行進曲を作曲した。「ラデツキー行進曲」である。今では、毎年元"},{"id":"revolutions-1848-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"revolutions-1848","x":"フローベール『感情教育』（小説、1869年）：二月革命の前後のパリを舞台に、夢と恋に破れていく青年の人生を描いた小説。革命の熱狂と幻滅が、冷めた目で描かれている。作品は史実をもとに"},{"id":"roman-culture-t1","k":"source","f":"src","kj":"史料｜記録","t":"「征服されたギリシアが、猛々しい勝者を征服した」","l":"roman-culture","x":"アウグストゥス時代の詩人ホラティウスは、ローマとギリシアの文化の関係を、次のように表現した。原文Graecia capta ferum victorem cepit et arte"},{"id":"roman-culture-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"9月は「7番目の月」","l":"roman-culture","x":"英語の月の名前の多くは、ローマの暦に由来する。September（9月）は、ラテン語の「7（セプテム）」、October（10月）は「8（オクト）」、November（11月）は「"},{"id":"roman-culture-t3","k":"source","f":"src","kj":"史料｜記録","t":"法学者ウルピアヌスの言葉","l":"roman-culture","x":"原文Iustitia est constans et perpetua voluntas ius suum cuique tribuendi.現代語訳正義とは、各人にその権利を与え"},{"id":"roman-culture-t4","k":"now","f":"now","kj":"いま","t":"日本の民法とローマ法","l":"roman-culture","x":"『ローマ法大全』は、11世紀末から北イタリアのボローニャ大学などで熱心に研究され、ヨーロッパ各国の法律の土台となった。19世紀初めのフランス民法典（ナポレオン法典）や、19世紀末の"},{"id":"roman-culture-t5","k":"now","f":"now","kj":"いま","t":"ローマのコンクリートはなぜ長持ちするのか","l":"roman-culture","x":"現代の鉄筋コンクリートの寿命は、ふつう数十年から100年ほどとされる。ところが、ローマのコンクリートの建物や港の防波堤は、2000年たっても崩れずに残っている。その理由については、"},{"id":"roman-culture-t6","k":"source","f":"src","kj":"史料｜記録","t":"「無用のピラミッドと比べてみよ」","l":"roman-culture","x":"97年に首都ローマの水道長官となったフロンティヌスは、『水道書』を著して、水道の管理や不正な盗水の取り締まりについて記した。彼は、ローマの水道を、次のように誇っている。原文Tot "},{"id":"roman-culture-t7","k":"confuse","f":"confuse","kj":"混同注意","t":"ローマ時代の学芸（「何語で書いたか」に注意）","l":"roman-culture","x":"分野人物主な作品書いた言葉ポイント叙事詩ウェルギリウス『アエネイス』ラテン語ローマの建国叙事詩叙情詩ホラティウス『歌章』ラテン語「征服されたギリシアが勝者を征服した」叙情詩オウィデ"},{"id":"roman-culture-t8","k":"view","f":"think","kj":"考える｜別の視点","t":"ローマ文化は「ギリシアの模倣」だったのか","l":"roman-culture","x":"かつて、ローマの文化は、独創性に乏しいギリシア文化の模倣にすぎない、と評価されることが多かった。たしかに、ローマの彫刻の多くはギリシアの作品の写しであり、ローマの神々の多くはギリシ"},{"id":"roman-culture-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"roman-culture","x":"ウェルギリウス『アエネーイス』（前1世紀）：トロイアの王子アエネアスが、燃え落ちるトロイアを逃れてイタリアに渡り、ローマ人の祖先となるまでを描いた叙事詩。アウグストゥスの時代のロー"},{"id":"roman-life-t1","k":"source","f":"src","kj":"史料｜記録","t":"小プリニウスの手紙","l":"roman-life","x":"噴火の様子は、当時17歳だった小プリニウスが、のちに歴史家タキトゥスに宛てて書いた2通の手紙によって、詳しく知ることができる。小プリニウスは、ナポリ湾の西の端のミセヌムにいた。伯父"},{"id":"roman-life-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"噴火は8月か、10月か","l":"roman-life","x":"ポンペイの噴火は、小プリニウスの手紙の写本の記述から、長く「79年8月24日」とされてきた。ところが、遺跡からは、秋に実るザクロやクルミ、ワインの仕込みが終わった壺、厚手の服を着た"},{"id":"roman-life-t3","k":"source","f":"src","kj":"史料｜記録","t":"ポンペイの落書き","l":"roman-life","x":"「パン屋たちが、アエディリス（造営官）にグナエウス＝ヘルウィウス＝サビヌスを推す」（選挙のポスター）「ここで私は、一人の女の子とやった」（品のない自慢）「壁よ、おまえがこれほど多く"},{"id":"roman-life-t4","k":"source","f":"src","kj":"史料｜記録","t":"「眠れない都市」","l":"roman-life","x":"1〜2世紀の詩人ユウェナリスは、首都ローマの暮らしのつらさを、皮肉たっぷりに描いている。原文magnis opibus dormitur in urbe. ……現代語訳この都で、眠"},{"id":"roman-life-t5","k":"source","f":"src","kj":"史料｜記録","t":"「パンとサーカス」","l":"roman-life","x":"ユウェナリスは、政治に無関心になったローマ市民を、次のように皮肉った。原文nam qui dabat olimimperium, fasces, legiones, omnia, "},{"id":"roman-life-t6","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"コロッセウムと戦車競走","l":"roman-life","x":"80年に完成したコロッセウム（正式にはフラウィウス円形闘技場）は、約5万人の観客を収容できた。観客席の上には、日よけの巨大な布（ウェラリウム）を張ることができ、艦隊の水兵がその操作"},{"id":"roman-life-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"名前でわかる身分","l":"roman-life","x":"ローマの男性市民は、ふつう3つの名前をもっていた。たとえば、「ガイウス・ユリウス・カエサル」は、個人名（ガイウス）・氏族名（ユリウス）・家名（カエサル）からなる。個人名はガイウス、"},{"id":"roman-life-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"roman-life","x":"ヤマザキマリ『テルマエ・ロマエ』（漫画、2008〜2013年連載）：ハドリアヌス帝の時代の浴場設計技師ルシウスが、現代日本の銭湯や温泉にタイムスリップし、そこで得たアイデアをローマ"},{"id":"rome-crisis-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"「属州」と「同盟市」と「植民地」","l":"rome-crisis","x":"イタリアの同盟市（3-13）属州（プロウィンキア）場所イタリア半島イタリアの外（シチリア、ヒスパニア、アフリカ、アシアなど）支配自治。ローマと個別に条約を結ぶローマから派遣された総"},{"id":"rome-crisis-t2","k":"source","f":"src","kj":"史料｜記録","t":"キケロとウェッレスの裁判","l":"rome-crisis","x":"属州の総督たちの不正を象徴するのが、シチリアの総督ウェッレスの事件である。ウェッレスは、前73〜前71年の在任中、属州の人々から財産を奪い、神殿の美術品を盗み、無実の人を罪に問うて"},{"id":"rome-crisis-t3","k":"source","f":"src","kj":"史料｜記録","t":"「年老いた奴隷、病気の奴隷は売れ」――大カトーの農業書","l":"rome-crisis","x":"前2世紀、ローマの政治家で、質実剛健な古い気風を重んじたことで知られる大カトーは、農場の経営について書いた『農業論』の中で、農場主に、こう助言している。原文Boves vetulo"},{"id":"rome-crisis-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"シチリアの奴隷反乱","l":"rome-crisis","x":"前135年ごろ、シチリア島で、大農場の奴隷たちが大規模な反乱を起こした（第1次シチリア奴隷反乱）。指導者は、シリア出身の奴隷エウヌスである。エウヌスは、口から火を吐いてみせる不思議"},{"id":"rome-crisis-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"rome-crisis","x":"映画『スパルタカス』（1960年、スタンリー・キューブリック監督、カーク・ダグラス主演）：前73年に始まった剣闘士奴隷の反乱を描いた大作。反乱の経過や、クラッススとの対決などは史実"},{"id":"rome-early-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ロムルスとレムス","l":"rome-early","x":"トロイア戦争で滅んだトロイアの王族アエネアスは、イタリアに逃れて、ラテン人の祖となった。その子孫の王女は、軍神マルスとの間に、双子の男の子ロムルスとレムスを産んだ。王位を奪った叔父"},{"id":"rome-early-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"ファスケスとファシズム","l":"rome-early","x":"ファスケスは、木の棒の束に斧を添えて縛ったもので、エトルリアの王、そしてローマの高位の役人の権力の象徴であった。役人が出かけるときには、ファスケスを肩に担いだ従者（リクトル）が先導"},{"id":"rome-early-t3","k":"source","f":"src","kj":"史料｜記録","t":"胃袋と手足のたとえ","l":"rome-early","x":"前494年、戦争から帰ってきた平民たちは、貴族の横暴に抗議して、全員でローマを去り、町の外の「聖山」に立てこもった。兵士となる平民がいなければ、ローマは戦争をすることができない。困"},{"id":"rome-early-t4","k":"source","f":"src","kj":"史料｜記録","t":"「呼び出されたら、行け」――十二表法","l":"rome-early","x":"前450年ごろに定められたローマ最初の成文法、十二表法の条文は、12枚の青銅（あるいは木）の板に刻まれて、ローマの中心の広場（フォルム）に掲げられた。原物は、前390年ごろのケルト"},{"id":"rome-early-t5","k":"confuse","f":"confuse","kj":"混同注意","t":"ローマの共和政とアテネの民主政","l":"rome-early","x":"アテネの民主政（前5世紀）ローマの共和政（前3世紀）最高議決機関民会（全市民が直接参加）実質的には元老院（終身の有力者）役人の選び方主に抽選選挙（立候補には富と家柄が有利）最高の役"},{"id":"rome-early-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"SPQR","l":"rome-early","x":"ローマの軍旗や公共の建物、硬貨には、「SPQR」という4文字がよく刻まれた。「セナトゥス・ポプルスクェ・ロマヌス」の略で、「ローマの元老院と民衆」という意味である。ローマという国家"},{"id":"rome-early-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"rome-early","x":"ダヴィッド『ホラティウス兄弟の誓い』（絵画、1784年）：ローマの王政時代、隣国との決闘に向かう三兄弟が父に誓う伝説の場面。祖国への献身をたたえるこの絵は、フランス革命の前夜のパリ"},{"id":"rome-italy-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「敗者に災いあれ」とガチョウの警報","l":"rome-italy","x":"ガリア人のローマ占領については、二つの有名な話が伝えられている。一つは、ガチョウの話である。ある夜、ガリア兵が、カピトリウムの丘の崖をよじ登って砦に忍び込もうとした。番犬さえ気づか"},{"id":"rome-italy-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「ピュロスの勝利」","l":"rome-italy","x":"ピュロスは、アレクサンドロス大王の親戚にあたる名将で、マケドニア式のファランクスと、イタリアの人々が初めて見る戦象を率いて上陸した。前280年のヘラクレアの戦い、前279年のアスク"},{"id":"rome-italy-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"ローマの支配下のイタリアの人々","l":"rome-italy","x":"区分権利主な例ローマ市民（完全な市民権）民会での投票権・公職に就く権利、ローマ法の保護。兵役の義務ローマ市とその周辺、各地に建設したローマ市民の植民市（コロニア）投票権のない市民ロ"},{"id":"rome-italy-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"ローマの道のつくり","l":"rome-italy","x":"ローマの街道は、地面を深く掘り下げ、大きな石・小さな石・砂利・砂と火山灰を固めたもの、と層を重ね、最上部に平らな石を敷き詰めて造られた。路面は中央がわずかに高く、雨水が両脇の溝に流"},{"id":"russia-peter-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"犬の首とほうき","l":"russia-peter","x":"オプリーチニキは、黒い服をまとい、黒い馬に乗った。そして、その鞍には、犬の首とほうきを結びつけていたという。犬の首は、ツァーリの敵をかぎ出して食いつくこと、ほうきは、国から裏切り者"},{"id":"russia-peter-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ステンカ・ラージンとペルシアの姫","l":"russia-peter","x":"日本でも歌われてきたロシア民謡「ステンカ・ラージン」は、ラージンが、カスピ海の遠征で捕らえたペルシアの姫を、仲間たちの前で、ヴォルガ川に投げ込む場面を歌っている。姫との恋に溺れたこ"},{"id":"russia-peter-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"「鉄頭」と呼ばれた王のその後","l":"russia-peter","x":"ポルタヴァから逃れたカール12世は、オスマン帝国の領内のベンデル（現在のモルドバ）にとどまり、オスマン帝国をロシアとの戦争に引き込んだ。1711年、ピョートルは、プルート川のほとり"},{"id":"russia-peter-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"ピョートルの改革は何を残したか","l":"russia-peter","x":"ピョートルの改革は、ロシアを、わずか一代でヨーロッパの大国に押し上げた。しかし、その改革は、農奴制を土台にしたまま、上から力ずくで進められたものであった。改革の費用は、重い税と兵役"},{"id":"russia-peter-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「ヨーロッパへの窓」","l":"russia-peter","x":"サンクトペテルブルクは、しばしば「ヨーロッパへの窓」と呼ばれる。この言葉を有名にしたのは、ロシアの国民詩人プーシキンが1833年に書いた長編詩「青銅の騎士」である。詩の冒頭で、ネヴ"},{"id":"russia-peter-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"russia-peter","x":"プーシキン『青銅の騎士』（物語詩、1833年）：ピョートル1世の騎馬像を題材に、洪水で恋人を失った青年の狂気を描いた詩。皇帝が築いた首都サンクトペテルブルクの壮大さと、そこに生きる"},{"id":"russia-reforms-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"処刑台から戻った作家","l":"russia-reforms","x":"1849年12月、サンクトペテルブルクのセミョーノフスキー練兵場。社会主義を論じ合うサークルに加わった罪で捕らえられた若者たちが、銃殺刑のために、柱に縛りつけられた。目隠しをされ、"},{"id":"russia-reforms-t2","k":"now","f":"now","kj":"いま","t":"血の上の救世主教会","l":"russia-reforms","x":"アレクサンドル2世が倒れたエカチェリーナ運河の岸辺には、彼の死を悼んで、色鮮やかなタマネギ形のドームを持つ教会が建てられた。「血の上の救世主教会」である。皇帝が倒れた場所の石畳と運"},{"id":"russia-reforms-t3","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"russia-reforms","x":"ツルゲーネフ『猟人日記』（1852年）：猟をしながら農村を歩く語り手の目を通して、農奴たちの暮らしと人間性を描いた作品集。農奴制への批判として読まれ、皇太子時代のアレクサンドル2世"},{"id":"russia-siberia-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「死ぬまでだよ、マルコヴナ」――シベリアの長司祭アヴァクーム","l":"russia-siberia","x":"17世紀の半ば、ロシア正教会では、総主教ニコンが、ギリシアの教会にならって、儀式を改める改革を進めた。十字を切る指を2本から3本に変えるといった改革に、昔ながらの儀式を守ろうとする"},{"id":"russia-siberia-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"清の皇帝とロシア","l":"russia-siberia","x":"ネルチンスク条約を結んだ康熙帝は、ロシアについての情報を、イエズス会士から熱心に集めていた。一方、ロシアのピョートル1世も、清との交易に強い関心を持ち、北京に何度も使節を送った。1"},{"id":"russia-siberia-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"27年で絶滅した海の巨獣","l":"russia-siberia","x":"ベーリングとともに無人島に漂着した探検隊の博物学者シュテラーは、島の周りの海で、見たこともない巨大な生き物を発見した。体長8m以上、体重は10トン近くにもなる、ジュゴンの仲間の海獣"},{"id":"russia-siberia-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"russia-siberia","x":"井上靖『おろしや国酔夢譚』（小説、1968年、映画1992年）：大黒屋光太夫らのアリューシャン列島への漂流と、シベリアを横断してエカチェリーナ2世に謁見し、帰国するまでの10年を描"},{"id":"russian-revolution-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「周りは裏切りと臆病と欺瞞ばかりだ」――ニコライ2世の日記","l":"russian-revolution","x":"1917年3月2日（ロシア暦）、前線の司令部から首都へ戻ろうとして、途中のプスコフで列車を止められた皇帝ニコライ2世は、将軍たちの勧めを受け入れ、退位の文書に署名した。その夜、皇帝"},{"id":"russian-revolution-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"映画の中の「冬宮襲撃」","l":"russian-revolution","x":"十月革命の「冬宮襲撃」というと、大勢の群衆が冬宮の門に殺到し、激しい銃撃戦の末に宮殿になだれ込む光景を思い浮かべる人が多いかもしれない。しかし、それは、主に、1927年に十月革命の"},{"id":"russian-revolution-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"生き延びた皇女アナスタシア？","l":"russian-revolution","x":"皇帝一家の遺体は、ひそかに森に埋められ、その場所は長い間分からなかった。そのため、末の皇女アナスタシアだけは、処刑を生き延びたのではないかという噂が広まった。1920年代には、ベル"},{"id":"russian-revolution-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"米騒動","l":"russian-revolution","x":"シベリア出兵の決定は、日本の国内にも思わぬ影響を及ぼした。大戦景気で物価が上がり続けていた日本では、米の値段も急上昇していた（→「東部戦線・中東・アジアの戦い」の回）。シベリア出兵"},{"id":"russian-revolution-t5","k":"voice","f":"src","kj":"史料｜証言","t":"ヴォルガの大飢饉――「骸骨のような子どもたち」","l":"russian-revolution","x":"1921年、内戦が終わったばかりのロシアを、大飢饉が襲った。ヴォルガ川流域の穀倉地帯は、日照りによる凶作に見舞われた。しかし、飢饉をここまでひどくしたのは、天候だけではなかった。内"},{"id":"russian-revolution-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"russian-revolution","x":"パステルナーク『ドクトル・ジバゴ』（小説、1957年、映画1965年）：ロシア革命と内戦の時代を生きた医師で詩人のジバゴの愛と運命を描いた小説。ソ連では出版が許されず、イタリアで刊"},{"id":"russo-japanese-war-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"戦争に反対した人々","l":"russo-japanese-war","x":"日本の国内では、新聞の多くが、ロシアとの開戦を求める強硬な論調を張った。東京帝国大学の7人の教授たちも、政府に早期の開戦を求める意見書を出した。一方で、戦争に反対する声もあった。キ"},{"id":"russo-japanese-war-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"脚気と白い米","l":"russo-japanese-war","x":"日露戦争で、日本の陸軍の兵士を苦しめたのは、ロシア軍の銃弾だけではなかった。ビタミンB1の不足から起こる脚気である。陸軍では、戦争中に20万人以上が脚気にかかり、2万人以上が命を落"},{"id":"russo-japanese-war-t3","k":"source","f":"src","kj":"史料｜記録","t":"「本日天気晴朗ナレドモ浪高シ」――日本海海戦の電報と信号","l":"russo-japanese-war","x":"1905年5月27日の早朝、哨戒中の仮装巡洋艦信濃丸が、「敵艦見ユ」と打電した。連合艦隊の旗艦三笠から、東京の大本営に向けて、次の電報が発せられた。起草したのは、参謀の秋山真之とさ"},{"id":"russo-japanese-war-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"敗将を見舞った東郷","l":"russo-japanese-war","x":"海戦の後、頭に重傷を負って捕虜となったロジェストヴェンスキーは、佐世保の海軍病院に収容された。東郷平八郎は、彼を見舞い、その手を握って、こう語ったという。「戦いに敗れることは、軍人"},{"id":"russo-japanese-war-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"安重根","l":"russo-japanese-war","x":"1909年10月26日の朝、満州のハルビンの駅のホームで、ロシアの蔵相との会談に訪れた伊藤博文が、一人の韓国人の青年に拳銃で撃たれ、まもなく息を引き取った。撃ったのは、義兵の運動に"},{"id":"russo-japanese-war-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"russo-japanese-war","x":"司馬遼太郎『坂の上の雲』（小説、1968〜1972年連載）：日本海海戦の参謀秋山真之らを主人公に、日露戦争を描いた長編。旅順攻略を指揮した乃木希典の描き方をめぐっては、批判も多い。"},{"id":"rwanda-t1","k":"source","f":"src","kj":"史料｜記録","t":"「ゴキブリを踏みつぶせ」","l":"rwanda","x":"フツの過激派は、1993年に開局したラジオ局「千の丘のラジオ・テレビ」（RTLM）を使って、ツチへの憎しみをあおった。RTLMは、軽快な音楽や冗談を交えた、若者に人気の放送局であっ"},{"id":"rwanda-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「明日、私たちは家族とともに殺されることを、お知らせします」","l":"rwanda","x":"1994年4月、ルワンダ西部のムゲネロの教会と病院には、ツチの人々が数多く逃げ込んでいた。4月15日、そこに避難していたツチの牧師たちは、セブンスデー・アドベンチスト教会の地区の長"},{"id":"rwanda-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"自衛隊、ゴマへ","l":"rwanda","x":"1994年9月、日本政府は、ザイールのゴマなどに、陸上自衛隊の部隊、約400人を派遣した。ルワンダ難民のキャンプで、医療、給水、防疫などの支援を行うためである。PKO協力法にもとづ"},{"id":"rwanda-t4","k":"now","f":"now","kj":"いま","t":"日本とアフリカ","l":"rwanda","x":"日本は、1993年から、アフリカの開発をテーマとする国際会議「アフリカ開発会議（TICAD）」を、ほぼ3年ごとに開いている。2009年からは、ソマリアの沖の海賊から船を守るため、海"},{"id":"rwanda-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"rwanda","x":"映画『ホテル・ルワンダ』（2004年）：ルワンダの虐殺の中で、首都キガリのホテルに1200人以上の人々をかくまった支配人ポール・ルセサバギナを描いた映画。作品は史実をもとにした創作"},{"id":"safavid-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"敗れた王の英雄の絵","l":"safavid","x":"上の壁画は、チャルディラーンの戦いから約130年後、アッバース2世の時代に、イスファハーンの宮殿の広間の壁に描かれたものである。不思議なことに、敗れたはずの戦いが、まるで勝利の場面"},{"id":"safavid-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"疑い深い名君","l":"safavid","x":"アッバース1世は、有能で精力的な君主であった。彼はしばしば変装して町を歩き、市場の商人や民衆の暮らしぶりを自分の目で確かめたという伝承。ヨーロッパの使節たちを気さくにもてなし、ワイ"},{"id":"sasanian-t1","k":"source","f":"src","kj":"史料｜記録","t":"「われらは自らの手で、皇帝ウァレリアヌスを捕らえた」――シャープール1世の碑文","l":"sasanian","x":"イランのナクシェ・ロスタムには、アケメネス朝の王たちの墓が刻まれた断崖の前に、「ゾロアスターのカアバ」と呼ばれる石造りの塔が立っている。その壁に、シャープール1世は、自らの業績を、"},{"id":"sasanian-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"日本にあったマニ教の絵","l":"sasanian","x":"2000年代に入って、日本に伝わる中国製の絵画の中に、マニ教の絵画が含まれていることが、研究者によって次々に明らかにされた。山梨県の栖雲寺に「虚空蔵菩薩」の画像として伝わってきた元"},{"id":"sasanian-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"チェスはインドからペルシアへ","l":"sasanian","x":"チェスの起源は、6世紀ごろのインドの「チャトランガ」というゲームだと考えられている。ササン朝の時代の中世ペルシア語の物語によれば、インドの王がホスロー1世のもとにチェスを送り、その"},{"id":"sasanian-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"亡命してきたギリシアの哲学者たち","l":"sasanian","x":"529年、ユスティニアヌス帝は、異教の哲学を教えることを禁じた。アテネのアカデメイア（プラトンが開いた学園の流れをくむ学校）の最後の学頭ダマスキオスや、アリストテレスの注釈で知られ"},{"id":"sasanian-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「彼らの国が、ずたずたに引き裂かれるように」――破り捨てられた手紙","l":"sasanian","x":"イスラームの伝承によれば、預言者ムハンマドは、628年ごろ、周辺の国々の君主たちに手紙を送り、イスラームに入るよう呼びかけた。ササン朝の王ホスロー2世のもとにも、使者が手紙を届けた"},{"id":"sasanian-t6","k":"now","f":"now","kj":"いま","t":"失われゆくカナート","l":"sasanian","x":"イランには、現在も数万本のカナートがあるといわれ、2016年には、11本の代表的なカナートが「ペルシアのカナート」として世界遺産に登録された。しかし、20世紀後半から、動力ポンプを"},{"id":"sasanian-t7","k":"works","f":"works","kj":"作品","t":"ササン朝にまつわる作品","l":"sasanian","x":"フィルドゥーシー『シャー＝ナーメ（王書）』（1010年完成）：神話の時代からササン朝の滅亡までのイランの王たちの歴史を、約5万の対句で歌った叙事詩。狩りの名手として知られる王バフラ"},{"id":"scientific-revolution-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ティコ・ブラーエの奇妙な宮廷","l":"scientific-revolution","x":"ティコの島の天文台には、ジェップという名の小人の道化がいて、食事の席でテーブルの下に座っていた。ティコは、ジェップには予知能力があると信じていたという。また、ティコは、飼っていたヘ"},{"id":"scientific-revolution-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"最後の魔術師","l":"scientific-revolution","x":"ニュートンは、気難しく、論争好きな人物であった。微分積分法をどちらが先に発見したかをめぐって、ドイツのライプニッツと激しく争い、王立協会の会長として、自分に有利な調査報告書を、自分"},{"id":"scientific-revolution-t3","k":"now","f":"now","kj":"いま","t":"日本に届いた科学革命","l":"scientific-revolution","x":"鎖国の時代の日本にも、科学革命の成果は、長崎のオランダ商館を通じて伝わった（→「江戸幕府と東アジアの国際関係」の回）。1774年、杉田玄白らは、オランダ語の解剖書を翻訳して『解体新"},{"id":"scientific-revolution-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"scientific-revolution","x":"魚豊『チ。―地球の運動について―』（漫画、2020〜2022年連載、アニメ2024〜2025年）：15世紀のヨーロッパを思わせる「P国」を舞台に、異端とされた地動説を命がけで受け継"},{"id":"scramble-africa-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「リヴィングストン博士でいらっしゃいますか？」","l":"scramble-africa","x":"スタンリーは、村人に囲まれて立つ、やせた白人の老人の前に進み出て、帽子を取り、こう言ったという。「リヴィングストン博士でいらっしゃいますか？（Dr. Livingstone, I "},{"id":"scramble-africa-t2","k":"source","f":"src","kj":"史料｜記録","t":"「山や川をあげたりもらったり」","l":"scramble-africa","x":"1890年、イギリスの首相ソールズベリは、ドイツとの間でアフリカの境界を取り決めた後の演説で、こう語った。原文…… we have been engaged in drawing "},{"id":"scramble-africa-t3","k":"voice","f":"src","kj":"史料｜証言","t":"娘の手と足――コンゴ自由国のゴム","l":"scramble-africa","x":"コンゴ自由国では、野生のゴムの採集の割り当てを果たせなかった村に、レオポルド2世の私兵が報復を加えた。兵士たちは、弾丸を無駄に使っていないことを証明するために、殺した相手の右手を切"},{"id":"scramble-africa-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ゴードンの最期","l":"scramble-africa","x":"1885年1月26日、10か月近い包囲の末に、マフディーの軍はハルツームに突入した。ゴードンは殺され、その首はマフディーのもとに届けられた。イギリスの救援部隊の汽船がハルツームに着"},{"id":"scramble-africa-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"担架を運んだガンディー","l":"scramble-africa","x":"南アフリカ戦争の戦場で、インド人の担架運搬部隊を組織して、負傷兵の救護にあたった一人の若いインド人の弁護士がいた。モーハンダース・ガンディーである。彼は、当時、南アフリカのインド人"},{"id":"scramble-africa-t6","k":"view","f":"think","kj":"考える｜別の視点","t":"遠い国の「先輩」日本","l":"scramble-africa","x":"アドワの戦いの9年後、日本がロシアを破ると、エチオピアの知識人たちは、日本に強い関心を寄せた。日本は、ヨーロッパの国ではないのに近代化に成功し、ヨーロッパの大国を打ち破った「手本」"},{"id":"scramble-africa-t7","k":"now","f":"now","kj":"いま","t":"返還された頭蓋骨","l":"scramble-africa","x":"2011年以降、ドイツの大学などに保管されていたヘレロやナマの人々の頭蓋骨が、何度かに分けてナミビアに返還された。返還式では、ナミビアの代表団が、ドイツ政府に正式な謝罪と補償を求め"},{"id":"scramble-africa-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"空から落とされた最初の爆弾","l":"scramble-africa","x":"1911年、イタリアは、オスマン帝国の領土であったリビアを奪うため、イタリア＝トルコ戦争を起こした。この戦争の11月1日、イタリア軍の飛行士ガヴォッティは、偵察飛行の途中、トリポリ"},{"id":"scramble-africa-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"scramble-africa","x":"コンラッド『闇の奥』（小説、1899年）：コンゴ川をさかのぼった船乗りが、奥地で象牙を集める謎の人物クルツに出会う物語。レオポルド2世のコンゴ自由国の実態が背景にある。映画『地獄の"},{"id":"seljuk-t1","k":"source","f":"src","kj":"史料｜記録","t":"「国は不信仰でも続くが、不正では続かない」――ニザーム・アルムルクの格言","l":"seljuk","x":"セルジューク朝の名宰相ニザーム・アルムルクは、晩年、スルタンのマリク・シャーの求めに応じて、君主の心得を説いた『統治の書（スィヤーサト・ナーメ）』を著した。そこには、正しい統治をめ"},{"id":"seljuk-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"天文学者ウマル・ハイヤームの暦","l":"seljuk","x":"マリク・シャーは、詩人として知られるウマル・ハイヤームら天文学者を集めて、イスファハーンに天文台を建て、新しい暦をつくらせた。1079年に採用されたこの暦（ジャラーリー暦）は、太陽"},{"id":"seljuk-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「アサシン」と「山の老人」","l":"seljuk","x":"十字軍の時代、シリアのニザール派の拠点の城も、要人の暗殺で恐れられた。ヨーロッパの人々は、彼らを「アサシン」と呼んだ。この言葉は、英語やフランス語の「暗殺者（assassin）」の"},{"id":"seljuk-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"東方のキリスト教徒の王","l":"seljuk","x":"カトワーンの戦いの知らせは、遠く十字軍の国々にも届いた。セルジューク朝を破ったのは、東方のどこかにいるキリスト教徒の王だといううわさが広まった。1145年、ドイツの年代記作家フライ"},{"id":"seljuk-t5","k":"works","f":"works","kj":"作品","t":"トルコ人の進出とセルジューク朝にまつわる作品","l":"seljuk","x":"ニザーム・アルムルク『統治の書』：名宰相がスルタンのために、統治の心得を、歴史上の逸話とともに説いた書。日本語訳がある（井谷鋼造・稲葉穣訳、岩波書店）。ウマル・ハイヤーム『ルバイヤ"},{"id":"shang-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「商人」という言葉の由来","l":"shang","x":"「商人」という言葉は、殷（商）が周に滅ぼされたあと、土地を失った商の遺民たちが各地を行き来して物を売り買いするようになったため、商売をする人を「商の人」と呼ぶようになったことに由来"},{"id":"shang-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"将軍となった王妃――婦好","l":"shang","x":"1976年、殷墟の宮殿区の近くで、盗掘を免れた墓が見つかった。そこからは、青銅器約460点、玉器約750点、子安貝約6800枚など、ぜいたくな副葬品が出土した。青銅器の多くに「婦好"},{"id":"shang-t3","k":"source","f":"src","kj":"史料｜記録","t":"甲骨文を読む","l":"shang","x":"甲骨文には、殷の王たちの生活が生々しく記録されている。ある甲骨では、王の妃・婦好の出産について占っている。原文甲申卜，㱿貞：婦好娩，嘉？王占曰：其惟丁娩，嘉；其惟庚娩，引吉。三旬又"},{"id":"shang-t4","k":"source","f":"src","kj":"史料｜記録","t":"「雨は西から来るか、東から来るか」――甲骨の占い","l":"shang","x":"殷の王は、天気や収穫、戦争、病気、出産など、あらゆることを、甲骨を焼いて占った。殷墟から出土した亀の甲羅の一枚には、雨について、こんな占いの言葉が刻まれている。原文癸卯卜：今日雨。"},{"id":"shang-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"重さ833kgの「鼎」","l":"shang","x":"殷墟から出土した青銅器のうち、最大のものが「后母戊鼎」（かつては「司母戊鼎」と読まれた）である。鼎は、三本または四本の足をもつ煮炊き用の器で、祭祀の中心となる器だった。この鼎は高さ"},{"id":"shang-t6","k":"now","f":"now","kj":"いま","t":"三星堆――もう一つの青銅器文明","l":"shang","x":"1986年、四川省広漢市の三星堆遺跡で、大量の青銅器や玉器、象牙を埋めた二つの穴が見つかった。中には、目が筒のように大きく飛び出した幅1.38mの巨大な仮面、金箔の仮面をつけた人頭"},{"id":"shang-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「暴君」紂王の姿","l":"shang","x":"夏の桀王と殷の紂王は、中国の歴史で「暴君」の代名詞とされる。しかし、二人の悪行の話はよく似ている。どちらも美しい女性におぼれ、酒の池を作り、忠臣を殺した、というのである。これは、新"},{"id":"shang-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"shang","x":"『封神演義』：明代に書かれた小説で、殷の紂王と妲己の暴政、周の武王による殷の打倒（殷周革命）を、仙人や妖怪が入り乱れる壮大な神話の戦いとして描く。日本では藤崎竜による漫画（1996"},{"id":"silk-road-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"東西交易の3つの道","l":"silk-road","x":"道経路担い手主な特色草原の道（ステップ＝ルート）モンゴル高原から、カザフ草原・南ロシアの草原を通って黒海北岸へスキタイ・匈奴などの騎馬遊牧民最も古い。騎馬遊牧民の移動とともに、青銅"},{"id":"silk-road-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"タクラマカン砂漠の名前","l":"silk-road","x":"「タクラマカン」の名前は、ウイグル語で「入ったら出られない」という意味だ、とよく説明される。しかし、この語源には確かな根拠はなく、「廃墟の場所」「ポプラの森の場所」など、さまざまな"},{"id":"silk-road-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"西域の主なオアシス都市","l":"silk-road","x":"漢代の名現在の地名道特色楼蘭（のちに鄯善）ロプ＝ノール湖畔（遺跡）南道の入口4世紀ごろ水源の変化などで衰退し、砂に埋もれた于闐ホータン南道玉の産地。のちに仏教の中心地亀茲クチャ北道"},{"id":"silk-road-t4","k":"source","f":"src","kj":"史料｜記録","t":"張騫の報告","l":"silk-road","x":"原文大宛在匈奴西南，在漢正西，去漢可萬里。其俗土著，耕田，田稻麥。現代語訳大宛は、匈奴の西南、漢のまっすぐ西にあり、漢から1万里ほど離れています。その風俗は、定住して田を耕し、稲や"},{"id":"silk-road-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「胡」のつく食べ物","l":"silk-road","x":"張騫の旅ののち、西方から中国にさまざまな植物や産物が伝わった。『史記』は、漢の使者が、大宛からぶどうと、馬の飼料となるうまごやし（苜蓿、もくしゅく）の種を持ち帰り、離宮の周りに植え"},{"id":"silk-road-t6","k":"now","f":"now","kj":"いま","t":"懸泉置――2000年前の駅の記録","l":"silk-road","x":"1990年から1992年にかけて、敦煌の東の懸泉置という、漢代の駅（公用の宿泊・通信施設）の遺跡が発掘され、2万3000枚を超える木簡などが見つかった。そこには、公文書の伝達の記録"},{"id":"silk-road-t7","k":"source","f":"src","kj":"史料｜記録","t":"虎穴に入らずんば虎子を得ず","l":"silk-road","x":"73年、班超は、わずか36人の部下を連れて、楼蘭の後身の鄯善国に使者として赴いた。鄯善の王は、はじめ班超を手厚くもてなしたが、やがて態度が冷たくなった。北匈奴の使者が来ていたのであ"},{"id":"silk-road-t8","k":"source","f":"src","kj":"史料｜記録","t":"甘英はなぜ引き返したのか","l":"silk-road","x":"甘英は、安息（パルティア）を通って、条支の国の西の海辺に達した。そこで、海を渡ろうとすると、安息の西の境の船乗りが、甘英に言った。原文海水廣大，往來者逢善風三月乃得度，若遇遲風，亦"},{"id":"silk-road-t9","k":"source","f":"src","kj":"史料｜記録","t":"ローマ人の絹の知識","l":"silk-road","x":"原文Seres lanicio silvarum nobiles, perfusam aqua depectentes frondium canitiem. ……現代語訳セレス人は"},{"id":"silk-road-t10","k":"confuse","f":"confuse","kj":"混同注意","t":"シルクロードを行き交ったもの","l":"silk-road","x":"方向主な物産文化・宗教東から西へ絹・絹織物、漆器、鉄器、のちに紙の製法・陶磁器漢字文化（西域の役所の文書）、のちに製紙法西から東へ馬（汗血馬）、ぶどう・うまごやし、ガラス器、玉（于"},{"id":"silk-road-t11","k":"now","f":"now","kj":"いま","t":"タリム盆地のミイラの正体","l":"silk-road","x":"「楼蘭の美女」をはじめとする、タリム盆地の青銅器時代のミイラは、西方的な顔立ちや毛織物の衣服から、はるか西方から移住してきた人々ではないかと考えられてきた。ところが、2021年に発"},{"id":"silk-road-t12","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"silk-road","x":"NHK特集『シルクロード』（1980〜1981年）：日中共同取材で、それまで外国人の立ち入りが難しかった中国西部の遺跡やオアシス都市を紹介したドキュメンタリー。喜多郎のテーマ音楽と"},{"id":"sino-japanese-war-2-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「地に南北の別なく、年に老幼の別なく」――蔣介石の廬山談話","l":"sino-japanese-war-2","x":"盧溝橋事件の10日後の1937年7月17日、国民政府の指導者蔣介石は、江西省の避暑地廬山で、各界の指導者たちを前に演説した。これまで、共産党との内戦を優先し、日本との全面的な戦争を"},{"id":"sino-japanese-war-2-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"パナイ号事件","l":"sino-japanese-war-2","x":"1937年12月12日、南京の近くの長江で、アメリカ海軍の砲艦パナイ号が、日本の海軍の飛行機に爆撃されて沈没し、乗組員らが死傷した。パナイ号は、南京から避難するアメリカ人を乗せ、甲"},{"id":"sino-japanese-war-2-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「この町で犯されなかった罪は、おそらくない」――ミニー・ヴォートリンの日記","l":"sino-japanese-war-2","x":"1937年12月、南京が陥落した後、市内に残った欧米人たちは、「安全区」をつくって、避難民を守ろうとした。アメリカ人の宣教師で、金陵女子文理学院の教師ミニー・ヴォートリンは、学院に"},{"id":"sino-japanese-war-2-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"北の戦い――ノモンハン","l":"sino-japanese-war-2","x":"日本が中国で戦っている間、北のソ連との国境でも、戦火が上がっていた。1939年5月、満州国とモンゴル人民共和国の国境のノモンハンで、両国の国境警備隊が衝突した。満州国の背後には関東"},{"id":"sino-japanese-war-t1","k":"source","f":"src","kj":"史料｜記録","t":"「脱亜論」","l":"sino-japanese-war","x":"甲申政変の失敗に、深く失望した日本人がいた。金玉均らを支援してきた、慶應義塾の創立者、福沢諭吉である。1885年3月、福沢が主宰する新聞『時事新報』に、「脱亜論」と題する社説が掲載"},{"id":"sino-japanese-war-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"砲弾の中身","l":"sino-japanese-war","x":"黄海海戦で、定遠と鎮遠は、日本艦隊から合わせて数百発の砲弾を浴びながら、沈まなかった。しかし、北洋艦隊の側にも、深刻な問題があった。北洋艦隊の顧問として鎮遠に乗り組んでいたアメリカ"},{"id":"sino-japanese-war-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"眠れる獅子は目覚めたか","l":"sino-japanese-war","x":"日清戦争は、東アジアの歴史の大きな転換点であった。それまで、ヨーロッパの人々の中には、清を、いつか目を覚ます「眠れる獅子」とみなす者が少なくなかった。広大な国土と膨大な人口を持ち、"},{"id":"sino-japanese-war-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"sino-japanese-war","x":"司馬遼太郎『坂の上の雲』（小説、1968〜1972年連載）：松山出身の秋山好古・真之の兄弟と正岡子規を主人公に、明治の日本の近代化と、日清・日露戦争を描いた長編。2009〜2011"},{"id":"six-dynasties-culture-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「五石散」――貴族たちの流行の薬","l":"six-dynasties-culture","x":"魏晋の貴族の間では、「五石散」（寒食散）と呼ばれる鉱物の薬を飲むことが流行した。魏の何晏が飲み始めたといわれ、気分を高揚させ、肌つやをよくする効果があると信じられた。しかし、この薬"},{"id":"six-dynasties-culture-t2","k":"source","f":"src","kj":"史料｜記録","t":"陶淵明「飲酒」其の五","l":"six-dynasties-culture","x":"原文結廬在人境，而無車馬喧。問君何能爾，心遠地自偏。采菊東籬下，悠然見南山。山氣日夕佳，飛鳥相與還。此中有真意，欲辨已忘言。書き下し廬を結んで人境に在り 而も車馬の喧しき無し君に問"},{"id":"six-dynasties-culture-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"『千字文』――1000の字が重ならない詩","l":"six-dynasties-culture","x":"梁の武帝は、皇子たちに書を学ばせるため、王羲之の書いた文字の中から、重ならない1000字を選ばせ、官僚の周興嗣に、それを使って詩を作るように命じた。周興嗣は、1字も重複させずに、4"},{"id":"six-dynasties-culture-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"鳩摩羅什――囚われの翻訳者","l":"six-dynasties-culture","x":"鳩摩羅什（クマーラジーヴァ、344〜413年ごろ）は、亀茲の王族の母と、インドの貴族の家系の父の間に生まれた。幼くして出家し、カシミールなどで学んで、西域に名の知れた高僧となった。"},{"id":"six-dynasties-culture-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"法顕――インドへの15年の旅","l":"six-dynasties-culture","x":"法顕は、中国に伝わっていた仏教の戒律が不完全であることを嘆き、正しい戒律の経典を求めて、399年、仲間とともに長安を出発した。すでに60歳を過ぎていた。一行は、敦煌から砂漠を越えた"},{"id":"six-dynasties-culture-t6","k":"view","f":"think","kj":"考える｜別の視点","t":"「皇帝は如来である」――北と南の仏教","l":"six-dynasties-culture","x":"華北（五胡十六国・北朝）：五胡の君主たちは、仏教を手厚く保護した。異民族の君主にとって、外来の宗教である仏教は、漢人の儒教の価値観に縛られない、新しい権威のよりどころとなった。北魏"},{"id":"six-dynasties-culture-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"達磨と虎渓三笑","l":"six-dynasties-culture","x":"この時代の仏教については、多くの伝説が生まれた。菩提達磨：禅宗の祖とされる菩提達磨は、南インドから海路で中国に来て、梁の武帝に会ったと伝えられる。多くの寺を建て、僧を養ってきた武帝"},{"id":"six-dynasties-culture-t8","k":"confuse","f":"confuse","kj":"混同注意","t":"魏晋南北朝の文化の主な人物と作品","l":"six-dynasties-culture","x":"分野人物時代作品・事績思想竹林の七賢（阮籍・嵇康ら）魏・西晋老荘思想、清談詩陶淵明東晋・宋「帰去来辞」「桃花源記」、田園詩詩謝霊運宋山水詩文学昭明太子梁『文選』文学劉義慶宋『世説新"},{"id":"six-dynasties-culture-t9","k":"works","f":"works","kj":"作品","t":"この時代にまつわる作品と言葉","l":"six-dynasties-culture","x":"「白眼視」：阮籍の「青眼・白眼」の逸話から、人を冷たい目で見ることをいう。「桃源郷」：陶淵明の「桃花源記」から、俗世間を離れた理想郷をいう。元号「令和」：『万葉集』の梅花の歌の序文"},{"id":"slavs-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「スラヴ」と「スレイブ」","l":"slavs","x":"英語で「奴隷」を意味する「スレイブ」（slave）は、「スラヴ人」（Slav）に由来する。9〜10世紀、ヴァイキングやドイツの商人、ユダヤ人の商人たちは、東ヨーロッパで捕らえたスラ"},{"id":"slavs-t2","k":"source","f":"src","kj":"史料｜記録","t":"教皇への106の質問","l":"slavs","x":"866年、ボリス1世は、ローマ教皇ニコラウス1世に、キリスト教徒としての暮らし方について、106の質問を送った。教皇の答えの書簡が残っており、そこからは、新しくキリスト教を受け入れ"},{"id":"slavs-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"キュリロスが作ったのは「キリル文字」ではない","l":"slavs","x":"ロシア語などで使われるキリル文字は、スラヴ人に布教したギリシア人の兄弟キュリロス（コンスタンティノス、827〜869年）と、メトディオスの名にちなむ。しかし、キュリロスが実際に考案"},{"id":"slavs-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"オリガの復讐","l":"slavs","x":"キエフ公イーゴリは、945年、東スラヴの一部族ドレヴリャネ人から、2度目の貢納を取り立てようとして殺された。『原初年代記』は、残された妃オリガの、すさまじい復讐の物語を伝えている。"},{"id":"slavs-t5","k":"now","f":"now","kj":"いま","t":"ヴァーツラフ広場","l":"slavs","x":"プラハの中心にある「ヴァーツラフ広場」には、馬に乗った聖ヴァーツラフの像が立っている。この広場は、チェコの近現代史の重要な舞台となってきた。1918年10月、チェコスロヴァキアの独"},{"id":"slavs-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"slavs","x":"『原初年代記』：キエフ公国の成り立ちと、ウラディミル1世の改宗の物語を伝える年代記。日本語訳に、國本哲男ほか訳『ロシア原初年代記』（名古屋大学出版会）がある。アルフォンス・ミュシャ"},{"id":"socialism-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"海がレモネードになる日","l":"socialism","x":"フーリエの著作には、奇抜な空想がちりばめられていた。彼によれば、人類が理想の社会を実現すれば、地球の気候は穏やかになり、北極の氷は溶け、海の水は塩辛さを失ってレモネードのような味に"},{"id":"socialism-t2","k":"music","f":"music","kj":"音楽","t":"「インターナショナル」","l":"socialism","x":"1871年、パリ・コミューンが政府軍によって鎮圧された直後、その一員であった詩人ウジェーヌ・ポティエは、「起て、飢えたる者よ」と始まる詩を書いた。1888年、北フランスのリールの労"},{"id":"socialism-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"「空想的」と「科学的」","l":"socialism","x":"エンゲルスは、のちに、オーウェンやサン・シモン、フーリエらの社会主義を「空想的社会主義」と呼び、マルクスと自分の社会主義を「科学的社会主義」と呼んで区別した。オーウェンたちは、資本"},{"id":"song-culture-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"泥より出でて染まらず","l":"song-culture","x":"周敦頤は、蓮の花を愛し、「愛蓮説」という短い文章を残した。その中で、彼は蓮を、次のようにたたえている。原文予獨愛蓮之出淤泥而不染，濯清漣而不妖。……蓮，花之君子者也。書き下しわれ独"},{"id":"song-culture-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"門の前に積もった雪","l":"song-culture","x":"程頤の弟子の楊時と游酢は、ある冬の日、師の程頤を訪ねた。程頤は、目を閉じて座ったまま瞑想していた。二人は、師の邪魔をしてはならないと、門の外に立って、師が目を開けるのを静かに待った"},{"id":"song-culture-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「少年老い易く学成り難し」は朱熹の作か","l":"song-culture","x":"「少年老い易く学成り難し、一寸の光陰軽んずべからず」という詩は、日本では長く、朱熹の「偶成」という詩として知られてきた。教科書や辞書にも、朱熹の作として紹介されることが多かった。と"},{"id":"song-culture-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"中国より日本で愛された画僧","l":"song-culture","x":"南宋の末の禅僧牧谿は、墨の濃淡だけで、鳥や猿、果物などを、柔らかく、気品のある筆づかいで描いた。牧谿の絵は、中国の文人たちの間では「粗野で、古い法に従っていない」と評価が低く、中国"},{"id":"song-culture-t5","k":"works","f":"works","kj":"作品","t":"宋代の文化にまつわる作品","l":"song-culture","x":"朱熹『四書集注』：『論語』『孟子』『大学』『中庸』に朱熹が注釈を加えたもの。元から清まで、科挙の基準とされた。沈括『夢渓筆談』：北宋の科学者沈括の随筆集。科学技術から逸話まで、60"},{"id":"song-liao-xixia-t1","k":"source","f":"src","kj":"史料｜記録","t":"夫の墓に納められた右手","l":"song-liao-xixia","x":"阿保機の死後、妻の述律后（述律平）は、実権を握った。『遼史』や『資治通鑑』などによれば、彼女は、自分に従わない有力者たちを次々に呼び出し、「亡き皇帝に、私の言葉を伝えてきなさい」と"},{"id":"song-liao-xixia-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"海を渡った東丹王","l":"song-liao-xixia","x":"皇帝の位を弟に奪われた阿保機の長男耶律倍は、渤海の故地に置かれた東丹国の王とされていたが、弟の監視の下で不遇の日々を送った。耶律倍は、中国の文化を深く愛した人物で、数万巻の書物を集"},{"id":"song-liao-xixia-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「帝羓」――塩漬けにされた皇帝","l":"song-liao-xixia","x":"『新五代史』によれば、耶律徳光が北へ帰る途中で亡くなると、契丹の人々は、遺体を本国まで運ぶために、腹を割いて内臓を取り出し、数斗の塩を詰めた。中国の人々は、これを「帝羓（皇帝の干し"},{"id":"song-liao-xixia-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「キタイ」から「キャセイ」へ","l":"song-liao-xixia","x":"契丹は、モンゴル高原から中央アジアまで、広い地域に名を知られた。そのため、中央アジアやイスラーム世界、ヨーロッパの人々は、中国そのものを「契丹（キタイ）」の名で呼ぶようになった。1"},{"id":"song-liao-xixia-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"楊家将の物語","l":"song-liao-xixia","x":"遼との戦いで命を落とした楊業と、その息子・孫たちの活躍は、のちに「楊家将」の物語として語り継がれた。明代には小説『楊家将演義』がまとめられ、京劇などの演目として、現在も中国で広く親"},{"id":"song-liao-xixia-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"3本の指","l":"song-liao-xixia","x":"和平の交渉にあたったのは、宋の役人曹利用であった。出発前、真宗は、「やむを得なければ、年に100万までなら出してもよい」と言った。ところが、寇準は、曹利用をひそかに呼びつけ、「陛下"},{"id":"song-liao-xixia-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"天から降ってきた手紙","l":"song-liao-xixia","x":"澶淵の盟は、宋の人々の目には、どのように映ったのか。寇準をねたむ重臣の王欽若は、真宗に、「澶淵の盟は、敵に城の下まで攻め込まれて結ばされた『城下の盟』であり、春秋時代でさえ恥とされ"},{"id":"song-liao-xixia-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"鼻を切られた皇帝","l":"song-liao-xixia","x":"李元昊の最期は、悲惨なものであった。彼は、息子の寧令哥の妻となるはずだった女性を、自分の妃にしてしまった。1048年、恨みを抱いた寧令哥は、宮殿で父に斬りかかり、李元昊の鼻をそぎ落"},{"id":"song-liao-xixia-t9","k":"now","f":"now","kj":"いま","t":"砂に埋もれた町から甦った文字","l":"song-liao-xixia","x":"西夏の文化が再び注目されるようになったのは、20世紀の初めのことである。1908〜09年、ロシアの探検家コズロフは、内モンゴルの砂漠にある西夏の町の遺跡カラ・ホト（黒水城）を発掘し"},{"id":"song-liao-xixia-t10","k":"debate","f":"think","kj":"考える｜諸説あり","t":"宋は「弱い王朝」だったのか","l":"song-liao-xixia","x":"宋は、遼や西夏に毎年多額の銀や絹を贈り、軍事的には北方の国々に勝てなかったことから、長く「弱い王朝」とみなされてきた。のちに金に都を奪われ、最後はモンゴルに滅ぼされたことも、その印"},{"id":"song-liao-xixia-t11","k":"works","f":"works","kj":"作品","t":"宋・遼・西夏にまつわる作品","l":"song-liao-xixia","x":"井上靖『敦煌』（1959年）：科挙に落第した宋の青年趙行徳が、西夏の文字に心ひかれて西夏に渡り、李元昊の時代の戦乱の中で、敦煌の莫高窟の経典を守ろうとする物語。1988年に佐藤純彌"},{"id":"song-society-t1","k":"source","f":"src","kj":"史料｜記録","t":"「書中おのずから黄金の屋あり」","l":"song-society","x":"北宋の真宗の作として伝えられる「勧学文」は、勉学の大切さを、次のように説いている伝承。原文富家不用買良田，書中自有千鍾粟。……娶妻莫恨無良媒，書中自有顏如玉。書き下し家を富ますに良"},{"id":"song-society-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"劉備が負けると泣く子ども","l":"song-society","x":"北宋の蘇軾は、次のような話を書き残している。町の子どもたちは、いたずらをして親を困らせると、お金を渡されて、講談を聞きに行かされた。講談師が三国時代の物語を語り、劉備が負ける場面に"},{"id":"song-society-t3","k":"now","f":"now","kj":"いま","t":"海の底からよみがえった南宋の商船","l":"song-society","x":"1987年、中国広東省の沖合の海底で、南宋の時代の商船の沈没船が発見された。「南海Ⅰ号」と名づけられたこの船は、長さ約30 mの木造の大型船で、2007年、船体を泥ごと巨大な鋼鉄の"},{"id":"song-society-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"茶と天目茶碗","l":"song-society","x":"宋の時代には、茶を飲む習慣が、社会のあらゆる層に広まった。茶は塩と並ぶ重要な商品となり、国家の専売とされた。士大夫たちの間では、茶の泡立ちや色を競い合う「闘茶」が流行した。黒い茶碗"},{"id":"song-society-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"宋代は「経済革命」の時代だったのか","l":"song-society","x":"宋の時代の経済の発展は、欧米の研究者の間では、「宋代経済革命」と呼ばれることもある。人口の増加、農業の生産性の向上、石炭と鉄の生産、紙幣の発行、遠隔地交易の発展など、その変化は、1"},{"id":"song-society-t6","k":"works","f":"works","kj":"作品","t":"宋代の社会と経済にまつわる作品","l":"song-society","x":"張択端「清明上河図」：北京の故宮博物院が所蔵する原本は、めったに公開されない。2015年に公開された際には、数時間待ちの長い行列ができた。明や清の時代にも、多くの模写や再創作の作品"},{"id":"south-india-trade-t1","k":"source","f":"src","kj":"史料｜記録","t":"『エリュトゥラー海案内記』が記すムジリス","l":"south-india-trade","x":"ムジリスは、同じ王国（ケーロボトラス＝チェーラの王の国）に属し、アラビアから運ばれた積荷を載せた船や、ギリシア人の船でにぎわっている。……これらの市場の町には、大量でかさばるコショ"},{"id":"south-india-trade-t2","k":"source","f":"src","kj":"史料｜記録","t":"サンガム文学に歌われたムジリス","l":"south-india-trade","x":"原文யவனர் தந்த வினைமாண் நன்கலம்பொன்னொடு வந்து கறியொடு பெயரும்現代語訳ヤヴァナの人々の、見事なつくりの大きな船が、金を積んで"},{"id":"south-india-trade-t3","k":"source","f":"src","kj":"史料｜記録","t":"プリニウスの嘆き","l":"south-india-trade","x":"原文minimaque computatione miliens centena milia sestertium annis omnibus India et Seres et "},{"id":"south-india-trade-t4","k":"now","f":"now","kj":"いま","t":"アリカメードゥとパッタナム――交易の港を掘る","l":"south-india-trade","x":"1940年代、イギリスの考古学者ウィーラーは、インド南東岸のポンディシェリ（プドゥチェリ）近くのアリカメードゥを発掘し、ローマの赤い陶器（アッレティウム陶器）や、ワインを運んだ壺（"},{"id":"south-india-trade-t5","k":"confuse","f":"confuse","kj":"混同注意","t":"紀元前後〜3世紀のインドの主な国々","l":"south-india-trade","x":"クシャーナ朝サータヴァーハナ朝タミル人の三王国地域中央アジア〜西北インド・ガンジス川上流デカン高原南インドの南端部担い手中央アジアから来た遊牧民（大月氏の一派）ドラヴィダ系ドラヴィ"},{"id":"southeast-asia-colonial-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"『マックス・ハーフェラール』","l":"southeast-asia-colonial","x":"1860年、オランダで一冊の小説が出版され、大きな反響を呼んだ。『マックス・ハーフェラール』である。作者の「ムルタトゥーリ」とは、ラテン語で「私は多くを耐え忍んだ」という意味の筆名"},{"id":"southeast-asia-colonial-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"『王様と私』","l":"southeast-asia-colonial","x":"アンナ・レオノーウェンズは、のちに、タイの宮廷での経験を回想録に書いた。この回想録をもとにした小説『アンナとシャム王』（1944年）は、ミュージカル『王様と私』となり、映画化されて"},{"id":"southeast-asia-colonial-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"リサールと日本","l":"southeast-asia-colonial","x":"1888年、ヨーロッパへ向かう途中のリサールは、日本に立ち寄り、約1か月半を東京で過ごした。彼は、日本語を学び、歌舞伎を見物し、日本の人々の清潔さや礼儀正しさに感心した。滞在中、彼"},{"id":"southeast-asia-colonial-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"southeast-asia-colonial","x":"ホセ・リサール『ノリ・メ・タンヘレ（私に触れるな）』（小説、1887年）：スペイン支配の下のフィリピンの社会と、修道士たちの横暴を描いた小説。フィリピンの民族意識を目覚めさせ、作者"},{"id":"southeast-asia-independence-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"独立戦争に加わった日本兵","l":"southeast-asia-independence","x":"日本の敗戦の後、インドネシアには、日本に帰らず、インドネシアの独立戦争に身を投じた日本兵たちがいた。その数は、900人ほどといわれ、その約半数が戦死したり、行方不明になったりした諸"},{"id":"southeast-asia-independence-t2","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"1945年の大飢饉","l":"southeast-asia-independence","x":"ベトナムの独立は、恐ろしい飢饉の中で迎えられた。1944年の末から1945年の春にかけて、ベトナム北部で大飢饉が起こり、40万人から200万人が餓死したといわれる諸説。ベトナム政府"},{"id":"southeast-asia-independence-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"拠点の名は愛人の名？","l":"southeast-asia-independence","x":"ディエンビエンフーのフランス軍の拠点には、ベアトリス、ガブリエル、アンヌ＝マリー、ユゲット、ドミニク、エリアーヌ、クローディーヌ、フランソワーズ、イザベルと、女性の名前がつけられて"},{"id":"southeast-asia-independence-t4","k":"confuse","f":"confuse","kj":"混同注意","t":"東南アジアの独立の相手","l":"southeast-asia-independence","x":"東南アジアの国々は、どの国から、どのようにして独立したのか。組み合わせで整理しておこう。国独立の年旧宗主国独立の形インドネシア1945年宣言、1949年承認オランダ独立戦争ベトナム"},{"id":"southeast-asia-indianized-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"海を渡った人々――台湾からマダガスカルまで","l":"southeast-asia-indianized","x":"オーストロネシア語族の人々の祖先は、約5000年前、台湾から南へ船で渡り始めたと考えられている。彼らは、フィリピン、インドネシアへと島々を渡り、さらに東は太平洋のハワイやイースター"},{"id":"southeast-asia-indianized-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「インド化」は誰が進めたのか","l":"southeast-asia-indianized","x":"20世紀前半、フランスの東洋学者ジョルジュ・セデスは、東南アジアの古代の国々を「インド化された国家」と呼んだ。この見方では、インドから来た商人やバラモンが、東南アジアに文明をもたら"},{"id":"southeast-asia-indianized-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"扶南の建国神話","l":"southeast-asia-indianized","x":"中国の史書『梁書』は、扶南の建国について、次のような話を伝えている伝承。扶南の国は、もとは柳葉という名の女王が治めていた。ある時、南方の国の混塡という男が、夢の中で神から弓を授かり"},{"id":"southeast-asia-indianized-t4","k":"source","f":"src","kj":"史料｜記録","t":"裸の人々に服を――呉の使者と扶南の王","l":"southeast-asia-indianized","x":"『梁書』扶南伝は、康泰と朱応が扶南を訪れた時の様子を、次のように伝えている。原文吳時，遣中郎康泰、宣化從事朱應使於尋國，國人猶裸，唯婦人著貫頭。泰、應謂曰：「國中實佳，但人褻露可怪"},{"id":"southeast-asia-indianized-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"最古のオーストロネシア語の文章","l":"southeast-asia-indianized","x":"ベトナム中部のチャキエウ（チャンパーの古い都の跡）の近くで見つかった碑文は、4世紀ごろに、インド系の文字で、チャム語で刻まれている。これは、オーストロネシア語族の言葉で書かれた、現"},{"id":"southeast-asia-indianized-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"ゼロの記号を探した数学者","l":"southeast-asia-indianized","x":"カンボジアのメコン川のほとりのサンボー（サンボー・プレイ・クックとは別の地）で、1891年、フランスの調査団によって、一つの石碑が発見された。碑文は古クメール語で書かれ、末尾に、寄"},{"id":"southeast-asia-indianized-t7","k":"source","f":"src","kj":"史料｜記録","t":"長安で演じられたピューの音楽","l":"southeast-asia-indianized","x":"802年、ピュー（驃国）の王は、王子に、楽人35人と12曲の音楽を携えさせて、唐の長安に送った。この「驃国楽」は、長安の人々に珍しがられた。唐の詩人白居易は、その音楽を題材に、「驃"},{"id":"southeast-asia-indianized-t8","k":"source","f":"src","kj":"史料｜記録","t":"シュリーヴィジャヤの碑文","l":"southeast-asia-indianized","x":"パレンバンの近くのクドゥカン・ブキットで1920年に見つかった石碑には、682〜683年（シャカ暦605年）に、「ダプンタ・ヒャン」という王が、2万の兵を率いて、船で遠征に出発し、"},{"id":"southeast-asia-indianized-t9","k":"source","f":"src","kj":"史料｜記録","t":"義浄が見たシュリーヴィジャヤ","l":"southeast-asia-indianized","x":"義浄は、シュリーヴィジャヤについて、次のように記している。原文佛逝……城中僧眾千餘，學問為懷，並多行鉢，所有尋讀，乃與中國不殊。……若其高僧欲向西方為聽讀者，停斯一二載，習其法式，"},{"id":"southeast-asia-indianized-t10","k":"trivia","f":"side","kj":"こぼれ話","t":"道に落ちた金の袋――訶陵の女王","l":"southeast-asia-indianized","x":"シュリーヴィジャヤが台頭した頃、ジャワ島中部には、中国の史書が「訶陵」と記す国があった。『新唐書』は、7世紀後半にこの国を治めた女王「悉莫」（シーマ）について、次のような話を伝えて"},{"id":"southeast-asia-indianized-t11","k":"trivia","f":"side","kj":"こぼれ話","t":"浮き彫りの船と、アフリカへの航海","l":"southeast-asia-indianized","x":"ボロブドゥールの浮き彫りの中には、複数の帆を張り、船体の両側に浮き（アウトリガー）をつけた大きな船が描かれたものがある。8〜9世紀の東南アジアの外洋船の姿を伝える貴重な資料である。"},{"id":"southeast-asia-indianized-t12","k":"trivia","f":"side","kj":"こぼれ話","t":"火山灰に埋もれた遺跡","l":"southeast-asia-indianized","x":"10世紀前半、ジャワ島の政治の中心は、中部から東部へと移った。その理由として、ジャワ島中部のムラピ山の大噴火などの自然災害があったとする説がある諸説。ボロブドゥールは、しだいに忘れ"},{"id":"southeast-asia-indianized-t13","k":"now","f":"now","kj":"いま","t":"現代の東南アジアと古代の遺産","l":"southeast-asia-indianized","x":"現代の東南アジアの国々にとって、古代の国家や遺跡は、国の誇りの象徴となっている。カンボジアの国旗には、アンコール＝ワットが描かれている。インドネシアは、シュリーヴィジャヤやマジャパ"},{"id":"southeast-asia-indianized-t14","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品・関連する文化","l":"southeast-asia-indianized","x":"ワヤン・クリ（影絵芝居）：インドネシアのジャワ島やバリ島の伝統的な影絵芝居。『ラーマーヤナ』や『マハーバーラタ』の物語を演じる。2003年、ユネスコの「人類の口承及び無形遺産の傑作"},{"id":"sovereign-states-t1","k":"war","f":"deep","kj":"深掘り｜戦術","t":"火縄銃が変えた戦場","l":"sovereign-states","x":"パヴィアの戦いで、フランス軍の騎士たちを倒したのは、スペインの火縄銃兵（アルケブス兵）であった。ペスカーラ侯は、火縄銃兵を、森や生け垣の中に散らばらせ、身軽に動き回りながら、近距離"},{"id":"sovereign-states-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"祝宴の槍試合","l":"sovereign-states","x":"カトー・カンブレジ条約では、和平のしるしとして、アンリ2世の娘エリザベートが、スペイン王フェリペ2世と結婚することが定められた。1559年6月30日、パリでは、この結婚を祝う盛大な"},{"id":"soviet-union-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"2＋2＝5","l":"soviet-union","x":"第1次五か年計画の時代、ソ連のポスターには、こんな不思議な計算式が大きく描かれた。「2＋2＝5」。5年の計画を、労働者の熱意で4年で達成しよう、という意味である。数学の常識さえ、党"},{"id":"soviet-union-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"「飢饉はない」と書いた記者","l":"soviet-union","x":"1933年3月、ウェールズ出身の若い記者ガレス・ジョーンズは、外国人の立ち入りを禁じられていたウクライナの村々を、ひそかに歩いて回った。帰国した彼は、ベルリンで記者会見を開き、ソ連"},{"id":"soviet-union-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「コーバ、なぜ私の死が必要なのか」","l":"soviet-union","x":"ブハーリンは、かつてレーニンが「党の寵児」と呼んだ理論家であった。スターリンとも、長く親しい友人であった。1937年に逮捕されたブハーリンは、獄中から、スターリンに何通もの手紙を書"},{"id":"soviet-union-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"消された国勢調査","l":"soviet-union","x":"1937年1月、ソ連で国勢調査が行われた。スターリンは、その3年前の党大会で、ソ連の人口は1億6800万人に達したと誇らしげに述べていた。社会主義の建設とともに、人口は順調に増えて"},{"id":"soviet-union-t5","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"白海運河と、たばこの箱","l":"soviet-union","x":"1931年から33年にかけて、北のカレリア地方で、白海とバルト海を結ぶ全長約230キロの運河が、わずか20か月で建設された。働かされたのは、10万人を超える収容所の囚人たちであった"},{"id":"soviet-union-t6","k":"person","f":"deep","kj":"深掘り｜人物","t":"独裁者の家族――スターリンの家庭","l":"soviet-union","x":"スターリンの最初の妻エカテリーナは、結婚の翌年の1907年、病気で亡くなった。幼なじみの回想によれば、葬儀でスターリンは、「この人は、私の石のような心を和らげてくれた。彼女が死んで"},{"id":"soviet-union-t7","k":"person","f":"deep","kj":"深掘り｜人物","t":"雪の国境を越えた二人","l":"soviet-union","x":"1938年1月3日、雪の積もる樺太（サハリン）の、日本とソ連の国境。日本の人気女優の岡田嘉子と、演出家の杉本良吉の二人が、国境の警備の見回りに来たと偽って、そりで国境に近づき、その"},{"id":"soviet-union-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"soviet-union","x":"ソルジェニーツィン『イワン・デニーソヴィチの一日』（小説、1962年）：スターリン時代の強制収容所（ラーゲリ）の囚人の、ある1日を淡々と描いた小説。作者自身の収容所体験にもとづく。"},{"id":"spanish-flu-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「ハエのように死んでいく」――軍の病院から","l":"spanish-flu","x":"1918年9月、アメリカ東部のボストン近郊の陸軍基地キャンプ・デヴェンスでは、スペイン風邪の第2波が猛威をふるっていた。基地の病院で働く一人の医師は、友人への手紙にこう書いた。原文"},{"id":"spanish-flu-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「彼らが窒息するまで、空気を求めて苦しむだけだ」――デヴンス基地の医師の手紙","l":"spanish-flu","x":"1918年9月、アメリカのボストンに近い陸軍のデヴンス基地では、インフルエンザが猛威を振るい、1日に100人もの兵士が死んでいた。基地の病院で働いていた医師が、友人に宛てて書いた手"},{"id":"spanish-flu-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"芸術座の悲劇","l":"spanish-flu","x":"1918年11月、近代演劇の指導者として知られた 島村抱月 が、スペイン風邪による肺炎で、47歳で急死した。抱月は、女優の松井須磨子とともに劇団「芸術座」を率い、トルストイの『復活"},{"id":"spring-autumn-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"春秋の五覇","l":"spring-autumn","x":"春秋時代の代表的な5人の覇者を「春秋の五覇」という。ただし、だれを数えるかについては、古くから複数の説がある諸説。覇者国主な事績桓公斉管仲を登用。葵丘の会盟（前651年）で最初の覇"},{"id":"spring-autumn-t2","k":"source","f":"src","kj":"史料｜記録","t":"鼎の軽重を問う","l":"spring-autumn","x":"前606年、楚の荘王は、兵を率いて周の都洛邑の郊外まで進み、周の王の使者・王孫満に、周の王室に伝わる九つの鼎の大きさと重さを尋ねた。鼎は、王権の象徴であった。王孫満は答えた。原文在"},{"id":"spring-autumn-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"臥薪嘗胆","l":"spring-autumn","x":"呉王闔閭は、越との戦いで受けた傷がもとで亡くなった。その子の夫差は、父の仇を忘れないよう、薪の上に寝て（臥薪）自分を奮い立たせ、ついに越王勾践を破った。敗れた勾践は、許されて国に帰"},{"id":"spring-autumn-t4","k":"voice","f":"src","kj":"史料｜証言","t":"長平――40万人の降兵","l":"spring-autumn","x":"前260年、秦と趙の軍は、長平（現在の山西省）でにらみ合った。秦の将軍白起は、趙軍を包囲して補給を断った。46日間食べ物を断たれた趙の兵士たちは、ひそかに殺し合い、仲間の肉を食べた"},{"id":"spring-autumn-t5","k":"source","f":"src","kj":"史料｜記録","t":"斉の都・臨淄のにぎわい","l":"spring-autumn","x":"原文臨淄之中七萬戶……臨淄甚富而實，其民無不吹竽鼓瑟、擊筑彈琴、鬥雞走犬、六博蹹踘者。 ……現代語訳臨淄の町の中には、7万戸がある。……臨淄はたいへん豊かで充実しており、その住民で"},{"id":"spring-autumn-t6","k":"confuse","f":"confuse","kj":"混同注意","t":"戦国時代の青銅貨幣","l":"spring-autumn","x":"貨幣形主に使われた地域刀銭（刀貨）小刀の形斉・燕（東方・北方）布銭（布貨）農具の鋤の形韓・魏・趙（中原）蟻鼻銭（ぎびせん）子安貝の形をまねた小さな貨幣。表の文字が蟻の顔や鼻に見える"},{"id":"spring-autumn-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"端午の節句とちまき","l":"spring-autumn","x":"端午の節句（もとは旧暦5月5日）に、ちまきを食べる習慣は、屈原に由来するとする話がある。屈原が汨羅の川に身を投げた日が旧暦の5月5日であり、人々が、屈原の遺体が魚に食べられないよう"},{"id":"spring-autumn-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"spring-autumn","x":"宮城谷昌光の歴史小説：『夏姫春秋』（直木賞、1991年）、『重耳』（晋の文公の物語）、『管仲』など、春秋・戦国時代の人物を主人公とする作品を数多く書いている。『春秋左氏伝』『史記』"},{"id":"steppe-early-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「インド＝ヨーロッパ」の言葉と馬","l":"steppe-early","x":"戦車の広がりは、インド＝ヨーロッパ語族の言葉の広がりと重なっていると考えられている。ヒッタイトの文書に残るミタンニ出身のキックリの馬の調教の手引きに、古代インドの言葉とそっくりの数"},{"id":"steppe-early-t2","k":"confuse","f":"confuse","kj":"混同注意","t":"遊牧民の「民族」を整理する","l":"steppe-early","x":"草原に現れた騎馬遊牧民は、時代によって、話す言葉も系統も異なる。時代主な遊牧民言語の系統（推定）活動した地域前8〜前3世紀スキタイ、サカ、サルマタイイラン系（インド＝ヨーロッパ語族"},{"id":"steppe-early-t3","k":"source","f":"src","kj":"史料｜記録","t":"鳥、ネズミ、カエル、5本の矢","l":"steppe-early","x":"前513年ごろ、アケメネス朝のダレイオス1世は、大軍を率いてボスポラス海峡を渡り、ドナウ川を越えてスキタイの地に攻め込んだ。しかしスキタイは決戦を避け、井戸を埋め、草を焼き払いなが"},{"id":"steppe-early-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"麻の蒸し風呂","l":"steppe-early","x":"ヘロドトスは、スキタイの人々の奇妙な習慣を伝えている。死者を葬ったあと、彼らは3本の棒を立ててフェルトで覆った小さなテントを作り、その中で真っ赤に焼いた石の上に麻（大麻）の種を投げ"},{"id":"steppe-early-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"アマゾネスは実在したか","l":"steppe-early","x":"ギリシア神話には、「アマゾネス」と呼ばれる女性だけの戦士の部族が登場する。ヘロドトスは、スキタイの若者たちがアマゾネスと結婚して生まれたのが、東の遊牧民サウロマタイ（サルマタイ）だ"},{"id":"steppe-early-t6","k":"now","f":"now","kj":"いま","t":"戦争に翻弄されるスキタイの黄金","l":"steppe-early","x":"2014年、クリミア半島の4つの博物館が所蔵するスキタイの黄金などの文化財が、オランダのアムステルダムの博物館で展示されていた。展示中に、ロシアがクリミア半島を一方的に併合した。文"},{"id":"steppe-early-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"氷に閉じ込められた入れ墨","l":"steppe-early","x":"アルタイ山脈の高地のパジリク古墳群（前5〜前3世紀）では、墓の中に入り込んだ水が凍り、そのまま永久凍土のように氷に閉ざされていた。そのため、ふつうなら腐ってしまう木材やフェルト、毛"},{"id":"steppe-early-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「騎馬民族征服王朝説」","l":"steppe-early","x":"1948年、日本の考古学者・江上波夫は、東北アジアの騎馬民族が朝鮮半島を経て日本列島に渡り、4〜5世紀ごろに大和の王権を打ち立てた、という「騎馬民族征服王朝説」を発表した。古墳時代"},{"id":"sui-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"科挙はいつ始まったのか","l":"sui","x":"科挙の始まりを何年とするかについては、研究者の間で意見が分かれている諸説。587年説：文帝が、各州から毎年3人を推薦させて試験を行った年。598年説：文帝が、「志行修謹」「清平幹済"},{"id":"sui-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"一箭双鵰","l":"sui","x":"長孫晟は、弓の名手であった。北周の使者として突厥に滞在していたとき、突厥の摂図（のちの沙鉢略可汗）とともに狩りに出かけた。空で2羽の鷲が肉を奪い合っているのを見た摂図が、長孫晟に2"},{"id":"sui-t3","k":"now","f":"now","kj":"いま","t":"今も働く大運河","l":"sui","x":"大運河は、隋の滅亡後も、唐・宋・元・明・清の各王朝にとって、江南の米を都に運ぶ生命線であった。元の時代には、都の大都（北京）まで直接結ぶ経路に改められ、現在の京杭大運河（北京〜杭州"},{"id":"sui-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"木に巻かれた絹","l":"sui","x":"610年の正月、煬帝は、洛陽に集まった西域の商人や使節たちに、隋の豊かさを見せつけようとした。洛陽の大通りでは、1か月にわたって、各地から集めた芸人たちが歌舞や曲芸を披露し、その演"},{"id":"sui-t5","k":"source","f":"src","kj":"史料｜記録","t":"「日出づる処の天子」","l":"sui","x":"607年、倭国の使者小野妹子は、煬帝に国書を差し出した。『隋書』倭国伝は、その様子を次のように記している。原文大業三年，其王多利思比孤遣使朝貢。使者曰：「聞海西菩薩天子重興佛法，故"},{"id":"sui-t6","k":"person","f":"deep","kj":"深掘り｜人物","t":"乙支文徳――朝鮮の救国の英雄","l":"sui","x":"乙支文徳は、高句麗の将軍で、その生い立ちはほとんどわかっていない。『三国史記』は、「沈着で知略に富み、文章も書けた」と記している。乙支文徳が隋の将軍于仲文に送った五言の詩は、朝鮮半"},{"id":"sui-t7","k":"source","f":"src","kj":"史料｜記録","t":"「遼東に向かって無駄死にするな」","l":"sui","x":"王薄が作ったとされる「無向遼東浪死歌」は、次のように歌う。原文長白山前知世郎，純著紅羅錦背襠。長矟侵天半，輪刀耀日光。上山喫獐鹿，下山喫牛羊。忽聞官軍至，提刀向前蕩。譬如遼東死，斬"},{"id":"sui-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"煬帝は暴君だったのか","l":"sui","x":"「煬」という諡（おくりな、死後の称号）は、唐の朝廷が贈ったもので、「天に逆らい民を虐げる」といった悪い意味を持つ。唐は、隋を倒したことを正当化するため、煬帝を暴君として描いた。中国"},{"id":"sui-t9","k":"works","f":"works","kj":"作品","t":"隋にまつわる作品","l":"sui","x":"『隋唐演義』（清代の褚人穫の小説）：隋の末期から唐の玄宗の時代までを描いた歴史小説。隋末の群雄や、唐の建国の英雄たちの活躍が語られる。『隋煬帝艶史』（明代の小説）：煬帝の遊興を描い"},{"id":"suleiman-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ピーリー・レイスの地図","l":"suleiman","x":"1929年、イスタンブルのトプカプ宮殿の図書館で、一枚の古い地図の断片が見つかった。羊皮紙に描かれたこの地図には、アフリカの西岸、大西洋、そして南北アメリカの東岸が描かれていた。作"},{"id":"suleiman-t2","k":"source","f":"src","kj":"史料｜記録","t":"「ひげを剃っただけだ」","l":"suleiman","x":"しかし、レパントの敗北は、オスマン帝国にとって致命的な打撃ではなかった。オスマン帝国は、ひと冬のうちに、新たに200隻もの艦隊を建造したといわれる。そして、その前年から攻めていたヴ"},{"id":"suleiman-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"クロワッサンとウィーンのコーヒー","l":"suleiman","x":"第2次ウィーン包囲には、いくつかの有名な「伝説」がまつわっている。一つは、クロワッサンの起源である。夜明け前に働いていたウィーンのパン職人たちが、オスマン軍が地下道を掘る音に気づい"},{"id":"suleiman-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"suleiman","x":"ドラマ『オスマン帝国外伝～愛と欲望のハレム～』（トルコ、2011〜2014年）：スレイマン1世と、奴隷から皇后となったヒュッレム（ロクセラーナ）を中心に、ハレムの権力争いを描いたド"},{"id":"sumer-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"「肥沃な三日月地帯」と「メソポタミア」","l":"sumer","x":"前の部で見た「肥沃な三日月地帯」は、雨水だけで麦が育つ丘陵地帯を中心とする広い地域で、最初に農耕が始まった場所である。一方、メソポタミア南部は、雨が少なく、灌漑なしでは農業ができな"},{"id":"sumer-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"世界最古の「給料」はビールとパン","l":"sumer","x":"ウルクの遺跡からは、「面取り縁鉢（ベヴェルド・リム・ボウル）」と呼ばれる、粗末な作りの土器の鉢が大量に見つかっている。どれもほぼ同じ大きさで、型で量産されたものらしい。これは、神殿"},{"id":"sumer-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"最古の文字の記録はビールの帳簿だった","l":"sumer","x":"「文字の発明」というと、詩や神話、王の功績を記すために生まれたと考えたくなるが、現実はもっと地味である。ウルクで見つかった初期の粘土板の約85パーセントは、麦やビール、家畜、労働者"},{"id":"sumer-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"書記学校の生徒はつらかった","l":"sumer","x":"楔形文字は何百もの記号からなり、覚えるのは大変だった。そこで、書記を養成する学校が作られた。シュメール語で「エドゥバ（粘土板の家）」という。生徒は、朝から晩まで粘土板に文字を書き写"},{"id":"sumer-t5","k":"source","f":"src","kj":"史料｜記録","t":"洪水の前に王たちは何万年も統治した――シュメール王名表","l":"sumer","x":"シュメール人は、自分たちの王の一覧表を残している。「シュメール王名表」と呼ばれる文書で、王権が天から降りてきてから、各都市の王が順に統治したことを記している。そこには、「大洪水」の"},{"id":"sumer-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"「自由」という言葉が最初に記された碑文","l":"sumer","x":"前2350年ごろ、ラガシュの王ウルカギナ（ウルイニムギナ）は、役人や神官の横暴を戒める改革を行った。重い税や手数料を引き下げ、借金のために奴隷にされた人々を解放し、孤児や寡婦が有力"},{"id":"sumer-t7","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"王とともに葬られた人々","l":"sumer","x":"ウルの王墓には、衝撃的な発見もあった。ある墓の竪穴（「大死坑」と呼ばれる）には、着飾った女性たちを中心に、74人もの人々が整然と並んで横たわっていた。兵士は武器を持ち、楽師は竪琴の"},{"id":"sumer-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"「ノアの洪水」の地層とアガサ・クリスティ","l":"sumer","x":"ウーリーは、ウルの王墓の下をさらに深く掘り進めたとき、厚さ3メートル近い、遺物をまったく含まない泥の層にぶつかった。ウーリーは興奮して、これこそ聖書の「ノアの洪水」の跡だと発表し、"},{"id":"sumer-t9","k":"source","f":"src","kj":"史料｜記録","t":"『ギルガメシュ叙事詩』の洪水物語","l":"sumer","x":"旅の果てに、ギルガメシュは、かつて大洪水を生き延びて不死を与えられた男ウトナピシュティムに出会う。ウトナピシュティムは、昔、神々が人間を滅ぼすために大洪水を起こそうとしたとき、知恵"},{"id":"sumer-t10","k":"source","f":"src","kj":"史料｜記録","t":"酒場の女主人の忠告","l":"sumer","x":"不死を求めて旅を続けるギルガメシュに、ある酒場の女主人シドゥリはこう語りかけたという（古バビロニア版）。原文Gilgameš ēš tadâlbalāṭam ša tasaḫḫur"},{"id":"sumer-t11","k":"debate","f":"think","kj":"考える｜諸説あり","t":"塩が文明を衰えさせた？","l":"sumer","x":"メソポタミア南部の灌漑農業には、大きな弱点があった。乾燥した土地で畑に水を引き続けると、水が蒸発するときに地中の塩分が地表に残り、少しずつ土地に塩がたまっていく（塩害）。シュメール"},{"id":"sumer-t12","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"sumer","x":"『ギルガメシュ叙事詩』：シュメールの都市ウルクの王ギルガメシュの冒険と、友エンキドゥの死、不死を求める旅を描いた、世界最古級の文学作品。粘土板に楔形文字で記された。TYPE-MOO"},{"id":"swahili-zimbabwe-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"シーラーズから来た王子","l":"swahili-zimbabwe","x":"キルワの町に伝わる16世紀の年代記『キルワ年代記』には、町の始まりについて、こんな話が書かれている。昔、ペルシアのシーラーズの王に、7人の息子がいた。その一人アリーは、アフリカ人の"},{"id":"swahili-zimbabwe-t2","k":"source","f":"src","kj":"史料｜記録","t":"「世界で最も美しい町の一つ」","l":"swahili-zimbabwe","x":"イブン＝バットゥータは、キルワについてこう書いている。キルワは、世界で最も美しく、最もよく建てられた町の一つである。町全体が、優美に造られている。当時のキルワのスルタン、ハサンは、"},{"id":"swahili-zimbabwe-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「アフリカ人に、これほどのものが造れるはずはない」","l":"swahili-zimbabwe","x":"1871年、この遺跡を訪れたドイツの地質学者カール・マウフは、ここは聖書に登場する「シバの女王」の宮殿だと考えた。その後、この地を植民地としたイギリス人たちの間では、大ジンバブエを"},{"id":"swahili-zimbabwe-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"ガマを案内した「海のライオン」？","l":"swahili-zimbabwe","x":"ガマをマリンディからインドへ案内した水先案内人は、アラブの有名な航海者イブン・マージドであった、という話が広く知られている。イブン・マージドは、インド洋の航海術についての書物を書き"},{"id":"taiping-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"男女は別々に","l":"taiping","x":"太平天国は、その理想を実現するために、さまざまな新しい制度をつくった。1853年に定められた「天朝田畝制度」は、すべての土地は神のものであるとして、土地を人々に平等に分け与え、余っ"},{"id":"taiping-t2","k":"source","f":"src","kj":"史料｜記録","t":"「天地開闢以来の名教の大変事」――曽国藩の檄文","l":"taiping","x":"1854年、湘軍を率いて太平天国軍との戦いに出陣するにあたって、曽国藩は、檄文「討粤匪檄」を発した。彼は、太平天国が、キリスト教の神（上帝）だけを崇め、儒教の経典を焼き、孔子の廟を"},{"id":"taiping-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"上海を見た高杉晋作","l":"taiping","x":"1862年、長州藩士の高杉晋作は、江戸幕府が派遣した千歳丸に乗って、上海を訪れた。上海の近くでは、太平軍と清軍・常勝軍との戦いが続いていた。高杉が上海で見たのは、欧米の商人たちが我"},{"id":"tang-culture-t1","k":"source","f":"src","kj":"史料｜記録","t":"大秦景教流行中国碑","l":"tang-culture","x":"781年、長安の大秦寺に、景教の伝来と布教の歴史を記した石碑が建てられた。碑文は、ペルシア出身の僧景浄（アダム）が作ったもので、漢文に加えて、シリア文字で僧たちの名が刻まれている。"},{"id":"tang-culture-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"義浄――海の道を往復した僧","l":"tang-culture","x":"義浄（635〜713年）は、玄奘にあこがれてインドへの旅を志した。671年、広州からペルシア商人の船に乗った義浄は、約20日で東南アジアのスマトラ島のシュリーヴィジャヤに着いた。そ"},{"id":"tang-culture-t3","k":"source","f":"src","kj":"史料｜記録","t":"李白「静夜思」と王維「送元二使安西」","l":"tang-culture","x":"李白「静夜思」原文牀前看月光，疑是地上霜。舉頭望山月，低頭思故鄉。書き下し牀前、月光を看る 疑うらくは是れ地上の霜かと頭を挙げて山月を望み 頭を低れて故郷を思う現代語訳寝台の前に差"},{"id":"tang-culture-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"水に映る月を抱こうとして","l":"tang-culture","x":"李白は、762年、62歳ごろに、安徽省の当塗で、親類の家に身を寄せたまま病死したとされる。しかし、後世には、もっと李白らしい死に方の伝説が生まれた。酒に酔った李白は、長江の采石磯で"},{"id":"tang-culture-t5","k":"now","f":"now","kj":"いま","t":"白居易と日本","l":"tang-culture","x":"唐の詩人の中で、平安時代の日本で最も愛されたのは、白居易（白楽天）であった。その詩文集『白氏文集』は、白居易の存命中にすでに日本に伝わり、貴族たちの必読書となった。清少納言の『枕草"},{"id":"tang-culture-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"世界最古の印刷物はどこにある？","l":"tang-culture","x":"年代が確実な印刷物として古いものに、日本の百万塔陀羅尼がある。764年の恵美押勝の乱の後、称徳天皇の命で、小さな木製の三重塔100万基が作られ、その中に仏教の呪文（陀羅尼）を刷った"},{"id":"tang-culture-t7","k":"works","f":"works","kj":"作品","t":"唐の文化にまつわる作品","l":"tang-culture","x":"『唐詩選』：明代に編まれたとされる唐詩の選集。江戸時代の日本で大流行し、漢詩を学ぶ人々の入門書となった。『三体詩』『唐詩三百首』：同じく、唐詩の代表的な選集。井上靖『敦煌』（195"},{"id":"tang-early-t1","k":"debate","f":"think","kj":"考える｜諸説あり","t":"唐の建国の主役はだれか","l":"tang-early","x":"唐の正史（『旧唐書』『新唐書』）や『資治通鑑』では、太原での挙兵をためらう父の李淵を、次男の李世民が説得し、挙兵を主導したように描かれている。しかし、挙兵に従った李淵の側近温大雅が"},{"id":"tang-early-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"平陽公主――娘子軍の将軍","l":"tang-early","x":"李淵の娘の平陽公主は、父が太原で挙兵したとき、夫の柴紹とともに長安にいた。夫が父のもとに駆けつけた後、公主は、長安の郊外の自分の領地に戻って、財産を投げ出して人々を集め、各地の反乱"},{"id":"tang-early-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"太宗が読みたがった記録","l":"tang-early","x":"中国の宮廷には、皇帝の日々の言動を記録する「起居注」という制度があった。皇帝は、自分についての記録を読んではならないとされていた。記録が皇帝の意向で書き換えられることを防ぐためであ"},{"id":"tang-early-t4","k":"source","f":"src","kj":"史料｜記録","t":"「三つの鏡」――魏徴の死","l":"tang-early","x":"643年、魏徴が死ぬと、太宗は朝廷を5日間休み、自ら葬儀に参列して、臣下たちにこう語った。原文夫以銅為鏡，可以正衣冠；以古為鏡，可以知興替；以人為鏡，可以明得失。朕常保此三鏡，以防"},{"id":"tang-early-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"懐に隠したハイタカ","l":"tang-early","x":"太宗は、狩りに使う鳥を好んだ。あるとき、太宗が、手に入れたばかりの立派なハイタカを腕に止まらせて遊んでいると、遠くから魏徴がやってくるのが見えた。遊んでいるところを見られて諫められ"},{"id":"tang-early-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"390人の死刑囚は戻ってきたか","l":"tang-early","x":"632年の年末、太宗は、死刑の判決を受けた390人の囚人を、いったん家に帰らせ、翌年の秋に戻ってきて刑を受けるよう命じた。翌年の秋、約束の日に、390人の死刑囚は、監視の役人もいな"},{"id":"tang-early-t7","k":"now","f":"now","kj":"いま","t":"『貞観政要』と日本","l":"tang-early","x":"太宗と臣下たちの問答を記録した『貞観政要』は、8世紀前半、唐の歴史家呉兢によってまとめられた。君主のあるべき姿を説く「帝王学」の教科書として、中国だけでなく、日本や朝鮮でも広く読ま"},{"id":"tang-early-t8","k":"works","f":"works","kj":"作品","t":"唐の建国にまつわる作品","l":"tang-early","x":"『隋唐演義』（清代の小説）：隋末から唐初の英雄たちの活躍を描く。秦叔宝・程咬金・尉遅敬徳らが、豪傑として大活躍する。門神の秦叔宝と尉遅敬徳：太宗が悪夢にうなされたとき、2人が寝室の"},{"id":"tang-system-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"唐の律令と日本の律令","l":"tang-system","x":"日本は、唐の律令を手本として、701年に大宝律令を制定した。しかし、日本の律令は、唐の制度をそのまま写したものではなかった。唐日本（大宝律令・養老律令）中央官制三省六部（中書・門下"},{"id":"tang-system-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「春風に意を得て、馬蹄疾し」――進士の喜び","l":"tang-system","x":"進士科に合格した者たちは、長安の東南の曲江池のほとりで、盛大な祝宴を開いた。また、慈恩寺の大雁塔の壁に、合格者の名前を書きつけるのが習わしであった（雁塔題名）。のちに唐を代表する詩"},{"id":"tang-system-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「請う、君、甕に入れ」","l":"tang-system","x":"酷吏の周興が謀反の疑いをかけられたとき、その取り調べを命じられたのは、同じ酷吏の来俊臣であった。来俊臣は、何も知らないふりをして周興を食事に招き、こう尋ねた。「罪を認めない囚人がい"},{"id":"tang-system-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"水戸黄門の「圀」は則天文字","l":"tang-system","x":"武則天は、自分の権威を示すために、新しい漢字を作らせた。これを則天文字という。「天」「地」「日」「月」「年」「人」などを表す十数字（数には諸説ある）が作られ、武則天の名「曌」（照）"},{"id":"tang-system-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"武則天をどう評価するか","l":"tang-system","x":"武則天は、儒教の価値観が支配的な中国の伝統的な歴史家から、皇帝の位を奪い、多くの人々を殺した悪女として厳しく非難されてきた。しかし、20世紀以降は、別の見方も示されるようになった。"},{"id":"tang-system-t6","k":"voice","f":"src","kj":"史料｜証言","t":"「一抔の土、未だ乾かざるに」――駱賓王の檄文と武則天","l":"tang-system","x":"684年、武則天が、皇帝の座から自分の息子を退けて実権を握ると、揚州で、徐敬業が反乱を起こした。そのとき、詩人の駱賓王が書いた、武則天を討つための檄文は、名文として後世に伝えられて"},{"id":"tang-system-t7","k":"works","f":"works","kj":"作品","t":"この時代にまつわる作品","l":"tang-system","x":"中国のテレビドラマ『則天武后』（『武則天』）：武則天を主人公とするドラマは、何度も作られてきた。2014年の『武則天 The Empress』（范冰冰主演）は、日本でも放送された。"},{"id":"tang-world-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"「東アジア文化圏」という見方","l":"tang-world","x":"日本の歴史家西嶋定生は、中国を中心に、朝鮮・日本・ベトナムなどを含む地域が、漢字・儒教・中国化した仏教・律令という共通の文化を持つ一つの「世界」を形づくっていたと考え、これを「東ア"},{"id":"tang-world-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"李白はキルギスで生まれた？","l":"tang-world","x":"唐を代表する詩人李白の出生地については、古くから議論がある。李白の死後まもなく書かれた伝記などによれば、李白の祖先は、隋末に罪を得て西域に移り住み、李白は705年ごろ、5歳のときに"},{"id":"tang-world-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"ペーローズ――長安に亡命したペルシアの王子","l":"tang-world","x":"651年、アラブのイスラーム勢力に追われたササン朝の最後の王ヤズデギルド3世が、中央アジアのメルヴで殺された（→「ササン朝ペルシア」の回）。その子ペーローズ（漢字では卑路斯）は、ト"},{"id":"tang-world-t4","k":"debate","f":"think","kj":"考える｜諸説あり","t":"製紙法はタラスで伝わったのか","l":"tang-world","x":"タラス河畔の戦いで捕虜となった唐の兵士の中に、紙すきの職人がいて、彼らによってサマルカンドで紙が作られるようになり、製紙法がイスラーム世界、さらにヨーロッパへと伝わった――この話は"},{"id":"tang-world-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"阿倍仲麻呂――唐の高官となった日本人","l":"tang-world","x":"阿倍仲麻呂（698〜770年）は、717年、19歳で、吉備真備・玄昉らとともに留学生として唐に渡った。唐の太学で学んだ仲麻呂は、科挙に合格したとも伝えられ諸説、「朝衡」（晁衡）とい"},{"id":"tang-world-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"鑑真――6度目の渡海","l":"tang-world","x":"鑑真（688〜763年）は、揚州の大明寺の高僧であった。742年、日本から来た留学僧の栄叡と普照が、日本に正式な戒律を伝える僧を招きたいと願い出ると、鑑真は、弟子たちの誰も応じない"},{"id":"tang-world-t7","k":"works","f":"works","kj":"作品","t":"唐と東アジアにまつわる作品","l":"tang-world","x":"井上靖『天平の甍』（1957年）：鑑真を日本に招くため唐に渡った留学僧の栄叡・普照らの苦闘を描いた小説。1980年に映画化された。『小倉百人一首』の阿倍仲麻呂の歌：「天の原ふりさけ"},{"id":"th-cities-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「お金は臭わない」――尿に税をかけた皇帝","l":"th-cities","x":"ローマには、公衆トイレもあった。石のベンチに穴がずらりと並び、仕切りはなく、人々は並んで座って用を足しながら、おしゃべりをした。お尻をふくのには、棒の先につけた海綿を使い、使った後"},{"id":"th-cities-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「ガーディルー！」――窓から降ってくるもの","l":"th-cities","x":"スコットランドのエディンバラでは、18世紀になっても、夜10時になると、人々が、おまるの中身を、高い建物の窓から通りへ投げ捨てる習慣があった。その前に、人々は、「ガーディルー！」と"},{"id":"th-cities-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「どうせ一度しかやらないのだから」","l":"th-cities","x":"バザルジェットは、下水管の太さを決めるとき、当時のロンドンの人口から必要な太さを計算したうえで、それを2倍にしたという。「どうせ、この工事は一度しかやらないのだ。それに、予想もしな"},{"id":"th-cities-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"世界で最も人口密度の高かった場所――九龍城砦","l":"th-cities","x":"香港の九龍半島にあった九龍城砦は、19世紀に清朝の役所が置かれた小さな砦の跡であった。1898年にイギリスが九龍の新界を租借したとき、この砦だけは、清の管轄のまま残された。その後、"},{"id":"th-cities-t5","k":"now","f":"now","kj":"いま","t":"トイレのない35億人","l":"th-cities","x":"2001年、シンガポールの実業家ジャック・シムは、世界トイレ機関（WTO――世界貿易機関と同じ略称なのは、わざとだという）を設立した。2013年、国連は、11月19日を「世界トイレ"},{"id":"th-climate-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"1200年分の桜の記録","l":"th-climate","x":"京都の桜の満開の日は、平安時代の初めから、断続的に記録されている。最も古いのは、812年、嵯峨天皇が神泉苑で花見の宴を開いたという『日本後紀』の記事である。日本の研究者たちは、天皇"},{"id":"th-climate-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「誰もが自分の子を食べるほどに」――エジプトの地方長官の碑文","l":"th-climate","x":"エジプトの第1中間期の地方長官アンクティフィは、上エジプトのモアッラにある自分の墓の壁に、自らの功績を誇る碑文を刻ませた。その中で、彼は、飢饉に襲われた国のありさまと、自分が人々を"},{"id":"th-climate-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「太陽は、月のように輝きを失っていた」","l":"th-climate","x":"536年、地中海世界の人々は、奇妙な現象に気づいた。ユスティニアヌス帝の歴史家プロコピオスは、こう書いている。現代語訳……この年、最も恐ろしい前兆が起こった。太陽は、1年じゅう、月"},{"id":"th-climate-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「良い名前なら、人々は行きたがるだろう」――グリーンランドの名づけ","l":"th-climate","x":"12世紀のアイスランドの歴史書は、エイリークが島に名前をつけたときのことを、こう伝えている。原文Hann gaf nafn landinu ok kallaði Grænland "},{"id":"th-climate-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「テムズ川の上に、通りができていた」――1684年の霜の市","l":"th-climate","x":"1683年から84年にかけての冬は、とりわけ厳しかった。テムズ川は2か月近く凍りつき、氷の厚さは30cmにも達したという。日記作家ジョン・イーヴリンは、こう書いている。原文The "},{"id":"th-climate-t6","k":"voice","f":"src","kj":"史料｜証言","t":"「夏の太陽が、霧を晴らせなかった」――フランクリンの観察","l":"th-climate","x":"当時、アメリカの外交官としてパリに滞在していたベンジャミン・フランクリンは、この異常な気象を観察し、その原因を考えた。原文During several of the summer "},{"id":"th-climate-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"「夏のない年」と自転車の誕生","l":"th-climate","x":"1815年のタンボラ山の噴火の後、1816年のヨーロッパは「夏のない年」となった。スイスやドイツ南部では、飢饉が起こり、人々は草や苔まで食べたという。翌1817年、ドイツのバーデン"},{"id":"th-climate-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"気候は歴史を決めるのか","l":"th-climate","x":"「気候が文明の盛衰を決める」という考え方は、古くからあった。しかし、19世紀から20世紀の初めには、この考え方が、「暑い地域の人々は怠惰で、寒い地域の人々は勤勉である」といった、ヨ"},{"id":"th-clothing-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「ヒツジが人間を食い殺している」――トマス・モア『ユートピア』","l":"th-clothing","x":"1516年、イギリスの法律家トマス・モアは、架空の理想の島を描いた『ユートピア』を出版した。その第1巻で、旅人ヒュトロダエウスは、イングランドの現状を、こう批判している。原文Ove"},{"id":"th-clothing-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「四十八茶百鼠」――禁止令が生んだ色","l":"th-clothing","x":"派手な色を禁じられた江戸の町人たちは、許された地味な茶色や鼠色（灰色）、藍色の中で、微妙な違いを楽しむようになった。茶色だけでも、歌舞伎役者の名にちなんだ「団十郎茶」「路考茶」、利"},{"id":"th-clothing-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「ビキニ」と原爆――名前の由来","l":"th-clothing","x":"1946年7月5日、パリで、フランスの技術者ルイ・レアールは、それまでにないほど布の面積の小さい、上下に分かれた女性の水着を発表した。その名は「ビキニ」。わずか4日前の7月1日に、"},{"id":"th-clothing-t4","k":"now","f":"now","kj":"いま","t":"服は何を語るのか","l":"th-clothing","x":"エッツィは、羊やヤギや熊や鹿の革を組み合わせて、アルプスの寒さに耐える服を、自分の手でつくった（あるいは、身近な誰かにつくってもらった）。今、私たちが着ている服は、どこで、誰が、何"},{"id":"th-disasters-t1","k":"source","f":"src","kj":"史料｜記録","t":"「天、災害を出して以て之を譴告す」――董仲舒","l":"th-disasters","x":"原文國家將有失道之敗，而天乃先出災害以譴告之；不知自省，又出怪異以警懼之；尚不知變，而傷敗乃至。書き下し国家将に失道の敗れ有らんとすれば、天乃ち先ず災害を出して以て之を譴告す。自ら"},{"id":"th-disasters-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「海口哮吼し、声は雷霆に似たり」――貞観地震","l":"th-disasters","x":"原文陸奧國地大震動。流光如晝隱映。頃之，人民叫呼，伏不能起。或屋仆壓死，或地裂埋殪。……海口哮吼，聲似雷霆。驚濤涌潮，泝洄漲長，忽至城下。去海數十百里，浩々不辨其涯。原野道路，惣爲"},{"id":"th-disasters-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「恐れのなかに恐るべかりけるは、ただ地震なりけり」――鴨長明","l":"th-disasters","x":"原文また、同じころかとよ、おびたたしく大地震振ること侍りき。そのさま、世の常ならず。山はくづれて河を埋み、海は傾きて陸地をひたせり。土裂けて水湧き出で、巌割れて谷にまろび入る。なぎ"},{"id":"th-disasters-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「すべては善である、と叫ぶ哲学者たちよ」――ヴォルテール","l":"th-disasters","x":"当時のヨーロッパでは、ドイツの哲学者ライプニッツの考えを受けて、この世界は、神がつくりうる「最善の世界」であり、そこで起こる悪にも、すべて意味があるのだ、という楽観的な考え方（楽天"},{"id":"th-disasters-t5","k":"view","f":"think","kj":"考える｜別の視点","t":"「地震を起こす機械を発明したそうですが」――天災と流言、昔も今も","l":"th-disasters","x":"大きな災害の後、人々の不安と恐怖は、しばしば「誰かのせい」を探し始める。関東大震災の1か月後に刊行された記録集『大正大震災大火災』は、「訛伝、誤報、流言、蜚語、地方騒ぎ」という章を"},{"id":"th-disasters-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"地理の授業が救った命","l":"th-disasters","x":"2004年12月26日、インドネシアのスマトラ島沖で、マグニチュード9.1の巨大地震が起こり、インド洋の沿岸の14か国を津波が襲った。死者は約23万人にのぼった。当時のインド洋には"},{"id":"th-disasters-t7","k":"person","f":"deep","kj":"深掘り｜人物","t":"「ほら吹き」と呼ばれた予言者――大森房吉と今村明恒","l":"th-disasters","x":"明治の初めの日本の地震学を築いたのは、ジョン・ミルンをはじめとする、政府に招かれたお雇い外国人たちであった。その教えを受けて、日本人の手で地震学を育てたのが、東京帝国大学の大森房吉"},{"id":"th-disasters-t8","k":"now","f":"now","kj":"いま","t":"災害は「自然」なのか","l":"th-disasters","x":"ルソーは、リスボン大地震の被害を大きくしたのは、自然ではなく、人々が密集して暮らす都市のあり方だと指摘した。250年後の現代の防災の考え方も、これに近い。地震や台風そのものは「自然"},{"id":"th-empire-t1","k":"source","f":"src","kj":"史料｜記録","t":"「われはキュロス、世界の王」――キュロスの円筒印章","l":"th-empire","x":"現代語訳われはキュロス、世界の王、偉大なる王、力強き王、バビロンの王、シュメールとアッカドの王、四方世界の王である。……私がバビロンに平和のうちに入ったとき、……私は、バビロンの民"},{"id":"th-empire-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「雪も雨も暑さも夜の闇も」――ニューヨークの郵便局の碑文","l":"th-empire","x":"ギリシアの歴史家ヘロドトスは、ペルシアの「王の道」の駅伝の制度に驚き、こう書いている。ペルシアの使者は、宿駅ごとに馬と人を替えながら、王の命令を次々に伝えていく。1日の行程ごとに、"},{"id":"th-empire-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「彼らは荒野をつくり、それを平和と呼ぶ」――カルガクスの演説","l":"th-empire","x":"83年ごろ、ローマ軍は、ブリタニア（イギリス）の北部、現在のスコットランドにまで攻め込んだ。ローマの歴史家タキトゥスは、義父のブリタニア総督アグリコラの伝記の中で、ローマ軍を迎え撃"},{"id":"th-empire-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「わが天朝には、ないものはない」――乾隆帝の返書","l":"th-empire","x":"1793年、イギリス国王ジョージ3世の使節マカートニーが、清の乾隆帝のもとを訪れた（→「康熙帝・雍正帝・乾隆帝の時代」の回）。イギリスは、清との貿易を広げ、北京に大使を常駐させるこ"},{"id":"th-empire-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「白人の重荷を背負え」――キプリング","l":"th-empire","x":"1899年、インド生まれのイギリスの作家ラドヤード・キプリングは、フィリピンを植民地にしようとしていたアメリカに向けて、一編の詩を発表した。原文Take up the White "},{"id":"th-empire-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"帝国はなぜ滅びるのか――そして、帝国は本当に終わったのか","l":"th-empire","x":"18世紀のイギリスの歴史家ギボンは、大著『ローマ帝国衰亡史』で、ローマが滅んだ原因を、キリスト教の広まりによるローマ人の尚武の精神の衰えや、「ゲルマン人の侵入」に求めた（→「西ロー"},{"id":"th-empire-t7","k":"now","f":"now","kj":"いま","t":"砂の中の像","l":"th-empire","x":"シェリーの詩の中のオジマンディアスは、自分の業績が永遠に続くと信じていた。アッシリアの王も、ペルシアの王も、ローマの皇帝も、中国の皇帝も、スペインやイギリスの王たちも、それぞれのや"},{"id":"th-epidemics-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ファラオの顔の発疹","l":"th-epidemics","x":"エジプト新王国の第20王朝のファラオ、ラメス5世（在位前1149〜前1145年ごろ）のミイラの顔や首には、小さな盛り上がった発疹の跡が無数に残っている。20世紀にミイラを調べた研究"},{"id":"th-epidemics-t2","k":"voice","f":"src","kj":"史料｜証言","t":"天平の疫病と、藤原4兄弟","l":"th-epidemics","x":"737年の天然痘の流行は、天皇の外戚として権力を握っていた藤原4兄弟の命を、わずか4か月のうちに奪った。4月17日、次男の房前が亡くなった。7月13日、四男の麻呂が亡くなった。7月"},{"id":"th-epidemics-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「疫病で死んだ」と刻まれた墓石","l":"th-epidemics","x":"19世紀の末、ロシアの学者たちは、中央アジアのキルギスのイシク・クル湖の近くで、14世紀のネストリウス派キリスト教徒の墓地を調べた。シリア文字で刻まれた墓石の中には、1338年から"},{"id":"th-epidemics-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"梅毒は「隣の国の病気」","l":"th-epidemics","x":"新しく現れた梅毒を、ヨーロッパの人々は、みな「よその国」のせいにした。イタリア人やイギリス人は、「フランス病」と呼んだ。フランス人は、「ナポリ病」と呼んだ。ロシア人は「ポーランド病"},{"id":"th-epidemics-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「ここではまったく無害なのです」――モンタギュー夫人の手紙","l":"th-epidemics","x":"1717年4月、モンタギュー夫人は、イギリスの友人にあてて、こう書き送った。原文The small-pox, so fatal, and so general amongst us"},{"id":"th-epidemics-t6","k":"person","f":"deep","kj":"深掘り｜人物","t":"最後の患者、アリ・マオ・マーラン","l":"th-epidemics","x":"1977年10月、アフリカのソマリアの港町メルカの病院で料理人として働いていた23歳の青年アリ・マオ・マーランは、天然痘の患者を乗せた車を、病院まで道案内した。2週間後、彼は発熱し"},{"id":"th-epidemics-t7","k":"voice","f":"src","kj":"史料｜証言","t":"「太陽に特許をとれますか」――ソークのワクチン","l":"th-epidemics","x":"1955年4月、アメリカの医師ジョナス・ソークが開発したポリオのワクチンが、大規模な試験で効果があると発表された。全米で教会の鐘が鳴らされ、人々は喜び合った。その日、テレビ番組でジ"},{"id":"th-epidemics-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"病気は歴史を動かしたのか","l":"th-epidemics","x":"ジャレド・ダイアモンドは、『銃・病原菌・鉄』（1997年）の中で、ヨーロッパ人がアメリカ大陸を征服できた最大の理由の一つは、彼らが家畜とともに暮らす長い歴史の中で、多くの病原体への"},{"id":"th-food-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"世界最古のビールのレシピ","l":"th-food","x":"メソポタミアのシュメール人も、ビールをこよなく愛した（→「シュメール人の都市国家」の回）。前1800年ごろの粘土板に記された「ニンカシ讃歌」は、ビールの女神ニンカシをたたえる歌であ"},{"id":"th-food-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「朱門には酒肉の臭いがし、路には凍死者の骨がある」――杜甫","l":"th-food","x":"755年の冬、杜甫は、長安から、家族を預けていた奉先県（陝西省）へ向かった。途中、玄宗と楊貴妃が冬を過ごす驪山の華清宮のそばを通り、宮中の宴のにぎわいを耳にした。その冬、長安の東で"},{"id":"th-food-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"死刑になったコーヒー好き","l":"th-food","x":"コーヒーは、エチオピアが原産で、15世紀ごろ、アラビア半島のイエメンのイスラーム神秘主義者（スーフィー）たちが、夜の祈りの眠気覚ましに飲み始めたといわれる。16世紀には、オスマン帝"},{"id":"th-food-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「パンがなければ、お菓子を食べればいい」","l":"th-food","x":"飢えた民衆に、「パンがないなら、ブリオッシュ（お菓子のような上等のパン）を食べればいいじゃない」と言い放った――マリー・アントワネットの言葉として、あまりにも有名な話である。しかし"},{"id":"th-food-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"1200年続いた肉食の禁止","l":"th-food","x":"日本でも、675年、天武天皇は、こんな命令を出している。原文且莫食牛馬犬猿鷄之宍。以外不在禁例。書き下し且つ牛・馬・犬・猿・鶏の宍を食うこと莫れ。以外は禁の例に在らず。現代語訳また"},{"id":"th-food-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"飢饉は「天災」か「人災」か","l":"th-food","x":"ベンガル地方で生まれ、9歳のときに1943年のベンガル飢饉を目撃した経済学者アマルティア・センは、飢饉の原因を研究した。彼は、多くの飢饉は、食料そのものが足りなくなったからではなく"},{"id":"th-japan-world-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「日出づる処の天子、書を日没する処の天子に致す」――遣隋使の国書","l":"th-japan-world","x":"607年、倭の王（推古天皇の朝廷）は、小野妹子を使者として、隋の皇帝煬帝のもとに送った。中国の歴史書『隋書』は、そのとき倭の使者が差し出した国書の書き出しと、それを読んだ煬帝の反応"},{"id":"th-japan-world-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"江戸時代の日本は「国を閉ざして」いたのか","l":"th-japan-world","x":"江戸時代の日本は、長い間、「鎖国」によって世界から孤立していた、と考えられてきた。しかし、最近の歴史学では、この見方は大きく見直されている。まず、「鎖国」という言葉そのものが、江戸"},{"id":"th-japan-world-t3","k":"source","f":"src","kj":"史料｜記録","t":"「人種による差別をしない」――人種差別撤廃提案","l":"th-japan-world","x":"1919年、第一次世界大戦の後のパリ講和会議で、日本は、国際連盟の規約に、次のような条項を加えることを提案した（→「ヴェルサイユ体制とワシントン体制」の回）。原文The equal"},{"id":"th-japan-world-t4","k":"now","f":"now","kj":"いま","t":"テーマ編を振り返って――「世界史の中の日本」と「日本の中の世界史」","l":"th-japan-world","x":"このテーマ編の20の回を振り返ると、日本の歴史が、いかに世界の歴史と深く結びついてきたかがわかる。天平の疫病は大陸から、黒船は太平洋の向こうからやって来た（→「感染症の世界史」の回"},{"id":"th-media-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"歴史に名を残した最初の人物は「会計係」？","l":"th-media","x":"ウルクから出土した、前3100年ごろのある粘土板には、2万9086単位の大麦が、37か月の間に受け取られたことが記録され、最後に「クシム」という署名があるという。これが人の名前だと"},{"id":"th-media-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「わかったぞ！」――シャンポリオンの解読","l":"th-media","x":"1799年、ナポレオンのエジプト遠征に加わったフランスの兵士たちが、ナイル川河口の町ロゼッタで、文字の刻まれた黒い石の板を掘り出した（→「ナポレオンの台頭」の回）。そこには、前19"},{"id":"th-media-t3","k":"source","f":"src","kj":"史料｜記録","t":"「天下、みな蔡侯紙と称す」――『後漢書』","l":"th-media","x":"原文自古書契多編以竹簡，其用縑帛者謂之為紙。縑貴而簡重，並不便於人。倫乃造意，用樹膚、麻頭及敝布、魚網以為紙。元興元年奏上之，帝善其能，自是莫不從用焉，故天下咸稱「蔡侯紙」。書き下"},{"id":"th-media-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"タラス河畔の戦いで「紙すき職人」が捕虜になった？","l":"th-media","x":"751年、中央アジアのタラス河畔で、唐の軍とアッバース朝の軍が戦い、唐が敗れた（→「唐と東アジア世界」の回）。このとき捕虜となった唐の兵士の中に紙すきの職人がいて、彼らがサマルカン"},{"id":"th-media-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"印刷術がなければ、宗教改革は起こらなかったのか","l":"th-media","x":"1517年、ヴィッテンベルクの神学教授マルティン・ルターは、教会の贖宥状（免罪符）の販売を批判する「95か条の論題」を発表した（→「ルターの宗教改革」の回）。もとはラテン語で書かれ"},{"id":"th-media-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"ハトから始まった通信社","l":"th-media","x":"1850年、ドイツの西部のアーヘンと、ベルギーのブリュッセルの間には、まだ電信線がつながっていなかった。この「すき間」に目をつけたのが、パウル・ユリウス・ロイターという若者であった"},{"id":"th-media-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「宇宙戦争」の放送で、アメリカ中がパニックになった？","l":"th-media","x":"1938年10月30日の夜、アメリカのラジオで、若き俳優オーソン・ウェルズが、H・G・ウェルズのSF小説『宇宙戦争』をもとにしたラジオドラマを放送した。番組は、ダンス音楽の中継の途"},{"id":"th-media-t8","k":"voice","f":"src","kj":"史料｜証言","t":"初めて国民が聞いた天皇の声――玉音放送","l":"th-media","x":"1945年8月15日の正午、日本のラジオから、昭和天皇の声が流れた。前日に録音された「終戦の詔書」の朗読である。それまで、天皇の肉声が国民に向けて放送されたことは、一度もなかった。"},{"id":"th-media-t9","k":"now","f":"now","kj":"いま","t":"「忘れっぽさ」の時代に","l":"th-media","x":"ソクラテスは、文字が人々を忘れっぽくすると心配した。その心配は、ある意味では当たっていた。文字を手に入れた人類は、もう、何千行もの叙事詩を暗記して語り継ぐ必要はなくなった。印刷術は"},{"id":"th-medicine-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「まず、害を与えるなかれ」は、ヒポクラテスの誓いの言葉？","l":"th-medicine","x":"ヒポクラテスの名で伝えられる「ヒポクラテスの誓い」は、医師の倫理の原点として、今も、世界中の医学部の卒業式などで、形を変えて読み上げられている。その書き出しは、こうである。原文Ὄμ"},{"id":"th-medicine-t2","k":"source","f":"src","kj":"史料｜記録","t":"「麻沸散を服せしむ」――華佗の外科手術","l":"th-medicine","x":"原文若疾發結於內，針藥所不能及者，乃令先以酒服麻沸散，既醉無所覺，因刳破腹背，抽割積聚。書き下し若し疾、内に発結して、針薬の及ぶ能わざる所の者は、乃ち先ず酒を以て麻沸散を服せしめ、"},{"id":"th-medicine-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「ただあきれにあきれて居たるまでなり」――杉田玄白","l":"th-medicine","x":"1771年（明和8年）、江戸の小浜藩の医師杉田玄白は、仲間の前野良沢、中川淳庵とともに、千住の小塚原の刑場で、刑死した罪人の腑分け（解剖）を見学した。玄白と良沢は、それぞれオランダ"},{"id":"th-medicine-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「私は、自分の死を見た」――最初のX線写真","l":"th-medicine","x":"1895年11月、ドイツのヴュルツブルク大学の物理学者ヴィルヘルム・レントゲンは、陰極線の実験をしているとき、黒い紙で覆った装置から、目に見えない何かが出て、離れた場所の蛍光板を光"},{"id":"th-medicine-t5","k":"now","f":"now","kj":"いま","t":"医学の未来と、変わらない問い","l":"th-medicine","x":"2020年、新型コロナウイルスの流行に対して、それまで実用化されていなかったmRNA（メッセンジャーRNA）の技術を使ったワクチンが、わずか1年足らずで開発され、世界中で使われた（"},{"id":"th-money-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"漢字に残る「貝」のお金","l":"th-money","x":"お金や財産に関係する漢字の多くには、「貝」という部分が含まれている。財（たから）、貨（かね）、貯（たくわえる）、資（もとで）買（かう）、賣（売る）、貸（かす）、賃（やとい賃）貴（と"},{"id":"th-money-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"お金を貯めると位がもらえた","l":"th-money","x":"708年、日本で和同開珎が発行された。しかし、物と物を交換することに慣れていた人々は、なかなか銭を使おうとしなかった。そこで朝廷は、711年、「蓄銭叙位令」を出した。銭を一定の額以"},{"id":"th-money-t3","k":"source","f":"src","kj":"史料｜記録","t":"「皇帝は、錬金術の秘密を完全に手にしている」――マルコ・ポーロの見た紙幣","l":"th-money","x":"現代語訳大カーンの都の造幣所では、皇帝は、錬金術の秘密を完全に手にしていると言ってよい。……彼は、桑の木の皮の内側の薄い皮から紙をつくらせ、それをさまざまな大きさに切って、役人たち"},{"id":"th-money-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「ドル」の語源はボヘミアの谷","l":"th-money","x":"1519年、ボヘミア（現在のチェコ）のヨアヒムスタールという谷の銀山で、大型の銀貨がつくられ始めた。この銀貨は「ヨアヒムスターラー」、略して「ターラー」と呼ばれ、ヨーロッパ中に広ま"},{"id":"th-money-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「私がいなければ、陛下は帝冠を得られなかった」――ヤーコプ・フッガーの手紙","l":"th-money","x":"1519年、神聖ローマ皇帝の選挙で、スペイン王カルロス1世は、フランス王フランソワ1世と争った。選挙権を持つ7人の選帝侯の票は、事実上、お金で買われた。カルロスが用意した買収資金約"},{"id":"th-money-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「天体の動きは計算できても、人々の狂気は計算できない」","l":"th-money","x":"南海会社の株の暴落で、多くの人々が財産を失った。その中には、造幣局の長官を務めていた物理学者アイザック・ニュートンもいた。ニュートンは、いったん株を売って利益を上げたが、その後も値"},{"id":"th-money-t7","k":"voice","f":"src","kj":"史料｜証言","t":"「ドルと金との交換を、一時的に停止する」――ニクソン・ショック","l":"th-money","x":"1971年8月15日の日曜日の夜、ニクソン大統領は、テレビとラジオで、突然、こう発表した。原文I have directed Secretary Connally to suspe"},{"id":"th-music-t1","k":"source","f":"src","kj":"史料｜記録","t":"「楽の、ここに至るとは」――孔子と韶の楽","l":"th-music","x":"原文子在齊聞韶，三月不知肉味。曰：不圖爲樂之至於斯也。書き下し子、斉に在りて韶を聞く。三月、肉の味を知らず。曰く、図らざりき、楽を為すことの斯に至らんとは。現代語訳孔子は、斉の国に"},{"id":"th-music-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"「ド・レ・ミ」の起源","l":"th-music","x":"原文Ut queant laxisresonare fibrisMira gestorumfamuli tuorum,Solve pollutilabii reatum,Sanct"},{"id":"th-music-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「あの男も、ただの人間にすぎなかったのか！」――ベートーヴェンとナポレオン","l":"th-music","x":"ベートーヴェンは、フランス革命の理念に共感し、革命の英雄ナポレオンを尊敬していた。1803〜04年、彼は、ナポレオンにささげるつもりで、壮大な交響曲を書き上げた。ところが、1804"},{"id":"th-music-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"日本で初めての「第九」――板東の捕虜たち","l":"th-music","x":"日本で初めて交響曲第9番が全曲演奏されたのは、1918年6月1日、徳島県の板東俘虜収容所であった。演奏したのは、第一次世界大戦で日本軍の捕虜となった、中国の青島のドイツ兵たちであっ"},{"id":"th-music-t5","k":"now","f":"now","kj":"いま","t":"ポケットの中の音楽","l":"th-music","x":"2000年代に入ると、インターネットとスマートフォンの普及によって、音楽の聴き方は、再び大きく変わった。現在、世界の録音音楽の売り上げの約7割は、インターネットを通じた配信（ストリ"},{"id":"th-nation-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"民族・国民・人種・エスニック集団――何が違うのか","l":"th-nation","x":"日本語の「民族」という言葉は、意味の幅が広く、いくつかの異なる概念が混ざり合って使われている。エスニック集団（エスニシティ）：言語、宗教、習慣、祖先の伝承など、共通の文化を持つと考"},{"id":"th-nation-t2","k":"source","f":"src","kj":"史料｜記録","t":"「血を同じくし、言葉を同じくする」――ギリシア人とは何か","l":"th-nation","x":"原文αὖτις δὲ τὸ Ἑλληνικόν, ἐὸν ὅμαιμόν τε καὶ ὁμόγλωσσον, καὶ θεῶν ἱδρύματά τε κοινὰ καὶ θυσ"},{"id":"th-nation-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"フランス語を話せないフランス人","l":"th-nation","x":"ところが、革命が「フランス国民」の誕生をうたったとき、フランスの人々の多くは、フランス語を話していなかった。1794年、革命政府の議員で聖職者のアンリ・グレゴワールは、全国の言葉の"},{"id":"th-nation-t4","k":"music","f":"music","kj":"音楽","t":"国歌になった皇帝の歌――「ドイツの歌」","l":"th-nation","x":"1797年、フランス革命軍との戦争のさなか、オーストリアの作曲家ハイドンは、イギリスの国歌に刺激されて、皇帝フランツ2世をたたえる歌「神よ、皇帝フランツを守りたまえ」を作曲した。こ"},{"id":"th-nation-t5","k":"debate","f":"think","kj":"考える｜諸説あり","t":"国民は「古い」のか「新しい」のか","l":"th-nation","x":"国民や民族は、いつから存在するのだろうか。この問いをめぐって、歴史学や社会学では、大きな論争が続いてきた。一つの立場は、民族は、言葉や宗教や祖先の記憶を共有する人々として、古代から"},{"id":"th-nation-t6","k":"now","f":"now","kj":"いま","t":"「日々の人民投票」は続く","l":"th-nation","x":"第二次世界大戦の後、ヨーロッパの国々は、民族主義がもたらした二度の世界大戦の反省から、国境を越えた統合の道を歩み始めた。ヨーロッパ連合（EU）の中では、人々は、国境を自由に越えて行"},{"id":"th-population-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"7万年前、人類は絶滅しかけた？","l":"th-population","x":"今から約7万4000年前、インドネシアのスマトラ島のトバ火山で、過去数百万年で最大級の噴火が起こった。この噴火で、地球は何年にもわたって寒冷化し、当時の人類は、数千〜1万人ほどにま"},{"id":"th-population-t2","k":"source","f":"src","kj":"史料｜記録","t":"「口、五千九百五十九万四千九百七十八」――前漢の人口調査","l":"th-population","x":"原文訖於孝平，凡郡國一百三，縣邑千三百一十四，道三十二，侯國二百四十一。……民戶千二百二十三萬三千六十二，口五千九百五十九萬四千九百七十八。書き下し孝平に訖るまで、凡そ郡国一百三、"},{"id":"th-population-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「人類全体を養う戦いは、もう終わった」――『人口爆弾』","l":"th-population","x":"1968年、アメリカの生物学者ポール・エーリックは、『人口爆弾』という本を出版し、世界的なベストセラーとなった。その冒頭で、エーリックは、こう予言した。原文The battle t"},{"id":"th-population-t4","k":"debate","f":"think","kj":"考える｜諸説あり","t":"マルサスは間違っていたのか","l":"th-population","x":"200年あまりの間に人口が8倍に増えても、人類が飢え死にしなかったのは、農業の技術が、マルサスの想像をはるかに超えて進歩したからである。1965年、デンマークの経済学者エスター・ボ"},{"id":"th-population-t5","k":"now","f":"now","kj":"いま","t":"人口は「運命」か","l":"th-population","x":"人口の歴史を振り返ると、人口は、気候や病気や戦争に翻弄されると同時に、人々の選択によっても形づくられてきたことがわかる。豊かになり、教育を受け、子どもが死ななくなったとき、人々は、"},{"id":"th-religion-t1","k":"source","f":"src","kj":"史料｜記録","t":"「他の宗派をも尊ぶべきである」――アショーカ王の法勅","l":"th-religion","x":"現代語訳自分の宗派だけを尊び、他の宗派を非難する者は、すべて、自分の宗派への信仰からそうするのであるが、そうすることによって、かえって自分の宗派に、より大きな害を与えることになる。"},{"id":"th-religion-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「ルーシの喜びは、飲むことにある」――ウラジーミルの宗教選び","l":"th-religion","x":"10世紀の末、キエフ公国の大公ウラジーミルは、どの宗教を国の宗教とするか、迷っていた。12世紀初めにまとめられたロシアの年代記『過ぎし年月の物語（原初年代記）』は、そのいきさつを、"},{"id":"th-religion-t3","k":"now","f":"now","kj":"いま","t":"「いくつもの指」の世界で","l":"th-religion","x":"モンケは、神が手に何本もの指を与えたように、人間にもいくつもの道を与えた、と言った。アショーカ王は、他の宗派を尊ぶことが、自分の宗派を尊ぶことになる、と説いた。歴史の中で、異なる宗"},{"id":"th-sea-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"サツマイモが語る、もう一つの「アメリカ到達」","l":"th-sea","x":"南アメリカ原産のサツマイモは、ヨーロッパ人が太平洋に来るよりも前から、ポリネシアの島々で栽培されていた。サツマイモを表すポリネシアの言葉「クマラ」は、アンデスのケチュア語の「クマル"},{"id":"th-sea-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"海の底から現れた「唐の輸出品」","l":"th-sea","x":"1998年、インドネシアのスマトラ島とボルネオ島の間に浮かぶブリトゥン島の沖で、地元の漁師が、海の底に沈んだ古い船を見つけた。調査の結果、それは9世紀前半にアラビアかペルシアでつく"},{"id":"th-sea-t3","k":"source","f":"src","kj":"史料｜記録","t":"「曇りの日には、指南針を見る」――羅針盤の最古の記録","l":"th-sea","x":"原文舟師識地理，夜則觀星，晝則觀日，陰晦觀指南針。書き下し舟師、地理を識り、夜は則ち星を観、昼は則ち日を観、陰晦には指南針を観る。現代語訳船の船頭たちは、地理をよく知っている。夜は"},{"id":"th-sea-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「誰も行かないのなら、私が行くまでだ」――鑑真","l":"th-sea","x":"742年、唐の揚州の大明寺に、日本から来た二人の僧、栄叡と普照が訪ねてきた。日本には、正式に僧となるための戒律を授けることのできる僧がいない。誰か、日本に渡ってくれる高僧はいないだ"},{"id":"th-sea-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"北京にやって来た「麒麟」","l":"th-sea","x":"1414年、ベンガルの王から、明の永楽帝に、一頭の珍しい動物が献上された。首が長く、背の高さは人の背丈の倍以上もあった。翌年には、アフリカ東岸のマリンディの使節も、同じ動物を連れて"},{"id":"th-sea-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「1421年、中国人がアメリカを発見した」？","l":"th-sea","x":"2002年、イギリスの元潜水艦長ギャヴィン・メンジーズは、『1421――中国が新大陸を発見した年』という本を出版し、鄭和の艦隊の一部が、コロンブスよりも70年以上前に、アメリカ大陸"},{"id":"th-sea-t7","k":"voice","f":"src","kj":"史料｜証言","t":"「悪魔にでも食われろ！ 何をしに来た？」――カリカットの出会い","l":"th-sea","x":"ガマの航海に加わった名もない乗組員が書き残した航海記（『ロテイロ』）には、カリカットに上陸した最初の一人の、印象的な場面が記されている。上陸した男は、北アフリカのチュニス出身の二人"},{"id":"th-sea-t8","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「地球は平らだと、皆が信じていた」？","l":"th-sea","x":"コロンブスの航海について、こんな話がよく語られる。当時の人々は地球が平らだと信じており、西へ進めば世界の果てから落ちてしまうと恐れていた。しかし、コロンブスだけは、地球が丸いことを"},{"id":"th-sea-t9","k":"voice","f":"src","kj":"史料｜証言","t":"「ネズミ1匹が、金貨半ドゥカート」――ピガフェッタの航海記","l":"th-sea","x":"この航海に加わったイタリアのヴィチェンツァの貴族アントニオ・ピガフェッタは、太平洋横断の飢えを、こう書き残している。原文Mangiavamo biscotto, non più b"},{"id":"th-sea-t10","k":"trivia","f":"side","kj":"こぼれ話","t":"消えた1日","l":"th-sea","x":"ヴィクトリア号が、帰国の途中、アフリカ西岸の沖のカボ・ヴェルデ諸島に立ち寄ったときのことである。ピガフェッタは、航海の間、1日も欠かさず日記をつけていた。ところが、島の人々に聞いて"},{"id":"th-sea-t11","k":"trivia","f":"side","kj":"こぼれ話","t":"海賊船の「民主主義」","l":"th-sea","x":"17世紀末から18世紀初めのカリブ海や大西洋の海賊たちは、意外なことに、当時のどの国よりも「民主的」な仕組みで船を運営していた。海賊船の船長は、乗組員の投票で選ばれ、無能だったり横"},{"id":"th-sea-t12","k":"trivia","f":"side","kj":"こぼれ話","t":"「ライミー」――ライムが救ったイギリス海軍","l":"th-sea","x":"大航海時代から18世紀まで、長い航海で最も多くの船乗りの命を奪ったのは、嵐でも海戦でもなく、壊血病であった。歯ぐきから血が出て、古い傷が開き、やがて死に至る。マゼランの船団を苦しめ"},{"id":"th-sea-t13","k":"now","f":"now","kj":"いま","t":"1隻の船が止めた世界","l":"th-sea","x":"2021年3月23日、大型コンテナ船「エヴァー・ギヴン」（長さ約400m）が、強風にあおられて、スエズ運河の中で斜めに座礁し、運河を完全にふさいでしまった。船が離れるまでの6日間、"},{"id":"th-slavery-t1","k":"source","f":"src","kj":"史料｜記録","t":"「生まれつきの奴隷」――アリストテレス","l":"th-slavery","x":"原文ὅτι μὲν τοίνυν εἰσὶ φύσει τινὲς οἱ μὲν ἐλεύθεροι οἱ δὲ δοῦλοι, φανερόν, οἷς καὶ συμφέρει"},{"id":"th-slavery-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「彼らは奴隷だ」「いや、人間だ」――セネカの手紙","l":"th-slavery","x":"ローマの奴隷の境遇は、主人によって天と地ほどの差があった。鉱山や大農場で使い捨てにされる奴隷もいれば、主人の秘書や子どもの家庭教師、医者として重んじられる奴隷もいた。1世紀の哲学者"},{"id":"th-slavery-t3","k":"source","f":"src","kj":"史料｜記録","t":"「日本人を売り渡すことは、けしからぬ」――秀吉の禁令","l":"th-slavery","x":"1587年（天正15年）、九州を平定した豊臣秀吉は、博多で、キリスト教の宣教師（バテレン）の国外追放を命じた（バテレン追放令）。その前日の日付で出された「覚」には、次のような一条が"},{"id":"th-slavery-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「スレイヴ」の語源は「スラヴ」","l":"th-slavery","x":"英語で奴隷を意味する「スレイヴ（slave）」、フランス語の「エスクラーヴ（esclave）」、ドイツ語の「スクラーヴェ（Sklave）」は、いずれも、中世のラテン語の「スクラーウ"},{"id":"th-slavery-t5","k":"confuse","f":"confuse","kj":"混同注意","t":"奴隷・農奴・年季奉公人・苦力――何が違うのか","l":"th-slavery","x":"歴史には、自由を奪われた、さまざまな形の労働者が登場する。奴隷：人そのものが、主人の所有物とされ、売り買いされる。多くの場合、その身分は子に受け継がれた。農奴：中世ヨーロッパや近代"},{"id":"th-slavery-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"自由の代価――ハイチの「独立の賠償金」","l":"th-slavery","x":"1825年、フランスは、軍艦を送ってハイチを脅し、独立を承認する代わりに、1億5000万フランという莫大な賠償金を支払うよう求めた（のちに9000万フランに減額）。名目は、奴隷と土"},{"id":"th-slavery-t7","k":"debate","f":"think","kj":"考える｜諸説あり","t":"奴隷制は、人道主義によって廃止されたのか","l":"th-slavery","x":"イギリスの奴隷制の廃止は、長い間、ウィルバーフォースのような人道主義者たちの、良心の勝利として語られてきた。1944年、のちにトリニダード・トバゴの初代首相となる歴史家エリック・ウ"},{"id":"th-slavery-t8","k":"voice","f":"src","kj":"史料｜証言","t":"「あなたがたの7月4日は、奴隷にとって何なのか」――フレデリック・ダグラス","l":"th-slavery","x":"メリーランド州の農園で奴隷として生まれ、20歳で北部へ逃亡したフレデリック・ダグラスは、すぐれた演説家として、奴隷制の廃止を訴えた。1852年7月5日、ニューヨーク州のロチェスター"},{"id":"th-slavery-t9","k":"now","f":"now","kj":"いま","t":"「奴隷制は過去の話」なのか","l":"th-slavery","x":"セネカは、奴隷を人間らしく扱えと説いたが、奴隷制そのものは疑わなかった。アリストテレスは、奴隷制を自然なものとした。2000年以上にわたって、世界のほとんどの社会は、奴隷制を当たり"},{"id":"th-transport-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「すべての道はローマに通ず」は、いつ生まれた言葉か","l":"th-transport","x":"「すべての道はローマに通ず」という言葉は、古代ローマの人が言ったものと思われがちである。しかし、この言葉が文献に現れるのは、ローマ帝国が滅びてから700年近くたった中世のことである"},{"id":"th-transport-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「日々旅にして旅を栖とす」――松尾芭蕉","l":"th-transport","x":"1689年（元禄2年）の春、46歳の俳人松尾芭蕉は、弟子の曾良とともに、江戸の深川を出発し、奥州と北陸をめぐる約2400kmの旅に出た。その紀行文『おくのほそ道』は、こう始まる。原"},{"id":"th-transport-t3","k":"now","f":"now","kj":"いま","t":"14億人の旅人の時代に","l":"th-transport","x":"国連の世界観光機関の推計によれば、2024年には、国境を越えて旅行した人の数は、のべ約14億人に達した。かつて、命をかけて、何年もかけて行われた旅は、今では、スマートフォンで航空券"},{"id":"th-warfare-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"214日間の調教マニュアル――キックリの馬の書","l":"th-warfare","x":"ヒッタイトの都ハットゥシャから出土した粘土板には、世界最古の「馬の調教マニュアル」が残されている。書いたのは、ミタンニ出身の馬の調教師キックリである（前14世紀ごろ）。そこには、戦"},{"id":"th-warfare-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"国連本部に飾られた「世界最古の平和条約」","l":"th-warfare","x":"カデシュの戦いから約15年後の前1259年ごろ、エジプトとヒッタイトは平和条約を結んだ。互いに攻めないこと、第三国から攻められたときは助け合うこと、逃げてきた亡命者を送り返すこと―"},{"id":"th-warfare-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「最前線で倒れて死ぬのは、美しい」――テュルタイオスと「スパルタの母」","l":"th-warfare","x":"前7世紀、スパルタが隣国メッセニアと戦っていたころ、詩人テュルタイオスは、兵士たちを奮い立たせる歌をつくった。原文τεθνάμεναι γὰρ καλὸν ἐνὶ προμάχοι"},{"id":"th-warfare-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"カンネーの包囲戦と、2000年後の作戦計画","l":"th-warfare","x":"前216年、イタリア南部のカンネーで、カルタゴの名将ハンニバルは、数で倍近いローマ軍を、包囲して全滅させた（→「ポエニ戦争」の回）。中央の部隊をわざと後退させて、ローマ軍を袋の中に"},{"id":"th-warfare-t5","k":"source","f":"src","kj":"史料｜記録","t":"「兵とは、詭道なり」――『孫子』","l":"th-warfare","x":"原文兵者，國之大事，死生之地，存亡之道，不可不察也。書き下し兵は国の大事にして、死生の地、存亡の道なり。察せざるべからず。現代語訳戦争は、国家の重大事であり、人々の生死が決まる場、"},{"id":"th-warfare-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「鐙が騎士を生んだ」――ある大論争","l":"th-warfare","x":"1962年、アメリカの歴史家リン・ホワイトは、鐙が中世ヨーロッパの社会を変えたという大胆な説を発表した。鐙があれば、騎兵は、馬上でしっかりと体を支え、脇にかかえた槍で、馬の突進の勢"},{"id":"th-warfare-t7","k":"source","f":"src","kj":"史料｜記録","t":"「死をもたらす、神に憎まれる技」――第2ラテラノ公会議","l":"th-warfare","x":"1139年、ローマで開かれた第2ラテラノ公会議は、次のような決議を出した。原文Artem autem illam mortiferam et Deo odibilem ballis"},{"id":"th-warfare-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"「狼戦士」を試したい王","l":"th-warfare","x":"1304年、スコットランドのスターリング城を包囲したイングランド王エドワード1世は、史上最大級といわれる投石機（トレビュシェット）を組み立てさせた。名は「ウォーウルフ（狼戦士）」。"},{"id":"th-warfare-t9","k":"voice","f":"src","kj":"史料｜証言","t":"「その発するや、稲妻の光のごとく」――『鉄炮記』","l":"th-warfare","x":"60年あまりのち、時尭の孫の久時の依頼で、薩摩の禅僧南浦文之が、鉄砲伝来のいきさつを漢文で書きとめた。ポルトガル人が手にしていた「一物」は、こう描かれている。原文手携一物，長二三尺"},{"id":"th-warfare-t10","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"長篠の戦いの「3000挺の三段撃ち」","l":"th-warfare","x":"1575年、三河の長篠・設楽原で、織田信長・徳川家康の連合軍は、武田勝頼の軍勢を打ち破った。教科書や時代劇でおなじみの長篠の戦いである。信長は、3000挺の鉄砲を3列に並べ、1列目"},{"id":"th-warfare-t11","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「軍事革命」と、「鉄砲を捨てた日本」","l":"th-warfare","x":"1955年、イギリスの歴史家マイケル・ロバーツは、16〜17世紀のヨーロッパで、戦争のやり方が根本から変わったとして、これを「軍事革命」と呼んだ。のちにジェフリー・パーカーは、この"},{"id":"th-warfare-t12","k":"trivia","f":"side","kj":"こぼれ話","t":"「レパントの片手の男」","l":"th-warfare","x":"レパントの海戦に、スペインの一人の若い兵士が加わっていた。熱を出して寝込んでいたにもかかわらず、彼は、甲板に出て戦うことを願い出た。戦いの中で、彼は胸に2発、左手に1発の銃弾を受け"},{"id":"th-warfare-t13","k":"trivia","f":"side","kj":"こぼれ話","t":"「弩級」の「弩」は、ドレッドノートの「ド」","l":"th-warfare","x":"1906年、イギリス海軍は、まったく新しい戦艦「ドレッドノート」を完成させた。大口径の主砲を10門もそろえて積み、蒸気タービンで、それまでの戦艦よりも速く走ることができた。この1隻"},{"id":"th-warfare-t14","k":"voice","f":"src","kj":"史料｜証言","t":"「何が起ころうとも、われらにはマキシム機関銃がある」","l":"th-warfare","x":"1898年、スーダンのオムドゥルマンで、キッチナーの率いるイギリス・エジプト軍は、マフディー国家の5万の軍勢を迎え撃った。機関銃と大砲の前に、マフディー軍は、わずか半日で1万人以上"},{"id":"th-warfare-t15","k":"person","f":"deep","kj":"深掘り｜人物","t":"「死の商人、死す」――アルフレッド・ノーベル","l":"th-warfare","x":"1888年、フランスのある新聞は、スウェーデンの化学者アルフレッド・ノーベルが死んだと伝え、こんな見出しをつけたという。画像はオンライン時に表示される（Wikimedia Comm"},{"id":"th-warfare-t16","k":"voice","f":"src","kj":"史料｜証言","t":"「古い嘘」――ウィルフレッド・オーウェン","l":"th-warfare","x":"イギリスの青年将校ウィルフレッド・オーウェンは、西部戦線で毒ガス攻撃を目の当たりにし、1917年、療養中の病院で、こんな詩を書いた。原文Gas! GAS! Quick, boys!"},{"id":"th-warfare-t17","k":"trivia","f":"side","kj":"こぼれ話","t":"「戦車」はなぜ「タンク」なのか","l":"th-warfare","x":"塹壕と鉄条網を乗り越え、機関銃の弾をはね返す兵器として、イギリスが秘密裏に開発したのが、キャタピラ（無限軌道）で走る装甲車両であった。工場で組み立てられている間、この兵器の正体を隠"},{"id":"th-warfare-t18","k":"voice","f":"src","kj":"史料｜証言","t":"「戦争を不可能にする発明だと思っていた」――オーヴィル・ライト","l":"th-warfare","x":"第一次世界大戦のさなかの1917年、オーヴィル・ライトは、知人にあてた手紙で、こう書いている。原文When my brother and I built and flew the "},{"id":"th-warfare-t19","k":"trivia","f":"side","kj":"こぼれ話","t":"撃たれた人よりも、つくらされた人のほうが多く死んだ兵器","l":"th-warfare","x":"1944年9月、ドイツは、世界初の弾道ミサイル「V2（報復兵器2号）」を、ロンドンやベルギーのアントウェルペンに向けて発射し始めた。音速の数倍で落ちてくるV2は、迎え撃つことも、警"},{"id":"th-warfare-t20","k":"voice","f":"src","kj":"史料｜証言","t":"「今や私は死となった」――オッペンハイマー","l":"th-warfare","x":"原文We knew the world would not be the same. A few people laughed, a few people cried, most "},{"id":"th-warfare-t21","k":"debate","f":"think","kj":"考える｜諸説あり","t":"核兵器は、戦争を防いだのか","l":"th-warfare","x":"1945年以後、大国どうしが直接戦う世界大戦は、80年以上起きていない。これを「長い平和」と呼び、核兵器の抑止力のおかげだと考える研究者がいる。核兵器を持つ国どうしは、互いに相手を"},{"id":"th-warfare-t22","k":"now","f":"now","kj":"いま","t":"「最後の兵器」は来るのか","l":"th-warfare","x":"ガトリングは機関銃が、ノーベルはダイナマイトが、ライト兄弟は飛行機が、戦争を終わらせると信じた。その願いは、いずれも裏切られた。新しい兵器は、戦争をなくすのではなく、戦争をより速く"},{"id":"th-women-t1","k":"source","f":"src","kj":"史料｜記録","t":"「男たちの間で、良くも悪くも話題にならないこと」――ペリクレスの演説","l":"th-women","x":"前431年、ペロポネソス戦争の最初の年の戦死者を弔う葬儀で、アテネの指導者ペリクレスは、民主政のアテネをたたえる有名な演説を行った。歴史家トゥキディデスが伝えるその演説は、民主政の"},{"id":"th-women-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「男の子でないのが、残念でならない」――紫式部","l":"th-women","x":"紫式部は、学者の家に生まれた。幼いころ、父の藤原為時が、兄（あるいは弟）の惟規に漢文の書物を読み聞かせていると、そばで聞いていた紫式部のほうが、先に覚えてしまったという。彼女は、の"},{"id":"th-women-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"魔女狩りは「中世の暗黒」だったのか","l":"th-women","x":"魔女狩りというと、「暗黒の中世」の迷信の産物というイメージが強い。しかし、魔女の裁判と処刑が最も激しく行われたのは、中世ではなく、16世紀後半から17世紀前半にかけての、ルネサンス"},{"id":"th-women-t4","k":"debate","f":"think","kj":"考える｜諸説あり","t":"結婚の遅さが、近代の豊かさを生んだのか","l":"th-women","x":"「ヨーロッパ型の結婚」が、北西ヨーロッパの経済発展、さらには産業革命の背景になったのではないか――と論じる研究者がいる。結婚が遅く、結婚しない人も多ければ、生まれる子どもの数は少な"},{"id":"th-women-t5","k":"voice","f":"src","kj":"史料｜証言","t":"セネカ・フォールズの宣言","l":"th-women","x":"原文We hold these truths to be self-evident: that all men and women are created equal; that "},{"id":"th-women-t6","k":"voice","f":"src","kj":"史料｜証言","t":"「元始、女性は実に太陽であった」――平塚らいてう","l":"th-women","x":"1911年9月、東京で、女性だけの手による文芸誌『青鞜』が創刊された。誌名は、18世紀のイギリスで、学問や文芸を語り合った女性たちが「ブルーストッキング（青い靴下）」とあだ名された"},{"id":"th-women-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"女性参政権が最も遅かったヨーロッパの国","l":"th-women","x":"直接民主政の伝統で知られるスイスでは、国の選挙で女性が投票できるようになったのは、なんと1971年のことであった。それまで、女性の参政権を認めるかどうかを決める国民投票は、男性だけ"},{"id":"th-women-t8","k":"now","f":"now","kj":"いま","t":"「歴史のもう半分」を取り戻す","l":"th-women","x":"1975年の「国際婦人年」以来、世界の女性の地位は、大きく向上した。しかし、課題も多く残されている。世界経済フォーラムが毎年発表する男女格差の報告書では、日本は、2025年に148"},{"id":"thaw-hungary-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"秘密報告は、どうやって漏れたか","l":"thaw-hungary","x":"フルシチョフの報告は「秘密報告」とされ、ソ連の国内でも、その全文は1989年まで公表されなかった。しかし、報告の写しは、党の幹部たちに読ませるため、東ヨーロッパの国々の共産党にも送"},{"id":"thaw-hungary-t2","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"水の中の血","l":"thaw-hungary","x":"ハンガリー事件の1か月後の1956年12月6日、オーストラリアのメルボルンで開かれていたオリンピックで、水球の決勝リーグの試合が行われた。対戦したのは、ハンガリーとソ連であった。オ"},{"id":"thaw-hungary-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「わが軍は戦闘中である。政府はその場にある」――ナジの最後の放送","l":"thaw-hungary","x":"1956年11月4日の早朝、ソ連軍の戦車部隊が、ブダペストに攻め込んだ。午前5時20分、首相ナジ・イムレは、ラジオで国民と世界に向けて語りかけた。原文Ma hajnalban a "},{"id":"thaw-hungary-t4","k":"voice","f":"src","kj":"史料｜証言","t":"台所で、二人は何を言い争ったのか","l":"thaw-hungary","x":"1959年7月24日、モスクワのソコーリニキ公園で、アメリカの生活を紹介する「アメリカ博覧会」が開かれた。開会式に訪れたアメリカのニクソン副大統領とソ連のフルシチョフ首相は、会場を"},{"id":"thaw-hungary-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「私はジャム入りのパン」？","l":"thaw-hungary","x":"1963年6月26日、西ベルリンを訪れたアメリカの大統領ケネディは、市庁舎の前に集まった数十万の市民を前に、ドイツ語でこう述べた。「イッヒ・ビン・アイン・ベルリーナー（私はベルリン"},{"id":"thirty-years-war-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「そこには、殺戮と放火と略奪しかなかった」――マクデブルクの惨劇","l":"thirty-years-war","x":"マクデブルクの市民で、のちに真空の実験（「マクデブルクの半球」）で知られることになるオットー・フォン・ゲーリケは、陥落の日に町にいて、からくも生き延びた。彼は、その日の光景を、こう"},{"id":"thirty-years-war-t2","k":"war","f":"deep","kj":"深掘り｜戦術","t":"グスタフ・アドルフの軍事改革","l":"thirty-years-war","x":"グスタフ・アドルフは、オランダのマウリッツが始めた軍事改革をさらに推し進めた（→「オランダの独立と繁栄」の回）。スペインのテルシオのような、何千人もの兵が厚い隊形を組む部隊は、重厚"},{"id":"thirty-years-war-t3","k":"source","f":"src","kj":"史料｜記録","t":"『阿呆物語』に描かれた戦争","l":"thirty-years-war","x":"17世紀のドイツの作家グリンメルスハウゼンは、少年時代に、三十年戦争の中で兵士たちにさらわれ、自らも兵士として戦場を渡り歩いた。1668年、彼は、その体験をもとに、小説『阿呆物語（"},{"id":"thirty-years-war-t4","k":"voice","f":"src","kj":"史料｜証言","t":"『阿呆物語』の一場面――「スウェーデンの飲み物」","l":"thirty-years-war","x":"グリンメルスハウゼンは、少年の家を襲った兵士たちの拷問を、こう描いている。原文Den Knecht legten sie gebunden auf die Erde, steckt"},{"id":"thirty-years-war-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"thirty-years-war","x":"グリンメルスハウゼン『阿呆物語』（小説、1668年）：三十年戦争で村を焼かれた無知な少年が、兵士や盗賊、隠者となって戦乱の世をさまよう物語。作者自身の従軍体験が生かされている。ブレ"},{"id":"three-kingdoms-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"正史『三国志』と『三国志演義』","l":"three-kingdoms","x":"私たちが「三国志」として親しんでいる物語には、二つの系統がある。正史『三国志』『三国志演義』成立3世紀末、西晋の陳寿が著した歴史書。5世紀に裴松之が多くの史料を引いて注を付けた14"},{"id":"three-kingdoms-t2","k":"source","f":"src","kj":"史料｜記録","t":"出師の表","l":"three-kingdoms","x":"原文臣本布衣，躬耕於南陽，苟全性命於亂世，不求聞達於諸侯。先帝不以臣卑鄙，猥自枉屈，三顧臣於草廬之中，諮臣以當世之事，由是感激，遂許先帝以驅馳。現代語訳臣はもと無位無官の身で、南陽"},{"id":"three-kingdoms-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「死せる孔明、生ける仲達を走らす」","l":"three-kingdoms","x":"234年、5度目の北伐で五丈原（現在の陝西省）に陣を敷いた諸葛亮は、陣中で病死した。蜀の軍が撤退を始めると、魏の司馬懿（字は仲達）は追撃しようとした。ところが、蜀の軍が旗を返し、太"},{"id":"three-kingdoms-t4","k":"source","f":"src","kj":"史料｜記録","t":"「酒に対してはまさに歌うべし、人生いくばくぞ」――曹操「短歌行」","l":"three-kingdoms","x":"戦いに明け暮れた曹操は、宴の席で、こんな詩をうたった。原文對酒當歌，人生幾何！譬如朝露，去日苦多。慨當以慷，憂思難忘。何以解憂？唯有杜康。書き下し酒に対しては当に歌うべし、人生幾何"},{"id":"three-kingdoms-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"七歩の詩","l":"three-kingdoms","x":"曹丕は、才能豊かな弟の曹植を警戒していた。南朝の逸話集『世説新語』によれば、曹丕は曹植に、「7歩歩く間に詩を作れ。できなければ処刑する」と命じた。曹植は、歩きながら次のような詩を作"},{"id":"three-kingdoms-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"曹操の墓の発見","l":"three-kingdoms","x":"2009年、河南省安陽市の西高穴村で、後漢末の大きな墓（西高穴2号墓）の発掘が発表され、曹操の墓（高陵）であると発表された。墓からは、「魏武王」（曹操の称号）と刻まれた石の札や、6"},{"id":"three-kingdoms-t7","k":"now","f":"now","kj":"いま","t":"関羽は「商売の神様」","l":"three-kingdoms","x":"劉備の武将関羽は、死後しだいに神格化され、宋代以降は「関帝」として、国家によって祀られるようになった。関羽は、正義と信義を重んじた人物とされたことから、約束を守ることが大切な商人た"},{"id":"three-kingdoms-t8","k":"works","f":"works","kj":"作品","t":"三国志にまつわる作品","l":"three-kingdoms","x":"羅貫中『三国志演義』（14世紀ごろ）：中国の四大奇書の一つ。蜀を正統とし、劉備・関羽・張飛・諸葛亮を英雄として描いた歴史小説。日本でも江戸時代に翻訳され、広く読まれた。吉川英治『三"},{"id":"tibet-nanzhao-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"文成公主","l":"tibet-nanzhao","x":"文成公主（？〜680年）は、唐の皇族の娘で、640年に吐蕃の宰相ガル・トンツェン（禄東賛）が長安に来て求婚した後、641年、太宗の命でソンツェン＝ガンポに嫁いだ（→「唐の成立と貞観"},{"id":"tibet-nanzhao-t2","k":"debate","f":"think","kj":"考える｜諸説あり","t":"サムイェーの宗論――インド仏教か、中国仏教か","l":"tibet-nanzhao","x":"8世紀の吐蕃には、インドからの仏教と、唐からの仏教（禅宗）の両方が伝わっていた。792年ごろから、サムイェー寺で、両者の代表者による論争が行われたと伝えられる。中国側：禅僧の摩訶衍"},{"id":"tibet-nanzhao-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"長安を占領した吐蕃","l":"tibet-nanzhao","x":"安史の乱で唐の兵力が東へ引き抜かれると、吐蕃は西方の領土を次々と奪った。763年10月、吐蕃の大軍はついに長安に迫った。代宗は都を捨てて陝州（河南省）に逃れ、吐蕃軍は長安に入った。"},{"id":"tibet-nanzhao-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"名前のしりとり――父子連名制","l":"tibet-nanzhao","x":"南詔の王の名前には、不思議な規則がある。初代から順に並べると、次のようになる。細奴邏 → 邏盛 → 盛邏皮 → 皮邏閣 → 閣羅鳳 → 鳳伽異 → 異牟尋 → 尋閣勧 → 勧龍晟・"},{"id":"tibet-nanzhao-t5","k":"source","f":"src","kj":"史料｜記録","t":"白居易「新豊折臂翁」","l":"tibet-nanzhao","x":"唐の雲南遠征の悲劇は、約50年後、白居易の詩に歌われた。白居易は、長安の東の新豊県で出会った88歳の老人の話を、こう記している。原文無何天寶大徵兵，戶有三丁點一丁。……聞道雲南有瀘"},{"id":"tibet-nanzhao-t6","k":"works","f":"works","kj":"作品","t":"吐蕃と南詔にまつわる作品","l":"tibet-nanzhao","x":"『天龍八部』（金庸の武侠小説、1963〜1966年連載）：主人公の一人段誉は、大理国の皇族という設定で、大理国の仏教文化や、吐蕃の国師なども登場する。何度もドラマ化された。文成公主"},{"id":"timur-t1","k":"source","f":"src","kj":"史料｜記録","t":"イブン＝ハルドゥーンとの会見","l":"timur","x":"1401年の冬、ティムールの軍に包囲されたダマスクスの城内に、一人の老学者がいた。『歴史序説』の著者として知られるイスラームの歴史家イブン＝ハルドゥーンである（→「「世界史」という"},{"id":"timur-t2","k":"now","f":"now","kj":"いま","t":"アンカラの戦いが変えたもの","l":"timur","x":"アンカラの戦いの結果、オスマン帝国は大混乱に陥った。バヤジットの息子たちは、帝位をめぐって10年余りにわたって争った（空位時代、1402〜13年）。アナトリアの君侯たちは、ティムー"},{"id":"timur-t3","k":"source","f":"src","kj":"史料｜記録","t":"クラビホの見たサマルカンド","l":"timur","x":"1404年、スペインのカスティリャ王国の使節クラビホが、サマルカンドにやってきた。アンカラの戦いの後、ティムールの力を知ったカスティリャ王が、友好を求めて送った使節である。クラビホ"},{"id":"timur-t4","k":"source","f":"src","kj":"史料｜記録","t":"「知を求めることは、すべてのムスリムの男女の務めである」――ウルグ・ベクの学院の門","l":"timur","x":"ウルグ・ベクは、サマルカンドだけでなく、ブハラにも学院（マドラサ）を建てた。1417年に完成したブハラのウルグ・ベク学院の門には、預言者ムハンマドの言葉として伝えられる、次の一節が"},{"id":"tokugawa-world-t1","k":"term","f":"deep","kj":"深掘り｜ことば","t":"「鎖国」という言葉","l":"tokugawa-world","x":"「鎖国」という言葉は、江戸時代の初めには存在しなかった。この言葉が生まれたのは、19世紀の初めである。1801年、長崎のオランダ通詞志筑忠雄は、ケンペルの『日本誌』の付録の論文を翻"},{"id":"tokugawa-world-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"康熙帝が認めた日本の「信牌」","l":"tokugawa-world","x":"日本の信牌には、日本の年号が書かれていた。これを受け取ることは、清の商人が日本の権威に従うことを意味するのではないか――信牌を受け取れなかった中国の商人たちは、こう清の役所に訴えた"},{"id":"tokugawa-world-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"雨森芳洲と「誠信の交わり」","l":"tokugawa-world","x":"対馬藩に仕えた儒学者雨森芳洲は、朝鮮語と中国語を学び、朝鮮との外交の第一線で活躍した。彼は、釜山の倭館に滞在して朝鮮語を身につけ、朝鮮語の教科書もつくった。芳洲は、朝鮮との外交の心"},{"id":"tokugawa-world-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"「日本型華夷秩序」","l":"tokugawa-world","x":"江戸幕府は、朝鮮や琉球の使節、オランダ商館長の江戸参府を、将軍の徳を慕って外国から使者がやって来る儀式として演出した。日本を中心とし、周辺の国々や人々を、その外側に位置づける考え方"},{"id":"tokugawa-world-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「江戸の日本橋より唐、阿蘭陀まで境なしの水路なり」――林子平の警告","l":"tokugawa-world","x":"ロシアの船が北の海に現れるようになったころ、仙台藩の藩士の弟であった林子平は、長崎で見聞を広め、海外の情勢を学んだ。1791年、彼は、海からの外国の侵入に備えるよう説いた『海国兵談"},{"id":"tokugawa-world-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"tokugawa-world","x":"遠藤周作『沈黙』（小説、1966年）：島原・天草一揆の後の禁教下の日本に潜入したポルトガルの宣教師が、拷問を受ける信徒たちを前に、神の沈黙に苦しむ物語。2016年にマーティン・スコ"},{"id":"travelers-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「黄金の国ジパング」","l":"travelers","x":"マルコの本には、マルコ自身は行ったことのない、日本についての話も書かれている。ジパングは、大陸から東へ1500マイル離れた、大海の中にある大きな島である。……金は限りなく豊かである"},{"id":"travelers-t2","k":"source","f":"src","kj":"史料｜記録","t":"牢獄で生まれた本","l":"travelers","x":"帰国から3年後、ヴェネツィアは、地中海の交易をめぐって、ライバルのジェノヴァと戦っていた。マルコは、この戦争でジェノヴァの捕虜となり、牢獄に入れられた。その牢獄で、マルコは、ピサ出"},{"id":"travelers-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"マルコ＝ポーロ中国不在説","l":"travelers","x":"1995年、イギリスの研究者フランシス・ウッドは、『マルコ・ポーロは本当に中国へ行ったのか』という本を書き、大きな話題を呼んだ。ウッドは、マルコの本には、中国にいれば必ず目にしたは"},{"id":"travelers-t4","k":"source","f":"src","kj":"史料｜記録","t":"イブン＝バットゥータが見た中国","l":"travelers","x":"イブン＝バットゥータは、中国の豊かさと、旅の安全さに感心した。原文وبلاد الصين آمن البلاد وأحسنها حالًا للمسافر، فإن الإنسان"},{"id":"travelers-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"世界の両端の兄弟","l":"travelers","x":"イブン＝バットゥータは、中国のカンジャンフーという町で、モロッコの北の港町セウタ出身の、一人のイスラーム教徒の商人に出会った。故郷の近くの人に、地球の反対側で出会ったのである。二人"},{"id":"travelers-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"『大旅行記』はどこまで本当か","l":"travelers","x":"『大旅行記』にも、マルコ＝ポーロの本と同じように、疑問が投げかけられてきた。たとえば、シリアのダマスクスなどについての記述の中には、それより150年ほど前の旅行家イブン・ジュバイル"},{"id":"tributary-system-t1","k":"source","f":"src","kj":"史料｜記録","t":"寧波の乱","l":"tributary-system","x":"1523年、明の港寧波に、二つの日本の使節団が相次いで到着した。一つは大内氏の使節団で、正式な勘合を持っていた。もう一つは細川氏の使節団で、古い期限切れの勘合しか持っていなかった。"},{"id":"tributary-system-t2","k":"source","f":"src","kj":"史料｜記録","t":"万国津梁の鐘","l":"tributary-system","x":"1458年、琉球国王の尚泰久は、首里城の正殿に、一つの鐘を掛けさせた。その鐘には、琉球の国の姿を誇らしげに語る、次のような銘文が刻まれている。画像はオンライン時に表示される（Wik"},{"id":"turks-uighur-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ビザンツ帝国への使節","l":"turks-uighur","x":"突厥は、支配下のソグド人の商人たちの求めに応じて、中国から手に入れた絹を、ササン朝を通じて西方に売ろうとした。しかし、絹の交易を独占しようとするササン朝は、これを拒んだ。そこで56"},{"id":"turks-uighur-t2","k":"source","f":"src","kj":"史料｜記録","t":"オルホン碑文が語る「中国」","l":"turks-uighur","x":"キュル・テギン碑文やビルゲ可汗碑文には、唐に支配された時代の屈辱と、唐への警戒が、繰り返し語られている。原文bäglik urï oġluŋ qul boltï, äšilik q"},{"id":"turks-uighur-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"1頭の馬と絹40匹","l":"turks-uighur","x":"安史の乱の鎮圧に力を貸したウイグルは、その見返りとして、唐に馬を売りつけるようになった。これを絹馬交易という。値段は、馬1頭につき絹40匹という、とてつもないものであった。北宋の司"},{"id":"turks-uighur-t4","k":"view","f":"think","kj":"考える｜別の視点","t":"中央アジアの「トルコ化」","l":"turks-uighur","x":"ウイグルの西遷は、中央アジアの歴史を大きく変えた。それまで、タリム盆地のオアシス都市には、トハラ語やコータン語などのインド・ヨーロッパ系の言葉を話す人々や、イラン系のソグド人が多く"},{"id":"turks-uighur-t5","k":"works","f":"works","kj":"作品","t":"突厥・ウイグルにまつわる作品と言葉","l":"turks-uighur","x":"トルコ共和国と突厥：トルコ共和国では、突厥（ギョクテュルク、「天のトルコ」の意）が、トルコ民族の最初の国家としてたたえられ、オルホン碑文は「トルコ語の最古の記録」として重視されてい"},{"id":"ukraine-war-t1","k":"source","f":"src","kj":"史料｜記録","t":"プーチンの論文","l":"ukraine-war","x":"2021年7月、プーチン大統領は、「ロシア人とウクライナ人の歴史的な一体性について」と題する長い論文を発表した。その中で、プーチンは、ロシア人とウクライナ人は「一つの民族」であり、"},{"id":"ukraine-war-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"「現在進行形の歴史」を学ぶということ","l":"ukraine-war","x":"この回で扱う戦争は、2026年10月の時点で、まだ終わっていない。死者の数や支配地域の広さなどの数字は、日々変わっていく。この回では、数字に「○○年○月時点」と注記をつけているが、"},{"id":"ukraine-war-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「キエフ」から「キーウ」へ","l":"ukraine-war","x":"2022年3月31日、日本政府は、ウクライナの首都の日本語での呼び方を、ロシア語の読み方にもとづく「キエフ」から、ウクライナ語の読み方にもとづく「キーウ」に変更すると発表した。同じ"},{"id":"ukraine-war-t4","k":"mech","f":"deep","kj":"深掘り｜しくみ","t":"ロシア流の「抑止」","l":"ukraine-war","x":"ロシアは、ヨーロッパに対して、さまざまな形で圧力をかけ続けている。2023年には、同盟国のベラルーシに戦術核兵器を配備したと発表した。2025年9月には、ロシアのドローン約20機が"},{"id":"ukraine-war-t5","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"日本とウクライナ","l":"ukraine-war","x":"2022年3月23日、ゼレンスキー大統領は、オンラインで日本の国会で演説した。彼は、チョルノービリの原子力発電所がロシア軍に占拠されたことに触れ、日本の人々に、核の危険を訴えた。日"},{"id":"ukraine-war-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"ukraine-war","x":"映画『マリウポリの20日間』（ムスティスラフ・チェルノフ監督、2023年）：ロシア軍に包囲されたマリウポリにとどまったウクライナのAP通信の記者が撮影したドキュメンタリー。アカデミ"},{"id":"umayyad-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"ムアーウィヤの「髪の毛」","l":"umayyad","x":"ムアーウィヤは、武力よりも、駆け引きと寛大さによって人々を従えることに長けた政治家として知られる。彼は、自らの政治のやり方を、次のように語ったと伝えられる。原文لا أضع سيف"},{"id":"umayyad-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「刈り取りの時を迎えた首が見える」――ハッジャージュのクーファ演説","l":"umayyad","x":"第2次内乱を終わらせたカリフ、アブド・アルマリクは、反乱の絶えないイラクを抑えるために、腹心のハッジャージュを総督として送り込んだ。694年ごろ、イラクの都市クーファに着いたハッジ"},{"id":"umayyad-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"書き換えられたカリフの名前","l":"umayyad","x":"岩のドームの内部の壁の上部には、全長約240mにも及ぶ帯状の碑文が、金色のモザイクで書かれている。その中には、「神は生みもせず、生まれもしない」（『クルアーン』第112章）、「マル"},{"id":"umayyad-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"金貨をめぐる皇帝とカリフの争い","l":"umayyad","x":"貨幣の改革の前、アブド・アルマリクは、一時、カリフ自身が剣を帯びて立つ姿を刻んだ金貨を発行していた。一方、ビザンツ皇帝ユスティニアノス2世は、692年ごろ、金貨の表に、初めてキリス"},{"id":"umayyad-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「ターリクの山」と、船を焼いた将軍","l":"umayyad","x":"ターリクが軍を上陸させた岩山は、アラビア語で「ジャバル・ターリク」（ターリクの山）と呼ばれるようになった。これがなまって、現在の「ジブラルタル」という地名になった。伝説によれば、タ"},{"id":"umayyad-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"クサイル・アムラの「6人の王」","l":"umayyad","x":"8世紀前半に建てられたクサイル・アムラの浴場の壁には、狩りや音楽、踊り、裸の女性たちの姿などが、生き生きと描かれている。モスクには人の姿を描かなかったウマイヤ朝の王族たちも、私的な"},{"id":"umayyad-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"宴の席の虐殺と、逃れた王子","l":"umayyad","x":"アッバース家は、ウマイヤ家の人々を徹底的に追及した。伝承によれば、アッバース家の将軍は、パレスチナで、ウマイヤ家の約80人の人々に、安全を約束して宴会に招いた。そして、宴の最中に彼"},{"id":"umayyad-t8","k":"now","f":"now","kj":"いま","t":"アーシューラーと現代","l":"umayyad","x":"カルバラーの悲劇は、シーア派の人々にとって、不正な権力に立ち向かい、殉教した者の物語として、現在まで語り継がれている。1979年のイラン革命の際にも、革命を指導した人々は、国王（シ"},{"id":"umayyad-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"umayyad","x":"嶋田襄平『イスラム教史』（山川出版社）：ウマイヤ朝・アッバース朝の時代のイスラームの歴史を概説した本。ターズィエ（受難劇）：イランで演じられる、カルバラーの悲劇を題材とした伝統的な"},{"id":"un-postwar-t1","k":"confuse","f":"confuse","kj":"混同注意","t":"国際連盟と国際連合","l":"un-postwar","x":"どちらも二つの世界大戦の後に作られた国際機構なので、よく比べられる。試験でもよく問われる。国際連盟国際連合成立1920年1945年本部ジュネーヴ（スイス）ニューヨーク（アメリカ）大"},{"id":"un-postwar-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"最初の拒否権","l":"un-postwar","x":"最初の拒否権が使われたのは、国連が活動を始めたばかりの1946年2月のことであった。シリアとレバノンに残っていたイギリス軍とフランス軍の撤退を求める決議案に対して、ソ連が「内容が生"},{"id":"un-postwar-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"1ドル＝360円の由来","l":"un-postwar","x":"日本の円とドルの交換比率は、1949年4月、1ドル＝360円と定められた。この比率は、1971年まで22年間続いた。「円は丸い。丸は360度だから、1ドル＝360円になった」という"},{"id":"un-postwar-t4","k":"debate","f":"think","kj":"考える｜諸説あり","t":"勝者の裁きか","l":"un-postwar","x":"ニュルンベルク裁判と東京裁判は、戦争の指導者個人の責任を国際的な法廷で問うという、歴史上初めての試みであった。しかし、当時から、さまざまな批判があった。「平和に対する罪」や「人道に"},{"id":"un-postwar-t5","k":"now","f":"now","kj":"いま","t":"憲章に残る「敵国条項」","l":"un-postwar","x":"国連憲章の第53条と第107条などには、第二次世界大戦中に連合国の「敵国」であった国――日本・ドイツ・イタリアなど――に対しては、安保理の許可がなくても、加盟国が強制的な行動をとる"},{"id":"us-civil-war-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「奴隷にとって、7月4日とは何か」――フレデリック・ダグラス","l":"us-civil-war","x":"メリーランドの奴隷の家に生まれ、20歳で北部へ逃れたフレデリック・ダグラスは、奴隷制廃止運動の最も力強い語り手となった。自伝の中で、彼は、少年の頃に初めて見た、おばのへスターがむち"},{"id":"us-civil-war-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"「私は乗客を一人も失わなかった」","l":"us-civil-war","x":"南部の奴隷たちの中には、命がけで北部やカナダへ逃げる者がいた。それを助ける秘密のネットワークは、「地下鉄道」と呼ばれた。逃亡者は「乗客」、かくまう家は「駅」、道案内は「車掌」と呼ば"},{"id":"us-civil-war-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"最初の死者","l":"us-civil-war","x":"34時間にわたる砲撃で、サムター要塞は降伏した。驚くべきことに、この砲撃では、双方ともに一人の戦死者も出なかった。ところが、降伏した北軍の守備隊が、要塞を明け渡す前に星条旗に100"},{"id":"us-civil-war-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「サラ、私の愛は死なない」――戦場に向かった兵士の手紙","l":"us-civil-war","x":"1861年7月、北軍の少佐サリヴァン・バルーは、最初の大きな戦いを前に、妻サラに手紙を書いた。原文Sarah, my love for you is deathless, it s"},{"id":"us-civil-war-t5","k":"music","f":"music","kj":"音楽","t":"南と北の歌","l":"us-civil-war","x":"南北戦争では、両軍の兵士たちが、それぞれの歌を歌って行進した。南軍が愛したのは、もとはミンストレル・ショー（白人が顔を黒く塗って黒人を演じる芝居）のためにつくられた「ディキシー」で"},{"id":"us-civil-war-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"戦争は、わが家の前庭で始まり、客間で終わった","l":"us-civil-war","x":"降伏の調印が行われたのは、村の商人ウィルマー・マクリーンの家の客間であった。実は、マクリーンは、もともとブル・ランの近くの農場に住んでいた。1861年、最初の大きな戦いで、彼の家は"},{"id":"us-civil-war-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"南軍の装甲艦、日本へ","l":"us-civil-war","x":"南北戦争の末期、南部連合は、フランスで1隻の装甲艦を手に入れた。船体を鉄の装甲で覆い、船首に敵艦を突き破る衝角を持つ、最新鋭の軍艦である。「ストーンウォール」と名づけられたこの艦は"},{"id":"us-civil-war-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"us-civil-war","x":"ストウ『アンクル・トムの小屋』（小説、1852年）：奴隷として売られていくトムの苦難を描き、北部で奴隷制への反対の世論を大きく高めた小説。マーガレット・ミッチェル『風と共に去りぬ』"},{"id":"us-expansion-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"サカガウィアと「投票」","l":"us-expansion","x":"ロッキー山脈の手前で、探検隊は馬を手に入れる必要に迫られた。交渉の相手のショショーニ族の首長の顔を見た時、サカガウィアは泣き出した。それは、子どもの頃に敵の部族にさらわれて以来、生"},{"id":"us-expansion-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"講和の後の大勝利","l":"us-expansion","x":"1814年12月24日、ベルギーのガンで、米英の講和条約が調印された。ところが、その知らせが大西洋を渡って届くには、何週間もかかった。1815年1月8日、講和を知らないまま、ニュー"},{"id":"us-expansion-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"砂の上の線","l":"us-expansion","x":"アラモの物語の中でも特に有名なのが、「砂の上の線」の逸話である。総攻撃の前、トラヴィスは剣で地面に一本の線を引き、「ここに残って共に死ぬ者は、この線を越えよ」と言った。全員が線を越"},{"id":"us-expansion-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"「英雄少年たち」と聖パトリック大隊","l":"us-expansion","x":"チャプルテペック城には、メキシコの陸軍士官学校があった。城を守って戦死した6人の若い士官候補生は、「英雄少年たち（ニーニョス・エロエス）」として、今もメキシコの国民的な英雄である。"},{"id":"us-expansion-t5","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"本当にもうかったのは誰か","l":"us-expansion","x":"ゴールドラッシュで大金持ちになった金鉱掘りは、ごく一部にすぎなかった。確実にもうけたのは、彼らに道具や食料や衣服を売った商人たちであった。金鉱の町では、卵1個が1ドル、シャベル1本"},{"id":"us-expansion-t6","k":"now","f":"now","kj":"いま","t":"今日のアラモ","l":"us-expansion","x":"アラモの礼拝堂は、今も、テキサス州サン・アントニオの市街地の真ん中に残っている。毎年、数百万人の観光客が訪れる、テキサスで最も有名な史跡である。高層ビルに囲まれた、思いのほか小さな"},{"id":"us-expansion-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"us-expansion","x":"ローラ・インガルス・ワイルダー『大草原の小さな家』（1935年）：19世紀の後半、西部の開拓地を幌馬車で移り住んだ一家の暮らしを、作者自身の少女時代をもとに描いた物語。ドラマ（19"},{"id":"us-industrial-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"「金持ちのまま死ぬのは恥である」","l":"us-industrial","x":"カーネギーは、1889年に発表した論文「富」の中で、こう書いた。「金持ちのまま死ぬ者は、恥辱のうちに死ぬのである」。富を得た者は、それを社会のために使う義務がある、というのである。"},{"id":"us-industrial-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"1ドル以下の寄付","l":"us-industrial","x":"像そのものはフランスが贈ったが、像を載せる台座は、アメリカ側がつくることになっていた。ところが、その資金がなかなか集まらなかった。そこで立ち上がったのが、新聞『ワールド』の社主ピュ"},{"id":"us-industrial-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"「るつぼ」か「サラダボウル」か","l":"us-industrial","x":"1908年、ニューヨークで、『るつぼ』という劇が上演され、評判となった。作者は、ロシア系ユダヤ人の家系のイギリスの作家ザングウィルである。劇の中で、主人公は叫ぶ。「アメリカは神のる"},{"id":"us-industrial-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"us-industrial","x":"アプトン・シンクレア『ジャングル』（小説、1906年）：シカゴの食肉工場で働く東ヨーロッパからの移民の悲惨な暮らしを描いた小説。不衛生な工場の実態が明らかになり、食品の安全を守る法"},{"id":"ussr-collapse-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"サハリン沖の撃墜","l":"ussr-collapse","x":"1983年9月1日の未明、アメリカのアンカレジからソウルへ向かっていた大韓航空007便のジャンボジェット機が、予定の航路を大きく外れて、ソ連の領空に入り込んだ。ソ連の戦闘機は、これ"},{"id":"ussr-collapse-t2","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"36時間後の避難","l":"ussr-collapse","x":"1986年4月26日、午前1時23分、ウクライナのチェルノブイリ原子力発電所の4号炉が、試験の運転の最中に爆発した。原子炉の建屋は吹き飛び、大量の放射性物質が、空に舞い上がった。発"},{"id":"ussr-collapse-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"18歳のパイロット","l":"ussr-collapse","x":"1987年5月28日、西ドイツの18歳の青年マティアス・ルストは、フィンランドのヘルシンキの空港から、小型のセスナ機で飛び立った。行き先は、ストックホルムと届け出ていた。ところが、"},{"id":"ussr-collapse-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"675キロメートルの人の鎖","l":"ussr-collapse","x":"1989年8月23日、独ソ不可侵条約の締結から50年目のその日の夕方、エストニアの首都タリン、ラトヴィアの首都リガ、リトアニアの首都ヴィリニュスを結ぶ、675キロメートルの道路に沿"},{"id":"ussr-collapse-t5","k":"source","f":"src","kj":"史料｜記録","t":"狩猟の館の決定","l":"ussr-collapse","x":"1991年12月8日、ロシアのエリツィン、ウクライナのクラフチュク、ベラルーシのシュシケヴィチの3人の首脳が、ポーランドとの国境に近い、ベラルーシのベロヴェーシの森の中にある政府の"},{"id":"ussr-collapse-t6","k":"mech","f":"deep","kj":"深掘り｜しくみ","t":"なぜソ連は崩壊したのか","l":"ussr-collapse","x":"超大国ソ連は、外国との戦争に敗れたわけでもないのに、わずか数年のうちに崩れ去った。その原因については、さまざまな見方があるが、いくつかの要因が重なっていたことは確かである。石油に頼"},{"id":"ussr-collapse-t7","k":"now","f":"now","kj":"いま","t":"ソ連の崩壊は「悲劇」か","l":"ussr-collapse","x":"2005年、ロシアのプーチン大統領は、年次教書演説で、ソ連の崩壊を「20世紀最大の地政学的な大惨事」と呼んだ。数千万の同胞が、一夜にして、ロシアの領土の外に取り残されることになった"},{"id":"ussr-collapse-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"ゴルバチョフとピザ","l":"ussr-collapse","x":"1997年、アメリカのテレビに、一本のコマーシャルが流れた。モスクワの「ピザハット」の店で、ロシア人の家族がテーブルを囲み、店に入ってきた白髪の男を見て、言い争いを始める。「あの男"},{"id":"ussr-collapse-t9","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"ussr-collapse","x":"ドラマ『チェルノブイリ』（HBO、2019年）：1986年のチェルノブイリ原子力発電所の事故と、その原因を隠そうとするソ連の体制を描いたドラマ。スヴェトラーナ・アレクシエーヴィチ『"},{"id":"vedic-t1","k":"source","f":"src","kj":"史料｜記録","t":"ウィリアム＝ジョーンズの講演（1786年）","l":"vedic","x":"原文The Sanscrit language, whatever be its antiquity, is of a wonderful structure; more perf"},{"id":"vedic-t2","k":"confuse","f":"confuse","kj":"混同注意","t":"似ている単語をくらべる","l":"vedic","x":"意味サンスクリット語アヴェスター語（古代イラン）ギリシア語ラテン語英語ドイツ語父ピタル（pitṛ）ピタル（pitar）パテール（patēr）パテル（pater）ファーザー（fath"},{"id":"vedic-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"アーリヤ人は「外から来た」のか","l":"vedic","x":"アーリヤ人が中央アジア方面からインドに移動してきたという考えは、言語学（インド＝ヨーロッパ語族の分布）や考古学、そして近年の古代DNAの研究によって、広く支持されている。前2千年紀"},{"id":"vedic-t4","k":"source","f":"src","kj":"史料｜記録","t":"牛を求める戦い","l":"vedic","x":"『リグ＝ヴェーダ』の世界では、牛は最も大切な財産だった。戦争を意味する言葉の一つ「ガヴィシュティ」は、もともと「牛を求めること」という意味である。神々への祈りにも、牛と馬が繰り返し"},{"id":"vedic-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"十王戦争と「バーラト」","l":"vedic","x":"『リグ＝ヴェーダ』には、アーリヤ人どうしの部族の戦いの記録も残っている。バラタ族の王スダースが、10人の王の連合軍を、パンジャーブのパルシュニー川（現在のラーヴィー川）のほとりで打"},{"id":"vedic-t6","k":"source","f":"src","kj":"史料｜記録","t":"原人プルシャの歌","l":"vedic","x":"『リグ＝ヴェーダ』の最も新しい層に属する賛歌の一つは、宇宙の始まりについて、神々が原初の巨人プルシャを犠牲として捧げ、その体から世界が生まれたと歌う。そして、四つの身分の起源を、次"},{"id":"vedic-t7","k":"confuse","f":"confuse","kj":"混同注意","t":"ヴァルナ・ジャーティ・カースト","l":"vedic","x":"用語意味由来ヴァルナバラモン・クシャトリヤ・ヴァイシャ・シュードラの4つの身分の枠組みサンスクリット語で「色」ジャーティ職業や出身などで結びついた、生まれによって決まる集団。結婚や"},{"id":"vedic-t8","k":"now","f":"now","kj":"いま","t":"現代インドとカースト","l":"vedic","x":"1950年に施行されたインド憲法は、カーストによる差別と「不可触民」制を禁止した。憲法の起草委員会の委員長を務めたのは、自らも「不可触民」とされた家に生まれたアンベードカルである。"},{"id":"vedic-t9","k":"source","f":"src","kj":"史料｜記録","t":"「汝はそれなり」","l":"vedic","x":"ウパニシャッドの中でも有名なのが、父ウッダーラカが息子シュヴェータケートゥに教えを説く場面である。父は息子に、塩を水に入れさせ、翌朝、その塩を取り出すように言う。しかし塩は溶けてい"},{"id":"vedic-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"vedic","x":"ピーター・ブルック演出『マハーバーラタ』（舞台1985年、映画1989年）：古代インドの大叙事詩『マハーバーラタ』を、世界各国の俳優を使って9時間の舞台に仕立てた作品。作品は史実を"},{"id":"versailles-t1","k":"source","f":"src","kj":"史料｜記録","t":"「国際連盟」の原点――十四か条の第14条","l":"versailles","x":"十四か条の最後の項目で、ウィルソンは、こう述べた。原文A general association of nations must be formed under specific "},{"id":"versailles-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"「カルタゴの平和」","l":"versailles","x":"パリ講和会議にイギリスの大蔵省の代表として参加していた若い経済学者ケインズは、講和の条件のあまりの過酷さに抗議して、会議の途中で辞任した。帰国した彼は、『平和の経済的帰結』という本"},{"id":"versailles-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「これは平和ではない。20年間の休戦だ」――フォッシュ元帥","l":"versailles","x":"ヴェルサイユ条約に、最も強く不満を抱いた人物の一人は、意外にも、勝者の側の、連合軍総司令官フォッシュ元帥であった。フォッシュは、ドイツが二度とフランスを攻撃できないように、ライン川"},{"id":"versailles-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"戦艦陸奥を守れ","l":"versailles","x":"ワシントン会議で、アメリカは、建造中の戦艦をすべて廃棄することを提案した。その中には、日本の最新鋭の戦艦陸奥が含まれていた。陸奥は、会議の直前に完成したばかりで、その建造費には、全"},{"id":"victorian-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「1ペニーを使う」","l":"victorian","x":"万国博覧会の会場には、世界で最初の有料の公衆水洗トイレが設けられた。利用料は1ペニーで、会期中に、のべ80万人以上が利用したという。英語で、トイレに行くことを婉曲に「1ペニーを使う"},{"id":"victorian-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"女王と2人の首相","l":"victorian","x":"ヴィクトリア女王は、ディズレーリを深く信頼し、グラッドストンを嫌っていた。女王は、グラッドストンについて、「あの人は、私に話しかける時、まるで公開の集会で演説するように話す」と不平"},{"id":"victorian-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"「ヴィクトリア朝の価値観」","l":"victorian","x":"ヴィクトリア時代のイギリスでは、勤勉、節約、自助、礼儀正しさ、家庭の尊重、そして性に関する厳格な道徳が重んじられた。サミュエル・スマイルズの『自助論』（1859年）は、「天は自ら助"},{"id":"victorian-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"victorian","x":"コナン・ドイル『シャーロック・ホームズ』シリーズ（1887年〜）：霧のロンドン、ガス灯、鉄道と電報――ヴィクトリア時代の都市を舞台にした探偵小説。森薫『エマ』（漫画、2002〜20"},{"id":"vienna-system-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「チーズの王様」の誕生","l":"vienna-system","x":"ウィーン会議の期間中、タレーランは、各国の代表を招いた晩餐会で、それぞれの国の自慢のチーズを持ち寄って、どれが最もおいしいかを競わせたという。イギリスのスティルトン、オランダのリン"},{"id":"vienna-system-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"ウィーン体制は「反動」だったのか","l":"vienna-system","x":"ウィーン体制は、長い間、自由とナショナリズムを押さえつけた「反動」の体制として、否定的に評価されてきた。しかし、20世紀の外交官で歴史家のキッシンジャーは、著書『回復された世界平和"},{"id":"vienna-system-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"「パリがくしゃみをすると」","l":"vienna-system","x":"メッテルニヒは、革命の震源地フランスの動向に、常に神経をとがらせていた。彼は、「パリがくしゃみをすると、ヨーロッパが風邪をひく」と言ったと伝えられる。この予言は、1830年の七月革"},{"id":"vienna-system-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"vienna-system","x":"映画『会議は踊る』（1931年、ドイツ）：ウィーン会議の時代のウィーンを舞台に、ロシア皇帝アレクサンドル1世と手袋屋の娘の恋を描いた音楽映画。題名は、「会議は踊る、されど進まず」と"},{"id":"vietnam-war-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「独立と自由ほど尊いものはない」――ホー・チ・ミンの呼びかけ","l":"vietnam-war","x":"アメリカ軍による北ベトナムへの爆撃（北爆）が激しくなる中、1966年7月17日、北ベトナムの国家主席ホー・チ・ミンは、ラジオで全国の人々に呼びかけた。原文Chiến tranh c"},{"id":"vietnam-war-t2","k":"voice","f":"src","kj":"史料｜証言","t":"ソンミ村","l":"vietnam-war","x":"テト攻勢のさなかの1968年3月16日、南ベトナムの中部のソンミ村（ミライ集落）に、アメリカ陸軍の一個中隊が踏み込んだ。村は、解放戦線の拠点だという情報があった。しかし、村にいたの"},{"id":"vietnam-war-t3","k":"voice","f":"src","kj":"史料｜証言","t":"「町を救うために、破壊することが必要になった」","l":"vietnam-war","x":"1968年2月のテト攻勢の間、メコン・デルタの町ベンチェは、解放戦線の部隊に占領され、アメリカ軍の砲撃と空爆によって、町の大部分が破壊された。AP通信の記者ピーター・アーネットは、"},{"id":"vietnam-war-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"「安全への逃避」","l":"vietnam-war","x":"ベトナム戦争は、カメラの前で戦われた、最初の戦争でもあった。各国の多くの報道カメラマンが、兵士たちに同行して戦場を取材した。日本の青森県出身のカメラマン、沢田教一は、1965年、ア"},{"id":"vietnam-war-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"屋上のヘリコプター","l":"vietnam-war","x":"サイゴンの陥落の前日の4月29日、アメリカは、残っていたアメリカ人と、アメリカに協力した南ベトナムの人々を、ヘリコプターで沖合の空母に運び出す、最後の救出作戦を行った。ある建物の屋"},{"id":"vietnam-war-t6","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"vietnam-war","x":"映画『プラトーン』（オリバー・ストーン監督、1986年）：ベトナム戦争に従軍した監督自身の体験をもとに、ジャングルでの戦闘と、兵士たちの対立や残虐行為を描いた。映画『地獄の黙示録』"},{"id":"vikings-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"角のついたかぶと","l":"vikings","x":"ヴァイキングといえば、角のついたかぶとをかぶった姿を思い浮かべる人も多いだろう。しかし、ヴァイキングが角つきのかぶとをかぶって戦ったことを示す証拠は、まったく見つかっていない俗説。"},{"id":"vikings-t2","k":"source","f":"src","kj":"史料｜記録","t":"アラブの使節が見たルーシ","l":"vikings","x":"921〜922年、アッバース朝のカリフの使節団の一員として、ヴォルガ川中流のブルガール人の国を訪れたイブン・ファドラーンは、そこで交易に来ていた「ルーシ」（スウェーデン系のノルマン"},{"id":"vikings-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「北の人々の怒りから、われらを救いたまえ」","l":"vikings","x":"中世ヨーロッパの教会では、ヴァイキングの襲撃を恐れて、「主よ、北の人々（ノルマン人）の怒りから、われらを救いたまえ」と祈っていた、という話がよく知られている。しかし、この言葉そのも"},{"id":"vikings-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"足に口づけしなかった首領","l":"vikings","x":"11世紀初めのノルマンディーの歴史家サン・カンタンのデュドンは、ロロと王の協定の場面について、次のような話を伝えている。家臣となったしるしに、王の足に口づけするよう求められたロロは"},{"id":"vikings-t5","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"パンを焦がした王","l":"vikings","x":"アルフレッドについては、次のような話が伝えられている。878年の初め、デーン人の奇襲を受けて追われたアルフレッドは、身分を隠して、沼地の農家に身を寄せた。農家の妻は、この男が王だと"},{"id":"vikings-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"波を止められなかった王","l":"vikings","x":"12世紀の歴史家ハンティンドンのヘンリーは、クヌートについて、次のような話を伝えている。権力の絶頂にあったクヌートは、海辺に王座を置かせ、満ちてくる潮に向かって、「わが足をぬらして"},{"id":"vikings-t7","k":"trivia","f":"side","kj":"こぼれ話","t":"ブタとポーク","l":"vikings","x":"ノルマン＝コンクェストの後、イングランドの王侯貴族は、フランス語を話すノルマン人となった。宮廷や法廷、教会ではフランス語とラテン語が使われ、英語は庶民の言葉となった。そのため、英語"},{"id":"vikings-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"ハギア・ソフィアの落書き","l":"vikings","x":"イスタンブルのハギア・ソフィア大聖堂の2階の回廊の大理石の手すりには、ルーン文字で刻まれた落書きが残っている。読み取れるのは、「ハールヴダン」という名前と、「刻んだ」という言葉の一"},{"id":"vikings-t9","k":"trivia","f":"side","kj":"こぼれ話","t":"ブルートゥースと青歯王","l":"vikings","x":"デンマークのイェリングには、10世紀の王ハーラル1世が、両親をしのんで立てた大きなルーン石碑が残っている。そこには、「デンマーク全土とノルウェーを手に入れ、デーン人をキリスト教徒に"},{"id":"vikings-t10","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"vikings","x":"幸村誠『ヴィンランド・サガ』（講談社、2005年〜）：11世紀初めの北欧とイングランドを舞台に、ヴァイキングの少年トルフィンの生涯を描いた漫画。クヌートやトルケルなど実在の人物が登"},{"id":"wako-silver-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"戚継光と鴛鴦の陣","l":"wako-silver","x":"倭寇との戦いで名を上げたのが、明の将軍戚継光である。戚継光は、それまでの明の兵が、倭寇の日本刀の前に、なすすべもなく逃げ散るのを見て、軍隊の根本からの立て直しに乗り出した。彼は、町"},{"id":"wako-silver-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「地獄の口が開いた」――ドミニコ会士の告発","l":"wako-silver","x":"1550年、ペルーで布教していたドミニコ会の修道士ドミンゴ・デ・サント・トマスは、スペインのインディアス枢機会議に宛てた手紙の中で、ポトシの銀山について、こう告発した。原文Habr"},{"id":"wako-silver-t3","k":"debate","f":"think","kj":"考える｜諸説あり","t":"なぜ銀は中国に向かったのか","l":"wako-silver","x":"16〜17世紀、世界の銀の大きな部分が、最終的に中国に流れ込んだと考えられている。その量については、さまざまな推定がある諸説。なぜ、銀は中国に向かったのだろうか。一つの理由は、中国"},{"id":"wang-anshi-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"ひげの上のシラミ","l":"wang-anshi","x":"王安石は、身なりにまったく構わない人物として知られた。何日も顔を洗わず、衣服も着替えなかったので、顔は垢で黒ずんでいたという。ある日、王安石が神宗と政治について話し合っていたとき、"},{"id":"wang-anshi-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"宋銭が日本を潤した","l":"wang-anshi","x":"宋の時代には、商業の発展にこたえるため、大量の銅銭が鋳造された。とくに、新法の時代の元豊年間（1078〜1085年）には、1年に500万貫（50億枚）を超える銅銭がつくられたとされ"},{"id":"wang-anshi-t3","k":"source","f":"src","kj":"史料｜記録","t":"王安石の反論","l":"wang-anshi","x":"1070年、司馬光は、王安石に長い手紙を送り、新法は役人の権限を勝手に広げ、事を起こして民を騒がせ、利益を争い、人々の諫めを拒んでいると非難した。これに対して、王安石は短い返書（「"},{"id":"wang-anshi-t4","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"かめを割った少年","l":"wang-anshi","x":"司馬光には、子どものころの有名な逸話がある。ある日、友達と遊んでいたところ、一人の子どもが、水をいっぱいに張った大きなかめに落ちてしまった。ほかの子どもたちは慌てて逃げ出したが、7"},{"id":"wang-anshi-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"「春風、又た緑にす」","l":"wang-anshi","x":"1075年、王安石は、宰相に復帰するために、金陵（江寧、現在の南京）から都へ向かった。その途中、長江の北岸の瓜洲に船を泊めたとき、次の詩を詠んだ。原文京口瓜洲一水間，鍾山只隔數重山"},{"id":"wang-anshi-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"5日で新法を廃止した男","l":"wang-anshi","x":"司馬光は、募役法を廃止して、もとの差役（労役）の制度に戻すことを命じ、5日以内に実施するよう各地に求めた。多くの役人がその期限に戸惑う中、都の開封の長官は、命令どおりにわずか5日で"},{"id":"wang-anshi-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"石工の願い","l":"wang-anshi","x":"『宋史』などによれば、長安で元祐党籍碑を刻むよう命じられた石工の安民は、こう言って断ろうとしたという。「私は愚かな者で、碑を立てる意味はわかりません。ただ、司馬相公（司馬光）のよう"},{"id":"wang-anshi-t8","k":"debate","f":"think","kj":"考える｜諸説あり","t":"王安石は「国を誤らせた」のか","l":"wang-anshi","x":"王安石の評価は、時代によって大きく変わってきた。南宋の時代には、北宋が金に滅ぼされたのは、王安石の新法が党争を生み、国を乱したからだと考えられた。朱子学を大成した朱熹も、王安石に厳"},{"id":"wang-anshi-t9","k":"works","f":"works","kj":"作品","t":"王安石の新法にまつわる作品","l":"wang-anshi","x":"蘇軾「赤壁賦」（1082年）：流刑地の黄州で書かれた名文。月夜の長江に舟を浮かべ、三国時代の英雄をしのびながら、人生と自然について語り合う。司馬光『資治通鑑』：日本でも、鎌倉時代以"},{"id":"war-on-terror-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「レッツ・ロール」","l":"war-on-terror","x":"ハイジャックされた4機目のユナイテッド航空93便の乗客たちは、機内の電話や携帯電話で家族と話し、ほかの旅客機がビルに突入したことを知った。この飛行機も、ワシントンのどこかに突入させ"},{"id":"war-on-terror-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「低すぎる。私たちは、低く飛びすぎている」","l":"war-on-terror","x":"2001年9月11日、ボストンからロサンゼルスに向かっていたアメリカン航空11便が、乗っ取られた。客室乗務員のマデリーン・エイミー・スウィーニーは、機内の電話でボストンの空港の地上"},{"id":"war-on-terror-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"「自己責任」","l":"war-on-terror","x":"日本の小泉政権は、イラク戦争を支持し、2003年にイラク復興支援特別措置法を成立させた。2004年1月から2006年7月まで、陸上自衛隊が、イラク南部のサマーワに派遣され、給水や道"},{"id":"war-on-terror-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"war-on-terror","x":"映画『ユナイテッド93』（ポール・グリーングラス監督、2006年）：2001年9月11日、ハイジャックされたユナイテッド航空93便の機内で、乗客たちが犯人に立ち向かった経過を描いた"},{"id":"wars-religion-france-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「ユグノーの殺戮」を記念したメダル","l":"wars-religion-france","x":"1572年8月24日の未明、パリのサン＝ジェルマン＝ローセロワ教会の鐘が鳴り響くのを合図に、旧教徒の群衆と兵士たちは、婚礼のためにパリに集まっていたユグノー（プロテスタント）の貴族"},{"id":"wars-religion-france-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"さまよえる国王の首","l":"wars-religion-france","x":"アンリ4世の遺体は、歴代のフランス国王とともに、パリの北のサン・ドニ大聖堂に葬られた。それから約180年後の1793年、フランス革命のさなか、革命派の人々は、王家の墓をあばき、遺体"},{"id":"wars-religion-france-t3","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"wars-religion-france","x":"デュマ『王妃マルゴ』（小説、1845年、映画1994年）：サン・バルテルミの虐殺の直前に、プロテスタントのアンリ（のちのアンリ4世）と結婚したカトリックの王女マルグリットを主人公に"},{"id":"west-africa-kingdoms-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"二つの世界を生きた旅人","l":"west-africa-kingdoms","x":"レオ・アフリカヌスの本名は、ハサン・アル・ワッザーンという。1494年ごろ、イベリア半島のイスラーム教徒の国グラナダに生まれたが、2歳ほどの時にグラナダがキリスト教徒に征服され、家"},{"id":"west-africa-kingdoms-t2","k":"now","f":"now","kj":"いま","t":"ベニン・ブロンズの返還","l":"west-africa-kingdoms","x":"1897年、イギリス軍は、ベニン王国に「懲罰遠征」を行って都を焼き払い、王宮の数千点の美術品を略奪した。これらの「ベニン・ブロンズ」は、イギリスで競売にかけられ、ヨーロッパやアメリ"},{"id":"west-africa-kingdoms-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"女王ンジンガの交渉術","l":"west-africa-kingdoms","x":"コンゴ王国の南のンドンゴ王国の王女ンジンガは、17世紀の前半、ポルトガルの侵略に抵抗し続けた女性である。1622年、兄の王の使者として、ルアンダのポルトガル総督との交渉に臨んだ時の"},{"id":"world-2025-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"「力による平和」","l":"world-2025","x":"トランプ政権の外交の標語は、「力による平和」である。1980年代のレーガン大統領が掲げた言葉を受け継いだものだ。トランプは、自分の手で、世界の戦争を次々に終わらせたと主張している。"},{"id":"world-2025-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"麦わらの海賊旗","l":"world-2025","x":"2025年、インドネシア、ネパール、フィリピン、マダガスカル、ペルーなどの抗議のデモで、同じ旗が、はためいていた。麦わら帽子をかぶったドクロの海賊旗。日本の漫画『ONE PIECE"},{"id":"world-2025-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"歴史は「今」に続いている","l":"world-2025","x":"この講座は、人類の誕生から始まって、2026年の「今」にたどり着いた。ウクライナの戦争の背景には、キエフ公国以来の、ロシアとウクライナの長い歴史がある。ガザの悲劇の根には、第一次世"},{"id":"writing-t1","k":"view","f":"think","kj":"考える｜別の視点","t":"文字は、言葉とは別物である","l":"writing","x":"文字と言葉（言語）は、別のものである。同じ漢字が、中国語・日本語・朝鮮語・ベトナム語という系統の違う言葉を書くのに使われ、逆に、同じ言葉が、時代によって違う文字で書かれることもある"},{"id":"writing-t2","k":"confuse","f":"confuse","kj":"混同注意","t":"主な古代文字の解読","l":"writing","x":"文字解読者年主な手がかりヒエログリフシャンポリオン（フランス）1822年ロゼッタ＝ストーン（ギリシア語との対訳）、コプト語楔形文字ローリンソン（イギリス）ら1850年代ベヒストゥー"},{"id":"writing-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"冷戦下のマヤ文字解読","l":"writing","x":"マヤ文字の解読は、20世紀の冷戦のもとで行われたドラマであった。16世紀、スペインの司教ランダは、マヤ文字の「アルファベット」を書き残していた。しかし、それはマヤの書記に、スペイン"},{"id":"writing-t4","k":"source","f":"src","kj":"史料｜記録","t":"文字は忘れっぽさを生む――プラトンの警告","l":"writing","x":"文字が広まったことを、手放しで喜ばなかった人もいた。古代ギリシアの哲学者プラトンは、対話篇『パイドロス』の中で、師のソクラテスに、エジプトの古い伝説として次のような話を語らせている"},{"id":"writing-t5","k":"now","f":"now","kj":"いま","t":"コンピュータの中の古代文字","l":"writing","x":"現在、世界中の文字をコンピュータで扱うための国際的な規格「ユニコード」には、160を超える文字体系が登録されている。その中には、楔形文字、ヒエログリフ、線文字B、フェニキア文字、甲"},{"id":"ww1-origins-t1","k":"voice","f":"src","kj":"史料｜証言","t":"「ゾフィー、死ぬな！」――大公の最後の言葉","l":"ww1-origins","x":"撃たれた大公夫妻の乗った車の中で、大公のそばに立っていた侍従武官ハラッハ伯爵は、のちに、その最期の様子を証言している。首を撃たれた大公は、腹部を撃たれて崩れ落ちた妻ゾフィーに向かっ"},{"id":"ww1-origins-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"サンドイッチと、写真の男","l":"ww1-origins","x":"サライェヴォ事件には、有名な「俗説」が二つある。一つは、最初の暗殺に失敗したプリンツィプが、がっかりして角の食料品店でサンドイッチを買っていたところに、偶然、大公の車が止まった、と"},{"id":"ww1-origins-t3","k":"source","f":"src","kj":"史料｜記録","t":"「ウィリー」と「ニッキー」","l":"ww1-origins","x":"ドイツの皇帝ヴィルヘルム2世とロシアの皇帝ニコライ2世は、遠縁の親戚どうしであった。ヴィルヘルムはイギリスのヴィクトリア女王の孫で、ニコライの皇后アレクサンドラも、同じくヴィクトリ"},{"id":"ww1-origins-t4","k":"music","f":"music","kj":"音楽","t":"「ティペラリーは遠い」","l":"ww1-origins","x":"1914年8月、フランスに上陸したイギリスの兵士たちが、行進しながら歌っていたのが、「ティペラリーへの道は遠い」である。新聞の記者がこれを報じると、たちまち大流行し、第一次世界大戦"},{"id":"ww1-origins-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"マルヌのタクシー","l":"ww1-origins","x":"マルヌの戦いの最中の9月6日から7日にかけて、パリの軍政長官ガリエニは、パリ市内のタクシーを徴発し、兵士たちを前線へ運ばせた。約600台のタクシーが、数千人の兵士を乗せて、夜通し走"},{"id":"ww1-origins-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"誰に戦争の責任があったのか","l":"ww1-origins","x":"第一次世界大戦 の責任は、どの国にあったのか。この問いは、100年以上にわたって議論されてきた。戦後のヴェルサイユ条約は、戦争の責任をドイツとその同盟国に負わせた（→「ヴェルサイユ"},{"id":"ww1-other-fronts-t1","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「あなた方の息子たちは、今、われわれの胸に抱かれている」","l":"ww1-other-fronts","x":"ガリポリのアンザック湾の記念碑には、1934年に、トルコの大統領となったケマル・アタテュルクが、この地で戦死したオーストラリアやニュージーランドの兵士の母親たちに贈ったとされる言葉"},{"id":"ww1-other-fronts-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「一つの民族への死刑宣告」――アルメニア人の追放","l":"ww1-other-fronts","x":"1915年、オスマン帝国の政府は、ロシアと内通しているとして、東部アナトリアのアルメニア人を、シリアの砂漠へ強制的に移送した。男たちの多くは途中で殺され、女や子ども、老人は、食べ物"},{"id":"ww1-other-fronts-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"歩いてエルサレムに入った将軍","l":"ww1-other-fronts","x":"1917年12月、イギリス軍の司令官アレンビーは、オスマン軍を破ってエルサレムを占領した。12月11日、アレンビーは、エルサレムの旧市街のヤッフォ門の前で馬を降り、歩いて町に入った"},{"id":"ww1-other-fronts-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"坂東の「第九」","l":"ww1-other-fronts","x":"青島で捕虜となった約4700人のドイツ兵は、日本に送られ、各地の捕虜収容所に入れられた。そのうち、徳島県の板東俘虜収容所では、所長の松江豊寿が、捕虜たちを人道的に扱い、彼らの自主的"},{"id":"ww1-other-fronts-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"ww1-other-fronts","x":"映画『アラビアのロレンス』（デヴィッド・リーン監督、1962年）：アラブの反乱に加わったイギリスの将校ロレンスを描いた大作。アカデミー賞作品賞を受賞した。作品は史実をもとにした創作"},{"id":"ww1-western-front-t1","k":"source","f":"src","kj":"史料｜記録","t":"「甘美にして名誉なるかな」","l":"ww1-western-front","x":"イギリスの若い将校で詩人のウィルフレッド・オーエンは、毒ガスの攻撃で仲間が死んでいく姿を、詩に書いた。その詩は、古代ローマの詩人ホラティウスの有名な一句で結ばれている。原文My f"},{"id":"ww1-western-front-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「ガスだ！ ガスだ！ 急げ！」――毒ガスの戦場","l":"ww1-western-front","x":"1915年4月、ドイツ軍は、ベルギーのイープルで、初めて大規模に塩素ガスを使った。その後、両軍は、より強力なホスゲンやマスタードガス（イペリット）を次々に投入した。イギリスの将校で"},{"id":"ww1-western-front-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"サッカーボールを蹴って","l":"ww1-western-front","x":"7月1日の朝、モントーバンの近くの前線で、イギリス軍のネヴィル大尉は、部下たちの恐怖を和らげるために、一計を案じた。攻撃の合図とともに、塹壕から無人地帯へ、サッカーボールを蹴り出し"},{"id":"ww1-western-front-t4","k":"music","f":"music","kj":"音楽","t":"「オーバー・ゼア（向こうへ）」","l":"ww1-western-front","x":"アメリカが参戦した1917年4月、ブロードウェイの作曲家ジョージ・M・コーハンは、「向こうへ、向こうへ、ヤンキーが行くと伝えろ」と歌う「オーバー・ゼア」を、わずか一晩で書き上げたと"},{"id":"ww1-western-front-t5","k":"trivia","f":"side","kj":"こぼれ話","t":"午前10時59分","l":"ww1-western-front","x":"休戦が午前11時に発効することは、その日の早朝には前線にも伝えられていた。それでも、多くの部隊では、最後の瞬間まで攻撃が続けられ、11月11日の午前中だけで、両軍の数千人が死傷した"},{"id":"ww1-western-front-t6","k":"voice","f":"src","kj":"史料｜証言","t":"「人類は初めて、自らを絶滅させる道具を手に入れた」――チャーチル","l":"ww1-western-front","x":"大戦中、海軍大臣や軍需大臣を務めたチャーチルは、戦後、戦争の性格が根本から変わってしまったことを、繰り返し書いた。かつてのアレクサンドロスやカエサルやナポレオンのように、指揮官が兵"},{"id":"ww1-western-front-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"ww1-western-front","x":"レマルク『西部戦線異状なし』（小説、1929年）：ドイツの若い志願兵たちが、西部戦線の塹壕で次々と命を落としていく姿を描いた反戦小説。1930年と2022年に映画化された。ナチスは"},{"id":"ww2-end-europe-t1","k":"music","f":"music","kj":"音楽","t":"「ベッラ・チャオ（さらば恋人よ）」","l":"ww2-end-europe","x":"ドイツ軍とファシストに抵抗したイタリアのパルチザンの歌として、今では世界中で知られているのが、「ベッラ・チャオ」である。「ある朝、目を覚ますと、侵略者がいた。ああ、パルチザンよ、私"},{"id":"ww2-end-europe-t2","k":"voice","f":"src","kj":"史料｜証言","t":"「単に恐怖を増すための爆撃」――ドレスデン","l":"ww2-end-europe","x":"1945年2月13日から15日にかけて、イギリス軍とアメリカ軍の爆撃機は、ドイツ東部の古都ドレスデンを爆撃した。町は火災旋風に包まれ、東部から逃れてきた多くの避難民を含む、約2万5"},{"id":"ww2-end-europe-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"日本へ向かったUボート","l":"ww2-end-europe","x":"ドイツの降伏の時、大西洋の上には、日本を目指して航海中の1隻のドイツの潜水艦がいた。U234である。積み荷は、ジェット機の設計図やロケットの部品、そして、560キログラムの酸化ウラ"},{"id":"ww2-end-europe-t4","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"ww2-end-europe","x":"映画『ヒトラー ～最期の12日間～』（2004年、ドイツ）：ヒトラーの秘書だったトラウドゥル・ユンゲの証言などをもとに、ベルリンの地下壕でのヒトラーの最期を描いた映画。映画『プライ"},{"id":"ww2-europe-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「ばかな連中め」","l":"ww2-europe","x":"ミュンヘン会談から帰国したフランス首相ダラディエは、飛行機の窓から、空港に詰めかけた大群衆を見て、自分は非難の嵐で迎えられるに違いないと覚悟していた。同盟国のチェコスロヴァキアを見"},{"id":"ww2-europe-t2","k":"view","f":"think","kj":"考える｜別の視点","t":"「欧州の天地は複雑怪奇」","l":"ww2-europe","x":"独ソ不可侵条約の締結は、日本に大きな衝撃を与えた。日本は、ソ連を共通の敵として、ドイツと防共協定を結んでいた（→「ファシズムとナチズム」の回）。しかも、この時、満州とモンゴルの国境"},{"id":"ww2-europe-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"モロトフ・カクテル","l":"ww2-europe","x":"冬戦争の時、ソ連の飛行機は、フィンランドの町に、多数の小さな爆弾をばらまく爆弾（クラスター爆弾）を落とした。ソ連の外相モロトフが、ラジオで「ソ連の飛行機は、飢えたフィンランドの人々"},{"id":"ww2-europe-t4","k":"voice","f":"src","kj":"史料｜証言","t":"「われわれは、海岸で戦う」――チャーチルの演説","l":"ww2-europe","x":"1940年5月末から6月の初めにかけて、フランス北部のダンケルクの海岸に追いつめられたイギリス軍とフランス軍の兵士たち約34万人が、軍艦や、漁船、ヨットなど、民間の小さな船まで動員"},{"id":"ww2-europe-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"ww2-europe","x":"映画『ダンケルク』（クリストファー・ノーラン監督、2017年）：1940年のダンケルクの撤退を、陸・海・空の3つの視点から描いた映画（この回の「われわれは、海岸で戦う」の項を参照）"},{"id":"ww2-life-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"風船爆弾","l":"ww2-life","x":"1944年11月から翌年の春にかけて、日本は、太平洋の向こうのアメリカ本土を攻撃する、奇想天外な兵器を放った。直径10mの気球に爆弾をつるし、冬の上空を吹く強い西風（ジェット気流）"},{"id":"ww2-life-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「ロージー」のポスター","l":"ww2-life","x":"腕まくりをして力こぶを見せる、赤い水玉のバンダナの女性のポスター。今では「リベット打ちのロージー」として、第二次世界大戦中の働く女性の象徴、さらには女性の力の象徴として世界中で知ら"},{"id":"ww2-life-t3","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"ww2-life","x":"野坂昭如『火垂るの墓』（小説、1967年、アニメ映画1988年）：神戸の空襲で母を亡くした14歳の少年と4歳の妹が、戦争の末期を生きようとする物語。高畑勲監督のアニメ映画は、世界で"},{"id":"xinhai-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"ロンドンで誘拐された孫文","l":"xinhai","x":"1896年10月、ロンドンにいた孫文は、通りで声をかけられ、そのまま清の公使館に連れ込まれて監禁された。公使館は、孫文をひそかに船で清に送り返し、処刑させるつもりであった。孫文は、"},{"id":"xinhai-t2","k":"person","f":"deep","kj":"深掘り｜人物","t":"秋瑾","l":"xinhai","x":"浙江省の裕福な家に生まれた秋瑾は、親が決めた結婚に縛られた生活を捨てて、1904年、日本に留学した。東京で、彼女は、女性の解放と清の打倒を訴え、剣を携えて写真に収まった。帰国した秋"},{"id":"xinhai-t3","k":"view","f":"think","kj":"考える｜別の視点","t":"仙台の魯迅","l":"xinhai","x":"同じ頃、仙台の医学専門学校で、一人の中国人の留学生が医学を学んでいた。のちに中国の近代文学の父と呼ばれる作家、魯迅である。ある日、授業の合間に、日露戦争の様子を伝える幻灯（スライド"},{"id":"xinhai-t4","k":"life","f":"deep","kj":"深掘り｜暮らし","t":"辮髪を切る","l":"xinhai","x":"清の時代、漢人の男性は、満州人の風習に従って、頭の前半分をそり、後ろの髪を長く伸ばして三つ編みにする「辮髪」を強制されていた（→「清の成立」の回）。辮髪をしないことは、清への反逆と"},{"id":"xinhai-t5","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"xinhai","x":"映画『ラストエンペラー』（ベルナルド・ベルトルッチ監督、1987年）：宣統帝溥儀の生涯を、紫禁城での少年時代から満州国の皇帝、戦犯収容所を経て、一市民として死ぬまで描いた映画。アカ"},{"id":"xiongnu-t1","k":"source","f":"src","kj":"史料｜記録","t":"司馬遷が見た匈奴","l":"xiongnu","x":"原文隨畜牧而轉移……逐水草遷徙，毋城郭常處耕田之業。 ……現代語訳匈奴は、家畜を追って移動し、……水と草を求めて移り住み、城郭や定住地、耕作の仕事はない。……子どもは羊に乗って弓を"},{"id":"xiongnu-t2","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"鳴鏑の矢","l":"xiongnu","x":"冒頓は、父の頭曼単于の太子であったが、父は、後妻の生んだ子を跡継ぎにしようとして、冒頓を西方の月氏に人質として送り、その上で月氏を攻めた。冒頓は、月氏の良馬を盗んで逃げ帰った。冒頓"},{"id":"xiongnu-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"遊牧国家と農耕国家","l":"xiongnu","x":"遊牧国家（匈奴）農耕国家（漢）生業羊・馬などの遊牧、狩猟穀物の栽培（定住農耕）住居移動式の天幕（フェルト製）城壁で囲まれた都市・村落社会部族連合。単于のもとに諸部族が結集皇帝と官僚"},{"id":"xiongnu-t4","k":"source","f":"src","kj":"史料｜記録","t":"冒頓単于から呂后への手紙","l":"xiongnu","x":"高祖の死後、冒頓は、未亡人となった呂后に、次のような手紙を送った。原文孤僨之君，生於沮澤之中，長於平野牛馬之域，數至邊境，願遊中國。現代語訳孤独な君主である私は、沼地に生まれ、牛や"},{"id":"xiongnu-t5","k":"source","f":"src","kj":"史料｜記録","t":"漢を捨てた宦官・中行説","l":"xiongnu","x":"文帝の時代、匈奴に嫁ぐ公主の付き人として、宦官の中行説が匈奴に送られた。中行説は、行くことを嫌がったが無理に送られたため、匈奴に着くとそのまま単于の側近となり、漢の内情を教えた。漢"},{"id":"xiongnu-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「匈奴未だ滅びず」","l":"xiongnu","x":"武帝は、霍去病のために立派な邸宅を建てて与えようとした。すると、霍去病は答えた。「匈奴いまだ滅びず、何ぞ家をもってなさんや（匈奴がまだ滅びていないのに、どうして家など持てましょうか"},{"id":"xiongnu-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"蘇武と雁の手紙","l":"xiongnu","x":"前100年、漢の使者として匈奴に赴いた蘇武は、匈奴の内紛に巻き込まれて捕らえられた。匈奴は、蘇武を降伏させようとしたが、蘇武は、穴蔵に閉じ込められても、雪と毛皮の毛を食べて生き延び"},{"id":"xiongnu-t8","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"中国に来たローマ兵？","l":"xiongnu","x":"郅支単于の城を攻めた漢の軍の報告には、城の外で「魚の鱗のような陣形」をとる100人余りの兵士がいたと記されている。1950年代、アメリカの歴史学者ダブスは、これが、前53年のカルラ"},{"id":"xiongnu-t9","k":"person","f":"deep","kj":"深掘り｜人物","t":"王昭君","l":"xiongnu","x":"前33年、呼韓邪単于は再び長安を訪れ、漢の皇族の娘を妻に迎えたいと願った。元帝は、後宮の女性の一人、王昭君を単于に嫁がせた。のちの時代の伝説によれば、後宮の女性たちは、皇帝に選ばれ"},{"id":"xiongnu-t10","k":"now","f":"now","kj":"いま","t":"2000年ぶりに見つかった「燕然山銘」","l":"xiongnu","x":"89年、北匈奴を破った竇憲は、モンゴル高原の燕然山に登り、勝利を記念する文章を岩に刻ませた。この文章を書いたのは、のちに『漢書』を著す歴史家の班固であった。この「燕然山銘」の文章は"},{"id":"xiongnu-t11","k":"debate","f":"think","kj":"考える｜諸説あり","t":"匈奴はフン族になったのか","l":"xiongnu","x":"4世紀後半、ヨーロッパ東部に、フン人と呼ばれる遊牧民が突然現れ、ゲルマン人の大移動を引き起こした（→「ゲルマン人の大移動」の回）。18世紀のフランスの学者ド＝ギーニュは、このフン人"},{"id":"xiongnu-t12","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"xiongnu","x":"中島敦『李陵』（1943年発表）：匈奴に降伏した将軍李陵、彼を弁護して宮刑を受けた司馬遷、そして匈奴の地で節を守り続けた蘇武の3人の生き方を描いた短編小説。漢文調の格調高い文体で知"},{"id":"yongle-zheng-he-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"完成から100日で燃えた宮殿","l":"yongle-zheng-he","x":"1421年の正月、永楽帝は、完成したばかりの紫禁城で、盛大な遷都の儀式を行った。ところが、それからわずか100日後の4月、雷が落ちて、正殿である奉天殿（のちの太和殿）など三つの大殿"},{"id":"yongle-zheng-he-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"鄭和の身長は「九尺」？","l":"yongle-zheng-he","x":"明の時代の記録の一つは、鄭和について、「身長は九尺（約2.8m）、腰回りは十囲、眉と目は秀で、耳は白く大きく、歯は貝殻を並べたよう、歩く姿は虎のよう、声は鐘のようであった」と書いて"},{"id":"yongle-zheng-he-t3","k":"source","f":"src","kj":"史料｜記録","t":"「巨浪は山のごとし」――鄭和の石碑","l":"yongle-zheng-he","x":"7回目の航海に出発する直前の1431年、鄭和は、福建の長楽の港で、航海の守り神である天妃（媽祖）をまつる宮に、一つの石碑を建てた。そこには、これまでの航海を振り返って、こう刻まれて"},{"id":"yongle-zheng-he-t4","k":"source","f":"src","kj":"史料｜記録","t":"三つの言葉で刻まれた石碑","l":"yongle-zheng-he","x":"1911年、スリランカの南の港町ゴールで、道路の工事中に、一枚の石碑が見つかった。調べてみると、それは、鄭和の艦隊が、1409年の日付で、この島に建てた石碑であった。驚くべきことに"},{"id":"yongle-zheng-he-t5","k":"source","f":"src","kj":"史料｜記録","t":"指で計算する商人たち――馬歓の『瀛涯勝覧』","l":"yongle-zheng-he","x":"鄭和の航海には、アラビア語に通じた、イスラーム教徒の通訳の馬歓も同行した。馬歓は、訪れた国々の見聞を『瀛涯勝覧』という本にまとめた。南インドの港町カリカット（古里）について、馬歓は"},{"id":"yongle-zheng-he-t6","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"「鄭和はアメリカ大陸を発見した」？","l":"yongle-zheng-he","x":"2002年、イギリスの元海軍士官ギャヴィン・メンジーズは、『1421――中国が新大陸を発見した年』という本を書き、鄭和の艦隊の一部が、コロンブスより70年も早くアメリカ大陸に到達し"},{"id":"yongle-zheng-he-t7","k":"debate","f":"think","kj":"考える｜諸説あり","t":"もし明が航海を続けていたら？","l":"yongle-zheng-he","x":"「もし明が大航海を続けていたら、世界の歴史は変わっていたのではないか」という問いが、よく投げかけられる。ただし、鄭和の航海と、のちのヨーロッパの大航海とは、目的がまったく違っていた"},{"id":"yuan-fall-t1","k":"person","f":"deep","kj":"深掘り｜人物","t":"「魯班天子」と呼ばれた皇帝","l":"yuan-fall","x":"トゴン・テムルは、政治よりも、ものづくりに熱中した皇帝として知られている。『元史』によれば、彼は自ら設計図を描いて、長さ120尺（約37m）の竜の形をした船を造らせた。船が進むと、"},{"id":"yuan-fall-t2","k":"trivia","f":"side","kj":"こぼれ話","t":"宰相トクトがまとめた三つの歴史書","l":"yuan-fall","x":"トクトは、元の末期の政治家の中で最も有能な人物といわれる。彼の名は、中国の歴史書の上にも残っている。中国では、新しい王朝が、前の王朝の正式な歴史（正史）を編纂するのが習わしであった"},{"id":"yuan-fall-t3","k":"person","f":"deep","kj":"深掘り｜人物","t":"「大足の馬皇后」","l":"yuan-fall","x":"馬氏は、朱元璋が郭子興の疑いを受けて閉じ込められ、食事を与えられなかったとき、焼きたての餅（中国の小麦粉の焼き菓子）を懐に隠して運び、胸にやけどを負ったという逸話がある伝承。朱元璋"},{"id":"yuan-fall-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"身代わりになった男","l":"yuan-fall","x":"鄱陽湖の戦いでは、朱元璋自身が、何度も命の危険にさらされた。旗艦が浅瀬に乗り上げて敵に囲まれかけたときには、部下の常遇春が、敵将を矢で射て、危機を救ったという。また、こんな話も伝わ"},{"id":"yuan-fall-t5","k":"source","f":"src","kj":"史料｜記録","t":"「わが大都よ」――トゴン・テムルの嘆き","l":"yuan-fall","x":"のちのモンゴルの年代記『蒙古源流』などには、大都を追われたトゴン・テムルが、こう嘆いたと記されている。「さまざまな宝で飾られた、わが大都よ。いにしえの帝たちが夏を過ごした、わが上都"},{"id":"yuan-fall-t6","k":"trivia","f":"side","kj":"こぼれ話","t":"炎から救い出された名画","l":"yuan-fall","x":"黄公望が70代の終わりに、数年をかけて描き上げた『富春山居図』は、中国の山水画の最高傑作の一つとされる。浙江省の富春江の穏やかな山と川の風景を、長さ6mを超える巻物に描いたものであ"},{"id":"yuan-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"「ザナドゥ」の伝説","l":"yuan","x":"上都は、のちにヨーロッパで「ザナドゥ（Xanadu）」として知られるようになった。マルコ＝ポーロは、上都の大理石の宮殿や、竹でつくられた移動式の宮殿、白い馬の群れなどについて書き残"},{"id":"yuan-t2","k":"war","f":"deep","kj":"深掘り｜戦術","t":"回回砲――おもりで石を飛ばす","l":"yuan","x":"それまで中国で使われていた投石機は、長い腕の一方に石を乗せ、もう一方の端に結んだ何十本もの綱を、大勢の人が一斉に引いて石を飛ばす仕組みであった。引く人の力やタイミングがばらばらなの"},{"id":"yuan-t3","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"マルコ＝ポーロが投石機を造った？","l":"yuan","x":"マルコ＝ポーロの『世界の記述（東方見聞録）』には、襄陽の包囲について、驚くべき話が書かれている。3年かかっても町を落とせずに困っていたクビライに、マルコの父ニコロと叔父マッフェオが"},{"id":"yuan-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"皇后チャブイの涙","l":"yuan","x":"臨安から大都へ、南宋の宮廷の財宝が運ばれてきた。クビライは、それを広げて、皇后のチャブイに見せた。ところが、チャブイは、それをひと目見ただけで、その場を去ってしまった。クビライが、"},{"id":"yuan-t5","k":"person","f":"deep","kj":"深掘り｜人物","t":"「正気の歌」――文天祥の最期","l":"yuan","x":"大都に送られた文天祥は、それから3年あまり、狭い牢獄に閉じ込められた。クビライは、文天祥の才能と人柄を高く評価し、何度も元に仕えるよう勧めた。高い位を約束する使いが、何度も牢獄を訪"},{"id":"yuan-t6","k":"debate","f":"think","kj":"考える｜諸説あり","t":"「四つの身分」は本当にあったのか","l":"yuan","x":"教科書では、元の社会は、モンゴル人・色目人・漢人（もとの金の支配下の人々や、契丹人・女真人など）・南人（もとの南宋の支配下の人々）の四つの身分に分けられ、この順に差別されていた、と"},{"id":"yuan-t7","k":"person","f":"deep","kj":"深掘り｜人物","t":"財務長官アフマドの暗殺","l":"yuan","x":"クビライの時代に、財政を一手に握ったのが、中央アジア出身のイスラーム教徒アフマドである。アフマドは、塩の専売や税の取り立てを強化して、戦争や宮廷の費用のための収入を大きく増やした。"},{"id":"yuan-t8","k":"trivia","f":"side","kj":"こぼれ話","t":"郭守敬の暦と、日本の改暦","l":"yuan","x":"郭守敬は、元の時代の最も優れた科学者の一人である。クビライの命令で、郭守敬は、新しい暦をつくるために、中国の各地に観測所を設け、精密な観測器械を考案して、太陽や星の動きを測った。こ"},{"id":"yugoslavia-t1","k":"trivia","f":"side","kj":"こぼれ話","t":"七から一へ","l":"yugoslavia","x":"ユーゴスラヴィアの複雑さを表す、有名な言い回しがある。「七つの国境、六つの共和国、五つの民族、四つの言語、三つの宗教、二つの文字、そして一つの国家（あるいは、一人のティトー）」。七"},{"id":"yugoslavia-t2","k":"source","f":"src","kj":"史料｜記録","t":"「誰にも、あなたたちを殴らせない」","l":"yugoslavia","x":"1987年4月、セルビアの共産党の幹部ミロシェヴィッチは、コソヴォの町コソヴォ・ポリエを訪れた。そこでは、少数派のセルビア人の住民たちが、多数派のアルバニア人から差別を受けていると"},{"id":"yugoslavia-t3","k":"trivia","f":"side","kj":"こぼれ話","t":"マクシミール競技場の乱闘","l":"yugoslavia","x":"1990年5月13日、クロアティアの首都ザグレブのマクシミール競技場で、地元のディナモ・ザグレブと、セルビアの首都ベオグラードのツルヴェナ・ズヴェズダ（レッドスター）のサッカーの試"},{"id":"yugoslavia-t4","k":"person","f":"deep","kj":"深掘り｜人物","t":"オシムの辞任","l":"yugoslavia","x":"サッカーのユーゴスラヴィア代表の監督を務めていたのは、サライェヴォ出身のイヴィツァ・オシムであった。1990年のワールドカップのイタリア大会では、多民族の選手たちをまとめ、チームを"},{"id":"yugoslavia-t5","k":"voice","f":"src","kj":"史料｜証言","t":"「トルコ人に復讐する時が来た」――スレブレニツァとフォチャ","l":"yugoslavia","x":"1995年7月11日、ボスニアのセルビア人勢力の軍司令官ラトコ・ムラディッチは、国連の「安全地帯」とされていた町スレブレニツァに入った。彼は、テレビカメラの前で、こう語った。原文…"},{"id":"yugoslavia-t6","k":"view","f":"think","kj":"考える｜別の視点","t":"「NATO STOP STRIKES」","l":"yugoslavia","x":"NATOの空爆が始まった直後の1999年3月、日本のJリーグの試合で、名古屋グランパスのセルビア人の選手ドラガン・ストイコビッチは、ゴールを決めた後、ユニフォームをまくり上げた。そ"},{"id":"yugoslavia-t7","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"yugoslavia","x":"映画『アンダーグラウンド』（エミール・クストリッツァ監督、1995年）：第二次世界大戦から、ユーゴスラヴィアの解体と内戦までの50年を、地下に閉じ込められた人々の寓話として描いた映"},{"id":"zhou-t1","k":"source","f":"src","kj":"史料｜記録","t":"「甲子の朝」――青銅器が証明した戦いの日","l":"zhou","x":"1976年、陝西省臨潼で、一つの青銅器が見つかった。器の内側に鋳込まれた銘文は、こう始まっている。原文珷征商，隹甲子朝，歲鼎，克昏夙有商。書き下し武王、商を征す。唯れ甲子の朝なり。"},{"id":"zhou-t2","k":"source","f":"src","kj":"史料｜記録","t":"「書を尽く信ずれば」――孟子の疑い","l":"zhou","x":"『尚書』の一篇（武成篇）は、牧野の戦いのすさまじさを「血流れて杵を漂わす」（流れた血で、臼をつく杵が浮かんで流れた）と描いていた。これに対して、戦国時代の儒家・孟子は、次のように言"},{"id":"zhou-t3","k":"confuse","f":"confuse","kj":"混同注意","t":"周の封建制と、ヨーロッパの封建制","l":"zhou","x":"「封建制」という同じ言葉が、中国の周と、中世ヨーロッパの両方に使われるので、混同しやすい。中身はかなり違う。周の封建制中世ヨーロッパの封建制時代前11〜前8世紀ごろ（西周）9〜13"},{"id":"zhou-t4","k":"trivia","f":"side","kj":"こぼれ話","t":"「中国」という言葉の最古の例","l":"zhou","x":"1963年、陝西省宝鶏で、農家の裏の崖から一つの青銅器（何尊）が見つかった。この器の内底には、周の成王の時代に、洛邑の建設について記した122字の銘文が鋳込まれていた。その中に、武"},{"id":"zhou-t5","k":"confuse","f":"confuse","kj":"混同注意","t":"禅譲と放伐","l":"zhou","x":"方法内容伝説上の例禅譲天子が、徳のある人物に平和的に位を譲る堯 → 舜 → 禹放伐徳を失った君主を、武力で討って追放する殷の湯王が夏の桀王を討つ、周の武王が殷の紂王を討つのちの時代"},{"id":"zhou-t6","k":"source","f":"src","kj":"史料｜記録","t":"周公の戒め――「殷を鑑とせよ」","l":"zhou","x":"天命が失われうるという考えは、王にとって脅しでもあった。周の初めの王たちは、殷が滅んだ理由を、酒におぼれて政治を怠ったことにあると考え、自らを強く戒めた。周の康王の時代の青銅器「大"},{"id":"zhou-t7","k":"myth","f":"think","kj":"考える｜俗説を検証","t":"笑わない后と烽火","l":"zhou","x":"西周の最後の王・幽王には、褒姒という美しい后がいた。しかし、褒姒はまったく笑わなかった。あるとき、幽王が敵の襲来を知らせる烽火を上げさせると、諸侯たちがあわてて駆けつけたが、敵はい"},{"id":"zhou-t8","k":"works","f":"works","kj":"作品","t":"この時代を描いた作品","l":"zhou","x":"藤崎竜『封神演義』（漫画、1996〜2000年連載）：殷から周への王朝交代を、仙人たちの戦いとして描いた明代の小説『封神演義』をもとにした漫画。主人公は、周の文王・武王に仕えた太公"}]);
